using System.IO;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEngine;

namespace TheRobotDraft.EditorTools
{
    /// <summary>
    /// Builds the macOS standalone (.app) for The Robot Draft.
    ///
    /// Run it either way:
    ///   • Editor menu:  The Robot Draft ▸ Build ▸ macOS
    ///   • Headless / CI: Unity -batchmode -nographics -quit -projectPath . \
    ///                          -executeMethod TheRobotDraft.EditorTools.BuildMac.Build
    ///     (the repo-root <c>build-mac.sh</c> wrapper does exactly this and auto-picks an
    ///      editor that has Mac Build Support)
    ///
    /// Requires the "Mac Build Support" module for the editor doing the build (the Mac editor
    /// does NOT always include it — add it in Unity Hub: Installs ▸ ⋮ ▸ Add modules). Without it
    /// the build fails fast with a clear error and exits non-zero. Architecture is left at the
    /// editor default (Apple silicon on an arm64 editor) to keep this script module-agnostic at
    /// compile time; set a universal/Intel target in Build Profiles if you need it.
    /// </summary>
    public static class BuildMac
    {
        private const string OutputDir = "Builds/macOS";
        private const string AppName = "The Robot Draft.app";

        [MenuItem("The Robot Draft/Build/macOS")]
        public static void Build()
        {
            // Set identity here rather than hand-editing ProjectSettings.asset.
            PlayerSettings.companyName = "Noizu Labs";
            PlayerSettings.productName = "The Robot Draft";

            // Run in a resizable window (not fullscreen). The runtime bootstrap also enforces this.
            PlayerSettings.fullScreenMode = FullScreenMode.Windowed;
            PlayerSettings.defaultIsNativeResolution = false;
            PlayerSettings.defaultScreenWidth = 1280;
            PlayerSettings.defaultScreenHeight = 720;
            PlayerSettings.resizableWindow = true;

            var options = new BuildPlayerOptions
            {
                scenes = new[] { "Assets/Scenes/Boot.unity" },
                locationPathName = Path.Combine(OutputDir, AppName),
                target = BuildTarget.StandaloneOSX,
                targetGroup = BuildTargetGroup.Standalone,
                options = BuildOptions.None,
            };

            Directory.CreateDirectory(OutputDir);

            BuildReport report = BuildPipeline.BuildPlayer(options);
            BuildSummary summary = report.summary;

            if (summary.result == BuildResult.Succeeded)
            {
                Debug.Log($"[BuildMac] Succeeded — {summary.totalSize} bytes -> {options.locationPathName}");
                if (Application.isBatchMode) EditorApplication.Exit(0);
            }
            else
            {
                Debug.LogError($"[BuildMac] FAILED — result={summary.result}, errors={summary.totalErrors}. " +
                               "If this says the Mac module is missing, add 'Mac Build Support' in Unity Hub.");
                if (Application.isBatchMode) EditorApplication.Exit(1);
            }
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using TheRobotDraft.Uml;

namespace TheRobotDraft
{
    /// <summary>
    /// Runtime entry point for the on-screen authoring harness. Stands up a camera + EventSystem and a single
    /// <see cref="UmlCanvas"/> that builds the interactive 2D UML editor and drives the real
    /// <c>AuthoringController</c> (Assets/Scripts/Authoring). It is a desktop stand-in for the (gated) DOTS
    /// bubble renderer — same command model, 2D boxes instead of 3D bubbles — so the authoring core is visible
    /// and usable today. The production surface is the UI Toolkit toolbar + VR radial (authoring-ux.md §2).
    /// </summary>
    public static class AuthoringDemoBootstrap
    {
        /// <summary>When true, <see cref="ComingSoonBootstrap"/> stands down so this harness owns the screen.
        /// Flip to <c>false</c> to restore the plain "Coming Soon" splash. (static readonly, not const, so the
        /// guard in <see cref="ComingSoonBootstrap"/> doesn't trip an unreachable-code warning.)</summary>
        public static readonly bool Active = true;

        private static readonly Color Background = new Color(0.07f, 0.08f, 0.10f, 1f);

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        private static void Boot()
        {
            if (!Active) return;

            EnsureCamera();
            EnsureEventSystem();
            RemoveComingSoon();

            // Fill the screen — a large windowed surface (avoid a runtime fullscreen-mode switch, which can
            // recreate the Metal surface mid-bootstrap). Cap to a sane max for very wide displays.
            if (!Application.isEditor)
            {
                int w = Mathf.Min(Display.main.systemWidth, 2560);
                int h = Mathf.Min(Display.main.systemHeight, 1440);
                Screen.SetResolution(w, h, FullScreenMode.Windowed);
            }

            var go = new GameObject("UmlAuthoringCanvas", typeof(RectTransform));
            Object.DontDestroyOnLoad(go);
            go.AddComponent<UmlCanvas>(); // builds its own Canvas + UI in Awake
        }

        private static void EnsureCamera()
        {
            var cam = Camera.main;
            if (cam == null)
            {
                var camGo = new GameObject("Main Camera") { tag = "MainCamera" };
                cam = camGo.AddComponent<Camera>();
                camGo.AddComponent<AudioListener>();
                Object.DontDestroyOnLoad(camGo);
            }
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = Background;
        }

        private static void EnsureEventSystem()
        {
            if (Object.FindFirstObjectByType<EventSystem>() != null) return;
            var es = new GameObject("EventSystem");
            es.AddComponent<EventSystem>();
            es.AddComponent<StandaloneInputModule>();
            Object.DontDestroyOnLoad(es);
        }

        private static void RemoveComingSoon()
        {
            var existing = GameObject.Find("ComingSoonCanvas");
            if (existing != null) Object.Destroy(existing);
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace TheRobotDraft
{
    /// <summary>
    /// Temporary placeholder splash for The Robot Draft.
    ///
    /// Builds a dark overlay with a "Coming Soon" title and an Exit button at runtime, and forces
    /// the standalone player into a resizable window. It is intentionally dependency-free: no scene
    /// wiring, no asset references, no render-pipeline setup — it runs automatically on Play and in a
    /// built player via <see cref="RuntimeInitializeOnLoadMethod"/>, so the project renders correctly
    /// on the very first try.
    ///
    /// This is a stub. The production shell will be a URP + Render Graph project with a UI Toolkit
    /// front-end and the DOTS/OpenXR bubble-view renderer described in docs/specs/unity-6.3-baseline.md
    /// and ADR-001. Replace this class when that shell lands.
    /// </summary>
    public static class ComingSoonBootstrap
    {
        private static readonly Color Background = new Color(0.06f, 0.07f, 0.09f, 1f);
        private static readonly Color TitleColor = new Color(0.92f, 0.94f, 0.98f, 1f);
        private static readonly Color SubtitleColor = new Color(0.55f, 0.60f, 0.70f, 1f);

        private const int WindowWidth = 1280;
        private const int WindowHeight = 720;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        private static void Boot()
        {
            // The authoring-core demo harness owns the screen (and the window size) when present.
            if (AuthoringDemoBootstrap.Active) return;

            EnsureWindowed();
            EnsureCamera();
            BuildOverlay();
        }

        private static void EnsureWindowed()
        {
            // Run in a window rather than fullscreen. PlayerSettings already requests this at build
            // time; this is the runtime safeguard (and a no-op worth skipping in the editor).
            if (!Application.isEditor)
                Screen.SetResolution(WindowWidth, WindowHeight, FullScreenMode.Windowed);
        }

        private static void EnsureCamera()
        {
            var cam = Camera.main;
            if (cam == null)
            {
                var camGo = new GameObject("Main Camera") { tag = "MainCamera" };
                cam = camGo.AddComponent<Camera>();
                camGo.AddComponent<AudioListener>();
                Object.DontDestroyOnLoad(camGo);
            }

            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = Background;
        }

        private static void BuildOverlay()
        {
            EnsureEventSystem();

            var canvasGo = new GameObject("ComingSoonCanvas");
            Object.DontDestroyOnLoad(canvasGo);

            var canvas = canvasGo.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvas.sortingOrder = 32760; // sit on top of anything else

            var scaler = canvasGo.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920f, 1080f);
            scaler.matchWidthOrHeight = 0.5f;

            canvasGo.AddComponent<GraphicRaycaster>();

            // LegacyRuntime.ttf is the built-in fallback font (the old "Arial.ttf"),
            // available without importing TextMeshPro essentials — ideal for a stub.
            var font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            CreateLabel(canvasGo.transform, "Title", "Coming Soon",
                font, 96, FontStyle.Bold, TitleColor, new Vector2(0f, 80f));

            CreateLabel(canvasGo.transform, "Subtitle", "The Robot Draft",
                font, 36, FontStyle.Normal, SubtitleColor, new Vector2(0f, -20f));

            CreateExitButton(canvasGo.transform, font, new Vector2(0f, -180f));
        }

        /// <summary>uGUI buttons need an EventSystem + input module to receive clicks.</summary>
        private static void EnsureEventSystem()
        {
            if (Object.FindFirstObjectByType<EventSystem>() != null)
                return;

            var es = new GameObject("EventSystem");
            es.AddComponent<EventSystem>();
            es.AddComponent<StandaloneInputModule>();
            Object.DontDestroyOnLoad(es);
        }

        private static void CreateExitButton(Transform parent, Font font, Vector2 anchoredPos)
        {
            var go = new GameObject("ExitButton");
            go.transform.SetParent(parent, false);

            var rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(220f, 64f);
            rect.anchoredPosition = anchoredPos;

            var img = go.AddComponent<Image>();
            img.color = new Color(0.16f, 0.18f, 0.22f, 1f);

            var button = go.AddComponent<Button>();
            button.targetGraphic = img;
            var colors = button.colors;
            colors.normalColor = new Color(0.16f, 0.18f, 0.22f, 1f);
            colors.highlightedColor = new Color(0.24f, 0.27f, 0.33f, 1f);
            colors.pressedColor = new Color(0.11f, 0.12f, 0.15f, 1f);
            colors.selectedColor = colors.highlightedColor;
            button.colors = colors;
            button.onClick.AddListener(Quit);

            var labelGo = new GameObject("Text");
            labelGo.transform.SetParent(go.transform, false);
            var lrect = labelGo.AddComponent<RectTransform>();
            lrect.anchorMin = Vector2.zero;
            lrect.anchorMax = Vector2.one;
            lrect.offsetMin = Vector2.zero;
            lrect.offsetMax = Vector2.zero;

            var label = labelGo.AddComponent<Text>();
            label.font = font;
            label.text = "Exit";
            label.fontSize = 28;
            label.alignment = TextAnchor.MiddleCenter;
            label.color = new Color(0.90f, 0.92f, 0.96f, 1f);
        }

        private static void Quit()
        {
#if UNITY_EDITOR
            UnityEditor.EditorApplication.isPlaying = false;
#else
            Application.Quit();
#endif
        }

        private static void CreateLabel(Transform parent, string name, string text,
            Font font, int size, FontStyle style, Color color, Vector2 anchoredPos)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);

            var rect = go.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(1600f, 240f);
            rect.anchoredPosition = anchoredPos;

            var label = go.AddComponent<Text>();
            label.font = font;
            label.text = text;
            label.fontSize = size;
            label.fontStyle = style;
            label.color = color;
            label.alignment = TextAnchor.MiddleCenter;
            label.horizontalOverflow = HorizontalWrapMode.Overflow;
            label.verticalOverflow = VerticalWrapMode.Overflow;
        }
    }
}

using System.Collections.Generic;
using System.Text;
using TheRobotDraft.Authoring.Model;

namespace TheRobotDraft.CodeGen
{
    /// <summary>
    /// Everything the code generator needs about one element: its identity (name / kind / language / stereotype /
    /// abstract), its members (attribute + operation signature strings as the model stores them), the text of any
    /// UML notes attached to it, and its relationships to other elements (collaborators it uses, callers, and the
    /// base classes / interfaces it extends or implements). Plain data — the UmlCanvas partial walks the model to
    /// populate it. <see cref="ToPromptString"/> renders it as a structured block for the LLM, and the deterministic
    /// <see cref="CodeSkeleton"/> consumes the same fields for the offline fallback.
    /// </summary>
    public sealed class CodeGenContext
    {
        public string Name;
        public ElementKind Kind;
        public string Language;     // null/empty ⇒ unspecified (skeleton defaults to C#)
        public string Stereotype;   // raw custom stereotype, no guillemets; null/empty ⇒ none
        public bool IsAbstract;
        public string Description;  // free-text documentation; null/empty ⇒ none

        /// <summary>
        /// The original source file's full text when this element was imported from a file (overlay round-trip).
        /// Null/empty ⇒ no stored source, so generation falls back to from-scratch synthesis.
        /// </summary>
        public string OriginalSource;

        /// <summary>The path the original source came from (the element's SourceFile); null ⇒ none. For status text only.</summary>
        public string OriginalSourcePath;

        public readonly List<string> Attributes = new();   // full signatures, e.g. "- id : Guid"
        public readonly List<string> Operations = new();    // full signatures, e.g. "+ submit() : void"
        // Per-member doc-comments, index-aligned with Attributes / Operations (empty string ⇒ no comment).
        public readonly List<string> AttributeComments = new();
        public readonly List<string> OperationComments = new();
        public readonly List<string> AttachedNotes = new(); // verbatim note texts linked via NoteLink

        /// <summary>The doc-comment for the i-th attribute, or "" if none / out of range (ragged-list safe).</summary>
        public string AttributeComment(int i) =>
            i >= 0 && i < AttributeComments.Count ? AttributeComments[i] ?? "" : "";

        /// <summary>The doc-comment for the i-th operation, or "" if none / out of range.</summary>
        public string OperationComment(int i) =>
            i >= 0 && i < OperationComments.Count ? OperationComments[i] ?? "" : "";

        public readonly List<Relationship> Relationships = new();

        /// <summary>How an element relates to a collaborator (a supertype, an interface, a used type, or a caller).</summary>
        public enum RelKind { Extends, Implements, Uses, UsedBy }

        public enum RelDirection { Out, In }

        /// <summary>One relationship to another element, with the other end's identity, role, and its member API.</summary>
        public sealed class Relationship
        {
            public RelKind Kind;
            public RelDirection Direction;
            public EdgeKind Edge;
            public string OtherName;
            public ElementKind OtherKind;
            public string Label;            // association name / role; null/empty ⇒ none
            public string SrcMultiplicity;  // multiplicity at this element's end
            public string TgtMultiplicity;  // multiplicity at the other element's end
            // The collaborator's own member signatures, so the LLM knows the API it calls into / extends.
            public readonly List<string> OtherAttributes = new();
            public readonly List<string> OtherOperations = new();
        }

        /// <summary>Render the context as a clear, structured text block the LLM can follow.</summary>
        public string ToPromptString()
        {
            var sb = new StringBuilder();
            string lang = string.IsNullOrWhiteSpace(Language) ? "C#" : Language.Trim();

            sb.Append("Target language: ").Append(lang).Append('\n');
            sb.Append("Element name: ").Append(Name).Append('\n');
            sb.Append("Element kind: ").Append(Kind).Append('\n');
            if (IsAbstract) sb.Append("Modifier: abstract\n");
            if (!string.IsNullOrWhiteSpace(Stereotype)) sb.Append("Stereotype: «").Append(Stereotype.Trim()).Append("»\n");

            if (!string.IsNullOrWhiteSpace(Description))
                sb.Append("\nDescription:\n").Append(Description.Trim()).Append('\n');

            if (Attributes.Count > 0)
            {
                sb.Append("\nAttributes (fields), in UML signature form (with their doc-comments):\n");
                for (int i = 0; i < Attributes.Count; i++)
                {
                    sb.Append("  ").Append(Attributes[i]).Append('\n');
                    string c = AttributeComment(i);
                    if (!string.IsNullOrWhiteSpace(c)) sb.Append("      // ").Append(c.Replace("\n", " ").Trim()).Append('\n');
                }
            }

            if (Operations.Count > 0)
            {
                sb.Append("\nOperations (methods), in UML signature form (with their doc-comments):\n");
                for (int i = 0; i < Operations.Count; i++)
                {
                    sb.Append("  ").Append(Operations[i]).Append('\n');
                    string c = OperationComment(i);
                    if (!string.IsNullOrWhiteSpace(c)) sb.Append("      // ").Append(c.Replace("\n", " ").Trim()).Append('\n');
                }
            }

            if (AttachedNotes.Count > 0)
            {
                sb.Append("\nAttached UML notes / constraints:\n");
                foreach (var n in AttachedNotes)
                {
                    // Indent every line of a multi-line note so the block reads as one item.
                    foreach (var line in n.Replace("\r\n", "\n").Split('\n'))
                        sb.Append("  ").Append(line).Append('\n');
                    sb.Append('\n');
                }
            }

            if (Relationships.Count > 0)
            {
                sb.Append("\nRelationships:\n");
                foreach (var r in Relationships)
                {
                    sb.Append("  - ").Append(DescribeRelationship(r)).Append('\n');
                    AppendMemberLines(sb, "      field", r.OtherAttributes);
                    AppendMemberLines(sb, "      method", r.OtherOperations);
                }
            }

            return sb.ToString();
        }

        private static void AppendMemberLines(StringBuilder sb, string prefix, List<string> members)
        {
            foreach (var m in members) sb.Append(prefix).Append(": ").Append(m).Append('\n');
        }

        private static string DescribeRelationship(Relationship r)
        {
            var sb = new StringBuilder();
            switch (r.Kind)
            {
                case RelKind.Extends:
                    sb.Append("extends ");
                    break;
                case RelKind.Implements:
                    sb.Append("implements interface ");
                    break;
                case RelKind.UsedBy:
                    sb.Append("is used by ");
                    break;
                default:
                    sb.Append("uses ");
                    break;
            }
            sb.Append(r.OtherName).Append(" (").Append(r.OtherKind).Append(')');
            if (!string.IsNullOrWhiteSpace(r.Label)) sb.Append(" — role \"").Append(r.Label.Trim()).Append('"');

            string src = string.IsNullOrWhiteSpace(r.SrcMultiplicity) ? null : r.SrcMultiplicity.Trim();
            string tgt = string.IsNullOrWhiteSpace(r.TgtMultiplicity) ? null : r.TgtMultiplicity.Trim();
            if (src != null || tgt != null)
                sb.Append(" [").Append(src ?? "?").Append(" .. ").Append(tgt ?? "?").Append(']');

            return sb.ToString();
        }
    }
}

using System;
using System.Text;
using UnityEngine;

namespace TheRobotDraft.CodeGen
{
    /// <summary>
    /// The inverse of <see cref="CodeSkeleton"/> / <see cref="CodeGenContext"/>: parses the LLM's structured
    /// description of pasted source back into model-ready data so the canvas can materialize UML elements
    /// (code → model). The DTOs are <see cref="JsonUtility"/>-shaped — a single root object with a named array
    /// of types — because the player runtime has no System.Text.Json (same constraint as <see cref="Llm.LlmClient"/>).
    /// <see cref="SystemPrompt"/> + <see cref="BuildUserPrompt"/> pin the exact JSON the model must emit; the
    /// UmlCanvas.CodeImport partial drives the request and turns a <see cref="ParsedModel"/> into elements + edges.
    /// </summary>
    public static class CodeParser
    {
        // --- structured-output DTOs (JsonUtility-serializable) ---

        /// <summary>One classifier the model found in the pasted source.</summary>
        [Serializable]
        public sealed class ParsedType
        {
            public string name;
            public string kind;        // Class | Interface | Enum | Struct (free text; mapped + defaulted to Class)
            public string language;    // implementation language, e.g. "C#", "TypeScript"
            public string comment;     // the type's doc-comment text, stripped of comment markers; "" when absent
            public string[] fields;    // UML attribute signatures, e.g. "- id : Guid"
            public string[] fieldComments;  // doc-comment per field, index-aligned with fields; "" when absent
            public string[] methods;   // UML operation signatures, e.g. "+ submit() : void"
            public string[] methodComments; // doc-comment per method, index-aligned with methods; "" when absent
            public string[] extends;   // base-type names (Generalization)
            public string[] implements; // interface names (Realization)
            public string[] uses;      // collaborator type names (Dependency)
        }

        /// <summary>The root object — a named array so <see cref="JsonUtility"/> can deserialize it.</summary>
        [Serializable]
        public sealed class ParsedModel
        {
            public ParsedType[] types;
        }

        // --- prompt ---

        /// <summary>System role: a precise instruction to return ONLY the JSON schema, no prose, no fences.</summary>
        public static string SystemPrompt =>
            "You are a senior software engineer that reverse-engineers source code into a UML class model. " +
            "Analyze the supplied source and identify every top-level type (class, interface, enum, struct). " +
            "Return ONLY a single JSON object — no markdown fences, no commentary — matching exactly this shape:\n" +
            "{\n" +
            "  \"types\": [\n" +
            "    {\n" +
            "      \"name\": \"TypeName\",\n" +
            "      \"kind\": \"Class\",                // one of: Class, Interface, Enum, Struct\n" +
            "      \"language\": \"C#\",                // the source language\n" +
            "      \"comment\": \"What this type is for.\",   // the type's doc-comment, plain text, markers stripped\n" +
            "      \"fields\":  [\"- id : Guid\", \"- total : decimal\"],   // UML attribute signatures\n" +
            "      \"fieldComments\": [\"The identity.\", \"\"],            // doc-comment per field, same order\n" +
            "      \"methods\": [\"+ submit() : void\", \"+ amountDue() : decimal\"], // UML operation signatures\n" +
            "      \"methodComments\": [\"Submit the order.\", \"\"],       // doc-comment per method, same order\n" +
            "      \"extends\": [\"BaseType\"],         // base class / parent type names\n" +
            "      \"implements\": [\"IPayable\"],      // interface names this type realizes\n" +
            "      \"uses\": [\"Customer\"]             // other type names this type depends on\n" +
            "    }\n" +
            "  ]\n" +
            "}\n" +
            "Rules: fields and methods are UML signature strings using visibility prefixes " +
            "(+ public, - private, # protected, ~ package) with the type after ':', e.g. \"- name : string\", " +
            "\"+ foo(a : int) : bool\". For enums, list each member as a field with no type, e.g. \"+ Pending\". " +
            "extends/implements/uses are bare type-name strings. Use empty arrays ([]) when a category is absent. " +
            "Extract doc-comments: put the type's documentation (XML doc, Javadoc, docstring, # comment, @doc/@moduledoc) " +
            "into \"comment\" as plain text with the comment markers removed; put each member's doc-comment into " +
            "\"fieldComments\"/\"methodComments\" in the SAME order and SAME length as \"fields\"/\"methods\" (use \"\" for " +
            "members with no comment). Do not invent types or comments that are not present in the source.";

        /// <summary>User role: the pasted source plus an optional language hint, framing it for analysis.</summary>
        public static string BuildUserPrompt(string code, string languageHint)
        {
            var sb = new StringBuilder();
            if (!string.IsNullOrWhiteSpace(languageHint))
                sb.Append("Language hint: ").Append(languageHint.Trim()).Append('\n');
            sb.Append("Analyze the following source and return the JSON model described above.\n\n");
            sb.Append("SOURCE:\n");
            sb.Append(code ?? "");
            return sb.ToString();
        }

        // --- parsing ---

        /// <summary>
        /// Parse the assistant's reply into a <see cref="ParsedModel"/>. Tolerates a stray markdown fence and any
        /// leading/trailing prose around the JSON object. On failure (no JSON, bad shape, no types) returns false
        /// and sets <paramref name="error"/>.
        /// </summary>
        public static bool TryParse(string content, out ParsedModel model, out string error)
        {
            model = null;
            error = null;
            if (string.IsNullOrWhiteSpace(content))
            {
                error = "empty response";
                return false;
            }

            string json = ExtractJsonObject(StripFences(content));
            if (string.IsNullOrWhiteSpace(json))
            {
                error = "no JSON object in response";
                return false;
            }

            try
            {
                var parsed = JsonUtility.FromJson<ParsedModel>(json);
                if (parsed == null || parsed.types == null)
                {
                    error = "JSON missing a \"types\" array";
                    return false;
                }
                if (parsed.types.Length == 0)
                {
                    error = "no types found in the source";
                    return false;
                }
                model = parsed;
                return true;
            }
            catch (Exception e)
            {
                error = "parse error: " + e.Message;
                return false;
            }
        }

        /// <summary>Strip a leading/trailing markdown code fence (```lang … ```) if the model added one anyway.</summary>
        private static string StripFences(string text)
        {
            if (string.IsNullOrEmpty(text)) return text;
            string s = text.Trim();
            if (!s.StartsWith("```")) return s;

            int firstNl = s.IndexOf('\n');
            if (firstNl < 0) return s;
            s = s.Substring(firstNl + 1); // drop the opening ```lang line

            int lastFence = s.LastIndexOf("```");
            if (lastFence >= 0) s = s.Substring(0, lastFence);
            return s.Trim();
        }

        /// <summary>Slice out the first balanced top-level <c>{ … }</c> so leading/trailing prose can't break parsing.</summary>
        private static string ExtractJsonObject(string s)
        {
            if (string.IsNullOrEmpty(s)) return s;
            int start = s.IndexOf('{');
            if (start < 0) return null;

            int depth = 0;
            bool inString = false, escaped = false;
            for (int i = start; i < s.Length; i++)
            {
                char c = s[i];
                if (inString)
                {
                    if (escaped) escaped = false;
                    else if (c == '\\') escaped = true;
                    else if (c == '"') inString = false;
                    continue;
                }
                if (c == '"') inString = true;
                else if (c == '{') depth++;
                else if (c == '}')
                {
                    depth--;
                    if (depth == 0) return s.Substring(start, i - start + 1);
                }
            }
            return null; // unbalanced — let the caller report a parse failure
        }
    }
}

using System.Collections.Generic;
using System.Text;
using TheRobotDraft.Authoring.Model;

namespace TheRobotDraft.CodeGen
{
    /// <summary>
    /// A deterministic, offline source skeleton for a <see cref="CodeGenContext"/>. It parses the model's UML
    /// member signatures (Rose/Sparx form, e.g. "- id : Guid", "+ submit(amount : decimal) : void") into the
    /// target language's declaration grammar, emits the type declaration with its extends/implements list (from
    /// Generalization / Realization relationships), and renders the description + attached notes as a doc-comment
    /// header. This is both the no-LLM fallback and the seed shown in the viewer while the LLM runs. Supported
    /// languages: C#, Java, TypeScript, Python; anything else falls back to C#.
    /// </summary>
    public static class CodeSkeleton
    {
        private enum Lang { CSharp, Java, TypeScript, Python, Elixir }

        public static string Generate(CodeGenContext ctx)
        {
            Lang lang = Detect(ctx.Language);
            return lang switch
            {
                Lang.Java => GenerateJava(ctx),
                Lang.TypeScript => GenerateTypeScript(ctx),
                Lang.Python => GeneratePython(ctx),
                Lang.Elixir => GenerateElixir(ctx),
                _ => GenerateCSharp(ctx),
            };
        }

        private static Lang Detect(string language)
        {
            if (string.IsNullOrWhiteSpace(language)) return Lang.CSharp;
            string l = language.Trim().ToLowerInvariant();
            if (l.Contains("elixir") || l == "ex" || l == "exs" || l.Contains("erlang")) return Lang.Elixir;
            if (l.Contains("java") && !l.Contains("javascript")) return Lang.Java;
            if (l.Contains("typescript") || l == "ts" || l.Contains("node") || l.Contains("javascript") || l == "js")
                return Lang.TypeScript;
            if (l.Contains("python") || l == "py") return Lang.Python;
            return Lang.CSharp; // C#, C/C++, Rust, Go, … → closest C-family skeleton
        }

        // --- parsed member signature ---

        /// <summary>A UML member signature decomposed into the parts a code skeleton needs.</summary>
        private struct Member
        {
            public string Visibility;  // "+", "-", "#", "~" or ""
            public string Name;
            public string Type;        // field type, or operation return type; may be empty
            public string Parameters;  // operation parameter list (inside the parens), raw UML; empty for fields
            public bool IsOperation;
        }

        /// <summary>
        /// Parse "± name : Type" (field) or "± name(args) : ReturnType" (operation). Tolerant: missing pieces just
        /// come back empty so the skeleton can apply language defaults.
        /// </summary>
        private static Member ParseMember(string raw, bool isOperation)
        {
            var m = new Member { IsOperation = isOperation };
            string s = (raw ?? "").Trim();
            if (s.Length > 0 && (s[0] == '+' || s[0] == '-' || s[0] == '#' || s[0] == '~'))
            {
                m.Visibility = s[0].ToString();
                s = s.Substring(1).Trim();
            }

            // Split off the return / field type after the last top-level ':'.
            int colon = s.LastIndexOf(':');
            if (colon >= 0)
            {
                m.Type = s.Substring(colon + 1).Trim();
                s = s.Substring(0, colon).Trim();
            }

            int open = s.IndexOf('(');
            if (open >= 0)
            {
                m.IsOperation = true;
                int close = s.LastIndexOf(')');
                if (close > open) m.Parameters = s.Substring(open + 1, close - open - 1).Trim();
                m.Name = s.Substring(0, open).Trim();
            }
            else
            {
                m.Name = s;
            }
            return m;
        }

        private static List<Member> Parse(IEnumerable<string> sigs, bool isOperation)
        {
            var list = new List<Member>();
            foreach (var s in sigs) list.Add(ParseMember(s, isOperation));
            return list;
        }

        // --- supertype / interface lists from relationships ---

        private static void CollectBases(CodeGenContext ctx, out List<string> extends, out List<string> implements)
        {
            extends = new List<string>();
            implements = new List<string>();
            foreach (var r in ctx.Relationships)
            {
                if (r.Kind == CodeGenContext.RelKind.Extends && !string.IsNullOrEmpty(r.OtherName))
                    extends.Add(r.OtherName);
                else if (r.Kind == CodeGenContext.RelKind.Implements && !string.IsNullOrEmpty(r.OtherName))
                    implements.Add(r.OtherName);
            }
        }

        private static string Sanitize(string name) => string.IsNullOrWhiteSpace(name) ? "Generated" : name.Trim();

        // --- visibility mapping ---

        private static string CSharpVis(string v) => v switch
        {
            "-" => "private", "#" => "protected", "~" => "internal", _ => "public",
        };

        private static string JavaVis(string v) => v switch
        {
            "-" => "private", "#" => "protected", "~" => "", _ => "public",
        };

        // --- C# ---

        private static string GenerateCSharp(CodeGenContext ctx)
        {
            var sb = new StringBuilder();
            DocComment(sb, ctx, "/// ", "/// ", "/// ");
            CollectBases(ctx, out var extends, out var implements);

            string name = Sanitize(ctx.Name);
            string keyword = ctx.Kind switch
            {
                ElementKind.Interface => "interface",
                ElementKind.Enum => "enum",
                ElementKind.Struct => "struct",
                _ => "class",
            };

            sb.Append("public ");
            if (ctx.IsAbstract && keyword == "class") sb.Append("abstract ");
            sb.Append(keyword).Append(' ').Append(name);

            var bases = new List<string>(extends);
            bases.AddRange(implements);
            if (bases.Count > 0) sb.Append(" : ").Append(string.Join(", ", bases));
            sb.Append('\n').Append("{\n");

            if (ctx.Kind == ElementKind.Enum)
            {
                foreach (var f in ctx.Attributes)
                {
                    var m = ParseMember(f, false);
                    sb.Append("    ").Append(string.IsNullOrEmpty(m.Name) ? f.Trim() : m.Name).Append(",\n");
                }
            }
            else
            {
                var attrs = Parse(ctx.Attributes, false);
                for (int i = 0; i < attrs.Count; i++)
                {
                    var m = attrs[i];
                    string type = string.IsNullOrEmpty(m.Type) ? "object" : m.Type;
                    MemberDoc(sb, ctx.AttributeComment(i), "    /// ");
                    sb.Append("    ").Append(CSharpVis(m.Visibility)).Append(' ')
                      .Append(type).Append(' ').Append(m.Name).Append(" { get; set; }\n");
                }
                if (ctx.Attributes.Count > 0 && ctx.Operations.Count > 0) sb.Append('\n');
                var ops = Parse(ctx.Operations, true);
                for (int i = 0; i < ops.Count; i++)
                {
                    var m = ops[i];
                    string ret = string.IsNullOrEmpty(m.Type) ? "void" : m.Type;
                    MemberDoc(sb, ctx.OperationComment(i), "    /// ");
                    sb.Append("    ").Append(CSharpVis(m.Visibility)).Append(' ');
                    if (ctx.Kind == ElementKind.Interface)
                    {
                        sb.Append(ret).Append(' ').Append(m.Name).Append('(').Append(m.Parameters).Append(");\n");
                    }
                    else
                    {
                        if (ctx.IsAbstract) sb.Append("abstract ").Append(ret).Append(' ')
                            .Append(m.Name).Append('(').Append(m.Parameters).Append(");\n");
                        else
                        {
                            sb.Append(ret).Append(' ').Append(m.Name).Append('(').Append(m.Parameters).Append(")\n");
                            sb.Append("    {\n        // TODO: implement\n");
                            if (ret != "void") sb.Append("        throw new System.NotImplementedException();\n");
                            sb.Append("    }\n");
                        }
                    }
                }
            }

            sb.Append("}\n");
            return sb.ToString();
        }

        // --- Java ---

        private static string GenerateJava(CodeGenContext ctx)
        {
            var sb = new StringBuilder();
            DocComment(sb, ctx, "/**\n", " * ", " */");
            CollectBases(ctx, out var extends, out var implements);

            string name = Sanitize(ctx.Name);
            string keyword = ctx.Kind switch
            {
                ElementKind.Interface => "interface",
                ElementKind.Enum => "enum",
                _ => "class",
            };

            sb.Append("public ");
            if (ctx.IsAbstract && keyword == "class") sb.Append("abstract ");
            sb.Append(keyword).Append(' ').Append(name);
            if (extends.Count > 0) sb.Append(" extends ").Append(string.Join(", ", extends));
            if (implements.Count > 0) sb.Append(" implements ").Append(string.Join(", ", implements));
            sb.Append(" {\n");

            if (ctx.Kind == ElementKind.Enum)
            {
                var names = new List<string>();
                foreach (var f in ctx.Attributes)
                {
                    var m = ParseMember(f, false);
                    names.Add(string.IsNullOrEmpty(m.Name) ? f.Trim() : m.Name);
                }
                sb.Append("    ").Append(string.Join(", ", names)).Append(";\n");
            }
            else
            {
                var attrs = Parse(ctx.Attributes, false);
                for (int i = 0; i < attrs.Count; i++)
                {
                    var m = attrs[i];
                    string vis = JavaVis(m.Visibility);
                    string type = string.IsNullOrEmpty(m.Type) ? "Object" : m.Type;
                    MemberDoc(sb, ctx.AttributeComment(i), "    // ");
                    sb.Append("    ");
                    if (!string.IsNullOrEmpty(vis)) sb.Append(vis).Append(' ');
                    sb.Append(type).Append(' ').Append(m.Name).Append(";\n");
                }
                if (ctx.Attributes.Count > 0 && ctx.Operations.Count > 0) sb.Append('\n');
                var ops = Parse(ctx.Operations, true);
                for (int i = 0; i < ops.Count; i++)
                {
                    var m = ops[i];
                    string ret = string.IsNullOrEmpty(m.Type) ? "void" : m.Type;
                    string vis = JavaVis(m.Visibility);
                    MemberDoc(sb, ctx.OperationComment(i), "    // ");
                    sb.Append("    ");
                    if (!string.IsNullOrEmpty(vis)) sb.Append(vis).Append(' ');
                    if (ctx.Kind == ElementKind.Interface)
                    {
                        sb.Append(ret).Append(' ').Append(m.Name).Append('(').Append(m.Parameters).Append(");\n");
                    }
                    else
                    {
                        sb.Append(ret).Append(' ').Append(m.Name).Append('(').Append(m.Parameters).Append(") {\n");
                        sb.Append("        // TODO: implement\n");
                        if (ret != "void") sb.Append("        throw new UnsupportedOperationException();\n");
                        sb.Append("    }\n");
                    }
                }
            }

            sb.Append("}\n");
            return sb.ToString();
        }

        // --- TypeScript ---

        private static string GenerateTypeScript(CodeGenContext ctx)
        {
            var sb = new StringBuilder();
            DocComment(sb, ctx, "/**\n", " * ", " */");
            CollectBases(ctx, out var extends, out var implements);

            string name = Sanitize(ctx.Name);

            if (ctx.Kind == ElementKind.Enum)
            {
                sb.Append("export enum ").Append(name).Append(" {\n");
                foreach (var f in ctx.Attributes)
                {
                    var m = ParseMember(f, false);
                    sb.Append("    ").Append(string.IsNullOrEmpty(m.Name) ? f.Trim() : m.Name).Append(",\n");
                }
                sb.Append("}\n");
                return sb.ToString();
            }

            bool isInterface = ctx.Kind == ElementKind.Interface;
            sb.Append("export ");
            if (ctx.IsAbstract && !isInterface) sb.Append("abstract ");
            sb.Append(isInterface ? "interface " : "class ").Append(name);
            if (extends.Count > 0) sb.Append(" extends ").Append(string.Join(", ", extends));
            if (implements.Count > 0) sb.Append(" implements ").Append(string.Join(", ", implements));
            sb.Append(" {\n");

            var tsAttrs = Parse(ctx.Attributes, false);
            for (int i = 0; i < tsAttrs.Count; i++)
            {
                var m = tsAttrs[i];
                string type = string.IsNullOrEmpty(m.Type) ? "unknown" : m.Type;
                MemberDoc(sb, ctx.AttributeComment(i), "    // ");
                sb.Append("    ");
                if (!isInterface && m.Visibility == "-") sb.Append("private ");
                else if (!isInterface && m.Visibility == "#") sb.Append("protected ");
                sb.Append(m.Name).Append(": ").Append(type).Append(";\n");
            }
            if (ctx.Attributes.Count > 0 && ctx.Operations.Count > 0) sb.Append('\n');
            var tsOps = Parse(ctx.Operations, true);
            for (int i = 0; i < tsOps.Count; i++)
            {
                var m = tsOps[i];
                string ret = string.IsNullOrEmpty(m.Type) ? "void" : m.Type;
                MemberDoc(sb, ctx.OperationComment(i), "    // ");
                sb.Append("    ");
                if (!isInterface && m.Visibility == "-") sb.Append("private ");
                else if (!isInterface && m.Visibility == "#") sb.Append("protected ");
                if (isInterface)
                {
                    sb.Append(m.Name).Append('(').Append(m.Parameters).Append("): ").Append(ret).Append(";\n");
                }
                else
                {
                    sb.Append(m.Name).Append('(').Append(m.Parameters).Append("): ").Append(ret).Append(" {\n");
                    sb.Append("        // TODO: implement\n");
                    sb.Append("    }\n");
                }
            }

            sb.Append("}\n");
            return sb.ToString();
        }

        // --- Python ---

        private static string GeneratePython(CodeGenContext ctx)
        {
            var sb = new StringBuilder();
            CollectBases(ctx, out var extends, out var implements);

            string name = Sanitize(ctx.Name);
            var bases = new List<string>(extends);
            bases.AddRange(implements);

            sb.Append("class ").Append(name);
            if (bases.Count > 0) sb.Append('(').Append(string.Join(", ", bases)).Append(')');
            sb.Append(":\n");

            // Docstring (description + notes).
            string doc = DocstringBody(ctx);
            if (!string.IsNullOrEmpty(doc))
            {
                sb.Append("    \"\"\"\n");
                foreach (var line in doc.Split('\n')) sb.Append("    ").Append(line).Append('\n');
                sb.Append("    \"\"\"\n");
            }

            bool wroteBody = false;
            var pyAttrs = Parse(ctx.Attributes, false);
            for (int i = 0; i < pyAttrs.Count; i++)
            {
                var m = pyAttrs[i];
                string type = string.IsNullOrEmpty(m.Type) ? "object" : m.Type;
                MemberDoc(sb, ctx.AttributeComment(i), "    # ");
                sb.Append("    ").Append(m.Name).Append(": ").Append(type).Append('\n');
                wroteBody = true;
            }
            var pyOps = Parse(ctx.Operations, true);
            for (int i = 0; i < pyOps.Count; i++)
            {
                var m = pyOps[i];
                string args = string.IsNullOrEmpty(m.Parameters) ? "self" : "self, " + m.Parameters;
                sb.Append('\n');
                MemberDoc(sb, ctx.OperationComment(i), "    # ");
                sb.Append("    def ").Append(m.Name).Append('(').Append(args).Append(')');
                if (!string.IsNullOrEmpty(m.Type)) sb.Append(" -> ").Append(m.Type);
                sb.Append(":\n        # TODO: implement\n        pass\n");
                wroteBody = true;
            }
            if (!wroteBody && string.IsNullOrEmpty(doc)) sb.Append("    pass\n");

            return sb.ToString();
        }

        // --- Elixir ---

        /// <summary>
        /// Elixir is not class-based: emit a <c>defmodule</c> with a <c>@moduledoc</c> (description + notes), a
        /// <c>defstruct</c> from the attributes, and <c>def</c>/<c>defp</c> functions from the operations.
        /// Realized interfaces become <c>@behaviour</c>s; an enum kind becomes a <c>@type</c> union of atoms.
        /// </summary>
        private static string GenerateElixir(CodeGenContext ctx)
        {
            var sb = new StringBuilder();
            string name = ModuleName(ctx.Name);
            CollectBases(ctx, out var extends, out var implements);

            sb.Append("defmodule ").Append(name).Append(" do\n");
            ElixirModuleDoc(sb, ctx);

            if (ctx.Kind == ElementKind.Enum)
            {
                var atoms = new List<string>();
                foreach (var f in ctx.Attributes)
                {
                    var m = ParseMember(f, false);
                    atoms.Add(":" + SnakeCase(string.IsNullOrEmpty(m.Name) ? f : m.Name));
                }
                if (atoms.Count > 0)
                    sb.Append("  @type t :: ").Append(string.Join(" | ", atoms)).Append('\n');
                else
                    sb.Append("  @type t :: atom()\n");
                sb.Append("end\n");
                return sb.ToString();
            }

            foreach (var b in implements) sb.Append("  @behaviour ").Append(ModuleName(b)).Append('\n');
            foreach (var b in extends) sb.Append("  # extends ").Append(ModuleName(b)).Append(" (compose via use/delegation)\n");
            if (implements.Count > 0 || extends.Count > 0) sb.Append('\n');

            var attrs = Parse(ctx.Attributes, false);
            if (attrs.Count > 0)
            {
                var keys = new List<string>();
                foreach (var a in attrs) keys.Add(":" + SnakeCase(a.Name));
                sb.Append("  defstruct [").Append(string.Join(", ", keys)).Append("]\n\n");
            }

            var ops = Parse(ctx.Operations, true);
            for (int i = 0; i < ops.Count; i++)
            {
                var m = ops[i];
                string def = (m.Visibility == "-" || m.Visibility == "#") ? "defp" : "def";
                // Public functions document with @doc; private ones use a plain # comment (Elixir warns on @doc for defp).
                string comment = ctx.OperationComment(i);
                if (!string.IsNullOrWhiteSpace(comment))
                {
                    string oneLine = comment.Replace("\r\n", "\n").Replace('\n', ' ').Trim();
                    if (def == "def") sb.Append("  @doc \"").Append(oneLine.Replace("\"", "\\\"")).Append("\"\n");
                    else sb.Append("  # ").Append(oneLine).Append('\n');
                }
                sb.Append("  ").Append(def).Append(' ').Append(SnakeCase(m.Name))
                  .Append('(').Append(ElixirArgs(m.Parameters)).Append(") do\n");
                sb.Append("    # TODO: implement\n");
                sb.Append("  end\n\n");
            }
            if (attrs.Count == 0 && ops.Count == 0) sb.Append("  # TODO: implement\n");

            sb.Append("end\n");
            return sb.ToString();
        }

        private static void ElixirModuleDoc(StringBuilder sb, CodeGenContext ctx)
        {
            string body = DocstringBody(ctx);
            if (string.IsNullOrEmpty(body)) return;
            sb.Append("  @moduledoc \"\"\"\n");
            foreach (var line in body.Split('\n')) sb.Append("  ").Append(line).Append('\n');
            sb.Append("  \"\"\"\n\n");
        }

        /// <summary>PascalCase/dotted module alias from a free-form name (keeps '.' for nested modules).</summary>
        private static string ModuleName(string raw)
        {
            string n = Sanitize(raw);
            var sb = new StringBuilder();
            bool up = true;
            foreach (char c in n)
            {
                if (c == '.') { sb.Append('.'); up = true; }
                else if (char.IsLetterOrDigit(c)) { sb.Append(up ? char.ToUpperInvariant(c) : c); up = false; }
                else up = true;
            }
            string r = sb.ToString();
            return string.IsNullOrEmpty(r) ? "Generated" : r;
        }

        /// <summary>snake_case identifier (valid Elixir function name / atom) from a UML member name.</summary>
        private static string SnakeCase(string raw)
        {
            string n = (raw ?? "").Trim();
            var sb = new StringBuilder();
            foreach (char c in n)
            {
                if (char.IsUpper(c)) { if (sb.Length > 0 && sb[sb.Length - 1] != '_') sb.Append('_'); sb.Append(char.ToLowerInvariant(c)); }
                else if (char.IsLetterOrDigit(c) || c == '_') sb.Append(c);
                else if (sb.Length > 0 && sb[sb.Length - 1] != '_') sb.Append('_');
            }
            string r = sb.ToString().Trim('_');
            return string.IsNullOrEmpty(r) ? "value" : r;
        }

        /// <summary>Elixir arg list: the parameter identifiers (UML "name : Type" → "name"), snake_cased.</summary>
        private static string ElixirArgs(string parameters)
        {
            if (string.IsNullOrWhiteSpace(parameters)) return "";
            var names = new List<string>();
            foreach (var part in parameters.Split(','))
            {
                string p = part.Trim();
                if (p.Length == 0) continue;
                int colon = p.IndexOf(':');
                string nm = colon >= 0 ? p.Substring(0, colon).Trim() : p;
                names.Add(SnakeCase(nm));
            }
            return string.Join(", ", names);
        }

        // --- doc-comment helpers ---

        /// <summary>
        /// Emit a member's doc-comment immediately above its declaration, indented and prefixed for the language
        /// (e.g. "    /// " for C#, "    # " for Python). Multi-line comments fold to a single line. Emits nothing
        /// for an empty comment.
        /// </summary>
        private static void MemberDoc(StringBuilder sb, string comment, string linePrefix)
        {
            if (string.IsNullOrWhiteSpace(comment)) return;
            string oneLine = comment.Replace("\r\n", "\n").Replace('\n', ' ').Trim();
            sb.Append(linePrefix).Append(oneLine).Append('\n');
        }

        /// <summary>The plain text body (description + notes) for any doc comment, newline-joined; may be empty.</summary>
        private static string DocstringBody(CodeGenContext ctx)
        {
            var lines = new List<string>();
            if (!string.IsNullOrWhiteSpace(ctx.Description))
                foreach (var l in ctx.Description.Replace("\r\n", "\n").Split('\n')) lines.Add(l);
            foreach (var note in ctx.AttachedNotes)
            {
                lines.Add("Note:");
                foreach (var l in note.Replace("\r\n", "\n").Split('\n')) lines.Add("  " + l);
            }
            return string.Join("\n", lines);
        }

        /// <summary>
        /// Emit a doc-comment header. <paramref name="open"/> is the opening line (e.g. "/**\n" or ""), each body
        /// line is prefixed with <paramref name="linePrefix"/> ("/// " or " * "), and <paramref name="close"/> is the
        /// closing line (" */" or, for C# line comments, the same "/// " — passed but unused there). Emits nothing
        /// when there is no description and no attached notes.
        /// </summary>
        private static void DocComment(StringBuilder sb, CodeGenContext ctx, string open, string linePrefix, string close)
        {
            string body = DocstringBody(ctx);
            if (string.IsNullOrEmpty(body)) return;

            bool block = open.StartsWith("/**");
            if (block) sb.Append(open);
            foreach (var line in body.Split('\n')) sb.Append(linePrefix).Append(line).Append('\n');
            if (block) sb.Append(close).Append('\n');
        }
    }
}

using System;
using System.Collections.Generic;
using System.Text;
using System.Text.RegularExpressions;

namespace TheRobotDraft.CodeGen
{
    /// <summary>
    /// A deterministic, network-free structural parser that recovers the same <see cref="CodeParser.ParsedModel"/>
    /// shape the LLM path produces — used as the first-choice import strategy so code → model round-trips work
    /// offline (and instantly). C# is handled well via brace-matching + a doc-comment scanner; TypeScript and Java
    /// get a lighter regex pass. Anything else returns <c>false</c> so the caller can fall back to <see cref="CodeParser"/>'s
    /// LLM prompt. The parser is deliberately tolerant: it skips what it can't understand rather than throwing, and
    /// top-level type extraction is enough (nested types are best-effort, partial classes import as separate boxes).
    /// </summary>
    public static class CodeStructParser
    {
        /// <summary>
        /// Try to extract the types in <paramref name="source"/> without any LLM call. Chooses a language strategy from
        /// <paramref name="languageHint"/> (a language name or a file extension). Returns <c>true</c> with a populated
        /// <paramref name="model"/> when at least one type was found; otherwise <c>false</c> with <c>model = null</c>
        /// (unsupported language, empty source, or nothing recognizable — let the caller fall back to the LLM).
        /// </summary>
        public static bool TryParse(string source, string languageHint, out CodeParser.ParsedModel model)
        {
            model = null;
            if (string.IsNullOrWhiteSpace(source)) return false;

            string lang = NormalizeLanguage(languageHint, source);
            List<CodeParser.ParsedType> types;
            switch (lang)
            {
                case "C#":
                    types = ParseCSharp(source);
                    break;
                case "TypeScript":
                    types = ParseCurlyBraceRegex(source, "TypeScript");
                    break;
                case "Java":
                    types = ParseCurlyBraceRegex(source, "Java");
                    break;
                default:
                    return false; // unsupported — caller falls back to the LLM
            }

            if (types == null || types.Count == 0) return false;
            model = new CodeParser.ParsedModel { types = types.ToArray() };
            return true;
        }

        /// <summary>
        /// Map a language hint or extension onto a canonical language label. An explicit hint wins; otherwise we sniff
        /// a leading extension-like token. Returns "" when nothing matches (caller treats that as "fall back to LLM").
        /// </summary>
        private static string NormalizeLanguage(string hint, string source)
        {
            string h = (hint ?? "").Trim().TrimStart('.').ToLowerInvariant();
            switch (h)
            {
                case "cs":
                case "c#":
                case "csharp": return "C#";
                case "ts":
                case "tsx":
                case "typescript": return "TypeScript";
                case "java": return "Java";
            }
            // No usable hint — the only language we can reliably auto-detect for the deterministic path is C#
            // (its using/namespace/`: base` grammar is distinctive). Other languages need an explicit hint.
            if (string.IsNullOrEmpty(h) && LooksLikeCSharp(source)) return "C#";
            return "";
        }

        /// <summary>Cheap heuristic: does this source read like C#? Used only when no language hint was supplied.</summary>
        private static bool LooksLikeCSharp(string source)
        {
            return Regex.IsMatch(source, @"\busing\s+[A-Za-z_][\w.]*\s*;")
                || Regex.IsMatch(source, @"\bnamespace\s+[A-Za-z_]")
                || source.Contains("MonoBehaviour")
                || Regex.IsMatch(source, @"\b(public|internal|private|protected)\s+(sealed\s+|abstract\s+|static\s+|partial\s+)*(class|interface|enum|struct)\b");
        }

        // ===================================================================================================
        //  C# parser (the well-supported path)
        // ===================================================================================================

        // Modifiers that may precede a type/member keyword. Order-independent; matched as a run.
        private const string ModifierPattern =
            @"(?:public|internal|private|protected|abstract|sealed|static|partial|readonly|const|virtual|override|new|extern|unsafe|volatile|async|ref|required|file)\b\s*";

        // A type declaration: optional modifiers, the type keyword, the name, optional generics, optional base list.
        private static readonly Regex TypeDeclRegex = new Regex(
            @"(?<mods>(?:" + ModifierPattern + @")*)(?<keyword>class|interface|enum|struct|record)\b" +
            @"(?:\s+(?:class|struct))?" +              // `record class` / `record struct`
            @"\s+(?<name>[A-Za-z_]\w*)" +
            @"\s*(?<generics><[^=;{]*?>)?" +           // generic params (non-greedy, stops before { ; =)
            @"\s*(?:\((?<primary>[^)]*)\))?" +         // record/primary-constructor params (ignored structurally)
            @"\s*(?::\s*(?<bases>[^{;]+?))?" +         // base list up to the body/`where`
            @"\s*(?:where\b[^{;]*)?" +                 // generic constraints — skip
            @"\s*(?=[{;])",                            // followed by a body or a forward-declared `;`
            RegexOptions.Compiled | RegexOptions.Singleline);

        /// <summary>
        /// Parse C# by scanning the comment-stripped source for type declarations, then brace-matching each type's
        /// body in the ORIGINAL text (so member doc-comments survive). Top-level types are captured; nested types are
        /// reached recursively from a body, best-effort.
        /// </summary>
        private static List<CodeParser.ParsedType> ParseCSharp(string original)
        {
            var types = new List<CodeParser.ParsedType>();
            // A comment-blanked copy keeps offsets identical to the original (comments replaced by spaces/newlines),
            // so a regex match at index i in the blanked text maps to the same i in the original.
            string scan = BlankComments(original);
            ParseCSharpScope(original, scan, 0, original.Length, types);
            return types;
        }

        /// <summary>
        /// Find every top-level type declaration whose body falls within [<paramref name="start"/>, <paramref name="end"/>)
        /// of the blanked <paramref name="scan"/> text, materialize it from the original, and recurse into its body for
        /// nested types. Declarations found inside an already-consumed body are skipped (handled by the recursion).
        /// </summary>
        private static void ParseCSharpScope(string original, string scan, int start, int end,
            List<CodeParser.ParsedType> outTypes)
        {
            int cursor = start;
            foreach (Match m in TypeDeclRegex.Matches(scan))
            {
                if (m.Index < cursor) continue;        // inside a body we've already consumed
                if (m.Index >= end) break;

                int afterDecl = m.Index + m.Length;
                // Locate the body: the next '{' in the blanked text (or a ';' for a forward declaration).
                int brace = scan.IndexOf('{', afterDecl);
                int semi = scan.IndexOf(';', afterDecl);
                if (semi >= 0 && (brace < 0 || semi < brace))
                {
                    // forward declaration / no body — record the type with no members.
                    outTypes.Add(BuildType(original, scan, m, -1, -1));
                    cursor = semi + 1;
                    continue;
                }
                if (brace < 0 || brace >= end) break;

                int bodyEnd = MatchBrace(scan, brace);
                if (bodyEnd < 0) bodyEnd = end;        // unbalanced — take the rest of the scope

                var pt = BuildType(original, scan, m, brace + 1, bodyEnd);
                outTypes.Add(pt);

                // Recurse for nested types (best-effort): they share the same out list as separate boxes.
                ParseCSharpScope(original, scan, brace + 1, bodyEnd, outTypes);

                cursor = bodyEnd + 1;
            }
        }

        /// <summary>
        /// Build one <see cref="CodeParser.ParsedType"/> from a matched declaration and (when present) its body span
        /// [<paramref name="bodyStart"/>, <paramref name="bodyEnd"/>) in the comment-blanked <paramref name="scan"/>.
        /// Members are walked from the body; the preceding doc-comment is pulled from the original text.
        /// </summary>
        private static CodeParser.ParsedType BuildType(string original, string scan, Match decl,
            int bodyStart, int bodyEnd)
        {
            string keyword = decl.Groups["keyword"].Value;
            string name = decl.Groups["name"].Value;
            bool isInterface = keyword == "interface";
            bool isEnum = keyword == "enum";
            bool isStruct = keyword == "struct";
            // `record` is a reference type → treat as Class; `record struct` already matched the struct keyword above.

            var pt = new CodeParser.ParsedType
            {
                name = name,
                kind = isInterface ? "Interface" : isEnum ? "Enum" : isStruct ? "Struct" : "Class",
                language = "C#",
                comment = DocCommentBefore(original, decl.Index),
                fields = Array.Empty<string>(),
                fieldComments = Array.Empty<string>(),
                methods = Array.Empty<string>(),
                methodComments = Array.Empty<string>(),
                extends = Array.Empty<string>(),
                implements = Array.Empty<string>(),
                uses = Array.Empty<string>(),
            };

            // Base list: class → first entry to extends, rest implements (heuristic; interfaces start uppercase 'I'…
            // but we don't rely on naming). For interface/struct, all bases → implements.
            var bases = SplitBases(decl.Groups["bases"].Value);
            if (bases.Count > 0)
            {
                if (!isInterface && !isStruct && !isEnum)
                {
                    // Class: conventionally the (optional) base class is first. We can't always tell a base class from
                    // an interface, so put the first into extends and the remainder into implements — approximate by design.
                    pt.extends = new[] { bases[0] };
                    if (bases.Count > 1) pt.implements = bases.GetRange(1, bases.Count - 1).ToArray();
                }
                else
                {
                    pt.implements = bases.ToArray();
                }
            }

            if (bodyStart < 0 || bodyEnd <= bodyStart) return pt; // forward decl / empty

            if (isEnum)
                ParseEnumMembers(original, bodyStart, bodyEnd, pt);
            else
                ParseTypeMembers(original, scan, bodyStart, bodyEnd, pt);

            return pt;
        }

        /// <summary>Split a comma-separated base list into bare type names, stripping generics and namespaces.</summary>
        private static List<string> SplitBases(string baseList)
        {
            var result = new List<string>();
            if (string.IsNullOrWhiteSpace(baseList)) return result;

            // Split on commas that are not inside generic angle brackets.
            int depth = 0, last = 0;
            for (int i = 0; i < baseList.Length; i++)
            {
                char c = baseList[i];
                if (c == '<') depth++;
                else if (c == '>') { if (depth > 0) depth--; }
                else if (c == ',' && depth == 0)
                {
                    AddBase(result, baseList.Substring(last, i - last));
                    last = i + 1;
                }
            }
            AddBase(result, baseList.Substring(last));
            return result;
        }

        private static void AddBase(List<string> list, string raw)
        {
            string name = CleanTypeName(raw);
            if (!string.IsNullOrEmpty(name)) list.Add(name);
        }

        /// <summary>Reduce a type expression to a bare, readable name: drop namespace qualifier, keep generic suffix.</summary>
        private static string CleanTypeName(string raw)
        {
            if (string.IsNullOrWhiteSpace(raw)) return "";
            string s = raw.Trim();
            // Keep generics on the simple name: strip a leading namespace from the base name only.
            int angle = s.IndexOf('<');
            string head = angle >= 0 ? s.Substring(0, angle) : s;
            string tail = angle >= 0 ? s.Substring(angle) : "";
            int dot = head.LastIndexOf('.');
            if (dot >= 0) head = head.Substring(dot + 1);
            return (head + tail).Trim();
        }

        /// <summary>Enum body: each comma-separated member name becomes a "+ Member" field signature with its doc-comment.</summary>
        private static void ParseEnumMembers(string original, int bodyStart, int bodyEnd, CodeParser.ParsedType pt)
        {
            var fields = new List<string>();
            var comments = new List<string>();

            int i = bodyStart;
            while (i < bodyEnd)
            {
                // Skip whitespace/commas to the next member token, capturing any doc-comment we pass.
                while (i < bodyEnd && (char.IsWhiteSpace(original[i]) || original[i] == ',')) i++;
                if (i >= bodyEnd) break;

                // An attribute like [Flags] on a member — skip the bracketed run.
                if (original[i] == '[') { i = SkipBalanced(original, i, '[', ']', bodyEnd); continue; }

                int memberStart = i;
                // A member runs until ',' or '=' (explicit value) or end of body.
                while (i < bodyEnd && original[i] != ',' && original[i] != '=' && original[i] != '}') i++;
                string token = original.Substring(memberStart, i - memberStart).Trim();
                if (i < bodyEnd && original[i] == '=')
                {
                    // skip the assigned value up to the next comma
                    while (i < bodyEnd && original[i] != ',' && original[i] != '}') i++;
                }
                var nameMatch = Regex.Match(token, @"[A-Za-z_]\w*");
                if (nameMatch.Success)
                {
                    fields.Add("+ " + nameMatch.Value);
                    comments.Add(DocCommentBefore(original, memberStart));
                }
            }

            pt.fields = fields.ToArray();
            pt.fieldComments = comments.ToArray();
        }

        /// <summary>
        /// Walk a class/interface/struct body, splitting it into top-level member declarations by brace/paren/semicolon,
        /// and classify each as a method (has a parameter list) or a field/property. Captures each member's preceding
        /// doc-comment into the parallel comment arrays. Nested types are skipped here (handled by the scope recursion).
        /// </summary>
        private static void ParseTypeMembers(string original, string scan, int bodyStart, int bodyEnd,
            CodeParser.ParsedType pt)
        {
            var fields = new List<string>();
            var fieldComments = new List<string>();
            var methods = new List<string>();
            var methodComments = new List<string>();

            int i = bodyStart;
            int memberStart = SkipLeading(scan, bodyStart, bodyEnd);
            while (i < bodyEnd)
            {
                char c = scan[i];
                if (c == '{')
                {
                    // A block: a method/property body or a nested type's body. Either way, the member ends after it.
                    int close = MatchBrace(scan, i);
                    if (close < 0 || close >= bodyEnd) close = bodyEnd - 1;
                    string decl = original.Substring(memberStart, i - memberStart);
                    ClassifyMember(original, scan, decl, memberStart, true,
                        fields, fieldComments, methods, methodComments);
                    i = close + 1;
                    // skip a trailing ; after a property/auto block
                    while (i < bodyEnd && (char.IsWhiteSpace(scan[i]) || scan[i] == ';')) i++;
                    memberStart = i;
                    continue;
                }
                if (c == ';')
                {
                    string decl = original.Substring(memberStart, i - memberStart);
                    ClassifyMember(original, scan, decl, memberStart, false,
                        fields, fieldComments, methods, methodComments);
                    i++;
                    memberStart = SkipLeading(scan, i, bodyEnd);
                    i = memberStart;
                    continue;
                }
                if (c == '(')
                {
                    // A parameter list: this member is a method/ctor. Consume to the matching ')', then to its body or ';'.
                    int closeParen = SkipBalanced(scan, i, '(', ')', bodyEnd);
                    // Find whether a body or a ';' follows (interface methods + expression-bodied/abstract use ';').
                    int j = closeParen;
                    // skip return-type-less arrow body `=> expr;` or `{ }`
                    int nextBrace = scan.IndexOf('{', j);
                    int nextSemi = scan.IndexOf(';', j);
                    int memberEnd;
                    bool hadBlock = false;
                    if (nextBrace >= bodyStart && nextBrace < bodyEnd && (nextSemi < 0 || nextBrace < nextSemi))
                    {
                        int close = MatchBrace(scan, nextBrace);
                        memberEnd = (close < 0 || close >= bodyEnd) ? bodyEnd - 1 : close;
                        hadBlock = true;
                    }
                    else if (nextSemi >= 0 && nextSemi < bodyEnd)
                    {
                        memberEnd = nextSemi;
                    }
                    else
                    {
                        memberEnd = bodyEnd - 1;
                    }
                    string decl = original.Substring(memberStart, memberEnd - memberStart + (hadBlock ? 0 : 0));
                    // For methods we want the signature only (up to and including the param list).
                    string sigSource = original.Substring(memberStart, closeParen - memberStart);
                    ClassifyMethod(original, sigSource, memberStart, methods, methodComments);
                    i = memberEnd + 1;
                    while (i < bodyEnd && (char.IsWhiteSpace(scan[i]) || scan[i] == ';')) i++;
                    memberStart = i;
                    continue;
                }
                i++;
            }

            pt.fields = fields.ToArray();
            pt.fieldComments = fieldComments.ToArray();
            pt.methods = methods.ToArray();
            pt.methodComments = methodComments.ToArray();
        }

        /// <summary>
        /// Classify a non-method member declaration (field, auto-property, or const) into a "± name : Type" signature.
        /// <paramref name="hadBlock"/> marks a property with an accessor block. Nested type declarations are ignored.
        /// </summary>
        private static void ClassifyMember(string original, string scan, string decl, int memberStart, bool hadBlock,
            List<string> fields, List<string> fieldComments,
            List<string> methods, List<string> methodComments)
        {
            string trimmed = StripAttributes(decl).Trim();
            if (trimmed.Length == 0) return;

            // Skip nested type declarations — the scope recursion handles those as their own boxes.
            if (Regex.IsMatch(trimmed, @"\b(class|interface|enum|struct|record)\b\s+[A-Za-z_]\w*"))
                return;
            // Skip property accessor noise that can leak through (get/set/init keywords on their own).
            if (Regex.IsMatch(trimmed, @"^\s*(get|set|init|add|remove)\b")) return;

            string vis = VisibilityPrefix(trimmed);
            string body = StripModifiers(trimmed);
            if (body.Length == 0) return;

            // Drop an initializer (= …) when present.
            int eq = IndexOfTopLevel(body, '=');
            if (eq >= 0) body = body.Substring(0, eq).Trim();

            // Expect "Type name" (optionally "Type name1, name2" for multi-field declarations).
            string sig = FieldSignature(vis, body);
            if (sig == null) return;
            fields.Add(sig);
            fieldComments.Add(DocCommentBefore(original, memberStart));
        }

        /// <summary>Turn a "Type name" (or "name : Type") fragment into a UML "± name : Type" attribute signature.</summary>
        private static string FieldSignature(string vis, string body)
        {
            // Already UML-ish ("name : Type")? keep the name + type.
            var uml = Regex.Match(body, @"^([A-Za-z_]\w*)\s*:\s*(.+)$");
            if (uml.Success)
                return vis + " " + uml.Groups[1].Value + " : " + CleanTypeName(uml.Groups[2].Value);

            // C# "Type name" — type may be generic / array / nullable; the name is the last identifier token.
            var m = Regex.Match(body, @"^(?<type>.+?)\s+(?<name>[A-Za-z_]\w*)$", RegexOptions.Singleline);
            if (!m.Success)
            {
                // A bare identifier (e.g. enum-ish leak) — emit as a typeless attribute.
                var bare = Regex.Match(body, @"^[A-Za-z_]\w*$");
                return bare.Success ? vis + " " + body : null;
            }
            string type = CleanTypeName(m.Groups["type"].Value);
            string name = m.Groups["name"].Value;
            // Reject keywords masquerading as names (e.g. "return").
            if (IsKeyword(name)) return null;
            return vis + " " + name + " : " + type;
        }

        /// <summary>Classify a member with a parameter list into a UML "± name(params) : ReturnType" operation signature.</summary>
        private static void ClassifyMethod(string original, string sigSource, int memberStart,
            List<string> methods, List<string> methodComments)
        {
            string s = StripAttributes(sigSource).Trim();
            if (s.Length == 0) return;

            int paren = s.IndexOf('(');
            if (paren < 0) return;
            string head = s.Substring(0, paren).Trim();   // modifiers + return type + name (+ generics)
            string paramList = s.Substring(paren + 1).Trim().TrimEnd(')');

            string vis = VisibilityPrefix(head);
            head = StripModifiers(head);

            // head is now "ReturnType Name" or just "Name" (constructor / operator). Name = last identifier (pre-generics).
            // Strip generic params on the method name.
            head = Regex.Replace(head, @"<[^>]*>", "").Trim();
            var hm = Regex.Match(head, @"^(?:(?<ret>.+?)\s+)?(?<name>[A-Za-z_]\w*)$", RegexOptions.Singleline);
            if (!hm.Success) return;
            string name = hm.Groups["name"].Value;
            if (IsKeyword(name)) return;
            string ret = hm.Groups["ret"].Success ? CleanTypeName(hm.Groups["ret"].Value) : "";

            string umlParams = SummarizeParams(paramList);
            string sig = vis + " " + name + "(" + umlParams + ")";
            if (!string.IsNullOrEmpty(ret)) sig += " : " + ret;

            methods.Add(sig);
            methodComments.Add(DocCommentBefore(original, memberStart));
        }

        /// <summary>Render a C# parameter list as UML "name : Type, …", dropping default values, modifiers, and attributes.</summary>
        private static string SummarizeParams(string paramList)
        {
            if (string.IsNullOrWhiteSpace(paramList)) return "";
            var outParams = new List<string>();
            foreach (var raw in SplitTopLevel(paramList, ','))
            {
                string p = StripAttributes(raw).Trim();
                if (p.Length == 0) continue;
                // Drop a default value.
                int eq = IndexOfTopLevel(p, '=');
                if (eq >= 0) p = p.Substring(0, eq).Trim();
                // Drop parameter modifiers.
                p = Regex.Replace(p, @"^\s*(?:this\s+|ref\s+|out\s+|in\s+|params\s+|readonly\s+|scoped\s+)+", "");
                var m = Regex.Match(p, @"^(?<type>.+?)\s+(?<name>[A-Za-z_]\w*)$", RegexOptions.Singleline);
                if (m.Success)
                    outParams.Add(m.Groups["name"].Value + " : " + CleanTypeName(m.Groups["type"].Value));
                else
                    outParams.Add(CleanTypeName(p)); // couldn't split — keep the type alone
            }
            return string.Join(", ", outParams);
        }

        // ---- C# lexical helpers ----

        private static readonly Regex VisRegex =
            new Regex(@"\b(public|private|protected|internal)\b", RegexOptions.Compiled);

        /// <summary>Map the leading visibility keyword(s) to a UML prefix. Default is "-" (C# member default is private).</summary>
        private static string VisibilityPrefix(string decl)
        {
            var m = VisRegex.Match(decl);
            if (!m.Success) return "-";
            // protected internal / private protected → use the broader/most-visible mark; keep it simple:
            switch (m.Value)
            {
                case "public": return "+";
                case "protected": return "#";
                case "internal": return "~";
                default: return "-";
            }
        }

        private static readonly Regex ModifiersLeadRegex = new Regex(
            @"^\s*(?:" + ModifierPattern + @")*", RegexOptions.Compiled);

        /// <summary>Strip leading C# modifiers (and any attribute runs) from a declaration fragment.</summary>
        private static string StripModifiers(string decl)
        {
            return ModifiersLeadRegex.Replace(StripAttributes(decl), "").Trim();
        }

        /// <summary>Remove leading [Attribute]… runs from a declaration fragment.</summary>
        private static string StripAttributes(string decl)
        {
            if (string.IsNullOrEmpty(decl)) return decl ?? "";
            string s = decl;
            // Repeatedly strip a leading [..] (balanced) run, with whitespace around it.
            while (true)
            {
                string t = s.TrimStart();
                if (t.Length == 0 || t[0] != '[') break;
                int close = SkipBalanced(t, 0, '[', ']', t.Length);
                if (close <= 0 || close >= t.Length) { s = ""; break; }
                s = t.Substring(close);
            }
            return s.Trim();
        }

        private static readonly HashSet<string> Keywords = new HashSet<string>(StringComparer.Ordinal)
        {
            "return", "if", "else", "for", "foreach", "while", "do", "switch", "case", "break", "continue",
            "throw", "try", "catch", "finally", "using", "lock", "yield", "get", "set", "init", "add", "remove",
            "namespace", "var", "new", "base", "this", "true", "false", "null",
        };

        private static bool IsKeyword(string name) => Keywords.Contains(name);

        // ===================================================================================================
        //  TypeScript / Java (light regex pass — bonus, not the primary path)
        // ===================================================================================================

        /// <summary>
        /// A deliberately light pass for curly-brace languages: find type declarations and capture each one's body, but
        /// extract only a coarse member list (TS supports many member forms; we keep it simple and tolerant). Good enough
        /// to give the user real boxes offline; the LLM remains the high-fidelity path for these.
        /// </summary>
        private static List<CodeParser.ParsedType> ParseCurlyBraceRegex(string original, string language)
        {
            var types = new List<CodeParser.ParsedType>();
            string scan = BlankComments(original);

            var declRe = new Regex(
                @"\b(?<keyword>class|interface|enum)\b\s+(?<name>[A-Za-z_]\w*)" +
                @"(?:\s*<[^>{]*>)?" +
                @"(?<bases>(?:\s+(?:extends|implements)\s+[^\{]+?)?)" +
                @"\s*\{",
                RegexOptions.Singleline);

            foreach (Match m in declRe.Matches(scan))
            {
                int brace = scan.IndexOf('{', m.Index + m.Length - 1);
                if (brace < 0) continue;
                int bodyEnd = MatchBrace(scan, brace);
                if (bodyEnd < 0) continue;

                string keyword = m.Groups["keyword"].Value;
                var pt = new CodeParser.ParsedType
                {
                    name = m.Groups["name"].Value,
                    kind = keyword == "interface" ? "Interface" : keyword == "enum" ? "Enum" : "Class",
                    language = language,
                    comment = DocCommentBefore(original, m.Index),
                    fields = Array.Empty<string>(),
                    fieldComments = Array.Empty<string>(),
                    methods = Array.Empty<string>(),
                    methodComments = Array.Empty<string>(),
                    extends = Array.Empty<string>(),
                    implements = Array.Empty<string>(),
                    uses = Array.Empty<string>(),
                };

                ParseCurlyBases(m.Groups["bases"].Value, pt);
                if (keyword == "enum")
                    ParseEnumMembers(original, brace + 1, bodyEnd, pt);
                else
                    ParseCurlyMembers(original, scan, brace + 1, bodyEnd, pt);

                types.Add(pt);
            }
            return types;
        }

        /// <summary>Parse `extends A` / `implements B, C` clauses for TS/Java into the parsed type's edges.</summary>
        private static void ParseCurlyBases(string clause, CodeParser.ParsedType pt)
        {
            if (string.IsNullOrWhiteSpace(clause)) return;
            var ext = Regex.Match(clause, @"extends\s+(?<list>[^{]+?)(?=\s+implements\b|$)", RegexOptions.Singleline);
            if (ext.Success) pt.extends = SplitBases(ext.Groups["list"].Value).ToArray();
            var impl = Regex.Match(clause, @"implements\s+(?<list>[^{]+)$", RegexOptions.Singleline);
            if (impl.Success) pt.implements = SplitBases(impl.Groups["list"].Value).ToArray();
        }

        /// <summary>Coarse member extraction for TS/Java bodies: methods (have `()`) vs fields, with doc-comments.</summary>
        private static void ParseCurlyMembers(string original, string scan, int bodyStart, int bodyEnd,
            CodeParser.ParsedType pt)
        {
            var fields = new List<string>();
            var fieldComments = new List<string>();
            var methods = new List<string>();
            var methodComments = new List<string>();

            int i = bodyStart, memberStart = SkipLeading(scan, bodyStart, bodyEnd);
            while (i < bodyEnd)
            {
                char c = scan[i];
                if (c == '{')
                {
                    int close = MatchBrace(scan, i);
                    if (close < 0 || close >= bodyEnd) close = bodyEnd - 1;
                    EmitCurlyMember(original, original.Substring(memberStart, i - memberStart), memberStart,
                        fields, fieldComments, methods, methodComments);
                    i = close + 1;
                    while (i < bodyEnd && (char.IsWhiteSpace(scan[i]) || scan[i] == ';')) i++;
                    memberStart = i;
                    continue;
                }
                if (c == ';')
                {
                    EmitCurlyMember(original, original.Substring(memberStart, i - memberStart), memberStart,
                        fields, fieldComments, methods, methodComments);
                    i++;
                    memberStart = SkipLeading(scan, i, bodyEnd);
                    i = memberStart;
                    continue;
                }
                i++;
            }

            pt.fields = fields.ToArray();
            pt.fieldComments = fieldComments.ToArray();
            pt.methods = methods.ToArray();
            pt.methodComments = methodComments.ToArray();
        }

        /// <summary>Emit one TS/Java member: methods get "+ name(params) : Ret"; fields get "+ name : Type" (default + visibility).</summary>
        private static void EmitCurlyMember(string original, string decl, int memberStart,
            List<string> fields, List<string> fieldComments,
            List<string> methods, List<string> methodComments)
        {
            string s = StripAttributes(decl).Trim();
            if (s.Length == 0) return;
            if (Regex.IsMatch(s, @"\b(class|interface|enum)\b\s+[A-Za-z_]\w*")) return; // nested decl
            if (Regex.IsMatch(s, @"^\s*(get|set|public|private|protected)?\s*(get|set)\b")) { /* accessor, fall through */ }

            string vis = CurlyVisibility(s);
            string bodyDecl = Regex.Replace(s, @"^\s*(public|private|protected|static|readonly|abstract|final|async|export|declare)\b\s*", "",
                RegexOptions.IgnoreCase);
            bodyDecl = Regex.Replace(bodyDecl, @"^\s*(public|private|protected|static|readonly|abstract|final|async|export|declare)\b\s*", "",
                RegexOptions.IgnoreCase).Trim();

            int paren = bodyDecl.IndexOf('(');
            if (paren >= 0 && (bodyDecl.IndexOf(':') < 0 || bodyDecl.IndexOf(':') > paren))
            {
                // method
                var nameMatch = Regex.Match(bodyDecl.Substring(0, paren), @"([A-Za-z_]\w*)\s*$");
                if (!nameMatch.Success) return;
                string name = nameMatch.Groups[1].Value;
                if (IsKeyword(name)) return;
                int closeParen = SkipBalanced(bodyDecl, paren, '(', ')', bodyDecl.Length);
                string paramList = bodyDecl.Substring(paren + 1, Math.Max(0, closeParen - paren - 2));
                string ret = "";
                var retMatch = Regex.Match(bodyDecl.Substring(Math.Min(closeParen, bodyDecl.Length)), @":\s*([A-Za-z_][\w.<>\[\]]*)");
                if (retMatch.Success) ret = CleanTypeName(retMatch.Groups[1].Value);
                string sig = vis + " " + name + "(" + SummarizeParams(NormalizeTsParams(paramList)) + ")";
                if (!string.IsNullOrEmpty(ret)) sig += " : " + ret;
                methods.Add(sig);
                methodComments.Add(DocCommentBefore(original, memberStart));
                return;
            }

            // field: "name : Type" (TS) or "Type name" (Java)
            var ts = Regex.Match(bodyDecl, @"^([A-Za-z_]\w*)\??\s*:\s*([^=;]+)");
            if (ts.Success)
            {
                fields.Add(vis + " " + ts.Groups[1].Value + " : " + CleanTypeName(ts.Groups[2].Value));
                fieldComments.Add(DocCommentBefore(original, memberStart));
                return;
            }
            var java = Regex.Match(bodyDecl, @"^(?<type>[A-Za-z_][\w.<>\[\]]*)\s+(?<name>[A-Za-z_]\w*)");
            if (java.Success && !IsKeyword(java.Groups["name"].Value))
            {
                fields.Add(vis + " " + java.Groups["name"].Value + " : " + CleanTypeName(java.Groups["type"].Value));
                fieldComments.Add(DocCommentBefore(original, memberStart));
            }
        }

        /// <summary>TS optional params (`a?: T`) → drop the `?` so the shared param summarizer can split "name : Type".</summary>
        private static string NormalizeTsParams(string paramList)
        {
            if (string.IsNullOrWhiteSpace(paramList)) return "";
            // Convert "name: Type" to "Type name" so SummarizeParams' C#-shaped regex can read it.
            var outParams = new List<string>();
            foreach (var raw in SplitTopLevel(paramList, ','))
            {
                string p = raw.Trim().Replace("?", "");
                var m = Regex.Match(p, @"^([A-Za-z_]\w*)\s*:\s*(.+)$");
                if (m.Success) outParams.Add(m.Groups[2].Value.Trim() + " " + m.Groups[1].Value);
                else outParams.Add(p);
            }
            return string.Join(", ", outParams);
        }

        private static string CurlyVisibility(string decl)
        {
            if (Regex.IsMatch(decl, @"^\s*private\b")) return "-";
            if (Regex.IsMatch(decl, @"^\s*protected\b")) return "#";
            return "+"; // TS/Java members default to public-ish visibility for a diagram
        }

        // ===================================================================================================
        //  Shared lexical utilities
        // ===================================================================================================

        /// <summary>
        /// Return a copy of <paramref name="src"/> with all comments replaced by spaces (newlines preserved), so a
        /// structural scan never trips on braces/semicolons inside comments or strings while offsets stay aligned with
        /// the original. String and char literals are also blanked (their contents can't be code), '@'/$ strings handled.
        /// </summary>
        private static string BlankComments(string src)
        {
            var sb = new StringBuilder(src.Length);
            int i = 0, n = src.Length;
            while (i < n)
            {
                char c = src[i];

                // line comment
                if (c == '/' && i + 1 < n && src[i + 1] == '/')
                {
                    while (i < n && src[i] != '\n') { sb.Append(src[i] == '\n' ? '\n' : ' '); i++; }
                    continue;
                }
                // block comment
                if (c == '/' && i + 1 < n && src[i + 1] == '*')
                {
                    while (i < n && !(src[i] == '*' && i + 1 < n && src[i + 1] == '/'))
                    { sb.Append(src[i] == '\n' ? '\n' : ' '); i++; }
                    if (i < n) { sb.Append(' '); i++; }      // '*'
                    if (i < n) { sb.Append(' '); i++; }      // '/'
                    continue;
                }
                // verbatim string @"..."
                if (c == '@' && i + 1 < n && src[i + 1] == '"')
                {
                    sb.Append(' '); sb.Append(' '); i += 2;
                    while (i < n)
                    {
                        if (src[i] == '"')
                        {
                            if (i + 1 < n && src[i + 1] == '"') { sb.Append(' '); sb.Append(' '); i += 2; continue; }
                            sb.Append(' '); i++; break;
                        }
                        sb.Append(src[i] == '\n' ? '\n' : ' '); i++;
                    }
                    continue;
                }
                // regular string "..."
                if (c == '"')
                {
                    sb.Append(' '); i++;
                    while (i < n && src[i] != '"')
                    {
                        if (src[i] == '\\' && i + 1 < n) { sb.Append(' '); sb.Append(' '); i += 2; continue; }
                        sb.Append(src[i] == '\n' ? '\n' : ' '); i++;
                    }
                    if (i < n) { sb.Append(' '); i++; }
                    continue;
                }
                // char literal '.'
                if (c == '\'')
                {
                    sb.Append(' '); i++;
                    while (i < n && src[i] != '\'')
                    {
                        if (src[i] == '\\' && i + 1 < n) { sb.Append(' '); sb.Append(' '); i += 2; continue; }
                        sb.Append(' '); i++;
                    }
                    if (i < n) { sb.Append(' '); i++; }
                    continue;
                }

                sb.Append(c);
                i++;
            }
            return sb.ToString();
        }

        /// <summary>
        /// Read the doc-comment immediately preceding <paramref name="declStart"/> in the ORIGINAL text (XML <c>///</c>
        /// run or a <c>/** … */</c> block), with markers stripped, joined to one line. Returns "" when there is none
        /// (e.g. only blank lines or code precede the declaration). Attributes/blank lines between the comment and the
        /// declaration are tolerated.
        /// </summary>
        private static string DocCommentBefore(string original, int declStart)
        {
            // Walk back over whitespace and any attribute lines to find the line before the declaration.
            int i = declStart - 1;
            // Skip back over the current line's leading whitespace.
            while (i >= 0 && original[i] != '\n') i--;
            // Now i is at the newline before the declaration line (or -1).

            var lines = new List<string>();
            int blockCount = 0; // safety cap on how far back we scan
            while (i >= 0 && blockCount++ < 200)
            {
                int lineEnd = i;               // points at '\n'
                int lineStart = i - 1;
                while (lineStart >= 0 && original[lineStart] != '\n') lineStart--;
                string line = original.Substring(lineStart + 1, lineEnd - lineStart - 1).Trim();

                if (line.Length == 0) { i = lineStart; continue; } // tolerate blank lines
                if (line.StartsWith("[") && line.EndsWith("]")) { i = lineStart; continue; } // attribute line

                if (line.StartsWith("///"))
                {
                    lines.Insert(0, StripXmlDoc(line));
                    i = lineStart;
                    continue;
                }
                if (line.EndsWith("*/"))
                {
                    // Gather a /** ... */ block backwards.
                    return ExtractBlockDocBackward(original, lineEnd);
                }
                break; // a code line — no doc-comment
            }

            return JoinDoc(lines);
        }

        /// <summary>Strip a single <c>///</c> XML-doc line down to its readable text (drops the slashes + simple tags).</summary>
        private static string StripXmlDoc(string line)
        {
            string s = line.TrimStart('/').Trim();
            s = Regex.Replace(s, @"</?summary>", "", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"<see\s+cref=""[^""]*?([A-Za-z_]\w*)""\s*/?>", "$1", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"<[^>]+>", ""); // any other tag
            return s.Trim();
        }

        /// <summary>Extract a <c>/** … */</c> block ending at <paramref name="blockEnd"/> (the '\n' after "*/"), markers stripped.</summary>
        private static string ExtractBlockDocBackward(string original, int blockEnd)
        {
            // Find the matching /** start before blockEnd.
            int end = original.LastIndexOf("*/", Math.Max(0, blockEnd), StringComparison.Ordinal);
            if (end < 0) return "";
            int start = original.LastIndexOf("/*", end, StringComparison.Ordinal);
            if (start < 0) return "";
            // Only treat /** … */ (or /* … */) as documentation if it directly precedes the decl (it does by construction).
            string inner = original.Substring(start + 2, end - start - 2);
            var parts = new List<string>();
            foreach (var rawLine in inner.Split('\n'))
            {
                string l = rawLine.Trim();
                if (l.StartsWith("*")) l = l.Substring(1).Trim();
                if (l.StartsWith("/")) l = l.Substring(1).Trim(); // leading extra '*' became '/' edge
                l = Regex.Replace(l, @"<[^>]+>", "");
                if (l.Length > 0) parts.Add(l);
            }
            return JoinDoc(parts);
        }

        private static string JoinDoc(List<string> lines)
        {
            if (lines == null || lines.Count == 0) return "";
            var nonEmpty = lines.FindAll(l => !string.IsNullOrWhiteSpace(l));
            return string.Join(" ", nonEmpty).Trim();
        }

        /// <summary>Index of the matching '}' for the '{' at <paramref name="open"/> in the blanked text, or -1.</summary>
        private static int MatchBrace(string s, int open)
        {
            int depth = 0;
            for (int i = open; i < s.Length; i++)
            {
                if (s[i] == '{') depth++;
                else if (s[i] == '}') { depth--; if (depth == 0) return i; }
            }
            return -1;
        }

        /// <summary>Index just past the matching close for the bracket at <paramref name="open"/> (one past it), or end.</summary>
        private static int SkipBalanced(string s, int open, char openCh, char closeCh, int end)
        {
            int depth = 0;
            for (int i = open; i < end && i < s.Length; i++)
            {
                if (s[i] == openCh) depth++;
                else if (s[i] == closeCh) { depth--; if (depth == 0) return i + 1; }
            }
            return end;
        }

        /// <summary>Skip leading whitespace from <paramref name="i"/> up to <paramref name="end"/>.</summary>
        private static int SkipLeading(string s, int i, int end)
        {
            while (i < end && char.IsWhiteSpace(s[i])) i++;
            return i;
        }

        /// <summary>Index of the first top-level (depth-0) occurrence of <paramref name="ch"/>, ignoring &lt;&gt;()[] nesting; -1 if none.</summary>
        private static int IndexOfTopLevel(string s, char ch)
        {
            int angle = 0, paren = 0, square = 0;
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                if (c == '<') angle++;
                else if (c == '>') { if (angle > 0) angle--; }
                else if (c == '(') paren++;
                else if (c == ')') { if (paren > 0) paren--; }
                else if (c == '[') square++;
                else if (c == ']') { if (square > 0) square--; }
                else if (c == ch && angle == 0 && paren == 0 && square == 0) return i;
            }
            return -1;
        }

        /// <summary>Split on a delimiter at top level (ignoring &lt;&gt;()[]{} nesting).</summary>
        private static List<string> SplitTopLevel(string s, char delim)
        {
            var parts = new List<string>();
            int angle = 0, paren = 0, square = 0, curly = 0, last = 0;
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                switch (c)
                {
                    case '<': angle++; break;
                    case '>': if (angle > 0) angle--; break;
                    case '(': paren++; break;
                    case ')': if (paren > 0) paren--; break;
                    case '[': square++; break;
                    case ']': if (square > 0) square--; break;
                    case '{': curly++; break;
                    case '}': if (curly > 0) curly--; break;
                    default:
                        if (c == delim && angle == 0 && paren == 0 && square == 0 && curly == 0)
                        {
                            parts.Add(s.Substring(last, i - last));
                            last = i + 1;
                        }
                        break;
                }
            }
            parts.Add(s.Substring(last));
            return parts;
        }
    }
}

using System;
using System.Text;
using UnityEngine;
using UnityEngine.Networking;

namespace TheRobotDraft.Llm
{
    /// <summary>
    /// A tiny, dependency-free client for an OpenAI-compatible <c>/chat/completions</c> endpoint. Builds the
    /// request with <see cref="JsonUtility"/> (no System.Text.Json in the player runtime) and parses the first
    /// choice's message content back out. The caller owns the <see cref="UnityWebRequest"/> lifecycle (send it
    /// inside a coroutine and dispose it); this class only constructs and parses.
    /// </summary>
    public static class LlmClient
    {
        // --- request DTOs (JsonUtility-serializable) ---

        [Serializable]
        public sealed class Message
        {
            public string role;
            public string content;
            public Message() { }
            public Message(string role, string content) { this.role = role; this.content = content; }
        }

        [Serializable]
        private sealed class Request
        {
            public string model;
            public Message[] messages;
            public float temperature;
        }

        // --- response DTOs ---

        [Serializable]
        private sealed class Choice
        {
            public Message message;
        }

        [Serializable]
        private sealed class Response
        {
            public Choice[] choices;
        }

        [Serializable]
        private sealed class ErrorEnvelope
        {
            public ApiError error;
        }

        [Serializable]
        private sealed class ApiError
        {
            public string message;
        }

        /// <summary>
        /// Build (but do not send) a POST to <c>{BaseUrl}/chat/completions</c> carrying the system + user prompt.
        /// Sets the JSON content type and a Bearer header only when an API key is configured.
        /// </summary>
        public static UnityWebRequest BuildChatRequest(string systemPrompt, string userPrompt)
        {
            var body = new Request
            {
                model = LlmSettings.Model,
                temperature = 0.2f,
                messages = new[]
                {
                    new Message("system", systemPrompt ?? ""),
                    new Message("user", userPrompt ?? ""),
                },
            };
            string json = JsonUtility.ToJson(body);
            byte[] payload = Encoding.UTF8.GetBytes(json);

            string url = LlmSettings.BaseUrl + "/chat/completions";
            var req = new UnityWebRequest(url, UnityWebRequest.kHttpVerbPOST)
            {
                uploadHandler = new UploadHandlerRaw(payload),
                downloadHandler = new DownloadHandlerBuffer(),
            };
            req.SetRequestHeader("Content-Type", "application/json");
            string key = LlmSettings.ApiKey;
            if (!string.IsNullOrEmpty(key))
                req.SetRequestHeader("Authorization", "Bearer " + key);
            return req;
        }

        /// <summary>
        /// Pull <c>choices[0].message.content</c> out of a chat-completions response body. On failure (empty body,
        /// missing choices, or an error envelope) returns false and sets <paramref name="error"/>.
        /// </summary>
        public static bool TryParseContent(string responseJson, out string content, out string error)
        {
            content = null;
            error = null;
            if (string.IsNullOrWhiteSpace(responseJson))
            {
                error = "empty response";
                return false;
            }

            try
            {
                var parsed = JsonUtility.FromJson<Response>(responseJson);
                if (parsed != null && parsed.choices != null && parsed.choices.Length > 0
                    && parsed.choices[0] != null && parsed.choices[0].message != null
                    && !string.IsNullOrEmpty(parsed.choices[0].message.content))
                {
                    content = parsed.choices[0].message.content;
                    return true;
                }

                // Surface an API-side error message if the server returned one instead of a completion.
                var envelope = JsonUtility.FromJson<ErrorEnvelope>(responseJson);
                if (envelope != null && envelope.error != null && !string.IsNullOrEmpty(envelope.error.message))
                {
                    error = envelope.error.message;
                    return false;
                }

                error = "no choices in response";
                return false;
            }
            catch (Exception e)
            {
                error = "parse error: " + e.Message;
                return false;
            }
        }
    }
}

using UnityEngine;

namespace TheRobotDraft.Llm
{
    /// <summary>
    /// Persisted connection settings for the OpenAI-compatible chat endpoint used by the "Generate code" feature.
    /// Stored in <see cref="PlayerPrefs"/> so they survive across sessions; the defaults target a local LM Studio
    /// server (the common offline setup). The base URL is trimmed of a trailing '/' on use so callers can append
    /// "/chat/completions" without doubling the slash.
    /// </summary>
    public static class LlmSettings
    {
        private const string BaseUrlKey = "trd.llm.baseUrl";
        private const string ApiKeyKey = "trd.llm.apiKey";
        private const string ModelKey = "trd.llm.model";

        public const string DefaultBaseUrl = "http://localhost:1234/v1"; // LM Studio's OpenAI-compatible default
        public const string DefaultApiKey = "";
        public const string DefaultModel = "local-model";

        /// <summary>Endpoint root (e.g. "http://localhost:1234/v1"), with any trailing slash stripped. Empty ⇒ not configured.</summary>
        public static string BaseUrl => Trim(PlayerPrefs.GetString(BaseUrlKey, DefaultBaseUrl));

        /// <summary>Bearer token. Empty ⇒ no Authorization header is sent (local servers usually need none).</summary>
        public static string ApiKey => PlayerPrefs.GetString(ApiKeyKey, DefaultApiKey);

        /// <summary>Model id passed in the request body (e.g. "gpt-4o-mini", "local-model").</summary>
        public static string Model => PlayerPrefs.GetString(ModelKey, DefaultModel);

        /// <summary>Load the raw (untrimmed) values for an editor dialog.</summary>
        public static void Load(out string baseUrl, out string apiKey, out string model)
        {
            baseUrl = PlayerPrefs.GetString(BaseUrlKey, DefaultBaseUrl);
            apiKey = PlayerPrefs.GetString(ApiKeyKey, DefaultApiKey);
            model = PlayerPrefs.GetString(ModelKey, DefaultModel);
        }

        public static void Save(string baseUrl, string apiKey, string model)
        {
            PlayerPrefs.SetString(BaseUrlKey, baseUrl ?? "");
            PlayerPrefs.SetString(ApiKeyKey, apiKey ?? "");
            PlayerPrefs.SetString(ModelKey, string.IsNullOrWhiteSpace(model) ? DefaultModel : model.Trim());
            PlayerPrefs.Save();
        }

        private static string Trim(string url) => string.IsNullOrEmpty(url) ? url : url.TrimEnd('/');
    }
}

using System.Collections;
using System.Collections.Generic;
using System.Text;
using UnityEngine;
using UnityEngine.Networking;
using UnityEngine.UI;
using TheRobotDraft.Authoring.Model;
using TheRobotDraft.CodeGen;
using TheRobotDraft.Llm;

namespace TheRobotDraft.Uml
{
    /// <summary>
    /// The "Generate code" feature: turns a UML element into source. A deterministic offline skeleton
    /// (<see cref="CodeSkeleton"/>) is shown immediately, then — if an LLM endpoint is configured
    /// (<see cref="LlmSettings"/>) — an OpenAI-compatible chat request refines it in place. The generation
    /// context (<see cref="CodeGenContext"/>) folds in the element's members, its Description, the text of any
    /// UML notes attached to it, and its relationships (collaborators it uses / is used by, plus the base
    /// classes and interfaces it extends / implements, each carrying the collaborator's member API). Reuses the
    /// canvas's model (<c>_model</c>) and modal/menu helpers from the other partials.
    /// </summary>
    public sealed partial class UmlCanvas
    {
        // --- context builder ---

        /// <summary>
        /// Gather everything the generator needs for one element: its identity + Description, its attribute /
        /// operation members, the text of notes anchored to it, and its relationships (uses / used-by / extends /
        /// implements) with each collaborator's own member API.
        /// </summary>
        private CodeGenContext BuildCodeContext(ElementId id)
        {
            var ctx = new CodeGenContext();
            if (!_model.TryGet(id, out var el)) return ctx;

            ctx.Name = el.Name;
            ctx.Kind = el.Kind;
            ctx.Language = el.Language;
            ctx.Stereotype = el.Stereotype;
            ctx.IsAbstract = el.IsAbstract;
            ctx.Description = el.Description;

            // The original imported source (overlay round-trip), keyed by the element's source-file path.
            if (!string.IsNullOrEmpty(el.SourceFile) && _sourceFiles.TryGetValue(el.SourceFile, out var orig))
            {
                ctx.OriginalSource = orig;
                ctx.OriginalSourcePath = el.SourceFile;
            }

            // Members (attributes / operations) live as child elements; their UML signature is the child's Name,
            // and the member's doc-comment is its Description. Keep the comment lists index-aligned with the members.
            foreach (var childId in el.ChildIds)
            {
                if (!_model.TryGet(childId, out var c)) continue;
                if (c.Kind == ElementKind.Field) { ctx.Attributes.Add(c.Name); ctx.AttributeComments.Add(c.Description ?? ""); }
                else if (c.Kind == ElementKind.Function) { ctx.Operations.Add(c.Name); ctx.OperationComments.Add(c.Description ?? ""); }
            }

            // Walk every edge touching this element to fold in notes + relationships.
            foreach (var edge in _model.Edges)
            {
                bool fromMe = edge.From == id;
                bool toMe = edge.To == id;
                if (!fromMe && !toMe) continue;

                ElementId otherId = fromMe ? edge.To : edge.From;
                if (!_model.TryGet(otherId, out var other)) continue;

                // A note anchored to this element → fold its text in (regardless of edge direction).
                if (edge.Kind == EdgeKind.NoteLink)
                {
                    if (other.Kind == ElementKind.Note && !string.IsNullOrWhiteSpace(other.Name))
                        ctx.AttachedNotes.Add(other.Name);
                    continue;
                }

                // Supertype / interface — only meaningful in the outgoing (from==id) direction.
                if (fromMe && edge.Kind == EdgeKind.Generalization)
                {
                    ctx.Relationships.Add(MakeRelationship(
                        CodeGenContext.RelKind.Extends, CodeGenContext.RelDirection.Out, edge, other));
                    continue;
                }
                if (fromMe && edge.Kind == EdgeKind.Realization)
                {
                    ctx.Relationships.Add(MakeRelationship(
                        CodeGenContext.RelKind.Implements, CodeGenContext.RelDirection.Out, edge, other));
                    continue;
                }

                // Collaborators / dependencies. Outgoing = something this element uses; incoming = a caller.
                if (IsCollaboratorEdge(edge.Kind))
                {
                    var kind = fromMe ? CodeGenContext.RelKind.Uses : CodeGenContext.RelKind.UsedBy;
                    var dir = fromMe ? CodeGenContext.RelDirection.Out : CodeGenContext.RelDirection.In;
                    ctx.Relationships.Add(MakeRelationship(kind, dir, edge, other));
                }
            }

            return ctx;
        }

        /// <summary>Class-diagram relationships that read as "collaborates with" (not inheritance, not a note anchor).</summary>
        private static bool IsCollaboratorEdge(EdgeKind k) =>
            k == EdgeKind.Association || k == EdgeKind.DirectedAssociation || k == EdgeKind.Dependency
            || k == EdgeKind.Aggregation || k == EdgeKind.Composition;

        /// <summary>Build one <see cref="CodeGenContext.Relationship"/>, including the other element's member API.</summary>
        private CodeGenContext.Relationship MakeRelationship(
            CodeGenContext.RelKind kind, CodeGenContext.RelDirection dir, ModelEdge edge, ModelElement other)
        {
            var rel = new CodeGenContext.Relationship
            {
                Kind = kind,
                Direction = dir,
                Edge = edge.Kind,
                OtherName = other.Name,
                OtherKind = other.Kind,
                Label = edge.Label,
                SrcMultiplicity = edge.SourceMultiplicity,
                TgtMultiplicity = edge.TargetMultiplicity,
            };
            foreach (var childId in other.ChildIds)
            {
                if (!_model.TryGet(childId, out var c)) continue;
                if (c.Kind == ElementKind.Field) rel.OtherAttributes.Add(c.Name);
                else if (c.Kind == ElementKind.Function) rel.OtherOperations.Add(c.Name);
            }
            return rel;
        }

        // --- public entry points ---

        /// <summary>
        /// Generate source for a single element: open the viewer seeded with the deterministic skeleton, then
        /// (when an endpoint is configured) refine it asynchronously via the LLM.
        /// </summary>
        public void GenerateCodeForElement(ElementId id)
        {
            CloseMenu();
            if (!_model.TryGet(id, out var el)) { Flash("nothing to generate"); return; }

            var ctx = BuildCodeContext(id);
            string skeleton = CodeSkeleton.Generate(ctx);
            string title = "Generate code — " + el.Name;

            System.Action<string, string> setText = null;

            // (Re)run generation into the open viewer: seed with the skeleton, then refine via the LLM if configured.
            void Generate()
            {
                setText(skeleton, "generating with LLM…");
                if (string.IsNullOrEmpty(LlmSettings.BaseUrl))
                {
                    setText(skeleton, "LLM not configured — showing skeleton (LLM settings… on the canvas menu)");
                    Flash("LLM not configured — showing skeleton");
                    return;
                }
                StartCoroutine(RunLlmCodeGen(ctx, setText, skeleton));
            }

            // If the node already has approved code, open on it (don't auto-clobber); otherwise generate fresh.
            string saved = el.Code;
            bool hasSaved = !string.IsNullOrWhiteSpace(saved);
            setText = ShowCodeViewer(title,
                hasSaved ? saved : skeleton,
                hasSaved ? "saved code loaded — edit & Approve, or Regenerate" : "generating with LLM…",
                id, Generate);

            if (!hasSaved) Generate();
        }

        /// <summary>
        /// Generate source for every selected element, concatenating each one's skeleton (and, when configured,
        /// its LLM refinement) into a single viewer with separators.
        /// </summary>
        public void GenerateCodeForSelection()
        {
            CloseMenu();
            var ids = new List<ElementId>();
            foreach (var sid in SelectedIds)
                if (_model.TryGet(sid, out var e) && KindInfo.IsDiagramNode(e.Kind) && e.Kind != ElementKind.Note)
                    ids.Add(sid);
            if (ids.Count == 0) { Flash("select 2+ elements to generate code for"); return; }

            var contexts = new List<CodeGenContext>(ids.Count);
            var sb = new StringBuilder();
            foreach (var id in ids)
            {
                var ctx = BuildCodeContext(id);
                contexts.Add(ctx);
                AppendSection(sb, ctx.Name, CodeSkeleton.Generate(ctx));
            }

            // Batch output spans multiple elements, so there's no single node to save onto and no regenerate hook.
            var setText = ShowCodeViewer($"Generate code — {ids.Count} elements", sb.ToString(), "generating with LLM…",
                ElementId.None, null);

            if (string.IsNullOrEmpty(LlmSettings.BaseUrl))
            {
                setText(sb.ToString(), "LLM not configured — showing skeletons");
                Flash("LLM not configured — showing skeletons");
                return;
            }
            StartCoroutine(RunLlmCodeGenBatch(contexts, setText));
        }

        private static void AppendSection(StringBuilder sb, string name, string code)
        {
            if (sb.Length > 0) sb.Append('\n');
            sb.Append("// ===== ").Append(name).Append(" =====\n");
            sb.Append(code);
            if (!code.EndsWith("\n")) sb.Append('\n');
        }

        // --- LLM coroutines ---

        private static string LanguageOf(CodeGenContext ctx) =>
            string.IsNullOrWhiteSpace(ctx.Language) ? "C#" : ctx.Language.Trim();

        private static string SystemPromptFor(string language) =>
            $"You are an expert {language} engineer. Output ONLY valid, idiomatic, compilable {language} source — " +
            "no markdown fences, no commentary, and absolutely NO other programming language. " +
            $"Model the described UML element the natural {language} way (for example, in Elixir use " +
            "defmodule/defstruct/def and @behaviour, NOT a class; in Go use structs + interfaces). " +
            "Use the attached notes and relationships to inform the implementation.";

        /// <summary>True when the element carries an original imported source file we can edit surgically (overlay mode).</summary>
        private static bool HasOverlaySource(CodeGenContext ctx) => !string.IsNullOrEmpty(ctx.OriginalSource);

        /// <summary>System role for an overlay edit: return the FULL file with only the modeled changes applied.</summary>
        private static string OverlaySystemPromptFor(string language) =>
            $"You are an expert {language} engineer performing a surgical edit of an existing source file. " +
            "You will be given the ORIGINAL file and an updated UML model of ONE element in it. " +
            "Return the COMPLETE updated file with ONLY the modeled changes applied — add, rename, or adjust the " +
            "modeled type and its members (and their doc-comments) to match the model, and otherwise PRESERVE " +
            "everything else verbatim: formatting, imports, comments, other declarations, and any code not described " +
            "by the model. Output ONLY the full file source — no markdown fences and no commentary.";

        /// <summary>User role for an overlay edit: the original file followed by the element's current model.</summary>
        private static string BuildOverlayUserPrompt(CodeGenContext ctx) =>
            "ORIGINAL FILE:\n" + ctx.OriginalSource +
            "\n\nUPDATED UML MODEL FOR ONE ELEMENT IN THIS FILE:\n" + ctx.ToPromptString() +
            "\nApply the model to the file surgically and return the full updated file.";

        private IEnumerator RunLlmCodeGen(CodeGenContext ctx, System.Action<string, string> setText, string skeleton)
        {
            string language = LanguageOf(ctx);
            bool overlay = HasOverlaySource(ctx);
            string sysPrompt = overlay ? OverlaySystemPromptFor(language) : SystemPromptFor(language);
            string userPrompt = overlay ? BuildOverlayUserPrompt(ctx) : ctx.ToPromptString();
            using (var req = LlmClient.BuildChatRequest(sysPrompt, userPrompt))
            {
                yield return req.SendWebRequest();

                if (req.result != UnityWebRequest.Result.Success)
                {
                    setText(skeleton, "LLM request failed: " + req.error + " — showing skeleton");
                    Flash("LLM request failed — showing skeleton");
                    yield break;
                }

                if (LlmClient.TryParseContent(req.downloadHandler.text, out var content, out var error))
                {
                    string verb = overlay ? "overlaid onto " + System.IO.Path.GetFileName(ctx.OriginalSourcePath ?? "") : "generated with";
                    setText(StripFences(content), (overlay ? "surgically " + verb + " via " : "generated with ") + LlmSettings.Model);
                    Flash(overlay ? "source overlay applied" : "code generated");
                }
                else
                {
                    setText(skeleton, "LLM parse failed: " + error + " — showing skeleton");
                    Flash("LLM parse failed — showing skeleton");
                }
            }
        }

        private IEnumerator RunLlmCodeGenBatch(List<CodeGenContext> contexts, System.Action<string, string> setText)
        {
            var sb = new StringBuilder();
            int ok = 0;
            for (int i = 0; i < contexts.Count; i++)
            {
                var ctx = contexts[i];
                string language = LanguageOf(ctx);
                setText(sb.Length == 0 ? "generating…" : sb.ToString(),
                    $"generating {i + 1}/{contexts.Count}: {ctx.Name}…");

                string section = CodeSkeleton.Generate(ctx); // fallback for this element
                using (var req = LlmClient.BuildChatRequest(SystemPromptFor(language), ctx.ToPromptString()))
                {
                    yield return req.SendWebRequest();
                    if (req.result == UnityWebRequest.Result.Success
                        && LlmClient.TryParseContent(req.downloadHandler.text, out var content, out _))
                    {
                        section = StripFences(content);
                        ok++;
                    }
                }
                AppendSection(sb, ctx.Name, section);
                setText(sb.ToString(), $"generating {i + 1}/{contexts.Count}…");
            }

            setText(sb.ToString(), $"generated {ok}/{contexts.Count} with {LlmSettings.Model}");
            Flash($"code generated ({ok}/{contexts.Count})");
        }

        /// <summary>Strip a leading/trailing markdown code fence (```lang … ```) if the model added one anyway.</summary>
        private static string StripFences(string code)
        {
            if (string.IsNullOrEmpty(code)) return code;
            string s = code.Trim();
            if (!s.StartsWith("```")) return code;

            int firstNl = s.IndexOf('\n');
            if (firstNl < 0) return code;
            s = s.Substring(firstNl + 1); // drop the opening ```lang line

            int lastFence = s.LastIndexOf("```");
            if (lastFence >= 0) s = s.Substring(0, lastFence);
            return s.TrimEnd('\n');
        }

        // --- code viewer modal ---

        /// <summary>
        /// Open a modal showing generated code in a scrollable, read-only multiline field, with Copy and Close
        /// buttons and a status line. Returns a setter the coroutine calls to replace the code + status text once
        /// the async request resolves (the InputField + status Text are captured in the closure).
        /// </summary>
        private System.Action<string, string> ShowCodeViewer(string title, string code, string status,
            ElementId saveTarget, System.Action onRegenerate)
        {
            float w = 760f, h = 560f;
            var panel = BeginModal(w, h, title);

            const float pad = 16f;
            float bodyTop = -46f;
            float bodyH = h - 46f - 92f; // leave room for the status line + buttons at the bottom
            float bodyW = w - pad * 2f;

            // Scroll view wrapping a multiline InputField so long source scrolls within the dialog.
            var viewportGo = new GameObject("CodeViewport", typeof(RectTransform));
            var vpRt = (RectTransform)viewportGo.transform;
            vpRt.SetParent(panel, false);
            vpRt.anchorMin = vpRt.anchorMax = new Vector2(0f, 1f);
            vpRt.pivot = new Vector2(0f, 1f);
            vpRt.sizeDelta = new Vector2(bodyW, bodyH);
            vpRt.anchoredPosition = new Vector2(pad, bodyTop);
            viewportGo.AddComponent<Image>().color = new Color(0.10f, 0.11f, 0.14f, 1f);
            viewportGo.AddComponent<RectMask2D>();
            var scroll = viewportGo.AddComponent<ScrollRect>();
            scroll.horizontal = false;
            scroll.vertical = true;
            scroll.movementType = ScrollRect.MovementType.Clamped;
            scroll.scrollSensitivity = 28f;

            var contentGo = new GameObject("CodeContent", typeof(RectTransform));
            var contentRt = (RectTransform)contentGo.transform;
            contentRt.SetParent(vpRt, false);
            contentRt.anchorMin = new Vector2(0f, 1f);
            contentRt.anchorMax = new Vector2(1f, 1f);
            contentRt.pivot = new Vector2(0.5f, 1f);
            contentRt.sizeDelta = new Vector2(0f, bodyH);
            contentRt.anchoredPosition = Vector2.zero;
            contentGo.AddComponent<Image>().color = new Color(0.10f, 0.11f, 0.14f, 1f);
            var input = contentGo.AddComponent<InputField>();

            // Monospace-ish: the built-in font isn't fixed-width, but a small left-aligned wrap reads as a listing.
            var textComp = MakeText(contentRt, "", new Vector2(8f, -6f), new Vector2(bodyW - 28f, bodyH - 12f), 14,
                new Color(0.80f, 0.86f, 0.78f, 1f), TextAnchor.UpperLeft);
            textComp.raycastTarget = true;
            textComp.horizontalOverflow = HorizontalWrapMode.Wrap;
            textComp.verticalOverflow = VerticalWrapMode.Overflow;

            input.textComponent = textComp;
            input.lineType = InputField.LineType.MultiLineNewline;
            input.readOnly = false; // editable so the user can tweak before approving + saving to the node
            input.text = code;

            scroll.viewport = vpRt;
            scroll.content = contentRt;
            FitCodeContent(contentRt, textComp, bodyW - 28f, bodyH);

            // Status line just below the viewport.
            float statusY = bodyTop - bodyH - 6f;
            var statusText = MakeText(panel, status, new Vector2(pad, statusY), new Vector2(bodyW, 20f), 13,
                new Color(0.60f, 0.66f, 0.76f, 1f), TextAnchor.MiddleLeft);

            // Buttons.
            float yBtn = -(h - 46f);
            MakeButton(panel, "Copy code", new Vector2(pad, yBtn), new Vector2(118f, 34f),
                new Color(0.20f, 0.42f, 0.52f, 1f), () =>
                {
                    GUIUtility.systemCopyBuffer = input.text;
                    if (statusText != null) statusText.text = "copied to clipboard";
                    Flash("code copied to clipboard");
                });
            if (onRegenerate != null)
                MakeButton(panel, "Regenerate", new Vector2(pad + 126f, yBtn), new Vector2(120f, 34f),
                    new Color(0.30f, 0.30f, 0.16f, 1f), () => onRegenerate());
            // Approve & save the (possibly edited) code onto the node — the round-trip counterpart to import.
            if (saveTarget.IsValid)
                MakeButton(panel, "Approve & save to node", new Vector2(w - 308f, yBtn), new Vector2(196f, 34f),
                    new Color(0.18f, 0.46f, 0.30f, 1f), () =>
                    {
                        _ctl.SetCode(saveTarget, input.text);
                        // If this node round-trips a stored source file, update the overlay so the next edit builds on it.
                        if (_model.TryGet(saveTarget, out var st) && !string.IsNullOrEmpty(st.SourceFile)
                            && _sourceFiles.ContainsKey(st.SourceFile))
                            _sourceFiles[st.SourceFile] = input.text;
                        Flash("saved code to node");
                        CloseMenu();
                    });
            MakeButton(panel, "Close", new Vector2(w - 104f, yBtn), new Vector2(88f, 34f),
                new Color(0.22f, 0.24f, 0.29f, 1f), CloseMenu);

            // The setter the coroutine uses to replace the displayed code + status after the async call.
            return (newCode, newStatus) =>
            {
                if (input != null) input.text = newCode ?? "";
                if (textComp != null) FitCodeContent(contentRt, textComp, bodyW - 28f, bodyH);
                if (statusText != null) statusText.text = newStatus ?? "";
            };
        }

        /// <summary>Grow the scroll content to fit the rendered text height so all of it can scroll into view.</summary>
        private static void FitCodeContent(RectTransform content, Text text, float width, float minHeight)
        {
            if (content == null || text == null) return;
            float preferred = text.preferredHeight + 16f;
            content.sizeDelta = new Vector2(0f, Mathf.Max(minHeight, preferred));
        }

        // --- LLM settings dialog ---

        /// <summary>Edit the OpenAI-compatible endpoint settings (base URL, API key, model) persisted in PlayerPrefs.</summary>
        public void ShowLlmSettings(Vector2 screenPos)
        {
            CloseMenu();
            LlmSettings.Load(out var baseUrl, out var apiKey, out var model);

            float w = 480f, h = 300f;
            var panel = BeginModal(w, h, "LLM settings   —   OpenAI-compatible endpoint");

            float y = -50f;
            FormLabel(panel, "Base URL   (e.g. http://localhost:1234/v1)", ref y, w);
            var urlInput = MakeInput(panel, new Vector2(16f, y), w - 32f, baseUrl, LlmSettings.DefaultBaseUrl);
            y -= 44f;

            FormLabel(panel, "API key   (leave blank for a local server)", ref y, w);
            var keyInput = MakeInput(panel, new Vector2(16f, y), w - 32f, apiKey, "sk-…  (optional)");
            keyInput.contentType = InputField.ContentType.Password;
            y -= 44f;

            FormLabel(panel, "Model", ref y, w);
            var modelInput = MakeInput(panel, new Vector2(16f, y), w - 32f, model, LlmSettings.DefaultModel);

            void Submit()
            {
                LlmSettings.Save(urlInput.text, keyInput.text, modelInput.text);
                CloseMenu();
                Flash("LLM settings saved");
            }

            float yBtn = -(h - 46f);
            MakeButton(panel, "Save", new Vector2(w - 198f, yBtn), new Vector2(84f, 34f),
                new Color(0.20f, 0.42f, 0.52f, 1f), Submit);
            MakeButton(panel, "Cancel", new Vector2(w - 104f, yBtn), new Vector2(88f, 34f),
                new Color(0.22f, 0.24f, 0.29f, 1f), CloseMenu);

            FocusInput(urlInput);
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.Networking;
using UnityEngine.UI;
using TheRobotDraft.Authoring.Model;
using TheRobotDraft.Authoring.State;
using TheRobotDraft.CodeGen;
using TheRobotDraft.Llm;

namespace TheRobotDraft.Uml
{
    /// <summary>
    /// The "Import code" feature — the inverse of UmlCanvas.CodeGen: paste source, send it to the configured
    /// LLM endpoint (<see cref="LlmSettings"/>), and turn the structured reply (<see cref="CodeParser.ParsedModel"/>)
    /// into UML classifiers + members + relationships on the active package. Drives element creation through the
    /// same authoring verbs SeedSample / PasteElement use (<c>_ctl.EnterAddNode</c> → <c>CommitAddNode</c>,
    /// <c>SetMeta</c>, <c>EnterConnect</c>/<c>BeginConnect</c>/<c>CommitConnect</c>) so undo / persistence behave
    /// identically. Reuses the canvas's model + modal helpers from the other partials.
    /// </summary>
    public sealed partial class UmlCanvas
    {
        /// <summary>
        /// Original text of each imported source file, keyed by its path (the same path stored on each element's
        /// <see cref="ModelElement.SourceFile"/>). Backs the surgical overlay round-trip: regeneration of an element
        /// that has a stored source edits that file in place instead of synthesizing from scratch. Cleared in
        /// <c>NewWorld</c>, persisted in <see cref="DiagramDto.sourceFiles"/>.
        /// </summary>
        private readonly Dictionary<string, string> _sourceFiles = new();

        /// <summary>Source-file extensions the folder importer ingests (lower-case, leading dot).</summary>
        private static readonly HashSet<string> ImportExtensions = new()
        {
            ".cs", ".java", ".ts", ".tsx", ".js", ".py", ".go", ".rs", ".ex", ".exs", ".rb", ".cpp", ".h", ".hpp", ".c",
        };

        /// <summary>Cap on files ingested in one folder import — keeps a huge tree from stalling the coroutine.</summary>
        private const int ImportFileCap = 200;

        /// <summary>Synthetic <see cref="ModelElement.SourceFile"/> key for paste imports, so pasted text round-trips like a file.</summary>
        private const string PasteSourceKey = "<pasted>";

        // --- public entry point ---

        /// <summary>
        /// Open a modal to paste source code (with an optional language hint), then import it as UML elements.
        /// The parent wires this onto a canvas menu item.
        /// </summary>
        public void ShowImportCodeDialog(Vector2 screenPos)
        {
            CloseMenu();

            float w = 620f, h = 560f;
            var panel = BeginModal(w, h, "Import code   —   paste source or migrate a folder, build UML via LLM");

            float y = -50f;
            FormLabel(panel, "Source code   (paste one or more types — any language)", ref y, w);
            float codeH = 260f;
            var codeInput = MakeMultilineInput(panel, new Vector2(16f, y), w - 32f, codeH, "",
                "// paste classes / interfaces / enums here…");
            y -= codeH + 12f;

            FormLabel(panel, "Language hint   (optional — e.g. C#, TypeScript, Python)", ref y, w);
            var langInput = MakeInput(panel, new Vector2(16f, y), w - 32f, "", "auto-detect");
            y -= 50f;

            // Folder import: a path text field plus a native macOS picker (the manual field is the cross-platform fallback).
            FormLabel(panel, "Folder path   (recursively import every source file under this directory)", ref y, w);
            var folderInput = MakeInput(panel, new Vector2(16f, y), w - 240f, "", "/path/to/src");

            // A native "Browse…" picker. In the editor we use EditorUtility; in a macOS player we shell out to
            // osascript (same pattern as UmlImageClipboard). On other standalone platforms the manual field stands in.
            bool canBrowse =
#if UNITY_EDITOR
                true;
#else
                Application.platform == RuntimePlatform.OSXPlayer;
#endif
            if (canBrowse)
            {
                MakeButton(panel, "Browse…", new Vector2(w - 218f, y), new Vector2(80f, 30f),
                    new Color(0.22f, 0.24f, 0.29f, 1f), () =>
                    {
                        string picked = BrowseForFolder();
                        if (!string.IsNullOrEmpty(picked)) folderInput.text = picked;
                    });
            }

            MakeButton(panel, "Import folder", new Vector2(w - 132f, y), new Vector2(116f, 30f),
                new Color(0.20f, 0.42f, 0.52f, 1f), () =>
                {
                    string folder = folderInput.text;
                    string langHint = langInput.text;
                    CloseMenu();
                    ImportFolder(folder, langHint);
                });

            void Submit()
            {
                string code = codeInput.text;
                string langHint = langInput.text;
                CloseMenu();
                ImportCode(code, langHint);
            }

            float yBtn = -(h - 46f);
            MakeButton(panel, "Import paste", new Vector2(w - 214f, yBtn), new Vector2(106f, 34f),
                new Color(0.20f, 0.42f, 0.52f, 1f), Submit);
            MakeButton(panel, "Cancel", new Vector2(w - 104f, yBtn), new Vector2(88f, 34f),
                new Color(0.22f, 0.24f, 0.29f, 1f), CloseMenu);

            FocusInput(codeInput);
        }

        /// <summary>
        /// Open a native folder chooser and return the selected POSIX path (or "" on cancel / unsupported platform). In
        /// the editor this uses <c>EditorUtility.OpenFolderPanel</c>; in a macOS player it shells out to <c>osascript</c>
        /// (mirroring <see cref="UmlImageClipboard"/>'s Process usage). A user cancel makes osascript exit non-zero with
        /// no stdout, which we read as "" and ignore.
        /// </summary>
        private static string BrowseForFolder()
        {
#if UNITY_EDITOR
            return UnityEditor.EditorUtility.OpenFolderPanel("Select source folder", "", "") ?? "";
#else
            if (Application.platform != RuntimePlatform.OSXPlayer) return "";
            try
            {
                // `choose folder` returns an alias; coerce it to a POSIX path so it drops straight into the path field.
                const string script = "POSIX path of (choose folder with prompt \"Select source folder\")";
                var psi = new System.Diagnostics.ProcessStartInfo("osascript")
                {
                    UseShellExecute = false,
                    CreateNoWindow = true,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                };
                psi.ArgumentList.Add("-e");
                psi.ArgumentList.Add(script);
                using (var proc = System.Diagnostics.Process.Start(psi))
                {
                    string outText = proc.StandardOutput.ReadToEnd();
                    proc.WaitForExit();
                    if (proc.ExitCode != 0) return ""; // user cancelled (osascript -128) or error
                    return (outText ?? "").Trim();
                }
            }
            catch (System.Exception ex)
            {
                Debug.LogWarning("folder picker failed: " + ex.Message);
                return "";
            }
#endif
        }

        // --- import driver ---

        /// <summary>
        /// Validate input, ensure there is a package to drop classifiers into, then kick off the async LLM
        /// request. The canvas is left untouched until the reply parses successfully.
        /// </summary>
        private void ImportCode(string code, string langHint)
        {
            if (string.IsNullOrWhiteSpace(code)) { Flash("paste some code to import"); return; }

            if (!ImportEnsurePackage()) { Flash("couldn't create a package to import into"); return; }

            // Deterministic first: a network-free structural parse handles the common case (C# / TS / Java) instantly.
            if (CodeStructParser.TryParse(code, langHint, out var model))
            {
                _sourceFiles[PasteSourceKey] = code; // pasted text round-trips like an imported file
                IngestParsed(model, PasteSourceKey);
                return;
            }

            // Deterministic parse found nothing — fall back to the LLM if one is configured, else explain why.
            if (string.IsNullOrEmpty(LlmSettings.BaseUrl))
            {
                Flash("couldn't parse the pasted code (unsupported language?) and no LLM configured — set one in LLM settings…");
                return;
            }

            Flash("importing code via LLM…");
            StartCoroutine(RunImport(code, langHint));
        }

        /// <summary>Make sure <c>_activePackage</c> is valid — create an "Imported" package if none exists (cf. SeedSample).</summary>
        private bool ImportEnsurePackage()
        {
            EnsureActivePackage();
            if (_activePackage.IsValid) return true;

            _ctl.EnterAddNode(ElementKind.Package);
            var pkg = _ctl.CommitAddNode(ElementId.None, "Imported");
            _ctl.EnterSelect();
            if (!pkg.IsValid) return false;
            _activePackage = pkg;
            return true;
        }

        private IEnumerator RunImport(string code, string langHint)
        {
            string userPrompt = CodeParser.BuildUserPrompt(code, langHint);
            using (var req = LlmClient.BuildChatRequest(CodeParser.SystemPrompt, userPrompt))
            {
                yield return req.SendWebRequest();

                if (req.result != UnityWebRequest.Result.Success)
                {
                    Flash("import failed: LLM request error — " + req.error);
                    yield break;
                }

                if (!LlmClient.TryParseContent(req.downloadHandler.text, out var content, out var apiError))
                {
                    Flash("import failed: " + apiError);
                    yield break;
                }

                if (!CodeParser.TryParse(content, out var model, out var parseError))
                {
                    Flash("import failed: " + parseError);
                    yield break;
                }

                _sourceFiles[PasteSourceKey] = code; // keep the original for surgical overlay regeneration
                IngestParsed(model, PasteSourceKey);
            }
        }

        // --- folder import ---

        /// <summary>
        /// Migrate a whole source tree: validate the path, then ingest every code file under it (recursively) via
        /// the same LLM parse path as paste import, tagging each created element with its file's <c>SourceFile</c>
        /// and stashing the file's original text in <see cref="_sourceFiles"/> for the overlay round-trip.
        /// </summary>
        private void ImportFolder(string folder, string langHint)
        {
            if (string.IsNullOrWhiteSpace(folder)) { Flash("enter a folder path to import"); return; }
            folder = folder.Trim();
            if (!Directory.Exists(folder)) { Flash("folder not found: " + folder); return; }

            if (!ImportEnsurePackage()) { Flash("couldn't create a package to import into"); return; }

            // No LLM gate here anymore: the deterministic parser runs offline. Files it can't handle fall back to the
            // LLM per-file when one is configured (RunImportFolder), so an unconfigured endpoint is no longer fatal.

            List<string> files;
            bool truncated;
            try { files = EnumerateSourceFiles(folder, out truncated); }
            catch (System.Exception ex) { Flash("couldn't read folder: " + ex.Message); return; }

            if (files.Count == 0) { Flash("no source files found under " + folder); return; }
            if (truncated) Flash($"importing first {ImportFileCap} of many files…");

            StartCoroutine(RunImportFolder(files, langHint));
        }

        /// <summary>Recursively collect code files under <paramref name="root"/>, capped at <see cref="ImportFileCap"/>.</summary>
        private static List<string> EnumerateSourceFiles(string root, out bool truncated)
        {
            var files = new List<string>();
            truncated = false;
            foreach (var path in Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories))
            {
                if (!ImportExtensions.Contains(Path.GetExtension(path).ToLowerInvariant())) continue;
                files.Add(path);
                if (files.Count >= ImportFileCap) { truncated = true; break; }
            }
            return files;
        }

        /// <summary>
        /// Sequentially parse each file via the LLM and materialize its types, sharing one name→id map across the
        /// whole batch so cross-file relationships resolve. A second pass adds edges once every type exists.
        /// </summary>
        private IEnumerator RunImportFolder(List<string> files, string langHint)
        {
            var created = new Dictionary<string, ElementId>();
            var models = new List<CodeParser.ParsedModel>(files.Count);
            int typeCount = 0, parsedFiles = 0, gridIndex = 0;
            bool llmConfigured = !string.IsNullOrEmpty(LlmSettings.BaseUrl);
            string firstFailure = null; // surfaced when nothing parsed at all

            for (int i = 0; i < files.Count; i++)
            {
                string path = files[i];
                Flash($"importing {i + 1}/{files.Count}: {Path.GetFileName(path)}…");

                string text;
                try { text = File.ReadAllText(path); }
                catch (System.Exception ex)
                {
                    firstFailure ??= Path.GetFileName(path) + ": unreadable — " + ex.Message;
                    continue; // unreadable file — skip, keep going
                }

                // Deterministic first: structural parse runs offline and is fast, so we batch many files per frame.
                string langForFile = string.IsNullOrWhiteSpace(langHint) ? Path.GetExtension(path) : langHint;
                if (CodeStructParser.TryParse(text, langForFile, out var detModel))
                {
                    _sourceFiles[path] = text; // keep the original for surgical overlay regeneration
                    typeCount += MaterializeTypes(detModel, created, ref gridIndex, path);
                    models.Add(detModel);
                    parsedFiles++;
                    if ((i % 10) == 9) yield return null; // let the progress hint repaint periodically
                    continue;
                }

                // Deterministic parse found nothing — fall back to the LLM per-file, but only if one is configured.
                if (!llmConfigured)
                {
                    firstFailure ??= Path.GetFileName(path) + ": no types parsed and no LLM configured";
                    continue;
                }

                string userPrompt = CodeParser.BuildUserPrompt(text, langHint);
                using (var req = LlmClient.BuildChatRequest(CodeParser.SystemPrompt, userPrompt))
                {
                    yield return req.SendWebRequest();
                    if (req.result != UnityWebRequest.Result.Success)
                    {
                        firstFailure ??= "LLM unreachable: " + req.error;
                        continue;
                    }
                    if (!LlmClient.TryParseContent(req.downloadHandler.text, out var content, out var apiErr))
                    {
                        firstFailure ??= "LLM error: " + apiErr;
                        continue;
                    }
                    if (!CodeParser.TryParse(content, out var model, out var parseErr))
                    {
                        firstFailure ??= Path.GetFileName(path) + ": " + parseErr;
                        continue;
                    }

                    _sourceFiles[path] = text; // keep the original for surgical overlay regeneration
                    typeCount += MaterializeTypes(model, created, ref gridIndex, path);
                    models.Add(model);
                    parsedFiles++;
                }
            }

            // Pass 2: resolve relationships by type name across the whole batch.
            int edgeCount = 0, skipped = 0;
            foreach (var model in models)
                edgeCount += LinkTypes(model, created, ref skipped);

            _ctl.EnterSelect();
            SetSelected(ElementId.None);
            RebuildFromModel();

            if (parsedFiles == 0)
            {
                string reason = firstFailure ?? (llmConfigured
                    ? "deterministic parse found none and the LLM returned nothing"
                    : "deterministic parse found none and no LLM is configured");
                Flash($"imported 0 types from 0/{files.Count} files — {reason}");
                yield break;
            }

            string note = $"imported {typeCount} types from {parsedFiles}/{files.Count} files, {edgeCount} relationships";
            if (skipped > 0) note += $" ({skipped} external ref{(skipped == 1 ? "" : "s")} skipped)";
            Flash(note);
        }

        // --- model materialization ---

        /// <summary>
        /// Create one classifier per parsed type (with its members), lay them out on a grid near the canvas
        /// center, then add extends/implements/uses edges between types that resolved within this import.
        /// </summary>
        private void IngestParsed(CodeParser.ParsedModel model, string sourceFile = null)
        {
            if (model == null || model.types == null || model.types.Length == 0)
            { Flash("nothing to import"); return; }

            // name → created element id, so relationships can resolve targets created in this same import.
            var created = new Dictionary<string, ElementId>();
            int gridIndex = 0;
            int typeCount = MaterializeTypes(model, created, ref gridIndex, sourceFile);

            int skipped = 0;
            int edgeCount = LinkTypes(model, created, ref skipped);

            _ctl.EnterSelect();
            SetSelected(ElementId.None);
            RebuildFromModel();

            string note = $"imported {typeCount} types, {edgeCount} relationships";
            if (skipped > 0) note += $" ({skipped} external ref{(skipped == 1 ? "" : "s")} skipped)";
            Flash(note);
        }

        /// <summary>
        /// Create a classifier (with members + comments) for each parsed type, laying them out on a grid that
        /// continues from <paramref name="gridIndex"/> (so a folder import groups each file's types and doesn't
        /// stack files on top of one another). Records each in <paramref name="created"/> and, when
        /// <paramref name="sourceFile"/> is set, tags the element with it. Returns the number of types created.
        /// </summary>
        private int MaterializeTypes(CodeParser.ParsedModel model, Dictionary<string, ElementId> created,
            ref int gridIndex, string sourceFile)
        {
            if (model?.types == null) return 0;

            // Grid layout: a small spread around the canvas center so imported boxes don't stack on the origin.
            const float colW = 240f, rowH = 200f, originX = -360f, originY = 160f;
            int made = 0;

            foreach (var pt in model.types)
            {
                if (pt == null || string.IsNullOrWhiteSpace(pt.name)) continue;

                var kind = ImportKind(pt.kind);
                _ctl.EnterAddNode(kind);
                var id = _ctl.CommitAddNode(_activePackage, ImportUniqueName(pt.name.Trim()));
                if (!id.IsValid) { _ctl.EnterSelect(); continue; }

                if (!string.IsNullOrWhiteSpace(pt.language))
                    _ctl.SetMeta(id, pt.language.Trim(), null);
                if (!string.IsNullOrWhiteSpace(pt.comment))
                    _ctl.SetDescription(id, pt.comment.Trim()); // class doc-comment → element Description
                if (!string.IsNullOrEmpty(sourceFile))
                    _ctl.SetSourceFile(id, sourceFile);

                ImportAddMembers(id, ElementKind.Field, pt.fields, pt.fieldComments);
                ImportAddMembers(id, ElementKind.Function, pt.methods, pt.methodComments);

                _ctl.EnterSelect();

                _pos[id] = new Vector2(
                    originX + (gridIndex % 4) * colW,
                    originY - (gridIndex / 4) * rowH);
                _ctl.SetZLayer(id, _activeLayer); // import onto the active layer

                // First writer wins on a name collision (we deduped the box name, but key on the original).
                if (!created.ContainsKey(pt.name.Trim())) created[pt.name.Trim()] = id;
                gridIndex++;
                made++;
            }
            return made;
        }

        /// <summary>
        /// Add extends/implements/uses edges for one parsed model, resolving targets against <paramref name="created"/>
        /// (which may span multiple files in a folder import). Returns the number of edges created.
        /// </summary>
        private int LinkTypes(CodeParser.ParsedModel model, Dictionary<string, ElementId> created, ref int skipped)
        {
            if (model?.types == null) return 0;
            int edgeCount = 0;
            foreach (var pt in model.types)
            {
                if (pt == null || string.IsNullOrWhiteSpace(pt.name)) continue;
                if (!created.TryGetValue(pt.name.Trim(), out var fromId)) continue;

                edgeCount += ImportConnect(fromId, pt.extends, EdgeKind.Generalization, created, ref skipped);
                edgeCount += ImportConnect(fromId, pt.implements, EdgeKind.Realization, created, ref skipped);
                edgeCount += ImportConnect(fromId, pt.uses, EdgeKind.Dependency, created, ref skipped);
            }
            return edgeCount;
        }

        /// <summary>
        /// Add each signature string as a member child of <paramref name="owner"/> (UML signature verbatim), setting
        /// the member's Description from the index-aligned <paramref name="comments"/> doc-comment when present.
        /// </summary>
        private void ImportAddMembers(ElementId owner, ElementKind memberKind, string[] signatures, string[] comments)
        {
            if (signatures == null) return;
            for (int i = 0; i < signatures.Length; i++)
            {
                string sig = signatures[i];
                if (string.IsNullOrWhiteSpace(sig)) continue;
                _ctl.EnterAddNode(memberKind);
                var mid = _ctl.CommitAddNode(owner, sig.Trim());
                if (!mid.IsValid) continue;
                string comment = comments != null && i < comments.Length ? comments[i] : null;
                if (!string.IsNullOrWhiteSpace(comment))
                    _ctl.SetDescription(mid, comment.Trim());
            }
        }

        /// <summary>
        /// Connect <paramref name="fromId"/> to each named target with <paramref name="edgeKind"/>, but only when
        /// the name resolves to a type created in this import. Counts unresolved (external) names into
        /// <paramref name="skipped"/>. Returns the number of edges actually created.
        /// </summary>
        private int ImportConnect(ElementId fromId, string[] targetNames, EdgeKind edgeKind,
            Dictionary<string, ElementId> created, ref int skipped)
        {
            if (targetNames == null) return 0;
            int made = 0;
            foreach (var raw in targetNames)
            {
                if (string.IsNullOrWhiteSpace(raw)) continue;
                string name = raw.Trim();
                if (!created.TryGetValue(name, out var toId) || toId == fromId) { skipped++; continue; }

                _ctl.EnterConnect(CommitStyle.OneShot, edgeKind);
                _ctl.BeginConnect(fromId);
                var edge = _ctl.CommitConnect(toId);
                if (edge.IsValid) made++;
            }
            return made;
        }

        /// <summary>Map the model's free-text kind string onto an <see cref="ElementKind"/> classifier (default Class).</summary>
        private static ElementKind ImportKind(string kind)
        {
            if (string.IsNullOrWhiteSpace(kind)) return ElementKind.Class;
            switch (kind.Trim().ToLowerInvariant())
            {
                case "interface": return ElementKind.Interface;
                case "enum":
                case "enumeration": return ElementKind.Enum;
                case "struct":
                case "structure": return ElementKind.Struct;
                default: return ElementKind.Class;
            }
        }

        /// <summary>Dedupe a classifier name against the active package so two imported types can't clash (cf. UniqueName).</summary>
        private string ImportUniqueName(string baseName)
        {
            if (!NameExistsInActive(baseName)) return baseName;
            int n = 2;
            string candidate;
            do { candidate = baseName + n++; } while (NameExistsInActive(candidate));
            return candidate;
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using TheRobotDraft.Authoring.Model;
using TheRobotDraft.Authoring.Rules;

namespace TheRobotDraft.Uml
{
    /// <summary>
    /// Structured property editors for the UML canvas — the Rational Rose / Sparx EA "feel": you pick visibility
    /// from a scope control, type the member name and its type / parameters / return type in labelled fields, and
    /// toggle static/abstract, instead of hand-typing UML punctuation. Members still serialize to the canonical
    /// signature string the model stores in <see cref="ModelElement.Name"/> (see <see cref="UmlMemberSignature"/>),
    /// so the renderer, reverse-engineering pipeline, and undo stack are all unchanged. Classifiers get a Properties
    /// dialog for name, implementation language, custom stereotype, and the abstract modifier.
    /// </summary>
    public sealed partial class UmlCanvas
    {
        private static readonly string[] CommonLanguages =
            { "C#", "C/C++", "Rust", "Go", "Java", "Python", "Node.js", "Elixir", "TypeScript" };
        private static readonly string[] CommonMultiplicities = { "1", "0..1", "0..*", "1..*", "*" };

        private static readonly Color LabelColor = new Color(0.62f, 0.68f, 0.78f, 1f);

        // --- member (attribute / operation) editor ---

        /// <summary>
        /// Open the structured attribute/operation editor. When <paramref name="existing"/> is valid the dialog
        /// edits that member (its signature is parsed back into the controls); otherwise it adds a new member
        /// under <paramref name="parent"/>.
        /// </summary>
        private void ShowMemberEditor(ElementId parent, ElementKind kind, ElementId existing, Vector2 screenPos,
            System.Action onClose = null)
        {
            CloseMenu();
            bool isField = kind == ElementKind.Field;
            bool editing = existing.IsValid && _model.TryGet(existing, out _);

            MemberParts parts = editing && _model.TryGet(existing, out var ex)
                ? UmlMemberSignature.Parse(kind, ex.Name)
                : MemberParts.ForNew(kind);

            float w = 470f, h = (isField ? 322f : 420f) + 110f; // +room for the comment / doc field
            string title = (editing ? "Edit " : "Add ") + (isField ? "Attribute" : "Operation")
                           + "   —   Rose / Sparx convention";
            var panel = BeginModal(w, h, title);

            float y = -50f;
            FormLabel(panel, "Visibility (scope)", ref y, w);
            var getVis = MakeVisibilityPicker(panel, new Vector2(16f, y), parts.Visibility);
            y -= 38f;

            FormLabel(panel, "Name", ref y, w);
            var nameInput = MakeInput(panel, new Vector2(16f, y), w - 32f, parts.Name,
                isField ? "fieldName" : "operationName");
            y -= 44f;

            InputField paramsInput = null;
            InputField typeInput;
            if (isField)
            {
                FormLabel(panel, "Type", ref y, w);
                typeInput = MakeInput(panel, new Vector2(16f, y), w - 32f, parts.Type,
                    "Type  (e.g. decimal, Guid, List<Order>)");
                y -= 44f;
            }
            else
            {
                FormLabel(panel, "Parameters   (name : Type, comma-separated)", ref y, w);
                paramsInput = MakeInput(panel, new Vector2(16f, y), w - 32f, parts.Parameters,
                    "amount : decimal, note : string");
                y -= 44f;
                FormLabel(panel, "Return type", ref y, w);
                typeInput = MakeInput(panel, new Vector2(16f, y), w - 32f, parts.Type, "void");
                y -= 44f;
            }

            var getStatic = MakeCheckbox(panel, new Vector2(16f, y), "static", parts.IsStatic);
            Func<bool> getAbstract = () => false;
            if (!isField) getAbstract = MakeCheckbox(panel, new Vector2(170f, y), "abstract", parts.IsAbstract);
            y -= 38f;

            // Comment / doc — the member's Description, surfaced for code generation + import round-trip.
            string currentComment = editing && _model.TryGet(existing, out var exc) ? exc.Description : "";
            FormLabel(panel, "Comment / doc   (rendered above the member in generated code)", ref y, w);
            var commentInput = MakeMultilineInput(panel, new Vector2(16f, y), w - 32f, 64f, currentComment,
                "What this member is for…");

            void Submit()
            {
                var np = new MemberParts
                {
                    Visibility = getVis(),
                    Name = nameInput.text,
                    Type = typeInput.text,
                    Parameters = paramsInput != null ? paramsInput.text : "",
                    DefaultValue = parts.DefaultValue,
                    IsStatic = getStatic(),
                    IsAbstract = !isField && getAbstract(),
                };
                string sig = UmlMemberSignature.Compose(kind, np);
                string comment = commentInput.text;
                CloseMenu();
                if (editing)
                {
                    _ctl.Rename(existing, sig);
                    _ctl.SetDescription(existing, comment);
                    RebuildFromModel();
                    SetSelected(parent);
                    Flash("updated " + (isField ? "attribute" : "operation"));
                }
                else
                {
                    _ctl.EnterAddNode(kind);
                    var id = _ctl.CommitAddNode(parent, sig);
                    if (!id.IsValid) { Flash("invalid placement"); _ctl.EnterSelect(); onClose?.Invoke(); return; }
                    if (!string.IsNullOrWhiteSpace(comment)) _ctl.SetDescription(id, comment);
                    RebuildFromModel();
                    SetSelected(parent);
                    Flash("added " + (isField ? "attribute" : "operation"));
                }
                onClose?.Invoke();
            }

            float yBtn = -(h - 46f);
            MakeButton(panel, "OK", new Vector2(w - 198f, yBtn), new Vector2(84f, 34f),
                new Color(0.20f, 0.42f, 0.52f, 1f), Submit);
            MakeButton(panel, "Cancel", new Vector2(w - 104f, yBtn), new Vector2(88f, 34f),
                new Color(0.22f, 0.24f, 0.29f, 1f), () => { CloseMenu(); onClose?.Invoke(); });
            if (editing)
                MakeButton(panel, "Delete", new Vector2(16f, yBtn), new Vector2(92f, 34f),
                    new Color(0.45f, 0.18f, 0.12f, 1f),
                    () => { CloseMenu(); _ctl.Delete(existing); RebuildFromModel(); SetSelected(parent); Flash("deleted member"); onClose?.Invoke(); });

            FocusInput(nameInput);
        }

        // --- element editor (single screen: properties + fields + operations) ---

        private void ShowClassifierEditor(ElementId id, Vector2 screenPos)
        {
            if (!_model.TryGet(id, out var el)) return;
            CloseMenu();

            // Gather members.
            var attrs = new List<(ElementId id, string name)>();
            var ops = new List<(ElementId id, string name)>();
            foreach (var cid in el.ChildIds)
                if (_model.TryGet(cid, out var c))
                {
                    if (c.Kind == ElementKind.Field) attrs.Add((cid, c.Name));
                    else if (c.Kind == ElementKind.Function) ops.Add((cid, c.Name));
                }

            const int perRow = 4;
            const float chipW = 100f, chipH = 26f, chipGap = 6f, rowH = 28f;
            int langRows = (CommonLanguages.Length + perRow - 1) / perRow;
            const float descH = 72f; // multiline description input height
            float w = 480f;
            float h = 250f + langRows * (chipH + chipGap) + (el.Kind == ElementKind.Class ? 36f : 0f)
                      + 24f + descH + 12f
                      + 48f + attrs.Count * rowH + 48f + ops.Count * rowH + 60f;
            var panel = BeginModal(w, h, "Edit " + el.Kind + "   —   " + el.Name);

            float y = -50f;
            FormLabel(panel, "Name", ref y, w);
            var nameInput = MakeInput(panel, new Vector2(16f, y), w - 32f, el.Name, "TypeName");
            y -= 44f;

            FormLabel(panel, "Implementation language", ref y, w);
            var langInput = MakeInput(panel, new Vector2(16f, y), w - 32f, el.Language,
                "C# / Rust / Go / Java / Python / Node.js / Elixir…");
            y -= 40f;
            for (int i = 0; i < CommonLanguages.Length; i++)
            {
                var captured = CommonLanguages[i];
                float cx = 16f + (i % perRow) * (chipW + chipGap);
                float cy = y - (i / perRow) * (chipH + chipGap);
                MakeButton(panel, captured, new Vector2(cx, cy), new Vector2(chipW, chipH),
                    new Color(0.18f, 0.22f, 0.28f, 1f), () => langInput.text = captured);
            }
            y -= langRows * (chipH + chipGap) + 4f;

            FormLabel(panel, "Stereotype   («…» — overrides the derived one)", ref y, w);
            var stereoInput = MakeInput(panel, new Vector2(16f, y), w - 32f, el.Stereotype,
                "entity, service, controller, value…");
            y -= 44f;

            FormLabel(panel, "Description   (free text — fed to code generation)", ref y, w);
            var descInput = MakeMultilineInput(panel, new Vector2(16f, y), w - 32f, descH, el.Description,
                "What this element is / does…");
            y -= descH + 12f;

            Func<bool> getAbstract = () => el.IsAbstract;
            if (el.Kind == ElementKind.Class)
            {
                getAbstract = MakeCheckbox(panel, new Vector2(16f, y), "abstract", el.IsAbstract);
                y -= 36f;
            }

            // Commit the property fields (so edits aren't lost when jumping to a member sub-dialog).
            void ApplyProps()
            {
                string nn = string.IsNullOrWhiteSpace(nameInput.text) ? el.Name : nameInput.text.Trim();
                if (nn != el.Name) _ctl.Rename(id, nn);
                if (el.Kind == ElementKind.Class && getAbstract() != el.IsAbstract) _ctl.SetAbstract(id, getAbstract());
                _ctl.SetMeta(id, langInput.text, stereoInput.text);
                _ctl.SetDescription(id, descInput.text);
            }
            void Reopen() => ShowClassifierEditor(id, screenPos);

            var rowText = new Color(0.86f, 0.89f, 0.94f, 1f);
            var editCol = new Color(0.20f, 0.34f, 0.42f, 1f);
            var delCol = new Color(0.42f, 0.20f, 0.16f, 1f);
            var addCol = new Color(0.18f, 0.30f, 0.24f, 1f);

            void MemberSection(string title, List<(ElementId id, string name)> list, ElementKind kind)
            {
                bool canHave = ContainmentRules.CanContain(el.Kind, kind).IsValid;
                FormLabel(panel, title + (canHave ? "" : "  (not allowed for this kind)"), ref y, w);
                foreach (var m in list)
                {
                    var mid = m.id; var mkind = kind;
                    MakeText(panel, "• " + Ellipsize(m.name, 42), new Vector2(20f, y), new Vector2(w - 190f, 22f),
                        14, rowText, TextAnchor.MiddleLeft);
                    MakeButton(panel, "Edit", new Vector2(w - 164f, y), new Vector2(66f, 22f), editCol,
                        () => { ApplyProps(); ShowMemberEditor(id, mkind, mid, screenPos, Reopen); });
                    MakeButton(panel, "Del", new Vector2(w - 92f, y), new Vector2(60f, 22f), delCol,
                        () => { ApplyProps(); _ctl.Delete(mid); RebuildFromModel(); Reopen(); });
                    y -= rowH;
                }
                if (canHave)
                {
                    string verb = kind == ElementKind.Field ? "＋ Add attribute" : "＋ Add operation";
                    MakeButton(panel, verb, new Vector2(20f, y), new Vector2(160f, 26f), addCol,
                        () => { ApplyProps(); ShowMemberEditor(id, kind, ElementId.None, screenPos, Reopen); });
                    y -= 32f;
                }
            }

            MemberSection("Attributes (fields)", attrs, ElementKind.Field);
            MemberSection("Operations (methods)", ops, ElementKind.Function);

            void Submit()
            {
                CloseMenu();
                ApplyProps();
                RebuildFromModel();
                SetSelected(id);
                Flash("updated element");
            }

            float yBtn = -(h - 46f);
            MakeButton(panel, "OK", new Vector2(w - 198f, yBtn), new Vector2(84f, 34f),
                new Color(0.20f, 0.42f, 0.52f, 1f), Submit);
            MakeButton(panel, "Cancel", new Vector2(w - 104f, yBtn), new Vector2(88f, 34f),
                new Color(0.22f, 0.24f, 0.29f, 1f), CloseMenu);

            FocusInput(nameInput);
        }

        // --- style editor (color / font / size) ---

        private static readonly Color[] StylePalette =
        {
            new Color(1f, 1f, 1f, 1f), new Color(0.90f, 0.91f, 0.93f, 1f),
            new Color(0.99f, 0.96f, 0.74f, 1f), new Color(0.80f, 0.89f, 0.98f, 1f),
            new Color(0.80f, 0.93f, 0.82f, 1f), new Color(0.98f, 0.83f, 0.80f, 1f),
            new Color(0.90f, 0.84f, 0.96f, 1f), new Color(0.99f, 0.88f, 0.74f, 1f),
            new Color(0.45f, 0.48f, 0.54f, 1f), new Color(0.14f, 0.15f, 0.18f, 1f),
        };

        private static readonly string[] StyleFonts =
            { "(default)", "Arial", "Helvetica", "Courier New", "Verdana", "Georgia", "Times New Roman" };

        private void ShowStyleEditor(ElementId id, Vector2 screenPos)
        {
            if (!_model.TryGet(id, out var el)) return;
            CloseMenu();
            bool has = _styles.TryGetValue(id, out var cur);

            Color fill = has ? cur.Fill : new Color(1f, 1f, 1f, 1f);
            Color border = has ? cur.Border : new Color(0.42f, 0.45f, 0.51f, 1f);
            Color text = has ? cur.Text : new Color(0.13f, 0.15f, 0.19f, 1f);
            string fontName = has ? (cur.FontName ?? "") : "";
            int size = has && cur.FontSize > 0 ? cur.FontSize : 15;

            float w = 520f, h = 424f;
            var panel = BeginModal(w, h, "Style   —   " + (el.Kind == ElementKind.Note ? "Note" : el.Name));
            float y = -50f;

            y = SwatchRow(panel, "Fill", y, w, fill, c => fill = c);
            y = SwatchRow(panel, "Border / line", y, w, border, c => border = c);
            y = SwatchRow(panel, "Text", y, w, text, c => text = c);

            FormLabel(panel, "Font  (OS fonts; falls back to default)", ref y, w);
            var fontLabel = MakeText(panel, "current: " + (string.IsNullOrEmpty(fontName) ? "(default)" : fontName),
                new Vector2(w - 220f, y + 22f), new Vector2(204f, 18f), 12, LabelColor, TextAnchor.MiddleRight);
            float fx = 16f;
            foreach (var fn in StyleFonts)
            {
                var cap = fn;
                MakeButton(panel, fn, new Vector2(fx, y), new Vector2(66f, 26f),
                    new Color(0.18f, 0.22f, 0.28f, 1f),
                    () => { fontName = cap == "(default)" ? "" : cap; fontLabel.text = "current: " + cap; });
                fx += 70f;
            }
            y -= 34f;

            FormLabel(panel, "Font size", ref y, w);
            var sizeLabel = MakeText(panel, size.ToString(), new Vector2(70f, y), new Vector2(50f, 24f), 16,
                new Color(0.92f, 0.95f, 1f, 1f), TextAnchor.MiddleCenter);
            MakeButton(panel, "−", new Vector2(16f, y), new Vector2(42f, 24f), new Color(0.18f, 0.22f, 0.28f, 1f),
                () => { size = Mathf.Max(8, size - 1); sizeLabel.text = size.ToString(); });
            MakeButton(panel, "+", new Vector2(126f, y), new Vector2(42f, 24f), new Color(0.18f, 0.22f, 0.28f, 1f),
                () => { size = Mathf.Min(40, size + 1); sizeLabel.text = size.ToString(); });
            y -= 34f;

            void Submit()
            {
                CloseMenu();
                _styles[id] = new NodeStyle
                {
                    Has = true, Fill = fill, Border = border, Text = text,
                    FontName = string.IsNullOrEmpty(fontName) ? null : fontName, FontSize = size,
                };
                RebuildFromModel();
                SetSelected(id);
                Flash("styled");
            }

            float yBtn = -(h - 46f);
            MakeButton(panel, "Reset", new Vector2(16f, yBtn), new Vector2(92f, 34f),
                new Color(0.40f, 0.30f, 0.16f, 1f),
                () => { CloseMenu(); _styles.Remove(id); RebuildFromModel(); SetSelected(id); Flash("style reset"); });
            MakeButton(panel, "OK", new Vector2(w - 198f, yBtn), new Vector2(84f, 34f),
                new Color(0.20f, 0.42f, 0.52f, 1f), Submit);
            MakeButton(panel, "Cancel", new Vector2(w - 104f, yBtn), new Vector2(88f, 34f),
                new Color(0.22f, 0.24f, 0.29f, 1f), CloseMenu);
        }

        private float SwatchRow(RectTransform panel, string label, float y, float w, Color initial,
            Action<Color> onPick)
        {
            FormLabel(panel, label, ref y, w);
            var preview = MakeSwatch(panel, new Vector2(w - 46f, y + 22f), 26f, initial);
            float x = 16f;
            const float sw = 32f, gap = 6f;
            foreach (var c in StylePalette)
            {
                var cap = c;
                MakeButton(panel, "", new Vector2(x, y), new Vector2(sw, 26f), c,
                    () => { onPick(cap); preview.color = cap; });
                x += sw + gap;
            }
            // "Pick…" opens the HSV wheel for any colour beyond the presets. The preview swatch holds the live
            // value, so it doubles as the picker's starting colour and reflects whatever the picker commits.
            MakeButton(panel, "Pick…", new Vector2(x + 4f, y), new Vector2(70f, 26f),
                new Color(0.24f, 0.30f, 0.40f, 1f),
                () => ShowColorPicker(label, preview.color, c => { onPick(c); preview.color = c; }));
            return y - 34f;
        }

        private Image MakeSwatch(RectTransform parent, Vector2 topLeft, float size, Color c)
        {
            var go = new GameObject("Swatch", typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            rt.anchorMin = rt.anchorMax = new Vector2(0f, 1f);
            rt.pivot = new Vector2(0f, 1f);
            rt.sizeDelta = new Vector2(size, size);
            rt.anchoredPosition = topLeft;
            var img = go.AddComponent<Image>();
            img.color = c;
            img.raycastTarget = false;
            return img;
        }

        /// <summary>
        /// HSV colour picker popup, layered above the Style modal: an interactive hue/saturation wheel plus vertical
        /// Value (brightness) and Alpha sliders, with a live hex readout + preview swatch. It is its own dim backdrop
        /// parented to <c>_root</c> (a sibling of the Style modal, NOT the shared <c>_menu</c>), so closing it leaves
        /// the Style modal intact. <paramref name="commit"/> receives the picked colour on OK.
        /// </summary>
        private void ShowColorPicker(string channel, Color initial, Action<Color> commit)
        {
            // Decompose the starting colour into the H/S/V/A state the picker edits. Sliders compose with the wheel.
            Color.RGBToHSV(initial, out float hue, out float sat, out float val);
            float alpha = initial.a;

            // Dim backdrop — a sibling of the Style modal, tracked locally. The Image blocks pointer events from
            // reaching the Style modal / canvas underneath, but clicking the dim area does NOT close the picker:
            // it closes only via its own OK / Cancel buttons (a stray click must not discard the pick).
            var backdrop = new GameObject("ColorPickerBackdrop", typeof(RectTransform));
            var bdRt = (RectTransform)backdrop.transform;
            bdRt.SetParent(_root, false);
            Stretch(bdRt);
            var bdImg = backdrop.AddComponent<Image>();
            bdImg.color = new Color(0f, 0f, 0f, 0.45f);
            bdImg.raycastTarget = true; // swallow clicks on the dim area without dismissing

            void Close() { if (backdrop != null) Destroy(backdrop); }

            const float w = 320f, h = 380f;
            var panelGo = new GameObject("ColorPicker", typeof(RectTransform));
            var rt = (RectTransform)panelGo.transform;
            rt.SetParent(bdRt, false);
            rt.anchorMin = rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.sizeDelta = new Vector2(w, h);
            rt.anchoredPosition = Vector2.zero;
            panelGo.AddComponent<Image>().color = new Color(0.14f, 0.16f, 0.20f, 1f);

            MakeText(rt, "Pick colour   —   " + channel, new Vector2(16f, -12f), new Vector2(w - 32f, 24f), 16,
                new Color(0.86f, 0.90f, 0.96f, 1f), TextAnchor.MiddleLeft).fontStyle = FontStyle.Bold;

            // Hue/saturation wheel.
            var wheelGo = new GameObject("Wheel", typeof(RectTransform));
            var wheelRt = (RectTransform)wheelGo.transform;
            wheelRt.SetParent(rt, false);
            wheelRt.anchorMin = wheelRt.anchorMax = new Vector2(0f, 1f);
            wheelRt.pivot = new Vector2(0f, 1f);
            wheelRt.sizeDelta = new Vector2(180f, 180f);
            wheelRt.anchoredPosition = new Vector2(16f, -48f);
            var wheel = wheelGo.AddComponent<UmlColorWheelGraphic>();

            // Live preview swatch + hex readout (declared before the slider/wheel callbacks that update them).
            var preview = MakeSwatch(rt, new Vector2(16f, -240f), 40f, initial);
            preview.raycastTarget = false;
            var hexLabel = MakeText(rt, "", new Vector2(64f, -244f), new Vector2(w - 80f, 24f), 16,
                new Color(0.92f, 0.95f, 1f, 1f), TextAnchor.MiddleLeft);

            void Refresh()
            {
                var c = Color.HSVToRGB(hue, sat, val);
                c.a = alpha;
                preview.color = c;
                hexLabel.text = "#" + ColorUtility.ToHtmlStringRGBA(c);
            }

            wheel.OnHueSat = (newHue, newSat) => { hue = newHue; sat = newSat; Refresh(); };

            // Vertical Value (brightness) and Alpha sliders to the right of the wheel.
            MakeText(rt, "Value", new Vector2(214f, -48f), new Vector2(48f, 18f), 12,
                LabelColor, TextAnchor.MiddleCenter);
            MakeVerticalSlider(rt, new Vector2(224f, -70f), 22f, 150f, val, v => { val = v; Refresh(); });

            MakeText(rt, "Alpha", new Vector2(262f, -48f), new Vector2(48f, 18f), 12,
                LabelColor, TextAnchor.MiddleCenter);
            MakeVerticalSlider(rt, new Vector2(272f, -70f), 22f, 150f, alpha, a => { alpha = a; Refresh(); });

            Refresh();

            float yBtn = -(h - 46f);
            MakeButton(rt, "OK", new Vector2(w - 198f, yBtn), new Vector2(84f, 34f),
                new Color(0.20f, 0.42f, 0.52f, 1f),
                () => { var c = Color.HSVToRGB(hue, sat, val); c.a = alpha; commit(c); Close(); });
            MakeButton(rt, "Cancel", new Vector2(w - 104f, yBtn), new Vector2(88f, 34f),
                new Color(0.22f, 0.24f, 0.29f, 1f), Close);
        }

        /// <summary>A bottom-to-top <see cref="Slider"/> (0..1) styled to match the dialog chrome; reports live drags.</summary>
        private Slider MakeVerticalSlider(RectTransform parent, Vector2 topLeft, float width, float height,
            float value, Action<float> onChange)
        {
            var go = new GameObject("Slider", typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            rt.anchorMin = rt.anchorMax = new Vector2(0f, 1f);
            rt.pivot = new Vector2(0f, 1f);
            rt.sizeDelta = new Vector2(width, height);
            rt.anchoredPosition = topLeft;

            // Track background.
            var bg = go.AddComponent<Image>();
            bg.color = new Color(0.20f, 0.22f, 0.27f, 1f);

            // Fill (grows from the bottom as the value increases).
            var fillArea = new GameObject("Fill", typeof(RectTransform));
            var fillRt = (RectTransform)fillArea.transform;
            fillRt.SetParent(rt, false);
            Stretch(fillRt);
            var fillImg = fillArea.AddComponent<Image>();
            fillImg.color = new Color(0.30f, 0.55f, 0.66f, 1f);

            // Handle.
            var handle = new GameObject("Handle", typeof(RectTransform));
            var handleRt = (RectTransform)handle.transform;
            handleRt.SetParent(rt, false);
            handleRt.sizeDelta = new Vector2(width, 10f);
            var handleImg = handle.AddComponent<Image>();
            handleImg.color = new Color(0.86f, 0.90f, 0.96f, 1f);

            var slider = go.AddComponent<Slider>();
            slider.direction = Slider.Direction.BottomToTop;
            slider.fillRect = fillRt;
            slider.handleRect = handleRt;
            slider.targetGraphic = handleImg;
            slider.minValue = 0f;
            slider.maxValue = 1f;
            slider.value = Mathf.Clamp01(value);
            slider.onValueChanged.AddListener(v => onChange(v));
            return slider;
        }

        // --- note (comment) editor ---

        private void ShowNoteEditor(ElementId parent, ElementId existing, Vector2 screenPos)
        {
            CloseMenu();
            bool editing = existing.IsValid && _model.TryGet(existing, out _);
            string current = editing && _model.TryGet(existing, out var ex) ? ex.Name : "note";
            string currentDesc = editing && _model.TryGet(existing, out var exd) ? exd.Description : "";

            float w = 460f, h = 360f;
            var panel = BeginModal(w, h, editing ? "Edit Note" : "Add Note");

            float y = -50f;
            FormLabel(panel, "Note text", ref y, w);
            var input = MakeMultilineInput(panel, new Vector2(16f, y), w - 32f, 110f, current, "Free comment text…");
            y -= 122f;

            FormLabel(panel, "Description   (free text — fed to code generation)", ref y, w);
            var descInput = MakeMultilineInput(panel, new Vector2(16f, y), w - 32f, 72f, currentDesc,
                "What this note is about…");

            void Submit()
            {
                string txt = string.IsNullOrWhiteSpace(input.text) ? "note" : input.text;
                CloseMenu();
                if (editing)
                {
                    _ctl.Rename(existing, txt);
                    _ctl.SetDescription(existing, descInput.text);
                    RebuildFromModel();
                    SetSelected(existing);
                    Flash("updated note");
                }
                else
                {
                    _ctl.EnterAddNode(ElementKind.Note);
                    var id = _ctl.CommitAddNode(parent, txt);
                    if (!id.IsValid) { Flash("invalid placement"); _ctl.EnterSelect(); return; }
                    _ctl.SetDescription(id, descInput.text);
                    _pos[id] = ScreenToLayer(screenPos);
                    RebuildFromModel();
                    SetSelected(id);
                    Flash("added note");
                }
            }

            float yBtn = -(h - 46f);
            MakeButton(panel, "OK", new Vector2(w - 198f, yBtn), new Vector2(84f, 34f),
                new Color(0.20f, 0.42f, 0.52f, 1f), Submit);
            MakeButton(panel, "Cancel", new Vector2(w - 104f, yBtn), new Vector2(88f, 34f),
                new Color(0.22f, 0.24f, 0.29f, 1f), CloseMenu);

            FocusInput(input);
        }

