            MakeText(rt, label, new Vector2(8f, 0f), new Vector2(width - 12f, 23f), 14,
                new Color(0.90f, 0.93f, 0.98f, 1f), TextAnchor.MiddleLeft);
        }

        private RectTransform NewLayer(string name)
        {
            var go = new GameObject(name, typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(_root, false);
            Stretch(rt);
            return rt;
        }

        private static void Stretch(RectTransform rt)
        {
            rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;
            rt.offsetMin = Vector2.zero; rt.offsetMax = Vector2.zero;
        }

        private void CloseMenu() { if (_menu != null) Destroy(_menu); _menu = null; }

        private void CreateMenu(Vector2 screenPos, string header, List<MenuItem> items)
        {
            CloseMenu();
            const float w = 250f, ih = 32f, hh = 26f, pad = 6f;
            float h = hh + pad + items.Count * ih + pad;
            var go = NewPanel("Menu", screenPos, new Vector2(w, h), new Color(0.12f, 0.14f, 0.17f, 0.98f));
            var rt = (RectTransform)go.transform;
            _menu = go;

            var head = MakeText(rt, header, new Vector2(10f, -4f), new Vector2(w - 20f, hh), 15,
                new Color(0.55f, 0.61f, 0.71f, 1f), TextAnchor.MiddleLeft);
            head.fontStyle = FontStyle.Bold;

            float y = -(hh + pad);
            foreach (var item in items)
            {
                if (item.IsSeparator) { y -= 6f; continue; }
                MakeMenuButton(rt, item, new Vector2(4f, y), new Vector2(w - 8f, ih));
                y -= ih;
            }
        }

        private void ShowNamePrompt(string title, string template, System.Action<string> onSubmit)
        {
            CloseMenu();

            // Dim modal backdrop (click outside = cancel).
            var backdrop = new GameObject("PromptBackdrop", typeof(RectTransform));
            var bdRt = (RectTransform)backdrop.transform;
            bdRt.SetParent(_root, false);
            Stretch(bdRt);
            backdrop.AddComponent<Image>().color = new Color(0f, 0f, 0f, 0.45f);
            backdrop.AddComponent<UmlModalBackdrop>().Canvas = this;
            _menu = backdrop;

            const float w = 460f, h = 168f;
            var panel = new GameObject("NamePrompt", typeof(RectTransform));
            var rt = (RectTransform)panel.transform;
            rt.SetParent(bdRt, false);
            rt.anchorMin = rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.sizeDelta = new Vector2(w, h);
            rt.anchoredPosition = Vector2.zero;
            panel.AddComponent<Image>().color = new Color(0.14f, 0.16f, 0.20f, 1f);

            MakeText(rt, title, new Vector2(16f, -12f), new Vector2(w - 32f, 24f), 16,
                new Color(0.84f, 0.88f, 0.94f, 1f), TextAnchor.MiddleLeft).fontStyle = FontStyle.Bold;

            var inputGo = new GameObject("Input", typeof(RectTransform));
            var inRt = (RectTransform)inputGo.transform;
            inRt.SetParent(rt, false);
            inRt.anchorMin = inRt.anchorMax = new Vector2(0f, 1f);
            inRt.pivot = new Vector2(0f, 1f);
            inRt.sizeDelta = new Vector2(w - 32f, 38f);
            inRt.anchoredPosition = new Vector2(16f, -48f);
            inputGo.AddComponent<Image>().color = new Color(0.20f, 0.22f, 0.27f, 1f);
            var input = inputGo.AddComponent<InputField>();

            var textComp = MakeText(inRt, "", new Vector2(10f, 0f), new Vector2(w - 56f, 38f), 18,
                new Color(0.96f, 0.97f, 1f, 1f), TextAnchor.MiddleLeft);
            textComp.raycastTarget = true;
            var placeholder = MakeText(inRt, template, new Vector2(10f, 0f), new Vector2(w - 56f, 38f), 18,
                new Color(0.5f, 0.55f, 0.62f, 1f), TextAnchor.MiddleLeft);
            placeholder.fontStyle = FontStyle.Italic;

            input.textComponent = textComp;
            input.placeholder = placeholder;
            input.lineType = InputField.LineType.SingleLine;
            input.text = template; // prefill the editable template so the user tweaks rather than retypes

            void Submit()
            {
                var value = input.text;
                CloseMenu();
                onSubmit(string.IsNullOrWhiteSpace(value) ? template : value);
            }
            input.onSubmit.AddListener(_ => Submit());

            // OK button + Cancel.
            MakeButton(rt, "OK", new Vector2(w - 200f, -100f), new Vector2(84f, 34f),
                new Color(0.20f, 0.42f, 0.52f, 1f), Submit);
            MakeButton(rt, "Cancel", new Vector2(w - 108f, -100f), new Vector2(92f, 34f),
                new Color(0.22f, 0.24f, 0.29f, 1f), CloseMenu);

            MakeText(rt, "Convention: + public  - private  # protected  ~ package · types after ‘:’",
                new Vector2(16f, -140f), new Vector2(w - 32f, 18f), 12,
                new Color(0.5f, 0.55f, 0.62f, 1f), TextAnchor.MiddleLeft);

            if (EventSystem.current != null) EventSystem.current.SetSelectedGameObject(inputGo);
            input.ActivateInputField();
            input.MoveTextEnd(false);
        }

        private void MakeButton(RectTransform parent, string label, Vector2 topLeft, Vector2 size,
            Color color, System.Action onClick)
        {
            var go = new GameObject("Button:" + label, typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            rt.anchorMin = rt.anchorMax = new Vector2(0f, 1f);
            rt.pivot = new Vector2(0f, 1f);
            rt.sizeDelta = size;
            rt.anchoredPosition = topLeft;
            var img = go.AddComponent<Image>();
            img.color = color;
            var btn = go.AddComponent<Button>();
            btn.targetGraphic = img;
            btn.onClick.AddListener(() => onClick());
            MakeText(rt, label, Vector2.zero, size, 16, new Color(0.95f, 0.97f, 1f), TextAnchor.MiddleCenter);
        }

        private GameObject NewPanel(string name, Vector2 screenPos, Vector2 size, Color color)
        {
            var go = new GameObject(name, typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(_root, false);
            rt.anchorMin = rt.anchorMax = new Vector2(0f, 0f);
            rt.pivot = new Vector2(0f, 1f);
            rt.sizeDelta = size;
            rt.anchoredPosition = new Vector2(screenPos.x, screenPos.y) / ScaleFactor;
            go.AddComponent<Image>().color = color;
            return go;
        }

        private void MakeMenuButton(RectTransform parent, MenuItem item, Vector2 topLeft, Vector2 size)
        {
            var go = new GameObject("Item", typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            rt.anchorMin = rt.anchorMax = new Vector2(0f, 1f);
            rt.pivot = new Vector2(0f, 1f);
            rt.sizeDelta = size;
            rt.anchoredPosition = topLeft;
            var img = go.AddComponent<Image>();
            img.color = new Color(0.16f, 0.18f, 0.22f, item.Enabled ? 1f : 0.4f);
            if (item.Enabled && item.Action != null)
            {
                var btn = go.AddComponent<Button>();
                btn.targetGraphic = img;
                var act = item.Action;
                btn.onClick.AddListener(() => act());
            }
            MakeText(rt, item.Label, new Vector2(10f, 0f), new Vector2(size.x - 14f, size.y), 16,
                item.Enabled ? new Color(0.91f, 0.94f, 0.98f, 1f) : new Color(0.6f, 0.64f, 0.72f, 1f),
                TextAnchor.MiddleLeft);
        }

        private Text MakeText(RectTransform parent, string text, Vector2 topLeft, Vector2 size, int fontSize,
            Color color, TextAnchor align)
        {
            var go = new GameObject("Text", typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            rt.anchorMin = rt.anchorMax = new Vector2(0f, 1f);
            rt.pivot = new Vector2(0f, 1f);
            rt.sizeDelta = size;
            rt.anchoredPosition = topLeft;
            var t = go.AddComponent<Text>();
            t.font = _font; t.text = text; t.fontSize = fontSize; t.color = color; t.alignment = align;
            t.supportRichText = false; t.raycastTarget = false;
            return t;
        }

        private readonly struct MenuItem
        {
            public readonly string Label;
            public readonly bool Enabled;
            public readonly System.Action Action;
            public readonly bool IsSeparator;
            public MenuItem(string label, bool enabled, System.Action action)
            { Label = label; Enabled = enabled; Action = action; IsSeparator = false; }
            private MenuItem(bool sep) { Label = null; Enabled = false; Action = null; IsSeparator = sep; }
            public static MenuItem Separator() => new MenuItem(true);
        }
    }

    /// <summary>
    /// Full-canvas backdrop: empty-space clicks (add menu / deselect). A plain drag rubber-band-selects nodes;
    /// a Ctrl/Cmd-drag pans the diagram instead. The mode is latched at drag-start so a modifier released
    /// mid-drag doesn't switch gestures.
    /// </summary>
    public sealed class UmlBackground : MonoBehaviour,
        IPointerClickHandler, IBeginDragHandler, IDragHandler, IEndDragHandler
    {
        public UmlCanvas Canvas;
        private bool _panning; // latched at OnBeginDrag: true ⇒ pan, false ⇒ marquee

        public void OnPointerClick(PointerEventData eventData) => Canvas.OnBackgroundClick(eventData);

        public void OnBeginDrag(PointerEventData e)
        {
            _panning = UmlCanvas.CtrlOrCmd();
            if (_panning) Canvas.BeginPan();
            else Canvas.BeginMarquee(e.position);
        }

        public void OnDrag(PointerEventData e)
        {
            if (_panning) Canvas.PanBy(e.delta);
            else Canvas.UpdateMarquee(e.position);
        }

        public void OnEndDrag(PointerEventData e)
        {
            if (!_panning) Canvas.EndMarquee(e.position);
        }
    }

    /// <summary>Dim modal backdrop behind a property/member dialog: a click on the dim area cancels the dialog.</summary>
    /// <summary>
    /// The dim backdrop behind a modal property dialog. It exists only to BLOCK pointer events from reaching the
    /// canvas/nodes underneath — it intentionally does NOT dismiss the dialog on click. Property dialogs close
    /// only via their explicit OK / Cancel buttons (a stray click outside must not discard in-progress edits).
    /// </summary>
    public sealed class UmlModalBackdrop : MonoBehaviour, IPointerClickHandler
    {
        public UmlCanvas Canvas;
        // Swallow the click (so it doesn't fall through to the diagram) without closing the dialog.
        public void OnPointerClick(PointerEventData eventData) { }
    }

    /// <summary>A toolbar palette entry: click to add at center, or drag onto the canvas to drop a new node.</summary>
    public sealed class UmlPaletteItem : MonoBehaviour,
        IBeginDragHandler, IDragHandler, IEndDragHandler, IPointerClickHandler
    {
        public UmlCanvas Canvas;
        public ElementKind Kind;
        public string Label;

        public void OnBeginDrag(PointerEventData e) => Canvas.BeginPaletteDrag(Kind, Label);
        public void OnDrag(PointerEventData e) => Canvas.UpdatePaletteDrag(e.position);
        public void OnEndDrag(PointerEventData e) => Canvas.EndPaletteDrag(e.position);
        public void OnPointerClick(PointerEventData e) =>
            Canvas.CreateNodeFromPalette(Kind, new Vector2(Screen.width * 0.5f, Screen.height * 0.5f));
    }
}

using System;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace TheRobotDraft.Uml
{
    /// <summary>
    /// A procedural HSV hue/saturation disc, drawn at full value (V=1): hue runs around the rim, saturation runs
    /// from white at the centre to fully-saturated at the rim. The mesh is a triangle fan so it stays crisp at any
    /// size without a texture. Click or drag anywhere on the disc to pick a hue/saturation pair — the chosen value
    /// is reported through <see cref="OnHueSat"/> as (hue, saturation) both normalised to 0..1. Brightness (value)
    /// and alpha are not part of the disc; the style picker composes them with separate sliders.
    /// </summary>
    [RequireComponent(typeof(RectTransform))]
    public sealed class UmlColorWheelGraphic : Graphic, IPointerDownHandler, IDragHandler
    {
        private const int Segments = 48;

        /// <summary>Invoked with (hue, saturation) — both 0..1 — whenever the user clicks or drags on the disc.</summary>
        public Action<float, float> OnHueSat;

        /// <summary>Radius (in local units) of the rendered disc; the disc fills the RectTransform's smaller dimension.</summary>
        public float Radius
        {
            get
            {
                var r = rectTransform.rect;
                return Mathf.Min(r.width, r.height) * 0.5f;
            }
        }

        protected override void OnPopulateMesh(VertexHelper vh)
        {
            vh.Clear();

            var rect = rectTransform.rect;
            Vector2 center = rect.center;
            float radius = Mathf.Min(rect.width, rect.height) * 0.5f;
            if (radius <= 0f) return;

            // Centre vertex (index 0): full white = saturation 0 at V=1.
            var v = UIVertex.simpleVert;
            v.position = center;
            v.color = Color.white;
            vh.AddVert(v);

            // Rim vertices: hue = θ/2π, saturation 1, value 1.
            for (int i = 0; i <= Segments; i++)
            {
                float t = (float)i / Segments;     // 0..1 around the circle
                float theta = t * Mathf.PI * 2f;
                var rim = UIVertex.simpleVert;
                rim.position = new Vector3(
                    center.x + Mathf.Cos(theta) * radius,
                    center.y + Mathf.Sin(theta) * radius, 0f);
                rim.color = Color.HSVToRGB(Mathf.Repeat(t, 1f), 1f, 1f);
                vh.AddVert(rim);
            }

            // Triangle fan from the centre (vertex 0) to consecutive rim vertices (1..Segments+1).
            for (int i = 1; i <= Segments; i++)
                vh.AddTriangle(0, i, i + 1);
        }

        public void OnPointerDown(PointerEventData eventData) => PickFrom(eventData);

        public void OnDrag(PointerEventData eventData) => PickFrom(eventData);

        private void PickFrom(PointerEventData eventData)
        {
            if (OnHueSat == null) return;

            // Canvas is ScreenSpaceOverlay, so the event camera is null for the conversion.
            if (!RectTransformUtility.ScreenPointToLocalPointInRectangle(
                    rectTransform, eventData.position, eventData.pressEventCamera, out var local))
                return;

            var rect = rectTransform.rect;
            Vector2 center = rect.center;
            float radius = Mathf.Min(rect.width, rect.height) * 0.5f;
            if (radius <= 0f) return;

            Vector2 d = local - center;

            // Hue from the angle (atan2), normalised so 0° = red on the right and increases counter-clockwise,
            // matching the rim colours laid down in OnPopulateMesh.
            float angle = Mathf.Atan2(d.y, d.x);                 // -π..π
            float hue = Mathf.Repeat(angle / (Mathf.PI * 2f), 1f); // 0..1

            float sat = Mathf.Clamp01(d.magnitude / radius);

            OnHueSat(hue, sat);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using TheRobotDraft.Authoring.Model;

namespace TheRobotDraft.Uml
{
    /// <summary>End decoration for a relationship line, in standard UML notation.</summary>
    public enum EndMarker { None, OpenArrow, HollowTriangle, HollowDiamond, FilledDiamond, StickArrow }

    /// <summary>
    /// A standard-UML relationship drawn as an orthogonal (right-angle) polyline between two class boxes:
    /// solid or dashed, with the correct end markers (open arrow, hollow inheritance triangle, hollow/filled
    /// aggregation-composition diamond), a midpoint association label, and per-end multiplicities. The route is
    /// a list of points the canvas computes (auto-routed or via user bend handles); this view just draws one
    /// segment rect per leg and seats the markers/labels along the first and last legs. Left-click selects
    /// (the canvas shows bend handles); right-click / ctrl-click re-types, adorns, or deletes (§4.6).
    /// </summary>
    public sealed class UmlEdgeView : MonoBehaviour, IPointerClickHandler
    {
        public EdgeId Edge;
        public bool Interactive = true;

        private UmlCanvas _canvas;
        private readonly List<RectTransform> _segments = new();
        private readonly List<Image> _segImgs = new();
        private RectTransform _srcM, _tgtM;
        private RectTransform _midRt, _srcMultRt, _tgtMultRt;
        private Color _color;
        private bool _dashed;

        private const float Thickness = 3f;
        private const float MarkerSize = 16f;

        public void Init(UmlCanvas canvas, Font font, Color color, string midLabel, string sourceMult,
            string targetMult, bool dashed, EndMarker source, EndMarker target)
        {
            _canvas = canvas;
            _color = color;
            _dashed = dashed;
            Stretch((RectTransform)transform);

            _srcM = BuildMarker("SrcMarker", source, color);
            _tgtM = BuildMarker("TgtMarker", target, color);

            // Midpoint association name / role label, and per-end multiplicities (e.g. "1", "0..*").
            _midRt = BuildText("Label", midLabel, font, new Color(0.18f, 0.20f, 0.26f, 1f), 15, 170f);
            _srcMultRt = BuildText("SrcMult", sourceMult, font, new Color(0.22f, 0.24f, 0.30f, 1f), 14, 56f);
            _tgtMultRt = BuildText("TgtMult", targetMult, font, new Color(0.22f, 0.24f, 0.30f, 1f), 14, 56f);
        }

        /// <summary>Draw the relationship along an orthogonal polyline of at least two points.</summary>
        public void SetRoute(IReadOnlyList<Vector2> pts)
        {
            if (pts == null || pts.Count < 2) return;
            int segCount = pts.Count - 1;
            EnsureSegments(segCount);
            for (int i = 0; i < _segments.Count; i++)
            {
                bool used = i < segCount;
                if (_segments[i].gameObject.activeSelf != used) _segments[i].gameObject.SetActive(used);
                if (used) PlaceSeg(_segments[i], pts[i], pts[i + 1]);
            }

            Vector2 a = pts[0], a1 = pts[1];
            Vector2 b = pts[pts.Count - 1], b0 = pts[pts.Count - 2];
            Vector2 dirA = Norm(a1 - a), dirB = Norm(b - b0);
            const float half = MarkerSize * 0.5f;
            if (_srcM != null)
            {
                _srcM.anchoredPosition = a + dirA * half;
                _srcM.localEulerAngles = new Vector3(0f, 0f, Ang(dirA) + 180f);
            }
            if (_tgtM != null)
            {
                _tgtM.anchoredPosition = b - dirB * half;
                _tgtM.localEulerAngles = new Vector3(0f, 0f, Ang(dirB));
            }

            Vector2 perpA = new Vector2(-dirA.y, dirA.x), perpB = new Vector2(-dirB.y, dirB.x);
            if (_srcMultRt != null) _srcMultRt.anchoredPosition = a + dirA * 26f + perpA * 12f;
            if (_tgtMultRt != null) _tgtMultRt.anchoredPosition = b - dirB * 26f + perpB * 12f;
            if (_midRt != null)
            {
                int k = segCount / 2;
                Vector2 p = pts[k], q = pts[k + 1];
                Vector2 dir = Norm(q - p), perp = new Vector2(-dir.y, dir.x);
                _midRt.anchoredPosition = (p + q) * 0.5f + perp * 14f;
            }
        }

        /// <summary>Tint the line when the edge is the selection (its bend handles are live).</summary>
        public void SetHighlighted(bool on)
        {
            var c = on ? new Color(0.12f, 0.55f, 0.85f, 1f) : _color;
            foreach (var img in _segImgs) if (img != null) img.color = c;
        }

        public void OnPointerClick(PointerEventData eventData)
        {
            if (Interactive && _canvas != null) _canvas.OnEdgePointerClick(this, eventData);
        }

        // --- segments ---

        private void EnsureSegments(int count)
        {
            while (_segments.Count < count)
            {
                var rt = NewChild("Seg");
                var img = rt.gameObject.AddComponent<Image>();
                img.color = _color;
                img.raycastTarget = Interactive;
                if (_dashed) { img.sprite = DashSprite(); img.type = Image.Type.Tiled; }
                _segments.Add(rt);
                _segImgs.Add(img);
            }
        }

        private void PlaceSeg(RectTransform seg, Vector2 p, Vector2 q)
        {
            Vector2 d = q - p;
            float len = d.magnitude;
            seg.anchoredPosition = (p + q) * 0.5f;
            seg.sizeDelta = new Vector2(Mathf.Max(len, 1f), Thickness);
            seg.localEulerAngles = new Vector3(0f, 0f, Mathf.Atan2(d.y, d.x) * Mathf.Rad2Deg);
        }

        private static Vector2 Norm(Vector2 v) { float m = v.magnitude; return m > 0.001f ? v / m : Vector2.right; }
        private static float Ang(Vector2 d) => Mathf.Atan2(d.y, d.x) * Mathf.Rad2Deg;

        // --- markers ---

        private RectTransform BuildMarker(string name, EndMarker marker, Color color)
        {
            if (marker == EndMarker.None) return null;
            var rt = NewChild(name);
            rt.sizeDelta = new Vector2(MarkerSize, MarkerSize);
            var img = rt.gameObject.AddComponent<Image>();
            img.raycastTarget = false;

            switch (marker)
            {
                case EndMarker.OpenArrow:
                    img.sprite = TriangleSprite(); img.color = color; break;
                case EndMarker.StickArrow:
                    img.sprite = StickArrowSprite(); img.color = color; break;
                case EndMarker.HollowTriangle:
                    img.sprite = TriangleSprite(); img.color = new Color(0.95f, 0.96f, 0.97f, 1f);
                    AddOutline(rt.gameObject, color); break;
                case EndMarker.FilledDiamond:
                    img.sprite = DiamondSprite(); img.color = color; break;
                case EndMarker.HollowDiamond:
                    img.sprite = DiamondSprite(); img.color = new Color(0.95f, 0.96f, 0.97f, 1f);
                    AddOutline(rt.gameObject, color); break;
            }
            return rt;
        }

        private static void AddOutline(GameObject go, Color color)
        {
            var o = go.AddComponent<Outline>();
            o.effectColor = color;
            o.effectDistance = new Vector2(1.4f, 1.4f);
        }

        // --- procedural sprites (reliable across fonts; no glyph dependency) ---

        private static Sprite _dash, _triangle, _diamond, _stick;

        /// <summary>An open "stick" (line) arrowhead — the two strokes of an async / reply message head.</summary>
        private static Sprite StickArrowSprite()
        {
            if (_stick != null) return _stick;
            const int n = 18;
            var tex = new Texture2D(n, n, TextureFormat.RGBA32, false) { filterMode = FilterMode.Bilinear };
            // Chevron ">" pointing +x: apex at right-center, two strokes back to the left corners.
            Vector2 apex = new Vector2(n - 1.5f, n / 2f);
            Vector2 top = new Vector2(1.5f, n - 1.5f);
            Vector2 bot = new Vector2(1.5f, 1.5f);
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                {
                    var p = new Vector2(x + 0.5f, y + 0.5f);
                    float d = Mathf.Min(DistSeg(p, apex, top), DistSeg(p, apex, bot));
                    tex.SetPixel(x, y, d <= 1.6f ? Color.white : new Color(1, 1, 1, 0));
                }
            tex.Apply();
            _stick = Sprite.Create(tex, new Rect(0, 0, n, n), new Vector2(0.5f, 0.5f), n);
            return _stick;
        }

        private static float DistSeg(Vector2 p, Vector2 a, Vector2 b)
        {
            Vector2 ab = b - a;
            float len2 = ab.sqrMagnitude;
            float t = len2 < 1e-4f ? 0f : Mathf.Clamp01(Vector2.Dot(p - a, ab) / len2);
            return (p - (a + ab * t)).magnitude;
        }

        private static Sprite DashSprite()
        {
            if (_dash != null) return _dash;
            // 6px period (3 on / 3 off) at 100 ppu → fine dashes (the old 8ppu sprite tiled ~100px: far too coarse).
            var tex = new Texture2D(6, 1, TextureFormat.RGBA32, false)
                { wrapMode = TextureWrapMode.Repeat, filterMode = FilterMode.Point };
            for (int x = 0; x < 6; x++)
                tex.SetPixel(x, 0, x < 3 ? Color.white : new Color(1, 1, 1, 0));
            tex.Apply();
            _dash = Sprite.Create(tex, new Rect(0, 0, 6, 1), new Vector2(0.5f, 0.5f), 100f);
            return _dash;
        }

        private static Sprite TriangleSprite()
        {
            if (_triangle != null) return _triangle;
            const int n = 16;
            var tex = new Texture2D(n, n, TextureFormat.RGBA32, false);
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                {
                    // Triangle pointing +x: apex at right-center, base on the left edge.
                    float edge = n * (1f - Mathf.Abs(y - n / 2f) / (n / 2f));
                    tex.SetPixel(x, y, x <= edge ? Color.white : new Color(1, 1, 1, 0));
                }
            tex.Apply();
            _triangle = Sprite.Create(tex, new Rect(0, 0, n, n), new Vector2(0.5f, 0.5f), n);
            return _triangle;
        }

        private static Sprite DiamondSprite()
        {
            if (_diamond != null) return _diamond;
            const int n = 16;
            var tex = new Texture2D(n, n, TextureFormat.RGBA32, false);
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                {
                    float m = Mathf.Abs(x - n / 2f) / (n / 2f) + Mathf.Abs(y - n / 2f) / (n / 2f);
                    tex.SetPixel(x, y, m <= 1f ? Color.white : new Color(1, 1, 1, 0));
                }
            tex.Apply();
            _diamond = Sprite.Create(tex, new Rect(0, 0, n, n), new Vector2(0.5f, 0.5f), n);
            return _diamond;
        }

        // --- text + helpers ---

        private RectTransform BuildText(string name, string text, Font font, Color color, int size, float width)
        {
            if (string.IsNullOrEmpty(text)) return null;
            var rt = NewChild(name);
            rt.sizeDelta = new Vector2(width, 22f);
            var t = rt.gameObject.AddComponent<Text>();
            t.font = font;
            t.text = text;
            t.fontSize = size;
            t.alignment = TextAnchor.MiddleCenter;
            t.color = color;
            t.supportRichText = false;
            t.horizontalOverflow = HorizontalWrapMode.Overflow;
            t.verticalOverflow = VerticalWrapMode.Overflow;
            t.raycastTarget = false;
            return rt;
        }

        private RectTransform NewChild(string name)
        {
            var go = new GameObject(name, typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(transform, false);
            rt.anchorMin = rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 0.5f);
            return rt;
        }

        private static void Stretch(RectTransform rt)
        {
            rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;
            rt.offsetMin = Vector2.zero; rt.offsetMax = Vector2.zero;
        }
    }

    /// <summary>What an edge handle controls: a pinned endpoint, a movable bend, or an "insert bend here" spot.</summary>
    public enum UmlHandleKind { EndpointStart, EndpointEnd, Vertex, Add }

    /// <summary>
    /// A handle on the selected relationship. Endpoint handles re-pin where the line meets a box (drag anywhere on
    /// its border); Vertex handles move a bend (drag) or delete it (right-click); Add handles insert a new bend at
    /// a segment midpoint (click). The canvas owns the geometry; this relays the gesture.
    /// </summary>
    public sealed class UmlEdgeHandle : MonoBehaviour,
        IBeginDragHandler, IDragHandler, IEndDragHandler, IPointerClickHandler
    {
        private UmlCanvas _canvas;
        private EdgeId _edge;
        public UmlHandleKind Kind { get; private set; }
        public int Index { get; private set; }

        public void Init(UmlCanvas canvas, EdgeId edge, UmlHandleKind kind, int index, float size, Color color)
        {
            _canvas = canvas; _edge = edge; Kind = kind; Index = index;
            var rt = (RectTransform)transform;
            rt.anchorMin = rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.sizeDelta = new Vector2(size, size);
            gameObject.AddComponent<Image>().color = color;
        }

        public void SetPosition(Vector2 p) => ((RectTransform)transform).anchoredPosition = p;

        private bool Draggable => Kind != UmlHandleKind.Add;

        public void OnBeginDrag(PointerEventData e)
        {
            if (Draggable) _canvas.BeginEdgeHandleDrag(_edge, Kind, Index);
        }

        public void OnDrag(PointerEventData e)
        {
            if (Draggable) _canvas.DragEdgeHandle(e.position);
        }

        public void OnEndDrag(PointerEventData e)
        {
            if (Draggable) _canvas.EndEdgeHandleDrag();
        }

        public void OnPointerClick(PointerEventData e)
        {
            if (Kind == UmlHandleKind.Add) _canvas.AddVertex(_edge, Index);
            else if (Kind == UmlHandleKind.Vertex && e.button == PointerEventData.InputButton.Right)
                _canvas.DeleteVertex(_edge, Index);
        }
    }
}

using System.Diagnostics;
using System.IO;
using UnityEngine;

namespace TheRobotDraft.Uml
{
    /// <summary>
    /// Writes a diagram snapshot to disk and pushes it onto the OS clipboard as an image. On macOS the PNG is
    /// placed on the pasteboard via <c>osascript</c> (so it pastes straight into Keynote / Slack / docs); on
    /// other platforms the file path is copied instead (the system copy buffer is text-only there).
    /// </summary>
    public static class UmlImageClipboard
    {
        /// <summary>
        /// Save <paramref name="png"/> to a temp file and copy it to the clipboard. Returns a short status line
        /// suitable for the canvas hint (whether the image landed on the clipboard or only the path did).
        /// </summary>
        public static string SaveAndCopyToClipboard(byte[] png)
        {
            string path = Path.Combine(Application.temporaryCachePath, "trd-diagram.png");
            try { File.WriteAllBytes(path, png); }
            catch (System.Exception ex) { return "PNG save failed: " + ex.Message; }

            if (Application.platform == RuntimePlatform.OSXEditor
                || Application.platform == RuntimePlatform.OSXPlayer)
            {
                try
                {
                    // Read the file as PNG image data and set it as the clipboard contents. The «class PNGf»
                    // four-char-code tells AppleScript to treat the bytes as a PNG image, not as text.
                    string script = "set the clipboard to (read (POSIX file \"" + path + "\") as «class PNGf»)";
                    var psi = new ProcessStartInfo("osascript")
                    {
                        UseShellExecute = false,
                        CreateNoWindow = true,
                        RedirectStandardError = true,
                    };
                    psi.ArgumentList.Add("-e");
                    psi.ArgumentList.Add(script);
                    using (var proc = Process.Start(psi))
                    {
                        proc.WaitForExit();
                        if (proc.ExitCode == 0) return "copied diagram to clipboard (PNG)";
                    }
                }
                catch { /* fall through to the path-copy fallback below */ }
            }

            GUIUtility.systemCopyBuffer = path;
            return "saved PNG → " + path + " (path copied)";
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace TheRobotDraft.Uml
{
    /// <summary>
    /// The "this relationship continues on another z-layer" glyph: a small chevron (▲ above / ▼ below) seated at
    /// the far end of a cross-layer stub, where the off-layer endpoint has been culled (UmlCanvas Z-layer view).
    /// Drawn as a procedural triangle Image tinted the link color so it reads as part of the line. Clicking it
    /// jumps the canvas to the layer the hidden endpoint lives on, so the user can "follow" the connector.
    /// </summary>
    public sealed class UmlLayerMarker : MonoBehaviour, IPointerClickHandler
    {
        private UmlCanvas _canvas;
        private int _targetLayer;

        private const float Size = 18f;

        /// <summary>
        /// Build the chevron at <paramref name="pos"/> pointing up (<paramref name="up"/> = the other endpoint is
        /// on a higher layer) or down, tinted <paramref name="color"/>. Clicking jumps to <paramref name="targetLayer"/>.
        /// </summary>
        public void Init(UmlCanvas canvas, Vector2 pos, bool up, Color color, int targetLayer)
        {
            _canvas = canvas;
            _targetLayer = targetLayer;

            var rt = (RectTransform)transform;
            rt.anchorMin = rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.sizeDelta = new Vector2(Size, Size);
            rt.anchoredPosition = pos;
            // The base triangle sprite points +x (apex right); rotate so the apex points up (90°) or down (-90°).
            rt.localEulerAngles = new Vector3(0f, 0f, up ? 90f : -90f);

            var img = gameObject.AddComponent<Image>();
            img.sprite = ChevronSprite();
            img.color = color;
            img.raycastTarget = true; // clickable: jump to the off-layer endpoint's layer
        }

        public void OnPointerClick(PointerEventData e)
        {
            if (_canvas != null) _canvas.GoToLayer(_targetLayer);
        }

        // --- procedural chevron (a filled triangle apex; reused tinted as ▲ / ▼ via rotation) ---

        private static Sprite _chevron;

        private static Sprite ChevronSprite()
        {
            if (_chevron != null) return _chevron;
            const int n = 16;
            var tex = new Texture2D(n, n, TextureFormat.RGBA32, false);
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                {
                    // Triangle pointing +x: apex at right-center, base on the left edge (matches UmlEdgeView).
                    float edge = n * (1f - Mathf.Abs(y - n / 2f) / (n / 2f));
                    tex.SetPixel(x, y, x <= edge ? Color.white : new Color(1, 1, 1, 0));
                }
            tex.Apply();
            _chevron = Sprite.Create(tex, new Rect(0, 0, n, n), new Vector2(0.5f, 0.5f), n);
            return _chevron;
        }
    }
}

using System;
using System.Text;
using TheRobotDraft.Authoring.Model;

namespace TheRobotDraft.Uml
{
    /// <summary>UML member visibility (Rational Rose / Sparx EA "scope"): the leading glyph on an attribute or operation.</summary>
    public enum UmlVisibility { Public, Private, Protected, Package }

    public static class UmlVisibilityExt
    {
        public static char Glyph(this UmlVisibility v) => v switch
        {
            UmlVisibility.Public => '+',
            UmlVisibility.Private => '-',
            UmlVisibility.Protected => '#',
            UmlVisibility.Package => '~',
            _ => '+',
        };

        public static string Label(this UmlVisibility v) => v switch
        {
            UmlVisibility.Public => "+ public",
            UmlVisibility.Private => "- private",
            UmlVisibility.Protected => "# protected",
            UmlVisibility.Package => "~ package",
            _ => "+ public",
        };

        public static UmlVisibility FromGlyph(char c) => c switch
        {
            '+' => UmlVisibility.Public,
            '-' => UmlVisibility.Private,
            '#' => UmlVisibility.Protected,
            '~' => UmlVisibility.Package,
            _ => UmlVisibility.Public,
        };
    }

    /// <summary>
    /// The structured form of a member signature, decomposed from / composed to the canonical Rose/Sparx text
    /// convention the model stores verbatim in <see cref="ModelElement.Name"/> — e.g. <c>- balance : decimal</c>
    /// or <c>+ deposit(amount : decimal) : void {abstract}</c>. The view's structured editor builds and reads
    /// this so the user picks visibility/type/params from controls instead of hand-typing UML punctuation.
    /// </summary>
    public struct MemberParts
    {
        public UmlVisibility Visibility;
        public string Name;
        public string Type;        // attribute type, OR operation return type
        public string Parameters;  // operation only: "amount : decimal, note : string"
        public string DefaultValue; // attribute only: initial value after '='
        public bool IsStatic;
        public bool IsAbstract;

        /// <summary>Rose/Sparx defaults for a freshly added member: attributes are private, operations public.</summary>
        public static MemberParts ForNew(ElementKind kind) => new MemberParts
        {
            Visibility = kind == ElementKind.Field ? UmlVisibility.Private : UmlVisibility.Public,
            Name = kind == ElementKind.Field ? "field" : "operation",
            Type = kind == ElementKind.Field ? "" : "void",
            Parameters = "",
            DefaultValue = "",
        };
    }

    /// <summary>
    /// Compose / parse the canonical UML member signature string used by Rational Rose, Sparx EA, and most UML
    /// tools. Pure C# (no Unity dependency) so it unit-tests directly and round-trips through the editor.
    /// </summary>
    public static class UmlMemberSignature
    {
        public static string Compose(ElementKind kind, in MemberParts p)
        {
            var sb = new StringBuilder();
            string name = Safe(p.Name, kind == ElementKind.Field ? "field" : "operation");
            sb.Append(p.Visibility.Glyph()).Append(' ').Append(name);

            if (kind == ElementKind.Function)
            {
                sb.Append('(').Append((p.Parameters ?? "").Trim()).Append(')');
                string ret = (p.Type ?? "").Trim();
                // Convention (Rose / Sparx / Visual Paradigm): a void return is implied — show only non-void.
                if (ret.Length > 0 && !ret.Equals("void", StringComparison.OrdinalIgnoreCase))
                    sb.Append(" : ").Append(ret);
            }
            else
            {
                string type = (p.Type ?? "").Trim();
                if (type.Length > 0) sb.Append(" : ").Append(type);
                string def = (p.DefaultValue ?? "").Trim();
                if (def.Length > 0) sb.Append(" = ").Append(def);
            }

            string mods = Modifiers(p);
            if (mods.Length > 0) sb.Append(" {").Append(mods).Append('}');
            return sb.ToString();
        }

        private static string Modifiers(in MemberParts p)
        {
            if (p.IsStatic && p.IsAbstract) return "static, abstract";
            if (p.IsStatic) return "static";
            if (p.IsAbstract) return "abstract";
            return "";
        }

        public static MemberParts Parse(ElementKind kind, string signature)
        {
            var parts = MemberParts.ForNew(kind);
            if (string.IsNullOrWhiteSpace(signature)) return parts;
            string s = signature.Trim();

            // Trailing modifiers: {static, abstract}.
            int brace = s.IndexOf('{');
            if (brace >= 0)
            {
                int close = s.IndexOf('}', brace + 1);
                string inside = close > brace ? s.Substring(brace + 1, close - brace - 1) : s.Substring(brace + 1);
                parts.IsStatic = inside.IndexOf("static", StringComparison.OrdinalIgnoreCase) >= 0;
                parts.IsAbstract = inside.IndexOf("abstract", StringComparison.OrdinalIgnoreCase) >= 0;
                s = s.Substring(0, brace).Trim();
            }

            // Leading visibility glyph.
            if (s.Length > 0 && "+-#~".IndexOf(s[0]) >= 0)
            {
                parts.Visibility = UmlVisibilityExt.FromGlyph(s[0]);
                s = s.Substring(1).Trim();
            }

            if (kind == ElementKind.Function)
            {
                int open = s.IndexOf('(');
                if (open >= 0)
                {
                    parts.Name = s.Substring(0, open).Trim();
                    int close = s.IndexOf(')', open + 1);
                    if (close > open)
                    {
                        parts.Parameters = s.Substring(open + 1, close - open - 1).Trim();
                        string rest = s.Substring(close + 1).Trim();
                        if (rest.StartsWith(":")) parts.Type = rest.Substring(1).Trim();
                    }
                    else
                    {
                        parts.Parameters = s.Substring(open + 1).Trim();
                    }
                }
                else
                {
                    SplitNameType(s, ref parts); // no parens typed — tolerate "name : ret"
                }
            }
            else
            {
                int eq = s.IndexOf('=');
                if (eq >= 0)
                {
                    parts.DefaultValue = s.Substring(eq + 1).Trim();
                    s = s.Substring(0, eq).Trim();
                }
                SplitNameType(s, ref parts);
            }

            if (string.IsNullOrWhiteSpace(parts.Name))
                parts.Name = kind == ElementKind.Field ? "field" : "operation";
            return parts;
        }

        private static void SplitNameType(string s, ref MemberParts parts)
        {
            int colon = s.IndexOf(':');
            if (colon >= 0)
            {
                parts.Name = s.Substring(0, colon).Trim();
                parts.Type = s.Substring(colon + 1).Trim();
            }
            else
            {
                parts.Name = s.Trim();
            }
        }

        private static string Safe(string s, string fallback) =>
            string.IsNullOrWhiteSpace(s) ? fallback : s.Trim();
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using TheRobotDraft.Authoring.Model;

namespace TheRobotDraft.Uml
{
    /// <summary>
    /// A standard-UML classifier box (class / interface / enum / struct) with three compartments —
    /// stereotype+name, attributes (fields), operations (methods) — so members render <em>inside</em> the box,
    /// not as separate nodes. Ctrl/Cmd-drag the body to move it (a plain drag is reserved for the background
    /// marquee), the right-edge handle drags to draw a relationship (§4.1), and the bottom-right grip drags to
    /// resize. Left-click selects; Shift+left-click toggles the multi-selection; right-click opens the
    /// add-member / delete menu (§3.1).
    /// </summary>
    public sealed class UmlNodeView : MonoBehaviour,
        IPointerClickHandler, IBeginDragHandler, IDragHandler,
        IPointerEnterHandler, IPointerExitHandler
    {
        public ElementId Id;
        public RectTransform Rt { get; private set; }

        /// <summary>True for a use-case system boundary / region — it carries the nodes inside it when it moves.</summary>
        public bool IsBoundary { get; private set; }
        private System.Collections.Generic.List<ElementId> _carrying; // nodes captured inside a boundary at drag-start

        private UmlCanvas _canvas;
        private CanvasGroup _hotspots; // the four connect handles, revealed on hover
        private Graphic _bg;           // Image for boxes, UmlNoteGraphic (clipped corner) for notes
        private Outline _outline;   // selection highlight (toggled)
        private Outline _border;    // permanent thin box border (conventional UML look)
        private Color _baseColor;   // resting body fill, restored after affordance tinting
        private Color _textColor = new Color(0.13f, 0.15f, 0.19f, 1f);
        private int _memberSize = 15;

        public const float DefaultWidth = 220f;
        private const float RowH = 18f;

        public void Init(UmlCanvas canvas, ElementId id, string name, string stereotype, ElementKind kind,
            Color hue, Font font, System.Collections.Generic.List<string> attributes,
            System.Collections.Generic.List<string> operations, string language, NodeStyle style,
            Vector2 sizeOverride)
        {
            _canvas = canvas;
            Id = id;
            Rt = (RectTransform)transform;
            Rt.anchorMin = Rt.anchorMax = new Vector2(0.5f, 0.5f);
            Rt.pivot = new Vector2(0.5f, 0.5f);

            // Kind-derived defaults (conventional UML look), overridden by an explicit per-element style.
            bool note = kind == ElementKind.Note;
            bool shape = IsShapeKind(kind);
            bool titled = IsTitledBox(kind);
            bool boundary = kind == ElementKind.Boundary;
            bool frame = kind == ElementKind.Frame;
            bool profile = kind == ElementKind.Profile;
            bool lifeline = kind == ElementKind.Lifeline;
            bool timing = kind == ElementKind.TimingLifeline;
            // Boundaries, interaction frames and profiles are "regions" that carry nested nodes when moved.
            IsBoundary = boundary || frame || profile;
            bool darkFill = kind == ElementKind.Actor || kind == ElementKind.StateStart || kind == ElementKind.StateEnd
                || kind == ElementKind.ForkJoin || kind == ElementKind.Junction
                || kind == ElementKind.Terminate || kind == ElementKind.FlowFinal;
            Color defaultFill =
                note ? new Color(0.99f, 0.96f, 0.74f, 1f)
                : darkFill ? new Color(0.20f, 0.21f, 0.25f, 1f)
                : Color.Lerp(hue, Color.white, 0.88f);
            Color defaultBorder = note ? new Color(0.78f, 0.70f, 0.40f, 1f)
                                       : Color.Lerp(hue, new Color(0.25f, 0.27f, 0.32f, 1f), 0.55f);
            Color defaultText = note ? new Color(0.16f, 0.15f, 0.06f, 1f) : new Color(0.13f, 0.15f, 0.19f, 1f);

            _baseColor = style.Has ? style.Fill : defaultFill;
            _textColor = style.Has ? style.Text : defaultText;
            _memberSize = style.Has && style.FontSize > 0 ? style.FontSize : 15;
            int nameSize = style.Has && style.FontSize > 0 ? style.FontSize + 3 : 18;
            font_ = style.Has && !string.IsNullOrEmpty(style.FontName) ? ResolveFont(style.FontName) : font;

            if (note) _bg = gameObject.AddComponent<UmlNoteGraphic>();
            else if (shape)
            {
                var sg = gameObject.AddComponent<UmlShapeGraphic>();
                sg.Shape = ShapeFor(kind);
                _bg = sg;
            }
            else _bg = gameObject.AddComponent<Image>();
            _bg.color = _baseColor;

            _border = gameObject.AddComponent<Outline>();
            _border.effectColor = style.Has ? style.Border : defaultBorder;
            _border.effectDistance = new Vector2(1f, 1f);

            _outline = gameObject.AddComponent<Outline>();
            _outline.effectColor = new Color(0.12f, 0.55f, 0.85f, 1f);
            _outline.effectDistance = new Vector2(2.5f, 2.5f);
            _outline.enabled = false;

            if (note)
            {
                BuildNote(name, sizeOverride);
            }
            else if (shape)
            {
                BuildShape(kind, name, sizeOverride);
            }
            else if (boundary)
            {
                BuildBoundary(name, sizeOverride, 360f, 260f);
            }
            else if (frame)
            {
                BuildBoundary(name, sizeOverride, 280f, 180f);
            }
            else if (profile)
            {
                BuildBoundary(name, sizeOverride, 320f, 220f);
            }
            else if (lifeline)
            {
                BuildLifeline(name, sizeOverride);
            }
            else if (timing)
            {
                BuildTiming(name, sizeOverride);
            }
            else if (titled)
            {
                BuildTitledBox(kind, name, stereotype, sizeOverride);
            }
            else
            {
                float stereoH = string.IsNullOrEmpty(stereotype) ? 0f : 16f;
                float langH = string.IsNullOrEmpty(language) ? 0f : 14f;
                float headerH = 30f + stereoH + langH;
                float attrH = Mathf.Max(1, attributes.Count) * RowH + 6f;
                float opH = Mathf.Max(1, operations.Count) * RowH + 6f;
                float contentH = headerH + 2f + attrH + 2f + opH;

                float w = sizeOverride.x > 1f ? sizeOverride.x : DefaultWidth;
                float h = Mathf.Max(contentH, sizeOverride.y);
                Rt.sizeDelta = new Vector2(w, h);

                Color headerColor = style.Has ? Color.Lerp(style.Fill, Color.black, 0.10f)
                                              : Color.Lerp(hue, Color.white, 0.52f);
                var header = Panel("Header", 0f, headerH, headerColor);
                var nameColor = style.Has ? style.Text : new Color(0.11f, 0.12f, 0.15f, 1f);
                var subColor = style.Has ? Color.Lerp(style.Text, _baseColor, 0.35f)
                                         : new Color(0.30f, 0.32f, 0.38f, 1f);
                float ty = -4f;
                if (stereoH > 0f)
                {
                    Row(header, stereotype, ty, stereoH, 14, subColor, TextAnchor.MiddleCenter);
                    ty -= stereoH;
                }
                var nameRow = Row(header, name, ty, 28f, nameSize, nameColor, TextAnchor.MiddleCenter);
                nameRow.fontStyle = FontStyle.Bold;
                // An object-diagram instance underlines "name : Class" — the UML hallmark of an instance.
                if (kind == ElementKind.ObjectInstance)
                {
                    var ul = NewChild("NameUnderline", header);
                    ul.anchorMin = new Vector2(0.5f, 1f); ul.anchorMax = new Vector2(0.5f, 1f);
                    ul.pivot = new Vector2(0.5f, 1f);
                    ul.sizeDelta = new Vector2(Mathf.Min(w - 28f, name.Length * (nameSize * 0.56f) + 8f), 2f);
                    ul.anchoredPosition = new Vector2(0f, ty - 22f);
                    var uimg = ul.gameObject.AddComponent<Image>();
                    uimg.color = nameColor; uimg.raycastTarget = false;
                }
                ty -= 28f;
                if (langH > 0f)
                    Row(header, "{" + language + "}", ty, langH, 12, subColor, TextAnchor.MiddleCenter);

                float y = -headerH;
                Divider(y); y -= 2f;

                // Attributes compartment (fields).
                float ay = y;
                AddRows(attributes, ref ay, attrH);
                y -= attrH;
                Divider(y); y -= 2f;

                // Operations compartment (methods).
                AddRows(operations, ref y, opH);
            }

            // Four connect hotspots (§4.1 quick-handle), one per side — revealed on hover (CanvasGroup), and the
            // link leaves from the side you grab.
            var hotGo = new GameObject("Hotspots", typeof(RectTransform));
            var hotRt = (RectTransform)hotGo.transform;
            hotRt.SetParent(transform, false);
            hotRt.anchorMin = Vector2.zero; hotRt.anchorMax = Vector2.one;
            hotRt.offsetMin = Vector2.zero; hotRt.offsetMax = Vector2.zero;
            _hotspots = hotGo.AddComponent<CanvasGroup>();
            _hotspots.alpha = 0f;
            _hotspots.blocksRaycasts = false;
            foreach (BoxSide side in new[] { BoxSide.Left, BoxSide.Right, BoxSide.Top, BoxSide.Bottom })
            {
                var handleGo = new GameObject("ConnectHandle:" + side, typeof(RectTransform));
                handleGo.AddComponent<UmlConnectHandle>().Init(_canvas, this, side, hotRt);
            }
            // Dedicated resize grip in the bottom-right corner — shown on hover with the connect handles, so the
            // resize gesture is visually distinct from the body-move gesture. Fixed-size glyphs get no grip.
            if (ResizableKind(kind))
            {
                var gripGo = new GameObject("ResizeGrip", typeof(RectTransform));
                gripGo.AddComponent<UmlResizeHandle>().Init(this, hotRt);
            }
        }

        /// <summary>Glyph nodes whose size is fixed (markers / ports) — no resize grip.</summary>
        private static bool ResizableKind(ElementKind k) => k switch
        {
            ElementKind.StateStart or ElementKind.StateEnd or ElementKind.Junction or ElementKind.FlowFinal
                or ElementKind.Terminate or ElementKind.Port or ElementKind.History => false,
            _ => true,
        };

        public void OnPointerEnter(PointerEventData e)
        {
            if (_hotspots != null) { _hotspots.alpha = 1f; _hotspots.blocksRaycasts = true; }
        }

        public void OnPointerExit(PointerEventData e)
        {
            if (_hotspots != null) { _hotspots.alpha = 0f; _hotspots.blocksRaycasts = false; }
        }

        public const float BorderGrab = 9f; // px from the edge that begins a resize instead of a move

        public void SetSelected(bool on) { if (_outline != null) _outline.enabled = on; }

        public void SetAffordance(AffordanceTint tint)
        {
            if (_bg == null) return;
            _bg.color = tint switch
            {
                AffordanceTint.Valid => new Color(0.80f, 0.93f, 0.82f, 1f),
                AffordanceTint.Invalid => new Color(0.97f, 0.82f, 0.78f, 1f), // §5.1 vermillion-family (light)
                _ => _baseColor,
            };
        }

        // --- interaction ---

        public void OnPointerClick(PointerEventData e)
        {
            // Right-click → context menu. (Ctrl is now the drag-to-move modifier, no longer a menu trigger.)
            if (e.button == PointerEventData.InputButton.Right) { _canvas.ShowNodeMenu(Id, e.position); return; }
            if (e.button != PointerEventData.InputButton.Left) return;
            // Shift+left toggles this node in/out of the multi-selection; plain left selects just this node.
            if (Input.GetKey(KeyCode.LeftShift) || Input.GetKey(KeyCode.RightShift)) _canvas.ToggleSelection(Id);
            else _canvas.Select(this);
        }

        private bool _dragMoving;   // true only when the body drag began with Ctrl/Cmd held (move gesture)

        public void OnBeginDrag(PointerEventData e)
        {
            // A node only MOVES when Ctrl/Cmd is held at drag start; otherwise the body drag does nothing (so the
            // background marquee / plain selection gestures stay the default). A region captures the nodes nested
            // inside it so they travel along.
            _dragMoving = UmlCanvas.CtrlOrCmd();
            _carrying = (_dragMoving && IsBoundary) ? _canvas.NodesInside(this) : null;
        }

        public void OnDrag(PointerEventData e)
        {
            if (!_dragMoving) return; // click-to-select mode: the body doesn't move without Ctrl/Cmd
            // Divide by canvas scale AND diagram zoom so geometry tracks the cursor at any zoom level.
            Vector2 d = e.delta / (_canvas.ScaleFactor * _canvas.Zoom);
            Rt.anchoredPosition += d;
            _canvas.OnNodeMoved(Id, Rt.anchoredPosition);
            if (IsBoundary && _carrying != null) _canvas.MoveNodesBy(_carrying, d);
            // If this node is part of a multi-selection, carry the rest of the selection with it.
            if (_canvas.IsSelected(Id)) _canvas.MoveSelectionBy(d, Id);
        }

        /// <summary>Drag from the bottom-right grip: grow/shrink while keeping the top-left corner fixed.</summary>
        public void ResizeFromGrip(Vector2 screenDelta)
        {
            Vector2 d = screenDelta / (_canvas.ScaleFactor * _canvas.Zoom);
            Vector2 size = Rt.sizeDelta, pos = Rt.anchoredPosition;
            size.x += d.x; pos.x += d.x * 0.5f;   // right edge follows the cursor
            size.y -= d.y; pos.y += d.y * 0.5f;   // bottom edge follows the cursor
            // Low floor so anything can shrink back toward its glyph size.
            size.x = Mathf.Max(18f, size.x);
            size.y = Mathf.Max(14f, size.y);
            Rt.sizeDelta = size;
            Rt.anchoredPosition = pos;
            _canvas.OnNodeResized(Id, size);
            _canvas.OnNodeMoved(Id, pos);
        }

        // --- layout helpers ---

        private void AddRows(System.Collections.Generic.List<string> items, ref float y, float compartmentH)
        {
            if (items.Count == 0) { y -= compartmentH; return; }
            float top = y - 3f;
            foreach (var s in items)
            {
                Row(transform, s, top, RowH, _memberSize, _textColor, TextAnchor.MiddleLeft);
                top -= RowH;
            }
            y -= compartmentH;
        }

        private RectTransform Panel(string name, float topY, float height, Color color)
        {
            var rt = NewChild(name, transform);
            rt.anchorMin = new Vector2(0f, 1f); rt.anchorMax = new Vector2(1f, 1f);
            rt.pivot = new Vector2(0.5f, 1f);
            rt.sizeDelta = new Vector2(0f, height);
            rt.anchoredPosition = new Vector2(0f, topY);
            var img = rt.gameObject.AddComponent<Image>();
            img.color = color;
            img.raycastTarget = false;
            return rt;
        }

        private void Divider(float y)
        {
            var rt = NewChild("Divider", transform);
            rt.anchorMin = new Vector2(0f, 1f); rt.anchorMax = new Vector2(1f, 1f);
            rt.pivot = new Vector2(0.5f, 1f);
            rt.sizeDelta = new Vector2(0f, 2f);
            rt.anchoredPosition = new Vector2(0f, y);
            var img = rt.gameObject.AddComponent<Image>();
            img.color = new Color(0.66f, 0.68f, 0.73f, 1f);
            img.raycastTarget = false;
        }

        private Text Row(Transform parent, string text, float topY, float height, int fontSize,
            Color color, TextAnchor align)
        {
            var rt = NewChild("Row", parent);
            rt.anchorMin = new Vector2(0f, 1f); rt.anchorMax = new Vector2(1f, 1f);
            rt.pivot = new Vector2(0.5f, 1f);
            rt.sizeDelta = new Vector2(-20f, height);
            rt.anchoredPosition = new Vector2(0f, topY);
            var t = rt.gameObject.AddComponent<Text>();
            t.font = font_ ?? (font_ = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"));
            t.text = text;
            t.fontSize = fontSize;
            t.color = color;
            t.alignment = align;
            t.supportRichText = false;
            t.raycastTarget = false;
            t.horizontalOverflow = HorizontalWrapMode.Overflow;
            t.verticalOverflow = VerticalWrapMode.Overflow;
            return t;
        }

        // --- use-case / state-machine / activity / deployment shapes ---

        private static bool IsShapeKind(ElementKind k) => k switch
        {
            ElementKind.Actor or ElementKind.UseCase or ElementKind.State or ElementKind.Activity
                or ElementKind.StateStart or ElementKind.StateEnd or ElementKind.Decision
                or ElementKind.ForkJoin or ElementKind.Junction or ElementKind.History
                or ElementKind.Terminate or ElementKind.FlowFinal or ElementKind.DeploymentNode
                or ElementKind.Collaboration or ElementKind.PackageNode or ElementKind.Activation
                or ElementKind.Port or ElementKind.CallActivity => true,
            _ => false,
        };

        /// <summary>A box rendered as a single titled rectangle (stereotype + name), with no member compartments.</summary>
        private static bool IsTitledBox(ElementKind k) =>
            k == ElementKind.PrimitiveType || k == ElementKind.Component || k == ElementKind.Artifact
            || k == ElementKind.Part || k == ElementKind.Metaclass || k == ElementKind.Stereotype;

        private static UmlShape ShapeFor(ElementKind k) => k switch
        {
            ElementKind.UseCase or ElementKind.Collaboration => UmlShape.Ellipse,
            ElementKind.State or ElementKind.Activity or ElementKind.CallActivity => UmlShape.RoundedRect,
            ElementKind.StateStart or ElementKind.Junction => UmlShape.Disc,
            ElementKind.StateEnd => UmlShape.RingDisc,
            ElementKind.Decision => UmlShape.Diamond,
            ElementKind.ForkJoin or ElementKind.Activation or ElementKind.Port => UmlShape.Bar,
            ElementKind.History => UmlShape.Disc,
            ElementKind.Terminate => UmlShape.Cross,
            ElementKind.FlowFinal => UmlShape.FlowFinal,
            ElementKind.DeploymentNode => UmlShape.Cube,
            ElementKind.PackageNode => UmlShape.Folder,
            _ => UmlShape.Actor,
        };

        private void BuildShape(ElementKind kind, string name, Vector2 sizeOverride)
        {
            Vector2 def = kind switch
            {
                ElementKind.UseCase => new Vector2(168f, 78f),
                ElementKind.State => new Vector2(132f, 60f),
                ElementKind.Activity => new Vector2(150f, 54f),
                ElementKind.Actor => new Vector2(74f, 116f),
                ElementKind.StateStart => new Vector2(26f, 26f),
                ElementKind.StateEnd => new Vector2(30f, 30f),
                ElementKind.Junction => new Vector2(16f, 16f),
                ElementKind.Decision => new Vector2(82f, 56f),
                ElementKind.ForkJoin => new Vector2(120f, 14f),
                ElementKind.History => new Vector2(30f, 30f),
                ElementKind.Terminate => new Vector2(28f, 28f),
                ElementKind.FlowFinal => new Vector2(28f, 28f),
                ElementKind.DeploymentNode => new Vector2(156f, 96f),
                ElementKind.Collaboration => new Vector2(150f, 90f),
                ElementKind.PackageNode => new Vector2(150f, 96f),
                ElementKind.Activation => new Vector2(14f, 90f),
                ElementKind.Port => new Vector2(16f, 16f),
                ElementKind.CallActivity => new Vector2(160f, 60f),
                _ => new Vector2(120f, 60f),
            };
            float w = sizeOverride.x > 1f ? sizeOverride.x : def.x;
            float h = sizeOverride.y > 1f ? sizeOverride.y : def.y;
            Rt.sizeDelta = new Vector2(w, h);

            // Markers / control nodes carry no internal label (their meaning is the glyph).
            switch (kind)
            {
                case ElementKind.StateStart:
                case ElementKind.StateEnd:
                case ElementKind.Junction:
                case ElementKind.ForkJoin:
                case ElementKind.FlowFinal:
                case ElementKind.Terminate:
                case ElementKind.Decision:
                case ElementKind.Activation:
                case ElementKind.Port:
                    return;
                case ElementKind.History:
                    AddCenteredLabel("H", _memberSize + 4, FontStyle.Bold, new Color(0.13f, 0.15f, 0.19f, 1f));
                    return;
            }

            var rt = NewChild("Name", transform);
            var t = rt.gameObject.AddComponent<Text>();
            t.font = font_ ?? (font_ = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"));
            t.text = name;
            t.fontSize = _memberSize + 1;
            t.color = kind == ElementKind.Actor || kind == ElementKind.DeploymentNode
                ? new Color(0.13f, 0.15f, 0.19f, 1f) : _textColor;
            t.alignment = TextAnchor.MiddleCenter;
            t.supportRichText = false;
            t.raycastTarget = false;
            t.horizontalOverflow = HorizontalWrapMode.Wrap;
            t.verticalOverflow = VerticalWrapMode.Overflow;
            if (kind == ElementKind.Actor)
            {
                // Name below the stick figure.
                rt.anchorMin = new Vector2(0f, 0f); rt.anchorMax = new Vector2(1f, 0f);
                rt.pivot = new Vector2(0.5f, 0f);
                rt.sizeDelta = new Vector2(40f, 22f);
                rt.anchoredPosition = new Vector2(0f, 0f);
            }
            else if (kind == ElementKind.DeploymentNode)
            {
                // Inside the front face of the 3-D box (leave the top/right depth clear).
                rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;
                rt.offsetMin = new Vector2(12f, 8f); rt.offsetMax = new Vector2(-12f - CubeDepth, -8f - CubeDepth);
            }
            else if (kind == ElementKind.PackageNode)
            {
                // In the folder body, below the tab.
                rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;
                rt.offsetMin = new Vector2(12f, 6f); rt.offsetMax = new Vector2(-12f, -24f);
            }
            else
            {
                // Centered inside the ellipse / rounded rect.
                rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;
                rt.offsetMin = new Vector2(12f, 6f); rt.offsetMax = new Vector2(-12f, -6f);
            }

            // A call-behavior activity carries the rake icon in its lower-right corner.
            if (kind == ElementKind.CallActivity) AddRakeIcon();
        }

        /// <summary>The "rake" / trident glyph (⊐) marking a call-behavior activity, lower-right.</summary>
        private void AddRakeIcon()
        {
            var col = _textColor;
            void Bar(float x, float yTop, float w, float h)
            {
                var rt = NewChild("Rake", transform);
                rt.anchorMin = rt.anchorMax = new Vector2(1f, 0f); rt.pivot = new Vector2(1f, 0f);
                rt.sizeDelta = new Vector2(w, h); rt.anchoredPosition = new Vector2(x, yTop);
                var img = rt.gameObject.AddComponent<Image>(); img.color = col; img.raycastTarget = false;
            }
            Bar(-10f, 8f, 2f, 14f);   // spine
            Bar(-10f, 8f, 9f, 2f);    // bottom tine
            Bar(-10f, 14f, 9f, 2f);   // middle tine
            Bar(-10f, 20f, 9f, 2f);   // top tine
        }

        internal const float CubeDepth = 14f;

        private void AddCenteredLabel(string text, int size, FontStyle weight, Color color)
        {
            var rt = NewChild("Name", transform);
            rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;
            rt.offsetMin = Vector2.zero; rt.offsetMax = Vector2.zero;
            var t = rt.gameObject.AddComponent<Text>();
            t.font = font_ ?? (font_ = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"));
            t.text = text; t.fontSize = size; t.color = color; t.fontStyle = weight;
            t.alignment = TextAnchor.MiddleCenter; t.supportRichText = false; t.raycastTarget = false;
            t.horizontalOverflow = HorizontalWrapMode.Overflow; t.verticalOverflow = VerticalWrapMode.Overflow;
        }

        // --- titled box (component / artifact / primitive) ---

        private void BuildTitledBox(ElementKind kind, string name, string stereotype, Vector2 sizeOverride)
        {
            float w = sizeOverride.x > 1f ? sizeOverride.x : (kind == ElementKind.PrimitiveType ? 150f : 180f);
            float h = sizeOverride.y > 1f ? sizeOverride.y : 64f;
            Rt.sizeDelta = new Vector2(w, h);

            float ty = -8f;
            if (!string.IsNullOrEmpty(stereotype))
            {
                Row(transform, stereotype, ty, 16f, 13,
                    new Color(0.30f, 0.32f, 0.38f, 1f), TextAnchor.MiddleCenter);
                ty -= 18f;
            }
            var nameRow = Row(transform, name, ty, 24f, _memberSize + 2, _textColor, TextAnchor.MiddleCenter);
            nameRow.fontStyle = FontStyle.Bold;

            if (kind == ElementKind.Component) AddComponentIcon();
            else if (kind == ElementKind.Artifact) AddArtifactIcon();
        }

        /// <summary>The two-tab component icon, tucked into the top-right corner.</summary>
        private void AddComponentIcon()
        {
            var iconCol = _border != null ? _border.effectColor : new Color(0.3f, 0.33f, 0.4f, 1f);
            var body = NewChild("CompIcon", transform);
            body.anchorMin = body.anchorMax = new Vector2(1f, 1f);
            body.pivot = new Vector2(1f, 1f);
            body.sizeDelta = new Vector2(20f, 16f);
            body.anchoredPosition = new Vector2(-8f, -8f);
            var bimg = body.gameObject.AddComponent<Image>(); bimg.color = _baseColor; bimg.raycastTarget = false;
            var bout = body.gameObject.AddComponent<Outline>();
            bout.effectColor = iconCol; bout.effectDistance = new Vector2(1f, 1f);
            for (int i = 0; i < 2; i++)
            {
                var tab = NewChild("CompTab", transform);
                tab.anchorMin = tab.anchorMax = new Vector2(1f, 1f);
                tab.pivot = new Vector2(1f, 1f);
                tab.sizeDelta = new Vector2(8f, 4f);
                tab.anchoredPosition = new Vector2(-24f, -10f - i * 6f);
                var timg = tab.gameObject.AddComponent<Image>(); timg.color = _baseColor; timg.raycastTarget = false;
                var tout = tab.gameObject.AddComponent<Outline>();
                tout.effectColor = iconCol; tout.effectDistance = new Vector2(1f, 1f);
            }
        }

        /// <summary>A small folded-corner mark identifying an «artifact».</summary>
        private void AddArtifactIcon()
        {
            var iconCol = _border != null ? _border.effectColor : new Color(0.3f, 0.33f, 0.4f, 1f);
            var corner = NewChild("ArtifactIcon", transform);
            corner.anchorMin = corner.anchorMax = new Vector2(1f, 1f);
