        // --- use-case system boundary (frame) ---

        private void BuildBoundary(string name, Vector2 sizeOverride, float defW, float defH)
        {
            float w = sizeOverride.x > 1f ? sizeOverride.x : defW;
            float h = sizeOverride.y > 1f ? sizeOverride.y : defH;
            Rt.sizeDelta = new Vector2(w, h);

            // The body itself is click-through so use cases dropped on top stay interactive; the visible frame
            // is four thin bars (which double as resize edges), and a title chip near the top is the move grab.
            if (_bg != null) { _bg.color = new Color(0f, 0f, 0f, 0f); _bg.raycastTarget = false; }
            if (_border != null) _border.enabled = false;

            var frameCol = new Color(0.42f, 0.46f, 0.54f, 1f);
            FrameBar(new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, 2f), frameCol);   // top
            FrameBar(new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 2f), frameCol);   // bottom
            FrameBar(new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0.5f), new Vector2(2f, 0f), frameCol);   // left
            FrameBar(new Vector2(1f, 0f), new Vector2(1f, 1f), new Vector2(1f, 0.5f), new Vector2(2f, 0f), frameCol);   // right

            // Title chip (inset from the top edge so grabbing it moves rather than resizes).
            var chip = NewChild("BoundaryTitle", transform);
            chip.anchorMin = new Vector2(0f, 1f); chip.anchorMax = new Vector2(0f, 1f);
            chip.pivot = new Vector2(0f, 1f);
            chip.sizeDelta = new Vector2(Mathf.Min(w - 8f, name.Length * 9f + 24f), 24f);
            chip.anchoredPosition = new Vector2(6f, -6f);
            var cimg = chip.gameObject.AddComponent<Image>();
            cimg.color = new Color(0.16f, 0.18f, 0.22f, 0.9f); cimg.raycastTarget = true;
            var label = Row(chip, name, -2f, 20f, _memberSize, new Color(0.90f, 0.93f, 0.98f, 1f), TextAnchor.MiddleLeft);
            label.fontStyle = FontStyle.Bold;
        }

        private void FrameBar(Vector2 aMin, Vector2 aMax, Vector2 pivot, Vector2 thickness, Color color)
        {
            var rt = NewChild("Frame", transform);
            rt.anchorMin = aMin; rt.anchorMax = aMax; rt.pivot = pivot;
            rt.sizeDelta = thickness; rt.anchoredPosition = Vector2.zero;
            var img = rt.gameObject.AddComponent<Image>();
            img.color = color; img.raycastTarget = true; // routes pointer events to the parent UmlNodeView
        }

        // --- sequence-diagram lifeline ---

        private void BuildLifeline(string name, Vector2 sizeOverride)
        {
            float w = sizeOverride.x > 1f ? sizeOverride.x : 132f;
            float h = sizeOverride.y > 1f ? sizeOverride.y : 240f;
            Rt.sizeDelta = new Vector2(w, h);

            var borderCol = _border != null ? _border.effectColor : new Color(0.3f, 0.33f, 0.4f, 1f);
            // The whole column is grabbable, but only the head box + dashed life line are drawn.
            if (_bg != null) { _bg.color = new Color(0f, 0f, 0f, 0f); _bg.raycastTarget = true; }
            if (_border != null) _border.enabled = false;

            const float headH = 40f;
            var head = Panel("LifelineHead", 0f, headH, _baseColor);
            var hb = head.gameObject.AddComponent<Outline>();
            hb.effectColor = borderCol; hb.effectDistance = new Vector2(1f, 1f);

            var nameRow = Row(head, name, -9f, 22f, _memberSize, _textColor, TextAnchor.MiddleCenter);
            nameRow.fontStyle = FontStyle.Bold;
            // Instance underline (a lifeline head is an object).
            var ul = NewChild("LLUnderline", head);
            ul.anchorMin = new Vector2(0.5f, 1f); ul.anchorMax = new Vector2(0.5f, 1f); ul.pivot = new Vector2(0.5f, 1f);
            ul.sizeDelta = new Vector2(Mathf.Min(w - 16f, name.Length * (_memberSize * 0.56f) + 8f), 2f);
            ul.anchoredPosition = new Vector2(0f, -30f);
            var uimg = ul.gameObject.AddComponent<Image>(); uimg.color = _textColor; uimg.raycastTarget = false;

            // Dashed life line down the center (a horizontal dash sprite rotated 90° tiles vertically).
            var line = NewChild("LifeLine", transform);
            line.anchorMin = line.anchorMax = new Vector2(0.5f, 0.5f); line.pivot = new Vector2(0.5f, 0.5f);
            line.sizeDelta = new Vector2(h - headH, 2.5f);
            line.localEulerAngles = new Vector3(0f, 0f, 90f);
            line.anchoredPosition = new Vector2(0f, -headH * 0.5f);
            var limg = line.gameObject.AddComponent<Image>();
            limg.sprite = DashSprite(); limg.type = Image.Type.Tiled;
            limg.color = new Color(0.45f, 0.49f, 0.56f, 1f); limg.raycastTarget = false;
        }

        // --- timing diagram ---

        /// <summary>
        /// A timing lifeline: a named participant whose state is drawn as a stepped waveform across a time axis,
        /// with state lanes on the left. The waveform is illustrative scaffolding (the editor doesn't yet model
        /// the time series) — rename the node and resize it to taste.
        /// </summary>
        private void BuildTiming(string name, Vector2 sizeOverride)
        {
            float w = sizeOverride.x > 1f ? sizeOverride.x : 300f;
            float h = sizeOverride.y > 1f ? sizeOverride.y : 120f;
            Rt.sizeDelta = new Vector2(w, h);

            var axisCol = new Color(0.55f, 0.59f, 0.66f, 1f);
            var waveCol = _border != null ? _border.effectColor : new Color(0.25f, 0.45f, 0.70f, 1f);

            // Participant name, vertical along the left gutter would be ideal; keep it simple at top-left.
            var nameRow = Row(transform, name, -4f, 18f, _memberSize, _textColor, TextAnchor.UpperLeft);
            nameRow.fontStyle = FontStyle.Bold;

            const float gutter = 46f, padTop = 22f, padBot = 12f;
            int lanes = 3;
            string[] laneNames = { "S2", "S1", "S0" };
            float plotH = h - padTop - padBot;
            float laneH = plotH / lanes;

            // State lane labels + dashed gridlines.
            for (int i = 0; i < lanes; i++)
            {
                float yTop = -padTop - i * laneH;           // from the top edge, going down
                Row(transform, laneNames[i], yTop - laneH * 0.5f + 9f, 14f, _memberSize - 2,
                    new Color(0.45f, 0.49f, 0.56f, 1f), TextAnchor.MiddleLeft).rectTransform.sizeDelta =
                    new Vector2(gutter - 8f, 14f);
                HBar(new Vector2(gutter, yTop), w - gutter - 8f, 1f, new Color(axisCol.r, axisCol.g, axisCol.b, 0.5f));
            }
            // Baseline + axis.
            HBar(new Vector2(gutter, -h + padBot), w - gutter - 8f, 2f, axisCol);

            // Illustrative stepped waveform across the lanes.
            float x0 = gutter, x1 = w - 8f, span = x1 - x0;
            float[] steps = { 0f, 1f, 1f, 2f, 0f, 2f, 1f }; // lane index per segment
            int n = steps.Length;
            float prevY = -padTop - (lanes - 1 - (int)steps[0]) * laneH - laneH * 0.5f;
            for (int i = 0; i < n; i++)
            {
                float sx = x0 + span * (i / (float)n);
                float ex = x0 + span * ((i + 1) / (float)n);
                float y = -padTop - (lanes - 1 - (int)steps[i]) * laneH - laneH * 0.5f;
                if (i > 0 && Mathf.Abs(y - prevY) > 0.5f) VBar(new Vector2(sx, Mathf.Max(y, prevY)),
                    2f, Mathf.Abs(y - prevY), waveCol); // riser
                HBar(new Vector2(sx, y), ex - sx, 2f, waveCol);                                       // tread
                prevY = y;
            }
        }

        private void HBar(Vector2 topLeft, float width, float thickness, Color color)
        {
            var rt = NewChild("TBar", transform);
            rt.anchorMin = new Vector2(0f, 1f); rt.anchorMax = new Vector2(0f, 1f); rt.pivot = new Vector2(0f, 1f);
            rt.sizeDelta = new Vector2(width, thickness); rt.anchoredPosition = topLeft;
            var img = rt.gameObject.AddComponent<Image>(); img.color = color; img.raycastTarget = false;
        }

        private void VBar(Vector2 topLeft, float thickness, float height, Color color)
        {
            var rt = NewChild("TBar", transform);
            rt.anchorMin = new Vector2(0f, 1f); rt.anchorMax = new Vector2(0f, 1f); rt.pivot = new Vector2(0f, 1f);
            rt.sizeDelta = new Vector2(thickness, height); rt.anchoredPosition = topLeft;
            var img = rt.gameObject.AddComponent<Image>(); img.color = color; img.raycastTarget = false;
        }

        private static Sprite _dashSprite;

        private static Sprite DashSprite()
        {
            if (_dashSprite != null) return _dashSprite;
            var tex = new Texture2D(6, 1, TextureFormat.RGBA32, false)
                { wrapMode = TextureWrapMode.Repeat, filterMode = FilterMode.Point };
            for (int x = 0; x < 6; x++) tex.SetPixel(x, 0, x < 3 ? Color.white : new Color(1, 1, 1, 0));
            tex.Apply();
            _dashSprite = Sprite.Create(tex, new Rect(0, 0, 6, 1), new Vector2(0.5f, 0.5f), 100f);
            return _dashSprite;
        }

        // --- note (comment) rendering ---

        private void BuildNote(string text, Vector2 sizeOverride)
        {
            float w = sizeOverride.x > 1f ? sizeOverride.x : 220f;
            float h = sizeOverride.y > 1f ? sizeOverride.y : 96f;
            Rt.sizeDelta = new Vector2(w, h);
            // The dog-eared corner + clipped top-right are drawn by UmlNoteGraphic (the box mesh itself).

            // Free wrapped text filling the box (with padding).
            var bodyRt = NewChild("NoteText", transform);
            bodyRt.anchorMin = Vector2.zero; bodyRt.anchorMax = Vector2.one;
            bodyRt.offsetMin = new Vector2(8f, 6f); bodyRt.offsetMax = new Vector2(-8f, -6f);
            var t = bodyRt.gameObject.AddComponent<Text>();
            t.font = font_ ?? (font_ = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"));
            t.text = text;
            t.fontSize = _memberSize;
            t.color = _textColor;
            t.alignment = TextAnchor.UpperLeft;
            t.supportRichText = false;
            t.raycastTarget = false;
            t.horizontalOverflow = HorizontalWrapMode.Wrap;
            t.verticalOverflow = VerticalWrapMode.Overflow;
        }

        private Font font_;

        private static readonly System.Collections.Generic.Dictionary<string, Font> _fontCache = new();

        /// <summary>Resolve an OS font by name (cached); falls back to the built-in legacy font.</summary>
        private static Font ResolveFont(string name)
        {
            if (string.IsNullOrEmpty(name)) return Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            if (_fontCache.TryGetValue(name, out var cached) && cached != null) return cached;
            Font f = null;
            try { f = Font.CreateDynamicFontFromOSFont(name, 16); } catch { /* unknown OS font */ }
            if (f == null) f = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            _fontCache[name] = f;
            return f;
        }

        private static RectTransform NewChild(string name, Transform parent)
        {
            var go = new GameObject(name, typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            return rt;
        }
    }

    public enum AffordanceTint { None, Valid, Invalid }

    /// <summary>The four box sides a relationship can attach to / leave from.</summary>
    public enum BoxSide { Left, Right, Top, Bottom }

    /// <summary>An optional per-element visual override (fill / border / text color, font, size). Has=false → defaults.</summary>
    public struct NodeStyle
    {
        public bool Has;
        public Color Fill, Border, Text;
        public int FontSize;     // 0 = default
        public string FontName;  // null/empty = default legacy font
    }

    /// <summary>A per-side connect hotspot: drag from it to start a relationship that leaves from that side.</summary>
    public sealed class UmlConnectHandle : MonoBehaviour,
        IBeginDragHandler, IDragHandler, IEndDragHandler
    {
        private UmlCanvas _canvas;
        private UmlNodeView _node;
        private BoxSide _side;

        public void Init(UmlCanvas canvas, UmlNodeView node, BoxSide side, Transform parent)
        {
            _canvas = canvas; _node = node; _side = side;
            var rt = (RectTransform)transform;
            rt.SetParent(parent, false);
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.sizeDelta = new Vector2(15f, 15f);
            switch (side)
            {
                case BoxSide.Left:   rt.anchorMin = rt.anchorMax = new Vector2(0f, 0.5f); rt.anchoredPosition = new Vector2(2f, 0f); break;
                case BoxSide.Right:  rt.anchorMin = rt.anchorMax = new Vector2(1f, 0.5f); rt.anchoredPosition = new Vector2(-2f, 0f); break;
                case BoxSide.Top:    rt.anchorMin = rt.anchorMax = new Vector2(0.5f, 1f); rt.anchoredPosition = new Vector2(0f, -2f); break;
                default:             rt.anchorMin = rt.anchorMax = new Vector2(0.5f, 0f); rt.anchoredPosition = new Vector2(0f, 2f); break;
            }
            gameObject.AddComponent<Image>().color = new Color(0.30f, 0.85f, 0.95f, 1f);
        }

        public void OnBeginDrag(PointerEventData e) => _canvas.BeginLink(_node, _side, e.position);
        public void OnDrag(PointerEventData e) => _canvas.UpdateLink(e.position);
        public void OnEndDrag(PointerEventData e) => _canvas.EndLink(e.position);
    }

    /// <summary>The bottom-right resize grip: dragging it resizes the node (vs. the body, which moves).</summary>
    public sealed class UmlResizeHandle : MonoBehaviour, IBeginDragHandler, IDragHandler, IEndDragHandler
    {
        private UmlNodeView _node;

        public void Init(UmlNodeView node, Transform parent)
        {
            _node = node;
            var rt = (RectTransform)transform;
            rt.SetParent(parent, false);
            rt.anchorMin = rt.anchorMax = new Vector2(1f, 0f);
            rt.pivot = new Vector2(1f, 0f);
            rt.sizeDelta = new Vector2(14f, 14f);
            rt.anchoredPosition = new Vector2(-1f, 1f);
            var img = gameObject.AddComponent<Image>();
            img.color = new Color(0.95f, 0.62f, 0.18f, 1f); // orange grip, matches the edge endpoint handles
        }

        public void OnBeginDrag(PointerEventData e) { }
        public void OnDrag(PointerEventData e) => _node.ResizeFromGrip(e.delta);
        public void OnEndDrag(PointerEventData e) { }
    }

    /// <summary>
    /// A UML note background: a rectangle whose top-right corner is actually clipped off (a pentagon), with the
    /// folded-over flap drawn in a darker shade. Outline effects then trace the clipped silhouette.
    /// </summary>
    public sealed class UmlNoteGraphic : Graphic
    {
        public float Fold = 16f;

        protected override void OnPopulateMesh(VertexHelper vh)
        {
            vh.Clear();
            Rect r = GetPixelAdjustedRect();
            float f = Mathf.Min(Fold, Mathf.Min(r.width, r.height) * 0.5f);
            float xMin = r.xMin, xMax = r.xMax, yMin = r.yMin, yMax = r.yMax;

            Color32 body = color;
            Color32 flap = new Color(color.r * 0.86f, color.g * 0.86f, color.b * 0.82f, color.a);

            // Body pentagon (top-right corner removed), as a fan from the bottom-left.
            var p0 = new Vector2(xMin, yMin);
            var p1 = new Vector2(xMax, yMin);
            var p2 = new Vector2(xMax, yMax - f);
            var p3 = new Vector2(xMax - f, yMax);
            var p4 = new Vector2(xMin, yMax);
            Tri(vh, p0, p1, p2, body);
            Tri(vh, p0, p2, p3, body);
            Tri(vh, p0, p3, p4, body);

            // Folded flap inside the cut corner (darker).
            Tri(vh, p3, p2, new Vector2(xMax - f, yMax - f), flap);
        }

        private static void Tri(VertexHelper vh, Vector2 a, Vector2 b, Vector2 c, Color32 col)
        {
            int i = vh.currentVertCount;
            vh.AddVert(a, col, Vector2.zero);
            vh.AddVert(b, col, Vector2.zero);
            vh.AddVert(c, col, Vector2.zero);
            vh.AddTriangle(i, i + 1, i + 2);
        }
    }

    /// <summary>The procedural shapes used by non-class UML nodes.</summary>
    public enum UmlShape { Ellipse, RoundedRect, Disc, RingDisc, Actor, Diamond, Bar, FlowFinal, Cube, Cross, Folder }

    /// <summary>Draws use-case (ellipse), state (rounded rect), start/final markers (disc / ring), and actors (stick figure).</summary>
    public sealed class UmlShapeGraphic : Graphic
    {
        public UmlShape Shape = UmlShape.Ellipse;

        protected override void OnPopulateMesh(VertexHelper vh)
        {
            vh.Clear();
            Rect r = GetPixelAdjustedRect();
            Vector2 c = r.center;
            Color32 col = color;
            switch (Shape)
            {
                case UmlShape.Ellipse:
                    AddEllipse(vh, c, r.width * 0.5f, r.height * 0.5f, 44, col);
                    break;
                case UmlShape.Disc:
                {
                    float rad = Mathf.Min(r.width, r.height) * 0.5f;
                    AddEllipse(vh, c, rad, rad, 36, col);
                    break;
                }
                case UmlShape.RingDisc:
                {
                    float rad = Mathf.Min(r.width, r.height) * 0.5f;
                    AddRing(vh, c, rad, rad * 0.74f, 36, col);
                    AddEllipse(vh, c, rad * 0.5f, rad * 0.5f, 28, col);
                    break;
                }
                case UmlShape.RoundedRect:
                    AddRoundedRect(vh, r, Mathf.Min(16f, Mathf.Min(r.width, r.height) * 0.5f), col);
                    break;
                case UmlShape.Actor:
                    AddActor(vh, r, col);
                    break;
                case UmlShape.Diamond:
                    AddDiamond(vh, r, col);
                    break;
                case UmlShape.Bar:
                    AddQuad(vh, new Vector2(r.xMin, r.yMin), new Vector2(r.xMax, r.yMin),
                        new Vector2(r.xMax, r.yMax), new Vector2(r.xMin, r.yMax), col);
                    break;
                case UmlShape.FlowFinal:
                {
                    float rad = Mathf.Min(r.width, r.height) * 0.5f;
                    AddRing(vh, c, rad, rad - Mathf.Max(2.5f, rad * 0.14f), 32, col);
                    float d = rad * 0.5f;
                    AddLine(vh, new Vector2(c.x - d, c.y - d), new Vector2(c.x + d, c.y + d), 3f, col);
                    AddLine(vh, new Vector2(c.x - d, c.y + d), new Vector2(c.x + d, c.y - d), 3f, col);
                    break;
                }
                case UmlShape.Cross:
                {
                    float d = Mathf.Min(r.width, r.height) * 0.5f;
                    AddLine(vh, new Vector2(c.x - d, c.y - d), new Vector2(c.x + d, c.y + d), 3.5f, col);
                    AddLine(vh, new Vector2(c.x - d, c.y + d), new Vector2(c.x + d, c.y - d), 3.5f, col);
                    break;
                }
                case UmlShape.Cube:
                    AddCube(vh, r, UmlNodeView.CubeDepth, col);
                    break;
                case UmlShape.Folder:
                    AddFolder(vh, r, col);
                    break;
            }
        }

        /// <summary>A package "folder": a small tab on the upper-left, then the body rectangle below it.</summary>
        private static void AddFolder(VertexHelper vh, Rect r, Color32 col)
        {
            float tabH = Mathf.Min(18f, r.height * 0.22f);
            float tabW = Mathf.Min(r.width * 0.42f, 80f);
            float bodyTop = r.yMax - tabH;
            // Tab.
            AddQuad(vh, new Vector2(r.xMin, bodyTop), new Vector2(r.xMin + tabW, bodyTop),
                new Vector2(r.xMin + tabW, r.yMax), new Vector2(r.xMin, r.yMax), col);
            // Body.
            AddQuad(vh, new Vector2(r.xMin, r.yMin), new Vector2(r.xMax, r.yMin),
                new Vector2(r.xMax, bodyTop), new Vector2(r.xMin, bodyTop), col);
        }

        private static void AddQuad(VertexHelper vh, Vector2 a, Vector2 b, Vector2 cc, Vector2 d, Color32 col)
        {
            int i = vh.currentVertCount;
            vh.AddVert(a, col, Vector2.zero);
            vh.AddVert(b, col, Vector2.zero);
            vh.AddVert(cc, col, Vector2.zero);
            vh.AddVert(d, col, Vector2.zero);
            vh.AddTriangle(i, i + 1, i + 2);
            vh.AddTriangle(i, i + 2, i + 3);
        }

        private static void AddDiamond(VertexHelper vh, Rect r, Color32 col)
        {
            Vector2 c = r.center;
            var top = new Vector2(c.x, r.yMax);
            var right = new Vector2(r.xMax, c.y);
            var bottom = new Vector2(c.x, r.yMin);
            var left = new Vector2(r.xMin, c.y);
            AddQuad(vh, left, bottom, right, top, col);
        }

        /// <summary>A 3-D box (deployment node): front face plus a top and right face in shaded tints.</summary>
        private static void AddCube(VertexHelper vh, Rect r, float depth, Color32 col)
        {
            float d = Mathf.Min(depth, Mathf.Min(r.width, r.height) * 0.3f);
            float xMin = r.xMin, xMax = r.xMax, yMin = r.yMin, yMax = r.yMax;
            Color32 top = Shade(col, 1.10f);
            Color32 side = Shade(col, 0.86f);

            // Front face.
            var fA = new Vector2(xMin, yMin);
            var fB = new Vector2(xMax - d, yMin);
            var fC = new Vector2(xMax - d, yMax - d);
            var fD = new Vector2(xMin, yMax - d);
            AddQuad(vh, fA, fB, fC, fD, col);
            // Top face.
            AddQuad(vh, fD, fC, new Vector2(xMax, yMax), new Vector2(xMin + d, yMax), top);
            // Right face.
            AddQuad(vh, fB, new Vector2(xMax, yMin + d), new Vector2(xMax, yMax), fC, side);
        }

        private static Color32 Shade(Color32 c, float f) =>
            new Color(Mathf.Clamp01(c.r / 255f * f), Mathf.Clamp01(c.g / 255f * f), Mathf.Clamp01(c.b / 255f * f),
                c.a / 255f);

        private static void AddEllipse(VertexHelper vh, Vector2 c, float rx, float ry, int segs, Color32 col)
        {
            int center = vh.currentVertCount;
            vh.AddVert(c, col, Vector2.zero);
            for (int i = 0; i <= segs; i++)
            {
                float a = i / (float)segs * Mathf.PI * 2f;
                vh.AddVert(new Vector3(c.x + Mathf.Cos(a) * rx, c.y + Mathf.Sin(a) * ry), col, Vector2.zero);
            }
            for (int i = 0; i < segs; i++) vh.AddTriangle(center, center + 1 + i, center + 2 + i);
        }

        private static void AddRing(VertexHelper vh, Vector2 c, float rOut, float rIn, int segs, Color32 col)
        {
            int start = vh.currentVertCount;
            for (int i = 0; i <= segs; i++)
            {
                float a = i / (float)segs * Mathf.PI * 2f;
                float cs = Mathf.Cos(a), sn = Mathf.Sin(a);
                vh.AddVert(new Vector3(c.x + cs * rOut, c.y + sn * rOut), col, Vector2.zero);
                vh.AddVert(new Vector3(c.x + cs * rIn, c.y + sn * rIn), col, Vector2.zero);
            }
            for (int i = 0; i < segs; i++)
            {
                int o = start + i * 2;
                vh.AddTriangle(o, o + 1, o + 2);
                vh.AddTriangle(o + 1, o + 3, o + 2);
            }
        }

        private static void AddRoundedRect(VertexHelper vh, Rect r, float rad, Color32 col)
        {
            var pts = new System.Collections.Generic.List<Vector2>();
            const int seg = 6;
            void Corner(Vector2 cc, float start)
            {
                for (int i = 0; i <= seg; i++)
                {
                    float a = start + i / (float)seg * (Mathf.PI * 0.5f);
                    pts.Add(new Vector2(cc.x + Mathf.Cos(a) * rad, cc.y + Mathf.Sin(a) * rad));
                }
            }
            Corner(new Vector2(r.xMin + rad, r.yMin + rad), Mathf.PI);
            Corner(new Vector2(r.xMax - rad, r.yMin + rad), Mathf.PI * 1.5f);
            Corner(new Vector2(r.xMax - rad, r.yMax - rad), 0f);
            Corner(new Vector2(r.xMin + rad, r.yMax - rad), Mathf.PI * 0.5f);

            int ci = vh.currentVertCount;
            vh.AddVert(r.center, col, Vector2.zero);
            for (int i = 0; i < pts.Count; i++) vh.AddVert(pts[i], col, Vector2.zero);
            for (int i = 0; i < pts.Count; i++)
            {
                int n = (i + 1) % pts.Count;
                vh.AddTriangle(ci, ci + 1 + i, ci + 1 + n);
            }
        }

        private static void AddLine(VertexHelper vh, Vector2 a, Vector2 b, float th, Color32 col)
        {
            Vector2 d = (b - a).normalized;
            Vector2 n = new Vector2(-d.y, d.x) * (th * 0.5f);
            int i = vh.currentVertCount;
            vh.AddVert(a - n, col, Vector2.zero);
            vh.AddVert(a + n, col, Vector2.zero);
            vh.AddVert(b + n, col, Vector2.zero);
            vh.AddVert(b - n, col, Vector2.zero);
            vh.AddTriangle(i, i + 1, i + 2);
            vh.AddTriangle(i, i + 2, i + 3);
        }

        private static void AddActor(VertexHelper vh, Rect r, Color32 col)
        {
            float cx = r.center.x, top = r.yMax, bot = r.yMin;
            float headR = Mathf.Min(r.width * 0.20f, r.height * 0.12f);
            float headCy = top - headR - 2f;
            AddEllipse(vh, new Vector2(cx, headCy), headR, headR, 22, col);
            float th = Mathf.Max(2.5f, r.width * 0.05f);
            float bodyTop = headCy - headR;
            float bodyBot = bot + r.height * 0.36f;
            AddLine(vh, new Vector2(cx, bodyTop), new Vector2(cx, bodyBot), th, col);            // spine
            float armY = bodyTop - (bodyTop - bodyBot) * 0.28f;
            AddLine(vh, new Vector2(cx - r.width * 0.30f, armY), new Vector2(cx + r.width * 0.30f, armY), th, col); // arms
            AddLine(vh, new Vector2(cx, bodyBot), new Vector2(cx - r.width * 0.26f, bot + 2f), th, col); // left leg
            AddLine(vh, new Vector2(cx, bodyBot), new Vector2(cx + r.width * 0.26f, bot + 2f), th, col); // right leg
        }
    }
}

using UnityEngine;

namespace TheRobotDraft.Uml3D
{
    /// <summary>
    /// Shared constants and the model→world coordinate contract for the 3-D diagram scene. The flat uGUI
    /// renderer (<c>UmlCanvas</c>) lays nodes out in <em>UI pixels</em>; the 3-D scene multiplies those by
    /// <see cref="WorldScale"/> so a conventional 220-px class box becomes ≈2.2 world units wide. Z-layering
    /// (the bubble-view "below / behind" stacking) is expressed as an integer <c>layerDepth</c> — the signed
    /// distance from the active layer — multiplied by <see cref="LayerGap"/>. Keeping all of this in one place
    /// means the camera rig, node, edge and scene code agree on units without a translation step.
    /// </summary>
    public static class Uml3DConfig
    {
        /// <summary>One UI pixel maps to this many world units. A 220-px node ≈ 2.2 units wide.</summary>
        public const float WorldScale = 0.01f;

        /// <summary>Depth (Z thickness) of a node slab, in world units.</summary>
        public const float NodeThickness = 0.18f;

        /// <summary>World-Z distance between two adjacent bubble-view layers (active vs. one-below, etc.).</summary>
        public const float LayerGap = 3.0f;

        /// <summary>
        /// Convert a model-space pixel position plus a (signed) layer depth into a world position.
        /// <paramref name="layerDepth"/> is <c>activeLayer - nodeLayer</c>: 0 = the active/front layer, a
        /// positive value pushes the node back (below/behind) by that many <see cref="LayerGap"/> steps. The
        /// UI's +Y-is-up convention is preserved (no Y flip), so the 3-D layout reads the same as the flat one.
        /// </summary>
        public static Vector3 ModelToWorld(Vector2 posPx, int layerDepth) =>
            new Vector3(posPx.x * WorldScale, posPx.y * WorldScale, layerDepth * LayerGap);
    }
}

using System.Collections.Generic;
using UnityEngine;
using TheRobotDraft.Authoring.Model;

namespace TheRobotDraft.Uml3D
{
    /// <summary>
    /// The manager the integration layer drives to render a UML diagram as a real 3-D scene. It does <em>not</em>
    /// read the authoring model directly (<c>UmlCanvas</c> owns that); instead it exposes an imperative API:
    /// add / remove nodes and edges, raycast the scene to pick a node, and pass orbit / dolly / pan / frame
    /// commands through to its <see cref="UmlCameraRig"/>. On <see cref="Awake"/> it builds the rig (on a child),
    /// a <see cref="DiagramRoot"/> transform that all nodes/edges parent under, and a directional light so the lit
    /// node material is visible.
    /// </summary>
    public sealed class Uml3DScene : MonoBehaviour
    {
        /// <summary>Transform all nodes and edges parent under, so the whole diagram can be moved as one.</summary>
        public Transform DiagramRoot { get; private set; }

        /// <summary>The rig camera — for positioning 2-D overlay menus over nodes and for screenshots.</summary>
        public Camera Camera => _rig != null ? _rig.Cam : null;

        /// <summary>The camera rig, exposed for callers that need direct access to its state.</summary>
        public UmlCameraRig Rig => _rig;

        /// <summary>All live nodes, keyed by element id.</summary>
        public IReadOnlyDictionary<ElementId, UmlNode3D> Nodes => _nodes;

        private UmlCameraRig _rig;
        private Transform _nodeRoot, _edgeRoot;
        private readonly Dictionary<ElementId, UmlNode3D> _nodes = new();
        private readonly List<UmlEdge3D> _edges = new();
        private Light _light;

        private bool _initialized;

        private void Awake() => Init();

        /// <summary>Idempotent setup: rig, diagram root, node/edge roots and a fill light. Safe to call early.</summary>
        public void Init()
        {
            if (_initialized) return;
            _initialized = true;

            DiagramRoot = new GameObject("DiagramRoot").transform;
            DiagramRoot.SetParent(transform, false);

            _nodeRoot = new GameObject("Nodes").transform;
            _nodeRoot.SetParent(DiagramRoot, false);
            _edgeRoot = new GameObject("Edges").transform;
            _edgeRoot.SetParent(DiagramRoot, false);

            var rigGo = new GameObject("CameraRig");
            rigGo.transform.SetParent(transform, false);
            _rig = rigGo.AddComponent<UmlCameraRig>();
            _rig.Init();
            // Pleasant solid slate background; applied after the rig is built so this wins over any rig default.
            if (_rig.Cam != null)
            {
                _rig.Cam.clearFlags = CameraClearFlags.SolidColor;
                _rig.Cam.backgroundColor = new Color(0.70f, 0.73f, 0.78f, 1f); // light slate
            }

            EnsureLight();
        }

        /// <summary>
        /// Create our own directional light (this is a standalone-built app, so don't gate on whether the scene
        /// already has one) and raise ambient so the slab side/back faces aren't pure black. The face content is
        /// unlit uGUI and readable regardless, but the lit slab should still shade nicely.
        /// </summary>
        private void EnsureLight()
        {
            if (_light == null)
            {
                var go = new GameObject("UmlSceneLight");
                go.transform.SetParent(transform, false);
                _light = go.AddComponent<Light>();
                _light.type = LightType.Directional;
                _light.color = Color.white;
                _light.intensity = 1.1f;
                go.transform.rotation = Quaternion.Euler(50f, -30f, 0f);
            }

            // Soft ambient fill so unlit faces read as dark-gray rather than black. Guarded so it never throws
            // in batchmode / headless builds where the lighting subsystem may be unavailable.
            try
            {
                RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
                RenderSettings.ambientLight = new Color(0.35f, 0.37f, 0.40f, 1f);
            }
            catch (System.Exception)
            {
                // Ignore: ambient settings are a visual nicety, not required for correctness.
            }
        }

        // --- nodes ---

        /// <summary>Create and register a node (same arguments as <see cref="UmlNode3D.Init"/>).</summary>
        public UmlNode3D AddNode(ElementId id, string name, string stereotype, ElementKind kind, Color fill,
            Color text, List<string> attributes, List<string> operations, Vector2 sizePx)
        {
            Init();
            var go = new GameObject("Node:" + (id.Value ?? "?"));
            go.transform.SetParent(_nodeRoot, false);
            var node = go.AddComponent<UmlNode3D>();
            node.Init(id, name, stereotype, kind, fill, text, attributes, operations, sizePx);
            _nodes[id] = node;
            return node;
        }

        /// <summary>Destroy every node and clear the registry (edges are left untouched).</summary>
        public void RemoveAllNodes()
        {
            foreach (var kv in _nodes)
                if (kv.Value != null) Destroy(kv.Value.gameObject);
            _nodes.Clear();
        }

        /// <summary>Look up a live node by id.</summary>
        public bool TryGetNode(ElementId id, out UmlNode3D node) => _nodes.TryGetValue(id, out node);

        // --- edges ---

        /// <summary>Create and register a blank edge; call <see cref="UmlEdge3D.SetRoute"/> to draw it.</summary>
        public UmlEdge3D AddEdge()
        {
            Init();
            var go = new GameObject("Edge");
            go.transform.SetParent(_edgeRoot, false);
            var edge = go.AddComponent<UmlEdge3D>();
            _edges.Add(edge);
            return edge;
        }

        /// <summary>Destroy every edge.</summary>
        public void ClearEdges()
        {
            foreach (var e in _edges)
                if (e != null) Destroy(e.gameObject);
            _edges.Clear();
        }

        // --- picking ---

        /// <summary>
        /// Raycast the rig camera through <paramref name="screenPos"/> and return the hit <see cref="UmlNode3D"/>,
        /// or null. A collider hit maps to its node via <c>GetComponentInParent</c> (the collider lives on the
        /// node's slab child).
        /// </summary>
        public UmlNode3D Raycast(Vector2 screenPos)
        {
            if (_rig == null) return null;
            Ray ray = _rig.ScreenPointToRay(screenPos);
            if (Physics.Raycast(ray, out RaycastHit hit, 10000f))
                return hit.collider != null ? hit.collider.GetComponentInParent<UmlNode3D>() : null;
            return null;
        }

        // --- camera pass-throughs ---

        public void Orbit(float dYaw, float dPitch) => _rig?.Orbit(dYaw, dPitch);
        public void Dolly(float delta) => _rig?.Dolly(delta);
        public void PanPivot(Vector2 screenDelta) => _rig?.PanPivot(screenDelta);
        public Vector3 WorldToScreen(Vector3 world) => _rig != null ? _rig.WorldToScreen(world) : Vector3.zero;
        public Ray ScreenPointToRay(Vector2 screenPos) =>
            _rig != null ? _rig.ScreenPointToRay(screenPos) : new Ray(Vector3.zero, Vector3.forward);

        /// <summary>Compute the bounds of all node colliders and frame them in the camera.</summary>
        public void FrameAll()
        {
            if (_rig == null) return;
            bool any = false;
            Bounds b = new Bounds(Vector3.zero, Vector3.zero);
            foreach (var kv in _nodes)
            {
                var n = kv.Value;
                if (n == null) continue;
                var col = n.GetComponentInChildren<Collider>();
                if (col == null) continue;
                if (!any) { b = col.bounds; any = true; }
                else b.Encapsulate(col.bounds);
            }
            if (!any) b = new Bounds(DiagramRoot != null ? DiagramRoot.position : Vector3.zero, Vector3.one * 4f);
            _rig.Frame(b);
        }
    }
}

using UnityEngine;

namespace TheRobotDraft.Uml3D
{
    /// <summary>
    /// A full 6-DOF camera rig for the 3-D diagram. It owns a perspective <see cref="Camera"/> and recomputes
    /// its transform every <see cref="LateUpdate"/> from a small piece of state — <see cref="Yaw"/>,
    /// <see cref="Pitch"/>, <see cref="Roll"/>, <see cref="Distance"/> — around a focus <see cref="Pivot"/>.
    /// The camera sits on the +Z side of the pivot looking back toward −Z, so by convention it views the nodes'
    /// front (+Z) faces (where the text/content lives) at the default pose.
    /// The integration layer drives it imperatively through <see cref="Uml3DScene"/>: orbit on drag, dolly on
    /// scroll, pan with a modifier, roll with Q/E, free-fly translate with WASD/RF, and <see cref="Frame"/> to
    /// fit the whole diagram in view. Add it to a GameObject (it creates its own child camera in
    /// <see cref="Awake"/> if one isn't supplied) and it is immediately usable.
    /// </summary>
    public sealed class UmlCameraRig : MonoBehaviour
    {
        /// <summary>The perspective camera this rig drives. Created lazily if not assigned.</summary>
        public Camera Cam { get; private set; }

        /// <summary>World-space point the camera orbits and looks at.</summary>
        public Vector3 Pivot = Vector3.zero;

        /// <summary>Orbit angle around the world-up axis, in degrees.</summary>
        public float Yaw = 0f;

        /// <summary>Orbit elevation, in degrees, clamped to (<see cref="MinPitch"/>, <see cref="MaxPitch"/>).</summary>
        public float Pitch = 18f;

        /// <summary>Roll about the view axis, in degrees. Unclamped (wraps freely).</summary>
        public float Roll = 0f;

        /// <summary>Distance from <see cref="Pivot"/> to the camera, clamped to [<see cref="MinDistance"/>, <see cref="MaxDistance"/>].</summary>
        public float Distance = 12f;

        public const float MinPitch = -85f;
        public const float MaxPitch = 85f;
        public const float MinDistance = 1.5f;
        public const float MaxDistance = 400f;

        /// <summary>World units a pan moves the pivot per screen pixel (scaled by distance for a steady feel).</summary>
        private const float PanSpeed = 0.0016f;

        /// <summary>World units a free-fly move shifts the pivot per unit of <see cref="MoveLocal"/> input (scaled
        /// by distance). Callers typically pass Time.deltaTime-scaled deltas, so this reads as units/second/distance.</summary>
        private const float MoveSpeed = 1.6f;

        private void Awake()
        {
            EnsureCamera();
        }

        /// <summary>
        /// Optional explicit setup the scene manager may call after <c>AddComponent</c> — supply an existing
        /// camera (or null to have the rig create one) and seed the starting orbit pose.
        /// </summary>
        public void Init(Camera cam = null, Vector3? pivot = null, float? yaw = null, float? pitch = null,
            float? distance = null, float? roll = null)
        {
            if (cam != null) Cam = cam;
            EnsureCamera();
            if (pivot.HasValue) Pivot = pivot.Value;
            if (yaw.HasValue) Yaw = yaw.Value;
            if (pitch.HasValue) Pitch = pitch.Value;
            if (distance.HasValue) Distance = distance.Value;
            if (roll.HasValue) Roll = roll.Value;
            ApplyTransform();
        }

        private void EnsureCamera()
        {
            if (Cam != null) return;
            // Prefer a Camera already living on this rig's hierarchy; otherwise build one on a child object so
            // the rig GameObject itself stays a plain transform the scene manager can parent under DiagramRoot.
            Cam = GetComponentInChildren<Camera>();
            if (Cam == null)
            {
                var camGo = new GameObject("UmlCamera");
                camGo.transform.SetParent(transform, false);
                Cam = camGo.AddComponent<Camera>();
            }
            Cam.orthographic = false;
            Cam.fieldOfView = 50f;
            Cam.nearClipPlane = 0.05f;
            Cam.farClipPlane = 1000f;
        }

        // --- imperative controls ---

        /// <summary>Rotate the orbit by the given yaw/pitch deltas (degrees); pitch is clamped. Composes with the
        /// current roll because <see cref="ApplyTransform"/> rebuilds the whole orientation from Yaw/Pitch/Roll.</summary>
        public void Orbit(float dYaw, float dPitch)
        {
            Yaw += dYaw;
            Pitch = Mathf.Clamp(Pitch + dPitch, MinPitch, MaxPitch);
        }

        /// <summary>Roll the camera about its own view axis by the given delta (degrees); unclamped (wraps).</summary>
        public void RollBy(float deg)
        {
            Roll += deg;
        }

        /// <summary>
        /// Fly the camera by translating the focus <see cref="Pivot"/> along the camera's own axes:
        /// <paramref name="localDelta"/>.x = right, .y = up, .z = forward (toward what the camera looks at). The
        /// camera follows because it is recomputed from the pivot each <see cref="LateUpdate"/>, so this moves the
        /// whole rig through the scene rather than orbiting a fixed point. Scaled by distance for a steady feel.</summary>
        public void MoveLocal(Vector3 localDelta)
        {
            EnsureCamera();
            float k = MoveSpeed * Distance;
            // Use the camera's actual axes so motion matches the (non-mirrored) view. Forward is the look
            // direction, so a positive localDelta.z flies into the scene.
            Pivot += Cam.transform.right * (localDelta.x * k);
            Pivot += Cam.transform.up * (localDelta.y * k);
            Pivot += Cam.transform.forward * (localDelta.z * k);
        }

        /// <summary>
        /// Move the camera toward (positive) or away from (negative) the pivot. The step scales with the
        /// current distance so zooming feels uniform whether near or far.
        /// </summary>
        public void Dolly(float delta)
        {
            Distance = Mathf.Clamp(Distance - delta * Distance * 0.1f, MinDistance, MaxDistance);
        }

        /// <summary>
        /// Slide the focus pivot in the plane facing the camera by a screen-space delta (right = camera right,
        /// up = camera up). The amount scales with distance so a drag covers a consistent fraction of the view.
        /// </summary>
        public void PanPivot(Vector2 screenDelta)
        {
            Quaternion rot = Orientation();
            Vector3 right = rot * Vector3.right;
            Vector3 up = rot * Vector3.up;
            float k = PanSpeed * Distance;
            Pivot -= right * (screenDelta.x * k);
            Pivot -= up * (screenDelta.y * k);
        }

        /// <summary>Center the pivot on <paramref name="worldBounds"/> and back the camera off to fit it in view.</summary>
        public void Frame(Bounds worldBounds)
        {
            Pivot = worldBounds.center;
            float radius = Mathf.Max(0.5f, worldBounds.extents.magnitude);
            EnsureCamera();
            // Distance that fits the bounding sphere in the smaller of the vertical / horizontal FOV, with margin.
            float vFov = Cam.fieldOfView * Mathf.Deg2Rad;
            float hFov = 2f * Mathf.Atan(Mathf.Tan(vFov * 0.5f) * Mathf.Max(0.0001f, Cam.aspect));
            float fov = Mathf.Min(vFov, hFov);
            float fit = radius / Mathf.Max(0.05f, Mathf.Sin(fov * 0.5f));
            Distance = Mathf.Clamp(fit * 1.15f, MinDistance, MaxDistance);
        }

        // --- queries delegated to the camera ---

        /// <summary>A world-space ray from the rig camera through the given screen point.</summary>
        public Ray ScreenPointToRay(Vector2 screenPos)
        {
            EnsureCamera();
            return Cam.ScreenPointToRay(screenPos);
        }

        /// <summary>Project a world position to screen-space pixels (for placing 2-D overlay menus over a node).</summary>
        public Vector3 WorldToScreen(Vector3 world)
        {
            EnsureCamera();
            return Cam.WorldToScreenPoint(world);
        }

        private void LateUpdate()
        {
            ApplyTransform();
        }

        /// <summary>The rig's full orientation (yaw, pitch, AND roll). The camera transform and every axis-relative
        /// motion (pan / free-fly) derive from this so roll is honored consistently.</summary>
        private Quaternion Orientation() => Quaternion.Euler(Pitch, Yaw, Roll);

        /// <summary>Recompute the camera position/orientation from the current 6-DOF state.</summary>
        private void ApplyTransform()
        {
            if (Cam == null) return;
            Quaternion rot = Orientation();
            // Sit on the +Z side of the pivot so the camera looks back toward −Z — i.e. it faces the nodes' front
            // (+Z) content faces by convention.
            Vector3 pos = Pivot + rot * new Vector3(0f, 0f, Distance);
            // Aim the camera at the pivot with a proper look-rotation (NOT a 180° yaw flip — that mirrors the X
            // axis and renders all text reversed). The rolled up-vector (rot * up) carries pitch/yaw/roll through.
            Vector3 fwd = Pivot - pos;
            if (fwd.sqrMagnitude < 1e-6f) fwd = Vector3.forward;
            Quaternion camRot = Quaternion.LookRotation(fwd.normalized, rot * Vector3.up);
            Cam.transform.SetPositionAndRotation(pos, camRot);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace TheRobotDraft.Uml3D
{
    /// <summary>
    /// A relationship drawn in 3-D as a world-space polyline (a <see cref="LineRenderer"/>) following a route the
    /// integration layer computes. The 3-D counterpart of <c>UmlEdgeView</c>'s segment chain: <see cref="SetRoute"/>
    /// feeds it the world points and a color; <see cref="SetArrow"/> toggles a small cone arrowhead at the last
    /// point, oriented along the final segment. Dashed relationship kinds (dependency, realization, «include»/«extend»,
    /// note anchors, reply messages) draw with true dashes via a tiled 1-px dash texture on the line material; the
    /// tiling is scaled to the route's total world length so dash density is uniform regardless of length.
    /// </summary>
    public sealed class UmlEdge3D : MonoBehaviour
    {
        private LineRenderer _line;
        private Material _lineMaterial;
        private Transform _arrow;          // cone mesh at the target end
        private MeshRenderer _arrowRenderer;
        private Material _arrowMaterial;
        private Vector3 _lastPoint, _lastDir = Vector3.forward;
        private Color _color = Color.gray;
        private bool _dashed;              // whether the current route renders with the tiled dash texture

        private const float LineWidth = 0.03f;
        private const float ArrowLength = 0.22f;
        private const float ArrowRadius = 0.09f;
        // World-space length of one dash+gap cycle; the dash texture is tiled once per this many world units.
        private const float DashPeriod = 0.18f;

        // A shared 1-px-tall horizontal dash strip (opaque run + transparent gap), tiled along the line.
        private static Texture2D _dashTex;
        private static readonly int MainTexId = Shader.PropertyToID("_MainTex");
        private static readonly int BaseMapId = Shader.PropertyToID("_BaseMap");

        private void EnsureLine()
        {
            if (_line != null) return;
            _line = gameObject.GetComponent<LineRenderer>();
            if (_line == null) _line = gameObject.AddComponent<LineRenderer>();
            _line.useWorldSpace = true;
            _line.widthMultiplier = LineWidth;
            _line.numCornerVertices = 2;
            _line.numCapVertices = 2;
            _line.alignment = LineAlignment.View;
            _line.textureMode = LineTextureMode.Tile;
            _lineMaterial = MakeMaterial(_color);
            _line.sharedMaterial = _lineMaterial;
        }

        /// <summary>Lay the relationship along <paramref name="worldPoints"/> (≥2 points), recolor it (solid).</summary>
        public void SetRoute(IReadOnlyList<Vector3> worldPoints, Color color) => SetRoute(worldPoints, color, false);

        /// <summary>
        /// Lay the relationship along <paramref name="worldPoints"/> (≥2 points) and recolor it. When
        /// <paramref name="dashed"/> is true the line draws with a tiled dash texture whose density is normalized to
        /// the route's total world length (so dashes look uniform regardless of how long the run is); when false it
        /// reverts to a solid line. Dashing composes with the highlight color passed for a selected edge.
        /// </summary>
        public void SetRoute(IReadOnlyList<Vector3> worldPoints, Color color, bool dashed)
        {
            EnsureLine();
            _color = color;
            if (_lineMaterial != null) _lineMaterial.color = color;
            _line.startColor = _line.endColor = color;

            if (worldPoints == null || worldPoints.Count < 2)
            {
                _line.positionCount = 0;
                if (_arrow != null) _arrow.gameObject.SetActive(false);
                return;
            }

            _line.positionCount = worldPoints.Count;
            float length = 0f;
            for (int i = 0; i < worldPoints.Count; i++)
            {
                _line.SetPosition(i, worldPoints[i]);
                if (i > 0) length += Vector3.Distance(worldPoints[i - 1], worldPoints[i]);
            }

            ApplyDash(dashed, length);

            _lastPoint = worldPoints[worldPoints.Count - 1];
            Vector3 prev = worldPoints[worldPoints.Count - 2];
            Vector3 dir = _lastPoint - prev;
            _lastDir = dir.sqrMagnitude > 1e-6f ? dir.normalized : Vector3.forward;
            UpdateArrowTransform();
        }

        /// <summary>
        /// Bind (or clear) the dash texture on the line material and scale its tiling so one dash period spans
        /// <see cref="DashPeriod"/> world units. Falls back gracefully to a solid line if the chosen shader has no
        /// texture slot. Re-tints the material's color each call so dashes inherit the (possibly highlight) color.
        /// </summary>
        private void ApplyDash(bool dashed, float worldLength)
        {
            _dashed = dashed;
            if (_lineMaterial == null) return;

            int texProp = _lineMaterial.HasProperty(BaseMapId) ? BaseMapId
                : _lineMaterial.HasProperty(MainTexId) ? MainTexId : 0;
            if (texProp == 0) return; // shader can't carry a texture → leave the solid line as-is

            if (!dashed)
            {
                _lineMaterial.SetTexture(texProp, null);
                _lineMaterial.mainTextureScale = Vector2.one;
                return;
            }

            _lineMaterial.SetTexture(texProp, GetDashTexture());
            float tiles = Mathf.Max(1f, worldLength / Mathf.Max(0.0001f, DashPeriod));
            // SetTextureScale targets the same property; mainTextureScale maps to _MainTex, so set both to be safe.
            _lineMaterial.SetTextureScale(texProp, new Vector2(tiles, 1f));
            _lineMaterial.mainTextureScale = new Vector2(tiles, 1f);
        }

        /// <summary>The shared dash strip: 8 px wide (5 opaque + 3 transparent), 1 px tall, repeating, point-filtered.</summary>
        private static Texture2D GetDashTexture()
        {
            if (_dashTex != null) return _dashTex;
            _dashTex = new Texture2D(8, 1, TextureFormat.RGBA32, false)
            {
                name = "EdgeDash",
                wrapMode = TextureWrapMode.Repeat,
                filterMode = FilterMode.Point,
            };
            var px = new Color32[8];
            for (int i = 0; i < 8; i++) px[i] = i < 5 ? new Color32(255, 255, 255, 255) : new Color32(255, 255, 255, 0);
            _dashTex.SetPixels32(px);
            _dashTex.Apply(false, false);
            return _dashTex;
        }

        /// <summary>Show or hide the cone arrowhead at the target end of the route.</summary>
        public void SetArrow(bool on)
        {
            if (on) EnsureArrow();
            if (_arrow != null) _arrow.gameObject.SetActive(on);
            if (on) UpdateArrowTransform();
        }

        private void EnsureArrow()
        {
            if (_arrow != null) return;
            var go = new GameObject("Arrowhead");
            _arrow = go.transform;
            _arrow.SetParent(transform, false);
            var mf = go.AddComponent<MeshFilter>();
            mf.sharedMesh = BuildConeMesh(ArrowRadius, ArrowLength, 12);
            _arrowRenderer = go.AddComponent<MeshRenderer>();
            _arrowMaterial = MakeMaterial(_color);
            _arrowRenderer.sharedMaterial = _arrowMaterial;
        }

        private void UpdateArrowTransform()
        {
            if (_arrow == null) return;
            if (_arrowMaterial != null) _arrowMaterial.color = _color;
            // The cone tip points along +Y in local space (see BuildConeMesh); seat the tip at the last point.
            _arrow.position = _lastPoint - _lastDir * ArrowLength;
            _arrow.rotation = Quaternion.FromToRotation(Vector3.up, _lastDir);
        }

        private static Material MakeMaterial(Color color)
        {
            Shader sh = Shader.Find("Universal Render Pipeline/Unlit");
            if (sh == null) sh = Shader.Find("Sprites/Default");
            if (sh == null) sh = Shader.Find("Unlit/Transparent");
            if (sh == null) sh = Shader.Find("Unlit/Color");
            if (sh == null) sh = Shader.Find("Standard");
            var m = new Material(sh);
            m.color = color;
            if (m.HasProperty(BaseColorId)) m.SetColor(BaseColorId, color);
            EnableAlpha(m);
            return m;
        }

        /// <summary>
        /// Put the material into an alpha-blended transparent mode so the dash texture's transparent gaps actually
        /// read as gaps (not opaque). Tuned for URP/Lit-style shaders; harmless on shaders that lack the keywords.
        /// </summary>
        private static void EnableAlpha(Material m)
        {
            if (m.HasProperty("_Surface")) m.SetFloat("_Surface", 1f);   // 0 = opaque, 1 = transparent (URP)
            if (m.HasProperty("_Blend")) m.SetFloat("_Blend", 0f);       // 0 = alpha blend
            if (m.HasProperty("_SrcBlend")) m.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
            if (m.HasProperty("_DstBlend")) m.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
            if (m.HasProperty("_ZWrite")) m.SetFloat("_ZWrite", 0f);
            m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            m.EnableKeyword("_ALPHABLEND_ON");
            m.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
        }

        private static readonly int BaseColorId = Shader.PropertyToID("_BaseColor");

        /// <summary>A simple cone: a base ring fanned to a single apex at +Y, plus a base fan. Tip at local +Y.</summary>
        private static Mesh BuildConeMesh(float radius, float length, int segs)
        {
            var verts = new List<Vector3>(segs + 2);
            var tris = new List<int>(segs * 6);
            int apex = 0;
            verts.Add(new Vector3(0f, length, 0f));        // 0: apex (tip)
            int baseCenter = 1;
            verts.Add(Vector3.zero);                        // 1: base center
            int ringStart = 2;
            for (int i = 0; i < segs; i++)
            {
                float a = i / (float)segs * Mathf.PI * 2f;
                verts.Add(new Vector3(Mathf.Cos(a) * radius, 0f, Mathf.Sin(a) * radius));
            }
            for (int i = 0; i < segs; i++)
            {
                int cur = ringStart + i;
                int next = ringStart + (i + 1) % segs;
                // Side.
                tris.Add(apex); tris.Add(next); tris.Add(cur);
                // Base.
                tris.Add(baseCenter); tris.Add(cur); tris.Add(next);
            }
            var mesh = new Mesh { name = "EdgeArrow" };
            mesh.SetVertices(verts);
            mesh.SetTriangles(tris, 0);
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }
    }
}

using UnityEngine;
using TheRobotDraft.Authoring.Model;

namespace TheRobotDraft.Uml3D
{
    /// <summary>
    /// A small draggable 3-D sphere used to edit the route of the selected link. The 3-D counterpart of the flat
    /// renderer's <c>UmlEdgeHandle</c>: the integration layer (<c>UmlCanvas</c>) spawns one per editable point on the
    /// selected edge — interior waypoints and segment midpoints (the polyline editing affordances) plus the two
    /// endpoint anchors (where the link meets each node face). A scene <see cref="Physics"/> raycast that hits the
    /// sphere maps back to this component via <c>GetComponentInParent&lt;UmlEdgeHandle3D&gt;</c>; the canvas then reads
    /// <see cref="Edge"/>, <see cref="Index"/> and <see cref="Role"/> to know what the drag should move.
    /// </summary>
    public sealed class UmlEdgeHandle3D : MonoBehaviour
    {
        /// <summary>What a handle drives.</summary>
        public enum HandleRole
        {
            /// <summary>An existing interior waypoint (drag = move, Alt-click = delete). <see cref="Index"/> = its slot.</summary>
            Waypoint,
            /// <summary>A segment midpoint (drag = insert a new waypoint there, then continue moving it).
            /// <see cref="Index"/> = the segment index it splits.</summary>
            AddMidpoint,
            /// <summary>The source endpoint attachment on the From node's face.</summary>
            SrcAnchor,
            /// <summary>The target endpoint attachment on the To node's face.</summary>
            TgtAnchor,
        }

        /// <summary>The link this handle belongs to.</summary>
        public EdgeId Edge;

        /// <summary>The route-order index this handle addresses (waypoint slot or segment index; unused for anchors).</summary>
        public int Index;

        /// <summary>What dragging/clicking this handle does.</summary>
        public HandleRole Role;

        private Material _material;
        private static readonly int BaseColorId = Shader.PropertyToID("_BaseColor");

        private const float Radius = 0.06f; // ⇒ ~0.12 world-unit diameter

        /// <summary>
        /// Build the sphere mesh, an unlit material and a <see cref="SphereCollider"/> sized to match, and tag it with
        /// the edge / index / role it edits. Returns the created component for the caller to keep in its handle list.
        /// </summary>
        public static UmlEdgeHandle3D Create(Transform parent, EdgeId edge, int index, HandleRole role, Color color)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            go.name = "EdgeHandle:" + role;
            go.transform.SetParent(parent, false);
            go.transform.localScale = Vector3.one * (Radius * 2f);

            // CreatePrimitive gives a unit-diameter SphereCollider already; just make sure it's a trigger-free solid
            // so Physics.Raycast picks it. (Sphere primitive ships with a SphereCollider of radius 0.5 in local space.)
            var col = go.GetComponent<SphereCollider>();
            if (col == null) col = go.AddComponent<SphereCollider>();

            var handle = go.AddComponent<UmlEdgeHandle3D>();
            handle.Edge = edge;
            handle.Index = index;
            handle.Role = role;

            var mr = go.GetComponent<MeshRenderer>();
            handle._material = MakeMaterial(color);
            mr.sharedMaterial = handle._material;
            return handle;
        }

        /// <summary>Place the handle at a world position (called each frame so handles track their route points).</summary>
        public void SetWorldPosition(Vector3 world) => transform.position = world;

        /// <summary>Recolor the handle (e.g. to flag a hovered/active drag target).</summary>
        public void SetColor(Color color)
        {
            if (_material == null) return;
            _material.color = color;
            if (_material.HasProperty(BaseColorId)) _material.SetColor(BaseColorId, color);
        }

        private static Material MakeMaterial(Color color)
        {
            Shader sh = Shader.Find("Universal Render Pipeline/Unlit");
            if (sh == null) sh = Shader.Find("Unlit/Color");
            if (sh == null) sh = Shader.Find("Sprites/Default");
            if (sh == null) sh = Shader.Find("Standard");
            var m = new Material(sh) { color = color };
            if (m.HasProperty(BaseColorId)) m.SetColor(BaseColorId, color);
            return m;
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TheRobotDraft.Authoring.Model;

namespace TheRobotDraft.Uml3D
{
    /// <summary>
    /// A real 3-D UML node: a procedurally-built box slab (a 12-triangle cuboid) whose front (+Z) face carries a
    /// world-space uGUI canvas reproducing the classifier compartments — stereotype, bold name, an attributes
    /// block, a divider, then an operations block — a faithful-enough port of <c>UmlNodeView</c>'s layout. The
    /// slab is lit (URP/Lit, with Standard and unlit fallbacks) and tinted with the node fill color; a
    /// <see cref="BoxCollider"/> matching the slab makes it pickable via <see cref="Physics"/> raycasts.
    ///
    /// The integration layer drives it imperatively: <see cref="Init"/> to build, <see cref="SetWorldPose"/> to
    /// place it on its layer, <see cref="AddLocalRotation"/> to spin the individual node, <see cref="SetSelected"/>
    /// for the selection highlight, and <see cref="SetDepthTint"/> to gray out below-layer nodes. A
    /// collider hit maps back to this component via <c>GetComponentInParent&lt;UmlNode3D&gt;</c>.
    /// </summary>
    public sealed class UmlNode3D : MonoBehaviour
    {
        /// <summary>The model element this node renders. Mirrors <c>UmlNodeView.Id</c>.</summary>
        public ElementId Id;

        /// <summary>The local (per-node) rotation applied on top of the world pose set by the layer.</summary>
        public Quaternion LocalRotation { get; private set; } = Quaternion.identity;

        private Transform _slab;            // the lit box mesh + collider (rotates with LocalRotation)
        private MeshRenderer _slabRenderer;
        private Material _slabMaterial;     // runtime instance; tinted for fill / depth / selection
        private BoxCollider _collider;
        private Canvas _faceCanvas;         // world-space content on the +Z face
        private CanvasGroup _faceGroup;     // alpha fades with depth tint
        private GameObject _selectionBox;   // wireframe-ish highlight border, toggled on selection

        private Vector3 _basePos = Vector3.zero;   // world pose set by the layer (before LocalRotation)
        private Quaternion _baseRot = Quaternion.identity;

        private Color _fill = Color.white;          // resting slab tint
        private Color _text = new Color(0.13f, 0.15f, 0.19f, 1f);
        private float _localPitch, _localYaw;       // accumulated per-node rotation (degrees)
        private float _depthT;                      // 0 = active/full-color, 1 = fully grayed (below layer)

        // World-space half-extents of the slab's +Z face, retained from Init/Resize so edges can attach to a point
        // on the face (see FacePointLocal). x = half-width, y = half-height (already × Uml3DConfig.WorldScale).
        private float _faceHalfW, _faceHalfH;

        // Build inputs retained so Resize can rebuild the mesh + face at a new size.
        private string _name, _stereotype;
        private ElementKind _kind;
        private List<string> _attrs, _ops;
        private float _depth;

        private const float RowH = 18f;             // matches UmlNodeView's compartment row height (px)
        private const float HeaderH = 30f;
        private const int NameSize = 18;
        private const int MemberSize = 15;
        private static Font _font;

        /// <summary>
        /// Build the slab, face content and collider. <paramref name="sizePx"/> is the node's UI-pixel size
        /// (as the flat renderer computed it); it is scaled by <see cref="Uml3DConfig.WorldScale"/> for the mesh.
        /// </summary>
        public void Init(ElementId id, string name, string stereotype, ElementKind kind, Color fill, Color text,
            List<string> attributes, List<string> operations, Vector2 sizePx)
        {
            Id = id;
            _fill = fill;
            _text = text;
            _name = name; _stereotype = stereotype; _kind = kind; _attrs = attributes; _ops = operations;

            float w = Mathf.Max(20f, sizePx.x) * Uml3DConfig.WorldScale;
            float h = Mathf.Max(14f, sizePx.y) * Uml3DConfig.WorldScale;
            float d = Uml3DConfig.NodeThickness;
            _depth = d;
            _faceHalfW = w * 0.5f; _faceHalfH = h * 0.5f;

            // The slab is a child so per-node LocalRotation can spin it (plus its face + collider) while the
            // node GameObject itself stays at the layer's world pose.
            var slabGo = new GameObject("Slab");
            _slab = slabGo.transform;
            _slab.SetParent(transform, false);

            var mf = slabGo.AddComponent<MeshFilter>();
            mf.sharedMesh = BuildBoxMesh(w, h, d);
            _slabRenderer = slabGo.AddComponent<MeshRenderer>();
            _slabMaterial = CreateMaterial(fill);
            _slabRenderer.sharedMaterial = _slabMaterial;

            _collider = slabGo.AddComponent<BoxCollider>();
            _collider.size = new Vector3(w, h, d);
            _collider.center = Vector3.zero;

            BuildFace(name, stereotype, kind, sizePx, w, h, d, attributes, operations);
            BuildSelectionBox(w, h, d);
        }

        // --- public API for the integration layer ---

        /// <summary>The slab transform whose +Z face carries the content. Falls back to this node's transform if the
        /// slab hasn't been built yet (so the face accessors are safe to call at any time).</summary>
        private Transform FaceTransform => _slab != null ? _slab : transform;

        /// <summary>World-space right axis of the +Z content face (accounts for the per-node local rotation).</summary>
        public Vector3 FaceRight => FaceTransform.right;

        /// <summary>World-space up axis of the +Z content face (accounts for the per-node local rotation).</summary>
        public Vector3 FaceUp => FaceTransform.up;

        /// <summary>World-space outward normal of the +Z content face (the face the camera reads).</summary>
        public Vector3 FaceForward => FaceTransform.forward;

        /// <summary>World half-extents of the slab's +Z face (x = half-width, y = half-height).</summary>
        public Vector2 FaceHalfExtents => new Vector2(_faceHalfW, _faceHalfH);

        /// <summary>
        /// Map a normalized face offset (each axis in roughly [-0.5,0.5]; (0,0) = face center) to a world point sitting
        /// just in front of the +Z face. Used to attach a link endpoint to a draggable spot on the node face. The
        /// offset is clamped to the face so an endpoint can never drift off the slab.
        /// </summary>
        public Vector3 FacePointLocal(Vector2 norm)
        {
            float fx = Mathf.Clamp(norm.x, -0.5f, 0.5f);
            float fy = Mathf.Clamp(norm.y, -0.5f, 0.5f);
            Vector3 center = transform.position;
            // Seat a hair in front of the face (matching the content canvas inset) so the attachment reads as on the
            // front surface rather than buried in the slab.
            return center
                + FaceRight * (fx * (_faceHalfW * 2f))
                + FaceUp * (fy * (_faceHalfH * 2f))
                + FaceForward * (_depth * 0.5f);
        }

        /// <summary>Place this node at its layer's world pose; <see cref="LocalRotation"/> is applied on top.</summary>
        public void SetWorldPose(Vector3 pos, Quaternion rot)
        {
            _basePos = pos;
            _baseRot = rot;
            transform.SetPositionAndRotation(pos, rot);
        }

        /// <summary>
        /// Rebuild the slab mesh, collider and face content at a new pixel size (interactive resize). Preserves
        /// the current selection, depth tint and per-node rotation.
        /// </summary>
        public void Resize(Vector2 sizePx)
        {
            float w = Mathf.Max(20f, sizePx.x) * Uml3DConfig.WorldScale;
            float h = Mathf.Max(14f, sizePx.y) * Uml3DConfig.WorldScale;
            float d = _depth;
            _faceHalfW = w * 0.5f; _faceHalfH = h * 0.5f;

            if (_slab != null)
            {
                var mf = _slab.GetComponent<MeshFilter>();
                if (mf != null) mf.sharedMesh = BuildBoxMesh(w, h, d);
            }
            if (_collider != null) _collider.size = new Vector3(w, h, d);

            if (_faceCanvas != null) Destroy(_faceCanvas.gameObject);
            if (_selectionBox != null) Destroy(_selectionBox);
            BuildFace(_name, _stereotype, _kind, sizePx, w, h, d, _attrs, _ops);
            BuildSelectionBox(w, h, d);

            if (_selectionBox != null) _selectionBox.SetActive(_selected);
            if (_faceGroup != null) _faceGroup.alpha = Mathf.Lerp(1f, 0.35f, _depthT);
        }

        /// <summary>Accumulate a per-node spin (degrees) about the node's local right (pitch) and up (yaw) axes.</summary>
        public void AddLocalRotation(float dPitch, float dYaw)
        {
            _localPitch += dPitch;
            _localYaw += dYaw;
            LocalRotation = Quaternion.Euler(_localPitch, _localYaw, 0f);
            if (_slab != null) _slab.localRotation = LocalRotation;
        }

        /// <summary>Toggle the selection highlight (a tinted border box around the slab plus an emissive lift).</summary>
        public void SetSelected(bool on)
        {
            _selected = on;
            if (_selectionBox != null) _selectionBox.SetActive(on);
            ApplyTint();
        }

        /// <summary>
        /// Depth graying for the bubble-view: <paramref name="t"/>=0 keeps full color (active layer); as t→1 the
        /// slab fades toward gray and the face content dims. Clamped to [0,1].
        /// </summary>
        public void SetDepthTint(float t)
        {
            _depthT = Mathf.Clamp01(t);
            ApplyTint();
            if (_faceGroup != null) _faceGroup.alpha = Mathf.Lerp(1f, 0.35f, _depthT);
        }

        private bool _selected;

        private void ApplyTint()
        {
            if (_slabMaterial == null) return;
            var gray = new Color(0.5f, 0.52f, 0.55f, 1f);
            Color c = Color.Lerp(_fill, gray, _depthT);
            _slabMaterial.color = c;
            if (_slabMaterial.HasProperty(BaseColorId)) _slabMaterial.SetColor(BaseColorId, c);
            // A subtle emissive lift when selected (works on Lit; harmless on Standard / ignored on unlit).
            if (_slabMaterial.HasProperty(EmissionColorId))
            {
                Color emis = _selected ? new Color(0.10f, 0.32f, 0.50f, 1f) : Color.black;
                _slabMaterial.SetColor(EmissionColorId, emis);
            }
        }

        // --- mesh / material / face construction ---

        private static readonly int BaseColorId = Shader.PropertyToID("_BaseColor");
        private static readonly int EmissionColorId = Shader.PropertyToID("_EmissionColor");

        /// <summary>A 24-vertex (per-face normals), 12-triangle box centered on the origin. Front face at +Z.</summary>
        private static Mesh BuildBoxMesh(float w, float h, float d)
        {
            float x = w * 0.5f, y = h * 0.5f, z = d * 0.5f;
            var v = new[]
            {
                // +Z (front)
                new Vector3(-x, -y, z), new Vector3(x, -y, z), new Vector3(x, y, z), new Vector3(-x, y, z),
                // -Z (back)
                new Vector3(x, -y, -z), new Vector3(-x, -y, -z), new Vector3(-x, y, -z), new Vector3(x, y, -z),
                // +X (right)
                new Vector3(x, -y, z), new Vector3(x, -y, -z), new Vector3(x, y, -z), new Vector3(x, y, z),
                // -X (left)
                new Vector3(-x, -y, -z), new Vector3(-x, -y, z), new Vector3(-x, y, z), new Vector3(-x, y, -z),
                // +Y (top)
                new Vector3(-x, y, z), new Vector3(x, y, z), new Vector3(x, y, -z), new Vector3(-x, y, -z),
                // -Y (bottom)
                new Vector3(-x, -y, -z), new Vector3(x, -y, -z), new Vector3(x, -y, z), new Vector3(-x, -y, z),
            };
            var n = new[]
            {
                Vector3.forward, Vector3.back, Vector3.right, Vector3.left, Vector3.up, Vector3.down,
            };
            var normals = new Vector3[24];
            for (int f = 0; f < 6; f++)
                for (int i = 0; i < 4; i++)
                    normals[f * 4 + i] = n[f];

            var tris = new int[36];
            for (int f = 0; f < 6; f++)
            {
                int b = f * 4, t = f * 6;
                tris[t] = b; tris[t + 1] = b + 1; tris[t + 2] = b + 2;
                tris[t + 3] = b; tris[t + 4] = b + 2; tris[t + 5] = b + 3;
            }

            var mesh = new Mesh { name = "UmlNodeSlab" };
            mesh.vertices = v;
            mesh.normals = normals;
            mesh.triangles = tris;
            mesh.RecalculateBounds();
            return mesh;
        }

        /// <summary>Build a lit material, falling back through Standard then an unlit color shader if URP is absent.</summary>
        private static Material CreateMaterial(Color color)
        {
            Shader sh = Shader.Find("Universal Render Pipeline/Lit");
            if (sh == null) sh = Shader.Find("Standard");
            if (sh == null) sh = Shader.Find("Sprites/Default");
            Material m = sh != null ? new Material(sh) : new Material(Shader.Find("Unlit/Color"));
            m.color = color;
            if (m.HasProperty(BaseColorId)) m.SetColor(BaseColorId, color);
            return m;
        }

        /// <summary>
        /// A world-space canvas on the +Z face reproducing the compartment layout. The canvas uses the node's
        /// pixel size for its <c>sizeDelta</c> and is scaled by <see cref="Uml3DConfig.WorldScale"/> so its text
        /// lands exactly on the slab face; it sits a hair in front of the face to avoid z-fighting.
        /// </summary>
        private void BuildFace(string name, string stereotype, ElementKind kind, Vector2 sizePx,
            float w, float h, float d, List<string> attributes, List<string> operations)
        {
            if (_font == null) _font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            var faceGo = new GameObject("Face", typeof(RectTransform));
            var faceRt = (RectTransform)faceGo.transform;
            faceRt.SetParent(_slab, false);
            _faceCanvas = faceGo.AddComponent<Canvas>();
            _faceCanvas.renderMode = RenderMode.WorldSpace;
            faceGo.AddComponent<GraphicRaycaster>().enabled = false; // picking is via the physics collider
            _faceGroup = faceGo.AddComponent<CanvasGroup>();
            _faceGroup.interactable = false;
            _faceGroup.blocksRaycasts = false;
            // Clip compartment content to the node face so long names/signatures don't spill past a small node.
            faceGo.AddComponent<RectMask2D>();

            float pxW = Mathf.Max(20f, sizePx.x), pxH = Mathf.Max(14f, sizePx.y);
            faceRt.sizeDelta = new Vector2(pxW, pxH);
            faceRt.pivot = new Vector2(0.5f, 0.5f);
            faceRt.localScale = Vector3.one * Uml3DConfig.WorldScale;
            // Just in front of the +Z face (nudged a hair further out so the opaque panel can't z-fight the slab).
            // Flipped 180° about Y so the canvas's READABLE side faces +Z (the camera): a uGUI world-space canvas
            // is legible from its −Z side, so an identity-rotated face shows its mirrored back to a +Z camera.
            faceRt.localPosition = new Vector3(0f, 0f, d * 0.5f + 0.004f);
            faceRt.localRotation = Quaternion.Euler(0f, 180f, 0f);

            // Opaque, full-face background panel drawn behind every row. uGUI renders unlit, so this panel plus the
            // text rows are always full-bright regardless of scene lighting, guaranteeing the (dark) member text has
            // contrast. Use the node fill; if it's very dark, lighten toward white so the dark text stays legible.
            BuildFacePanel(faceRt, pxW, pxH);

            Color nameColor = _text;
            Color subColor = Color.Lerp(_text, _fill, 0.35f);
            float stereoH = string.IsNullOrEmpty(stereotype) ? 0f : 16f;

            bool hasAttrs = attributes != null && attributes.Count > 0;
            bool hasOps = operations != null && operations.Count > 0;
            bool hasMembers = hasAttrs || hasOps;

            // Header: optional stereotype, then the bold name. When the node has no member compartments (use case,
            // state, junction, decision, fork, actor, …) the header block is centered on the face with no dividers;
            // with members it sits at the top and the compartments stack below it.
            float headerBlockH = (stereoH > 0f ? stereoH : 0f) + 28f;
            float ty = hasMembers
                ? pxH * 0.5f - 4f          // top edge, working downward (canvas center is origin)
                : headerBlockH * 0.5f;     // top of a vertically-centered header block
            if (stereoH > 0f)
            {
                Row(faceRt, stereotype, ty, stereoH, 14, subColor, TextAnchor.MiddleCenter, false);
                ty -= stereoH;
            }
            Row(faceRt, name, ty, 28f, NameSize, nameColor, TextAnchor.MiddleCenter, true);
            ty -= 28f;

            // Header divider only when at least one compartment below it is non-empty.
            if (hasMembers)
            {
                Divider(faceRt, ty, pxW);
                ty -= 4f;
            }

            // Attributes compartment — only drawn when it actually has rows.
            if (hasAttrs)
            {
                foreach (var a in attributes) { Row(faceRt, a, ty, RowH, MemberSize, _text, TextAnchor.MiddleLeft, false); ty -= RowH; }
                // Divider between attributes and operations only when operations follow.
                if (hasOps)
                {
                    ty -= 4f;
                    Divider(faceRt, ty, pxW);
                    ty -= 4f;
                }
            }

            // Operations compartment — only drawn when it actually has rows.
            if (hasOps)
                foreach (var o in operations) { Row(faceRt, o, ty, RowH, MemberSize, _text, TextAnchor.MiddleLeft, false); ty -= RowH; }
        }

        /// <summary>
        /// An opaque full-face background card (panel + thin darker border) added as the FIRST children of the face
        /// canvas so it draws behind the stereotype/name/dividers/members. The panel covers the whole face
        /// (<c>sizeDelta == sizePx</c>); subsequent rows are siblings added after it, so canvas sibling order keeps
        /// the text on top.
        /// </summary>
        private void BuildFacePanel(RectTransform parent, float pxW, float pxH)
        {
            // Lighten the fill toward white when it's too dark for the dark member text to read against.
            Color panelColor = _fill;
            float lum = 0.2126f * panelColor.r + 0.7152f * panelColor.g + 0.0722f * panelColor.b;
            if (lum < 0.55f) panelColor = Color.Lerp(panelColor, Color.white, 0.55f);
            panelColor.a = 1f;

            // Border: a slightly larger panel in a darker tone, placed first (drawn furthest back).
            var borderGo = new GameObject("FaceBorder", typeof(RectTransform));
            var borderRt = (RectTransform)borderGo.transform;
            borderRt.SetParent(parent, false);
            borderRt.anchorMin = new Vector2(0.5f, 0.5f);
            borderRt.anchorMax = new Vector2(0.5f, 0.5f);
            borderRt.pivot = new Vector2(0.5f, 0.5f);
            borderRt.sizeDelta = new Vector2(pxW, pxH);
            borderRt.anchoredPosition = Vector2.zero;
            var borderImg = borderGo.AddComponent<Image>();
            borderImg.color = new Color(0.30f, 0.32f, 0.37f, 1f);
            borderImg.raycastTarget = false;
            borderRt.SetAsFirstSibling();

            // Fill panel: inset by the border thickness, drawn just after the border.
            const float border = 2f;
            var panelGo = new GameObject("FacePanel", typeof(RectTransform));
            var panelRt = (RectTransform)panelGo.transform;
            panelRt.SetParent(parent, false);
            panelRt.anchorMin = new Vector2(0.5f, 0.5f);
            panelRt.anchorMax = new Vector2(0.5f, 0.5f);
            panelRt.pivot = new Vector2(0.5f, 0.5f);
            panelRt.sizeDelta = new Vector2(Mathf.Max(0f, pxW - border * 2f), Mathf.Max(0f, pxH - border * 2f));
            panelRt.anchoredPosition = Vector2.zero;
            var panelImg = panelGo.AddComponent<Image>();
            panelImg.color = panelColor;
            panelImg.raycastTarget = false;
            // Sit immediately above the border but below the text rows added afterward.
            panelRt.SetSiblingIndex(1);
        }

        /// <summary>One text row laid out from the canvas center, top-anchored at <paramref name="topY"/> (px).</summary>
        private void Row(RectTransform parent, string text, float topY, float height, int fontSize, Color color,
            TextAnchor align, bool bold)
        {
            var go = new GameObject("Row", typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            rt.anchorMin = new Vector2(0.5f, 0.5f);
            rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 1f);
            rt.sizeDelta = new Vector2(parent.sizeDelta.x - 20f, height);
            rt.anchoredPosition = new Vector2(0f, topY);
            var t = go.AddComponent<Text>();
            t.font = _font;
            t.text = text;
            t.fontSize = fontSize;
            t.color = color;
            t.alignment = align;
            t.fontStyle = bold ? FontStyle.Bold : FontStyle.Normal;
            t.supportRichText = false;
            t.raycastTarget = false;
            // Wrap within the row width and truncate vertically; the face RectMask2D hard-clips anything that still
            // exceeds the node bounds, so text never spills outside a too-small node.
            t.horizontalOverflow = HorizontalWrapMode.Wrap;
            t.verticalOverflow = VerticalWrapMode.Truncate;
        }

        private void Divider(RectTransform parent, float topY, float pxW)
        {
            var go = new GameObject("Divider", typeof(RectTransform));
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            rt.anchorMin = new Vector2(0.5f, 0.5f);
            rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 1f);
            rt.sizeDelta = new Vector2(pxW, 2f);
            rt.anchoredPosition = new Vector2(0f, topY);
            var img = go.AddComponent<Image>();
            img.color = new Color(0.66f, 0.68f, 0.73f, 1f);
            img.raycastTarget = false;
        }

        /// <summary>
        /// A thin highlight border: a slightly larger box rendered as a wireframe-ish line cage via a
        /// <see cref="LineRenderer"/>. Hidden until <see cref="SetSelected"/>(true).
        /// </summary>
        private void BuildSelectionBox(float w, float h, float d)
        {
            _selectionBox = new GameObject("Selection");
            _selectionBox.transform.SetParent(_slab, false);
            float x = w * 0.5f + 0.02f, y = h * 0.5f + 0.02f, z = d * 0.5f + 0.02f;
            var lr = _selectionBox.AddComponent<LineRenderer>();
            lr.useWorldSpace = false;
            lr.loop = false;
            lr.widthMultiplier = 0.02f;
            lr.material = CreateMaterial(new Color(0.12f, 0.55f, 0.85f, 1f));
            lr.startColor = lr.endColor = new Color(0.12f, 0.55f, 0.85f, 1f);
            // Front face loop, then a hop to the back face loop (a single continuous polyline traces the cage).
            var pts = new[]
            {
                new Vector3(-x, -y, z), new Vector3(x, -y, z), new Vector3(x, y, z), new Vector3(-x, y, z), new Vector3(-x, -y, z),
                new Vector3(-x, -y, -z), new Vector3(x, -y, -z), new Vector3(x, y, -z), new Vector3(-x, y, -z), new Vector3(-x, -y, -z),
            };
            lr.positionCount = pts.Length;
            lr.SetPositions(pts);
            _selectionBox.SetActive(false);
        }
    }
}

using NUnit.Framework;
using TheRobotDraft.Authoring.Commands;
using TheRobotDraft.Authoring.Model;
using TheRobotDraft.Authoring.Rules;
using TheRobotDraft.Authoring.Seams;
using TheRobotDraft.Authoring.State;

namespace TheRobotDraft.Authoring.Tests
{
    /// <summary>
    /// EditMode tests for the engine-agnostic authoring core (authoring-ux.md §0–§4). These validate the
    /// invariants the whole authoring surface depends on: containment + edge legality, single-step undo,
    /// spring-loaded modes, and never-stranded cancel. No renderer / XR required — the core is pure C#.
    /// </summary>
    public class AuthoringCoreTests
    {
        private AuthoringModel _model;
        private AuthoringController _ctl;
        private CommandContext _ctx;

        private static (AuthoringModel model, AuthoringController ctl, CommandContext ctx) NewWorld()
        {
            var model = new AuthoringModel();
            var ctx = new CommandContext(model, new NullPacker(), new CountingIdFactory());
            var ctl = new AuthoringController(model, new UndoStack(ctx));
            return (model, ctl, ctx);
        }

        [SetUp]
        public void SetUp() => (_model, _ctl, _ctx) = NewWorld();

        // Helper: directly seed an element (bypasses the controller) for arranging fixtures.
        private ElementId Seed(ElementKind kind, string name, ElementId parent)
        {
            var id = new ElementId($"seed:{name}");
            _model.AddElement(id, kind, name, parent, false);
            return id;
        }

        // --- containment rules (§3.1) ---

        [Test]
        public void Field_Under_Package_Is_Invalid()
        {
            Assert.IsFalse(ContainmentRules.CanContain(ElementKind.Package, ElementKind.Field).IsValid);
        }

        [Test]
        public void Field_Under_Class_Is_Valid()
        {
            Assert.IsTrue(ContainmentRules.CanContain(ElementKind.Class, ElementKind.Field).IsValid);
        }

        [Test]
        public void Members_Cannot_Contain_Anything()
        {
            Assert.IsFalse(ContainmentRules.CanContain(ElementKind.Function, ElementKind.Field).IsValid);
            Assert.IsFalse(ContainmentRules.CanContain(ElementKind.Field, ElementKind.Class).IsValid);
        }

        [Test]
        public void Invalid_Containment_Carries_A_Reason()
        {
            // The §B invalid affordance shows a hover reason at point-of-use, so the reason must be populated.
            var v = ContainmentRules.CanContain(ElementKind.Package, ElementKind.Field);
            Assert.IsFalse(v.IsValid);
            Assert.IsNotNull(v.Reason);
            Assert.IsNotEmpty(v.Reason);
        }

        // --- edge rules (§4.4) ---

        [Test]
        public void Generalization_Class_To_Class_Is_Valid()
        {
            var a = Seed(ElementKind.Class, "A", ElementId.None);
            var b = Seed(ElementKind.Class, "B", ElementId.None);
            Assert.IsTrue(EdgeRules.CanConnect(_model, EdgeKind.Generalization, a, b).IsValid);
        }

        [Test]
        public void Generalization_Class_To_Interface_Is_Invalid()
        {
            var a = Seed(ElementKind.Class, "A", ElementId.None);
            var i = Seed(ElementKind.Interface, "I", ElementId.None);
            Assert.IsFalse(EdgeRules.CanConnect(_model, EdgeKind.Generalization, a, i).IsValid);
        }

        [Test]
        public void Realization_Class_To_Interface_Is_Valid()
        {
            var a = Seed(ElementKind.Class, "A", ElementId.None);
            var i = Seed(ElementKind.Interface, "I", ElementId.None);
            Assert.IsTrue(EdgeRules.CanConnect(_model, EdgeKind.Realization, a, i).IsValid);
        }

        [Test]
        public void Member_As_Edge_Endpoint_Is_Invalid()
        {
            var c = Seed(ElementKind.Class, "C", ElementId.None);
            var f = Seed(ElementKind.Field, "f", c);
            Assert.IsFalse(EdgeRules.CanConnect(_model, EdgeKind.Association, c, f).IsValid);
        }

        [Test]
        public void Reflexive_Association_Is_Valid_But_Self_Generalization_Is_Not()
        {
            var c = Seed(ElementKind.Class, "C", ElementId.None);
            Assert.IsTrue(EdgeRules.CanConnect(_model, EdgeKind.Association, c, c).IsValid);
            Assert.IsFalse(EdgeRules.CanConnect(_model, EdgeKind.Generalization, c, c).IsValid);
        }

        [Test]
        public void Generalization_Cycle_Is_Rejected()
        {
            var a = Seed(ElementKind.Class, "A", ElementId.None);
            var b = Seed(ElementKind.Class, "B", ElementId.None);
            // A --|> B exists; now B --|> A would close a cycle.
            _model.AddEdge(new EdgeId("g1"), EdgeKind.Generalization, a, b);
            Assert.IsFalse(EdgeRules.CanConnect(_model, EdgeKind.Generalization, b, a).IsValid);
        }

        [Test]
        public void Package_Level_Dependency_Is_Valid()
        {
            var p1 = Seed(ElementKind.Package, "p1", ElementId.None);
            var p2 = Seed(ElementKind.Package, "p2", ElementId.None);
            Assert.IsTrue(EdgeRules.CanConnect(_model, EdgeKind.Dependency, p1, p2).IsValid);
        }

        // --- add-node + undo (§3, §0.2) ---

        [Test]
        public void AddNode_Then_Undo_Round_Trips()
        {
            var pkg = Seed(ElementKind.Package, "root", ElementId.None);
            _ctl.EnterAddNode(ElementKind.Class, CommitStyle.OneShot);
            var created = _ctl.CommitAddNode(pkg, "MyClass");

            Assert.IsTrue(created.IsValid);
            Assert.IsTrue(_model.Contains(created));
            Assert.AreEqual(AuthoringMode.Select, _ctl.Mode, "one-shot returns to Select");

            Assert.IsTrue(_ctl.Undo());
            Assert.IsFalse(_model.Contains(created), "undo removes the added node");

            Assert.IsTrue(_ctl.Redo());
            Assert.IsTrue(_model.Contains(created), "redo restores it");
        }

        [Test]
        public void AddNode_Refuses_Invalid_Parent()
        {
            var pkg = Seed(ElementKind.Package, "root", ElementId.None);
            _ctl.EnterAddNode(ElementKind.Field, CommitStyle.OneShot); // Field under Package is illegal
            var created = _ctl.CommitAddNode(pkg, "f");
            Assert.IsFalse(created.IsValid, "commit refused on invalid target");
            Assert.IsFalse(_ctl.CanUndo, "nothing was recorded");
        }

        // --- spring-loaded modes (§1) ---

        [Test]
        public void Sticky_AddNode_Stays_In_Mode()
        {
            var pkg = Seed(ElementKind.Package, "root", ElementId.None);
            _ctl.EnterAddNode(ElementKind.Class, CommitStyle.Sticky);
            _ctl.CommitAddNode(pkg, "A");
            Assert.AreEqual(AuthoringMode.AddNode, _ctl.Mode, "sticky stays for the next placement");
            _ctl.CommitAddNode(pkg, "B");
            Assert.AreEqual(AuthoringMode.AddNode, _ctl.Mode);
        }

        [Test]
        public void Cancel_Always_Returns_To_Select()
        {
            _ctl.EnterConnect(CommitStyle.Sticky);
            var c = Seed(ElementKind.Class, "C", ElementId.None);
            _ctl.BeginConnect(c);
            Assert.IsTrue(_ctl.ConnectDragActive);

            _ctl.Cancel();
            Assert.AreEqual(AuthoringMode.Select, _ctl.Mode, "never stranded");
            Assert.IsFalse(_ctl.ConnectDragActive, "cancel clears the in-progress drag");
        }

        // --- connect + sticky type (§4.2) ---

        [Test]
        public void Connect_Commits_And_Sticky_Type_Persists()
        {
            var a = Seed(ElementKind.Class, "A", ElementId.None);
            var b = Seed(ElementKind.Class, "B", ElementId.None);

            _ctl.EnterConnect(CommitStyle.Sticky, EdgeKind.Dependency);
            Assert.IsTrue(_ctl.BeginConnect(a));
            var edge = _ctl.CommitConnect(b);

            Assert.IsTrue(edge.IsValid);
            Assert.AreEqual(EdgeKind.Dependency, _ctl.PendingEdgeKind, "sticky type carries to the next edge");
            Assert.AreEqual(1, CountEdges());
        }

        [Test]
        public void Connect_Release_On_Empty_Cancels_Drag_Without_Edge()
        {
            var a = Seed(ElementKind.Class, "A", ElementId.None);
            _ctl.EnterConnect(CommitStyle.Sticky);
            _ctl.BeginConnect(a);
            var edge = _ctl.CommitConnect(ElementId.None); // released over empty space
            Assert.IsFalse(edge.IsValid);
            Assert.IsFalse(_ctl.ConnectDragActive);
            Assert.AreEqual(0, CountEdges(), "no orphan edge");
            Assert.AreEqual(AuthoringMode.Connect, _ctl.Mode, "sticky stays after an empty release");
        }

        // --- delete subtree + undo (§4.6 / §3.6) ---

        [Test]
        public void Delete_Removes_Subtree_And_Incident_Edges_And_Undo_Restores()
        {
            var pkg = Seed(ElementKind.Package, "root", ElementId.None);
            var cls = Seed(ElementKind.Class, "C", pkg);
            var field = Seed(ElementKind.Field, "f", cls);
            var other = Seed(ElementKind.Class, "Other", pkg);
            _model.AddEdge(new EdgeId("dep"), EdgeKind.Dependency, cls, other);

            Assert.IsTrue(_ctl.Delete(cls));
            Assert.IsFalse(_model.Contains(cls));
            Assert.IsFalse(_model.Contains(field), "subtree removed");
            Assert.AreEqual(0, CountEdges(), "incident edge removed");
            Assert.IsTrue(_model.Contains(other), "unrelated element untouched");

            Assert.IsTrue(_ctl.Undo());
            Assert.IsTrue(_model.Contains(cls));
            Assert.IsTrue(_model.Contains(field), "subtree restored");
            Assert.AreEqual(1, CountEdges(), "incident edge restored");
        }

        // --- reparent guard (§3.6) ---

        [Test]
        public void Cannot_Reparent_Into_Own_Descendant()
        {
            var outer = Seed(ElementKind.Package, "outer", ElementId.None);
            var inner = Seed(ElementKind.Package, "inner", outer);
            Assert.IsFalse(_ctl.Reparent(outer, inner), "would orphan the subtree");
        }

        [Test]
        public void Reparent_Valid_Move_Succeeds_And_Undo_Restores_Parent()
        {
            var p1 = Seed(ElementKind.Package, "p1", ElementId.None);
            var p2 = Seed(ElementKind.Package, "p2", ElementId.None);
            var cls = Seed(ElementKind.Class, "C", p1);

            Assert.IsTrue(_ctl.Reparent(cls, p2));
            Assert.AreEqual(p2, _model.Get(cls).Parent);

            Assert.IsTrue(_ctl.Undo());
            Assert.AreEqual(p1, _model.Get(cls).Parent, "undo restores the original parent");
        }

        private int CountEdges()
        {
            int n = 0;
            foreach (var _ in _model.Edges) n++;
            return n;
        }
    }
}

using System;
using System.Collections.Generic;
using TheRobotDraft.Authoring.Model;
using TheRobotDraft.Authoring.Seams;

namespace TheRobotDraft.Authoring.Commands
{
    /// <summary>Mints stable ids for new elements/edges. Default uses GUIDs; the real pipeline uses qualified-name hashes.</summary>
    public interface IIdFactory
    {
        ElementId NewElementId(ElementId parent, ElementKind kind, string name);
        EdgeId NewEdgeId(ElementId from, ElementId to, EdgeKind kind);
    }

    /// <summary>Deterministic-enough default id source. Monotonic counter avoids collisions without a clock.</summary>
    public sealed class CountingIdFactory : IIdFactory
    {
        private int _n;
        public ElementId NewElementId(ElementId parent, ElementKind kind, string name)
            => new ElementId($"e{++_n}:{kind}");
        public EdgeId NewEdgeId(ElementId from, ElementId to, EdgeKind kind)
            => new EdgeId($"r{++_n}:{kind}");
    }

    /// <summary>What a command operates on: the model, the packer (position/re-pack), and the id source.</summary>
    public sealed class CommandContext
    {
        public AuthoringModel Model { get; }
        public IPacker Packer { get; }
        public IIdFactory Ids { get; }

        public CommandContext(AuthoringModel model, IPacker packer, IIdFactory ids)
        {
            Model = model;
            Packer = packer;
            Ids = ids;
        }
    }

    /// <summary>
    /// One reversible authoring mutation. Every authoring verb is exactly one of these so it is a single undo
    /// step (authoring-ux.md §0.2). <see cref="Do"/> must capture whatever <see cref="Undo"/> needs to restore
    /// the prior state precisely.
    /// </summary>
    public interface IAuthoringCommand
    {
        string Label { get; }
        void Do(CommandContext ctx);
        void Undo(CommandContext ctx);
    }

    /// <summary>Add a node as a child of <c>parent</c> (placement = pick the parent, §0.1/§3). Packer positions it.</summary>
    public sealed class AddNodeCommand : IAuthoringCommand
    {
        private readonly ElementId _parent;
        private readonly ElementKind _kind;
        private readonly string _name;
        private readonly bool _isAbstract;
        public ElementId CreatedId { get; private set; }

        public AddNodeCommand(ElementId parent, ElementKind kind, string name, bool isAbstract)
        {
            _parent = parent;
            _kind = kind;
            _name = name;
            _isAbstract = isAbstract;
        }

        public string Label => $"Add {_kind}";

        public void Do(CommandContext ctx)
        {
            if (!CreatedId.IsValid)
                CreatedId = ctx.Ids.NewElementId(_parent, _kind, _name);
            ctx.Model.AddElement(CreatedId, _kind, _name, _parent, _isAbstract);
            ctx.Packer.OnInserted(CreatedId, _parent);
        }

        public void Undo(CommandContext ctx)
        {
            ctx.Model.RemoveElement(CreatedId);
            ctx.Packer.OnRemoved(_parent);
        }
    }

    /// <summary>Connect two elements with a relationship (§4). Direction is from→to.</summary>
    public sealed class ConnectCommand : IAuthoringCommand
    {
        private readonly ElementId _from, _to;
        private readonly EdgeKind _kind;
        public EdgeId CreatedId { get; private set; }

        public ConnectCommand(ElementId from, ElementId to, EdgeKind kind)
        {
            _from = from;
            _to = to;
            _kind = kind;
        }

        public string Label => $"Connect ({_kind})";

        public void Do(CommandContext ctx)
        {
            if (!CreatedId.IsValid)
                CreatedId = ctx.Ids.NewEdgeId(_from, _to, _kind);
            ctx.Model.AddEdge(CreatedId, _kind, _from, _to);
        }

        public void Undo(CommandContext ctx) => ctx.Model.RemoveEdge(CreatedId);
    }

    /// <summary>Re-parent — the only "move" gesture (§3.6). Packer re-packs both old and new parent.</summary>
    public sealed class ReParentCommand : IAuthoringCommand
    {
        private readonly ElementId _element, _newParent;
        private ElementId _oldParent;

        public ReParentCommand(ElementId element, ElementId newParent)
        {
            _element = element;
            _newParent = newParent;
        }

        public string Label => "Re-parent";

        public void Do(CommandContext ctx)
        {
            _oldParent = ctx.Model.Get(_element).Parent;
            ctx.Model.Reparent(_element, _newParent);
            ctx.Packer.OnRemoved(_oldParent);
            ctx.Packer.OnInserted(_element, _newParent);
        }

        public void Undo(CommandContext ctx)
        {
            ctx.Model.Reparent(_element, _oldParent);
            ctx.Packer.OnRemoved(_newParent);
            ctx.Packer.OnInserted(_element, _oldParent);
        }
    }

    /// <summary>Change a relationship's type in place (§4.6 re-type).</summary>
    public sealed class ReTypeEdgeCommand : IAuthoringCommand
    {
        private readonly EdgeId _edge;
        private readonly EdgeKind _newKind;
        private EdgeKind _oldKind;

        public ReTypeEdgeCommand(EdgeId edge, EdgeKind newKind)
        {
            _edge = edge;
            _newKind = newKind;
        }

        public string Label => $"Re-type → {_newKind}";

        public void Do(CommandContext ctx)
        {
            _oldKind = ctx.Model.Get(_edge).Kind;
            ctx.Model.SetEdgeType(_edge, _newKind);
        }

        public void Undo(CommandContext ctx) => ctx.Model.SetEdgeType(_edge, _oldKind);
    }

    /// <summary>
    /// Set a relationship's adornments — midpoint <c>label</c> (association name / role) and the
    /// per-end <c>source</c>/<c>target</c> multiplicities (e.g. "1", "0..*"). One reversible undo step.
    /// </summary>
    public sealed class SetEdgeMetaCommand : IAuthoringCommand
    {
        private readonly EdgeId _edge;
        private readonly string _label, _source, _target;
        private string _oldLabel, _oldSource, _oldTarget;

        public SetEdgeMetaCommand(EdgeId edge, string label, string source, string target)
        {
            _edge = edge;
            _label = Norm(label);
            _source = Norm(source);
            _target = Norm(target);
        }

        private static string Norm(string s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim();

        public string Label => "Edit relationship";

        public void Do(CommandContext ctx)
        {
            var e = ctx.Model.Get(_edge);
            _oldLabel = e.Label;
            _oldSource = e.SourceMultiplicity;
            _oldTarget = e.TargetMultiplicity;
            ctx.Model.SetEdgeLabel(_edge, _label);
            ctx.Model.SetEdgeMultiplicity(_edge, _source, _target);
        }

        public void Undo(CommandContext ctx)
        {
            ctx.Model.SetEdgeLabel(_edge, _oldLabel);
            ctx.Model.SetEdgeMultiplicity(_edge, _oldSource, _oldTarget);
        }
    }

