    /// <summary>
    /// Delete an element and its whole subtree plus every incident edge, as a single undo step (§4.6/§3.6).
    /// Snapshots everything removed so <see cref="Undo"/> restores the subtree and edges exactly.
    /// </summary>
    public sealed class DeleteElementCommand : IAuthoringCommand
    {
        private readonly ElementId _root;
        private ElementId _rootParent;

        private readonly struct ElementSnap
        {
            public readonly ElementId Id, Parent;
            public readonly ElementKind Kind;
            public readonly string Name, Language, Stereotype, Description, Code, SourceFile;
            public readonly bool IsAbstract;
            public readonly int ZLayer;
            public ElementSnap(ModelElement e)
            {
                Id = e.Id; Parent = e.Parent; Kind = e.Kind; Name = e.Name; IsAbstract = e.IsAbstract;
                Language = e.Language; Stereotype = e.Stereotype; Description = e.Description;
                ZLayer = e.ZLayer; Code = e.Code; SourceFile = e.SourceFile;
            }
        }

        private readonly struct EdgeSnap
        {
            public readonly EdgeId Id; public readonly EdgeKind Kind; public readonly ElementId From, To;
            public readonly string Label, Source, Target;
            public EdgeSnap(ModelEdge e)
            {
                Id = e.Id; Kind = e.Kind; From = e.From; To = e.To;
                Label = e.Label; Source = e.SourceMultiplicity; Target = e.TargetMultiplicity;
            }
        }

        private List<ElementSnap> _removedElements;
        private List<EdgeSnap> _removedEdges;

        public DeleteElementCommand(ElementId root) => _root = root;

        public string Label => "Delete";

        public void Do(CommandContext ctx)
        {
            var model = ctx.Model;
            var root = model.Get(_root);
            _rootParent = root.Parent;

            // Collect the subtree in parent-before-child order so undo can re-add parents first.
            var ordered = new List<ElementId>();
            var queue = new Queue<ElementId>();
            queue.Enqueue(_root);
            while (queue.Count > 0)
            {
                var id = queue.Dequeue();
                ordered.Add(id);
                foreach (var child in model.Get(id).ChildIds)
                    queue.Enqueue(child);
            }

            var subtree = new HashSet<ElementId>(ordered);
            _removedElements = new List<ElementSnap>(ordered.Count);
            foreach (var id in ordered)
                _removedElements.Add(new ElementSnap(model.Get(id)));

            // Any edge touching the subtree goes too.
            _removedEdges = new List<EdgeSnap>();
            foreach (var edge in model.Edges)
                if (subtree.Contains(edge.From) || subtree.Contains(edge.To))
                    _removedEdges.Add(new EdgeSnap(edge));

            foreach (var e in _removedEdges) model.RemoveEdge(e.Id);
            // Remove children before parents (reverse of add order) to keep the tree consistent.
            for (int i = ordered.Count - 1; i >= 0; i--)
                model.RemoveElement(ordered[i]);

            ctx.Packer.OnRemoved(_rootParent);
        }

        public void Undo(CommandContext ctx)
        {
            var model = ctx.Model;
            // Parents first (snapshot is in BFS order), so each child's parent already exists.
            foreach (var s in _removedElements)
            {
                var restored = model.AddElement(s.Id, s.Kind, s.Name, s.Parent, s.IsAbstract);
                restored.Language = s.Language;
                restored.Stereotype = s.Stereotype;
                restored.Description = s.Description;
                restored.ZLayer = s.ZLayer;
                restored.Code = s.Code;
                restored.SourceFile = s.SourceFile;
            }
            foreach (var e in _removedEdges)
            {
                var edge = model.AddEdge(e.Id, e.Kind, e.From, e.To);
                edge.Label = e.Label;
                edge.SourceMultiplicity = e.Source;
                edge.TargetMultiplicity = e.Target;
            }
            ctx.Packer.OnInserted(_root, _rootParent);
        }
    }
}

using System.Collections.Generic;

namespace TheRobotDraft.Authoring.Commands
{
    /// <summary>
    /// The authoring history. Executing a command runs it and pushes it onto the undo stack, clearing the redo
    /// stack (standard linear history). <c>Undo</c>/<c>Redo</c> are the instantaneous §1 verbs — never modes.
    /// Toolbar Undo/Redo dim from <see cref="CanUndo"/>/<see cref="CanRedo"/> (authoring-ux.md §2.2).
    /// </summary>
    public sealed class UndoStack
    {
        private readonly CommandContext _ctx;
        private readonly Stack<IAuthoringCommand> _undo = new();
        private readonly Stack<IAuthoringCommand> _redo = new();

        public UndoStack(CommandContext ctx) => _ctx = ctx;

        public bool CanUndo => _undo.Count > 0;
        public bool CanRedo => _redo.Count > 0;
        public int Depth => _undo.Count;

        /// <summary>The label of the command Undo would reverse (for the tooltip), or null.</summary>
        public string PendingUndoLabel => _undo.Count > 0 ? _undo.Peek().Label : null;
        public string PendingRedoLabel => _redo.Count > 0 ? _redo.Peek().Label : null;

        /// <summary>Run a command and record it. Returns the same instance so callers can read its result (e.g. CreatedId).</summary>
        public T Execute<T>(T command) where T : IAuthoringCommand
        {
            command.Do(_ctx);
            _undo.Push(command);
            _redo.Clear();
            return command;
        }

        public bool Undo()
        {
            if (_undo.Count == 0) return false;
            var cmd = _undo.Pop();
            cmd.Undo(_ctx);
            _redo.Push(cmd);
            return true;
        }

        public bool Redo()
        {
            if (_redo.Count == 0) return false;
            var cmd = _redo.Pop();
            cmd.Do(_ctx);
            _undo.Push(cmd);
            return true;
        }

        public void Clear()
        {
            _undo.Clear();
            _redo.Clear();
        }
    }
}

using System;
using System.Collections.Generic;

namespace TheRobotDraft.Authoring.Model
{
    /// <summary>One element (node) in the unified model: a kind, a name, a containment parent, and modifiers.</summary>
    public sealed class ModelElement
    {
        public ElementId Id { get; }
        public ElementKind Kind { get; internal set; }
        public string Name { get; internal set; }
        public ElementId Parent { get; internal set; }

        /// <summary>UML <c>abstract</c> is a modifier, not a kind (§3.1) — outline/wireframe glyph.</summary>
        public bool IsAbstract { get; internal set; }

        /// <summary>
        /// Implementation language for a classifier (e.g. "C#", "Java", "C++", "TypeScript") — Rational Rose /
        /// Sparx EA track this per type so generated code and type semantics follow the right grammar.
        /// Null/empty = unspecified. Members ignore it.
        /// </summary>
        public string Language { get; internal set; }

        /// <summary>
        /// Custom UML stereotype override (e.g. "entity", "service", "controller"). When set it replaces the
        /// kind-derived «interface»/«enumeration» guillemet label. Null/empty = use the derived stereotype.
        /// </summary>
        public string Stereotype { get; internal set; }

        /// <summary>Free-text description / documentation of this element. Null/empty = none. Used by code generation.</summary>
        public string Description { get; internal set; }

        /// <summary>
        /// The element's saved source code — the approved output of "Generate code", and the round-trip
        /// counterpart to code→elements (the module/class body lives on the node). Null/empty = none.
        /// </summary>
        public string Code { get; internal set; }

        /// <summary>
        /// The source file this element was imported from (relative or absolute path) — set by folder import and
        /// used to drive surgical overlay regeneration back into the same file. Null/empty = none.
        /// </summary>
        public string SourceFile { get; internal set; }

        /// <summary>
        /// The diagram Z-layer this element lives on (0 = base). The canvas shows one active layer; elements on
        /// other layers are hidden, with cross-layer relationships shown as up/down connector stubs.
        /// </summary>
        public int ZLayer { get; internal set; }

        internal readonly List<ElementId> Children = new();

        internal ModelElement(ElementId id, ElementKind kind, string name, ElementId parent)
        {
            Id = id;
            Kind = kind;
            Name = name;
            Parent = parent;
        }

        public IReadOnlyList<ElementId> ChildIds => Children;
    }

    /// <summary>One relationship (edge) in the unified model. Direction is from→to (§4.2).</summary>
    public sealed class ModelEdge
    {
        public EdgeId Id { get; }
        public EdgeKind Kind { get; internal set; }
        public ElementId From { get; internal set; }
        public ElementId To { get; internal set; }

        /// <summary>Association name / role label drawn at the relationship's midpoint (e.g. "line item"). Null = none.</summary>
        public string Label { get; internal set; }

        /// <summary>UML multiplicity at the <see cref="From"/> end (e.g. "1", "0..*", "1..*"). Null = unspecified.</summary>
        public string SourceMultiplicity { get; internal set; }

        /// <summary>UML multiplicity at the <see cref="To"/> end (e.g. "1", "0..*", "1..*"). Null = unspecified.</summary>
        public string TargetMultiplicity { get; internal set; }

        internal ModelEdge(EdgeId id, EdgeKind kind, ElementId from, ElementId to)
        {
            Id = id;
            Kind = kind;
            From = from;
            To = to;
        }
    }

    /// <summary>
    /// The in-memory unified model that authoring verbs mutate (authoring-ux.md §0.2: every verb is a model
    /// edit; all views are re-derived from this). This type owns the containment <em>tree</em> and the edge
    /// list and enforces structural integrity (a node has exactly one parent; ids are unique). It does
    /// <em>not</em> own geometry — positions/radii are the packer's job (ADR-003) and live behind
    /// <see cref="Seams.IPacker"/>. Mutators are deliberately low-level and reversible so the command layer
    /// (§0.2 "each is a single undo step") can compose and unwind them precisely.
    /// </summary>
    public sealed class AuthoringModel
    {
        private readonly Dictionary<ElementId, ModelElement> _elements = new();
        private readonly Dictionary<EdgeId, ModelEdge> _edges = new();

        public IReadOnlyCollection<ModelElement> Elements => _elements.Values;
        public IReadOnlyCollection<ModelEdge> Edges => _edges.Values;

        public bool TryGet(ElementId id, out ModelElement element) => _elements.TryGetValue(id, out element);
        public bool TryGet(EdgeId id, out ModelEdge edge) => _edges.TryGetValue(id, out edge);
        public bool Contains(ElementId id) => _elements.ContainsKey(id);

        public ModelElement Get(ElementId id) =>
            _elements.TryGetValue(id, out var e) ? e : throw new KeyNotFoundException($"element {id}");

        public ModelEdge Get(EdgeId id) =>
            _edges.TryGetValue(id, out var e) ? e : throw new KeyNotFoundException($"edge {id}");

        // --- element mutators (called only by commands) ---

        internal ModelElement AddElement(ElementId id, ElementKind kind, string name, ElementId parent,
            bool isAbstract)
        {
            if (_elements.ContainsKey(id))
                throw new InvalidOperationException($"element {id} already exists");
            if (parent.IsValid && !_elements.ContainsKey(parent))
                throw new InvalidOperationException($"parent {parent} does not exist");

            var element = new ModelElement(id, kind, name, parent) { IsAbstract = isAbstract };
            _elements.Add(id, element);
            if (parent.IsValid)
                _elements[parent].Children.Add(id);
            return element;
        }

        internal void RemoveElement(ElementId id)
        {
            if (!_elements.TryGetValue(id, out var element)) return;
            if (element.Parent.IsValid && _elements.TryGetValue(element.Parent, out var parent))
                parent.Children.Remove(id);
            _elements.Remove(id);
        }

        internal void Reparent(ElementId id, ElementId newParent)
        {
            var element = _elements[id];
            if (element.Parent.IsValid && _elements.TryGetValue(element.Parent, out var old))
                old.Children.Remove(id);
            element.Parent = newParent;
            if (newParent.IsValid)
                _elements[newParent].Children.Add(id);
        }

        internal void Rename(ElementId id, string name) => _elements[id].Name = name;
        internal void SetKind(ElementId id, ElementKind kind) => _elements[id].Kind = kind;
        internal void SetAbstract(ElementId id, bool isAbstract) => _elements[id].IsAbstract = isAbstract;
        internal void SetLanguage(ElementId id, string language) => _elements[id].Language = language;
        internal void SetStereotype(ElementId id, string stereotype) => _elements[id].Stereotype = stereotype;
        internal void SetDescription(ElementId id, string description) => _elements[id].Description = description;
        internal void SetCode(ElementId id, string code) => _elements[id].Code = code;
        internal void SetSourceFile(ElementId id, string sourceFile) => _elements[id].SourceFile = sourceFile;
        internal void SetZLayer(ElementId id, int z) => _elements[id].ZLayer = z;

        // --- edge mutators ---

        internal ModelEdge AddEdge(EdgeId id, EdgeKind kind, ElementId from, ElementId to)
        {
            if (_edges.ContainsKey(id))
                throw new InvalidOperationException($"edge {id} already exists");
            var edge = new ModelEdge(id, kind, from, to);
            _edges.Add(id, edge);
            return edge;
        }

        internal void RemoveEdge(EdgeId id) => _edges.Remove(id);
        internal void SetEdgeType(EdgeId id, EdgeKind kind) => _edges[id].Kind = kind;
        internal void SetEdgeLabel(EdgeId id, string label) => _edges[id].Label = label;
        internal void SetEdgeMultiplicity(EdgeId id, string source, string target)
        {
            var edge = _edges[id];
            edge.SourceMultiplicity = source;
            edge.TargetMultiplicity = target;
        }
        internal void SetEdgeEndpoints(EdgeId id, ElementId from, ElementId to)
        {
            var edge = _edges[id];
            edge.From = from;
            edge.To = to;
        }

        /// <summary>True if <paramref name="ancestor"/> contains <paramref name="node"/> transitively (cycle/containment checks).</summary>
        public bool IsAncestorOf(ElementId ancestor, ElementId node)
        {
            var cur = node;
            var guard = 0;
            while (cur.IsValid && _elements.TryGetValue(cur, out var e))
            {
                if (e.Parent == ancestor) return true;
                cur = e.Parent;
                if (++guard > 100_000) break; // defensive: malformed tree
            }
            return false;
        }
    }
}

using System;

namespace TheRobotDraft.Authoring.Model
{
    /// <summary>
    /// Stable identity for a model element. The value is the element's <em>stable key</em> (qualified-name
    /// hash, rendering-and-vr.md §2.1 "stable addresses") so a node keeps its identity — and roughly its
    /// packed position — across edits and re-derivation. Authoring commands address elements by this id, never
    /// by transient array index or scene-object reference.
    /// </summary>
    public readonly struct ElementId : IEquatable<ElementId>
    {
        public readonly string Value;

        public ElementId(string value) => Value = value;

        public bool IsValid => !string.IsNullOrEmpty(Value);
        public static readonly ElementId None = new ElementId(null);

        public bool Equals(ElementId other) => string.Equals(Value, other.Value, StringComparison.Ordinal);
        public override bool Equals(object obj) => obj is ElementId other && Equals(other);
        public override int GetHashCode() => Value is null ? 0 : StringComparer.Ordinal.GetHashCode(Value);
        public override string ToString() => Value ?? "<none>";

        public static bool operator ==(ElementId a, ElementId b) => a.Equals(b);
        public static bool operator !=(ElementId a, ElementId b) => !a.Equals(b);
    }

    /// <summary>Stable identity for an edge (relationship). Edges are model objects, not drawn artifacts (§0.2).</summary>
    public readonly struct EdgeId : IEquatable<EdgeId>
    {
        public readonly string Value;

        public EdgeId(string value) => Value = value;

        public bool IsValid => !string.IsNullOrEmpty(Value);
        public static readonly EdgeId None = new EdgeId(null);

        public bool Equals(EdgeId other) => string.Equals(Value, other.Value, StringComparison.Ordinal);
        public override bool Equals(object obj) => obj is EdgeId other && Equals(other);
        public override int GetHashCode() => Value is null ? 0 : StringComparer.Ordinal.GetHashCode(Value);
        public override string ToString() => Value ?? "<none>";

        public static bool operator ==(EdgeId a, EdgeId b) => a.Equals(b);
        public static bool operator !=(EdgeId a, EdgeId b) => !a.Equals(b);
    }
}

namespace TheRobotDraft.Authoring.Model
{
    /// <summary>
    /// The UML class/bubble-core element kinds for v1 (authoring-ux.md §3.1). These are the kinds the
    /// code→model reverse-engineering pipeline produces; the patterns generalize to other notations later.
    /// Order matches the creation-palette table; <see cref="ElementKind.Class"/> is the palette default.
    /// </summary>
    public enum ElementKind
    {
        Package,
        Class,
        Interface,
        Enum,
        Struct,
        Function,
        Field,

        /// <summary>A free-text UML note / comment (dog-eared box). Holds no members; attaches via a dashed link.</summary>
        Note,

        // --- use-case diagram ---
        Actor,
        UseCase,

        // --- state-machine diagram ---
        State,
        StateStart,
        StateEnd,

        /// <summary>External / library element — read-only (§5.3). Not a creation-palette slot.</summary>
        External,

        // --- additions (appended so saved-diagram kind ordinals stay stable) ---

        // class / object diagrams
        /// <summary>A «dataType» classifier (value type with attributes/operations).</summary>
        DataType,
        /// <summary>A «primitive» type leaf (Integer, String, …).</summary>
        PrimitiveType,
        /// <summary>An object-diagram instance specification ("name : Class", underlined; slots in the body).</summary>
        ObjectInstance,

        // use-case diagram
        /// <summary>A use-case system boundary / subject — a titled frame that visually groups use cases.</summary>
        Boundary,

        // state-machine + activity control nodes
        /// <summary>A decision / choice / merge pseudostate (diamond). Guards on the outgoing transitions.</summary>
        Decision,
        /// <summary>A fork / join bar — splits one flow into concurrent flows, or synchronizes them back.</summary>
        ForkJoin,
        /// <summary>A junction pseudostate (small filled dot) chaining transition segments.</summary>
        Junction,
        /// <summary>A (shallow) history pseudostate — the circled H.</summary>
        History,
        /// <summary>A terminate pseudostate — the crossed circle that ends the whole machine.</summary>
        Terminate,

        // activity diagram
        /// <summary>An activity action node (rounded "pill"), the verb of an activity diagram.</summary>
        Activity,
        /// <summary>An activity flow-final node — a circled ✕ that consumes a single incoming token.</summary>
        FlowFinal,

        // component / deployment diagrams
        /// <summary>A «component» classifier (rectangle with the two-tab component icon).</summary>
        Component,
        /// <summary>An «artifact» (a physical file/document, dog-eared rectangle).</summary>
        Artifact,
        /// <summary>A deployment node / device — drawn as a 3-D box.</summary>
        DeploymentNode,

        // package diagram
        /// <summary>A package shown as a node (folder/tabbed rectangle) inside a package diagram.</summary>
        PackageNode,

        // composite-structure diagram
        /// <summary>An internal part of a composite structure (a typed role rectangle).</summary>
        Part,
        /// <summary>A port — the small square interaction point on a part / component border.</summary>
        Port,
        /// <summary>A collaboration — the dashed ellipse naming a structural pattern of roles.</summary>
        Collaboration,

        // sequence / communication / interaction-overview diagrams
        /// <summary>A sequence-diagram lifeline: a head (object) box with a dashed life line dropping below it.</summary>
        Lifeline,
        /// <summary>An execution / activation bar sitting on a lifeline.</summary>
        Activation,
        /// <summary>An interaction frame / combined fragment (sd, alt, opt, loop, par) — a labeled region.</summary>
        Frame,

        // profile diagram
        /// <summary>A «metaclass» — an element of the reference metamodel that a stereotype extends.</summary>
        Metaclass,
        /// <summary>A «stereotype» definition (a profile-diagram classifier).</summary>
        Stereotype,
        /// <summary>A «profile» — the package/region that groups stereotype definitions.</summary>
        Profile,

        // timing diagram
        /// <summary>A timing-diagram lifeline: a participant's state plotted as a waveform over a time axis.</summary>
        TimingLifeline,

        /// <summary>A call-behavior activity node (rounded rect with the rake icon) — distinct from an atomic action.</summary>
        CallActivity,
    }

    /// <summary>
    /// The UML relationship edge kinds. The first six are class-diagram relationships; the rest carry the
    /// behavioral / cross-diagram connectors (state &amp; activity flow, use-case include/extend, note anchors,
    /// directed associations) so every node type gets a relationship that shows the correct direction (§4.2).
    /// Appended so saved-diagram edge ordinals stay stable.
    /// </summary>
    public enum EdgeKind
    {
        Association,
        Dependency,
        Generalization,
        Realization,
        Aggregation,
        Composition,

        /// <summary>A state-machine / activity flow (solid line, open arrow) — the "information flow" connector.</summary>
        Transition,
        /// <summary>A use-case «include» (dashed, open arrow): the base use case always pulls in the included one.</summary>
        Include,
        /// <summary>A use-case «extend» (dashed, open arrow): the extension optionally augments the base.</summary>
        Extend,
        /// <summary>A note / comment anchor (dashed line, no arrowhead) tying a note to the element it annotates.</summary>
        NoteLink,
        /// <summary>A navigable / directed association (solid line, open arrow) — class-diagram information flow.</summary>
        DirectedAssociation,

        /// <summary>A synchronous sequence message (solid line, filled arrowhead) — a blocking call.</summary>
        MessageSync,
        /// <summary>An asynchronous sequence message (solid line, open stick arrowhead) — a signal / non-blocking send.</summary>
        MessageAsync,
        /// <summary>A reply / return message (dashed line, open stick arrowhead).</summary>
        MessageReply,

        /// <summary>A profile «extension» — a stereotype extends a metaclass (solid line, filled triangle head).</summary>
        Extension,
    }

    /// <summary>
    /// Static metadata about kinds. The hue strings are the §2.1 Okabe-Ito palette tokens; the renderer maps
    /// them to materials. Kept here (not in the renderer) so the authoring palette and the bubble show the
    /// same kind the same way without a translation step (§3.1, §5).
    /// </summary>
    public static class KindInfo
    {
        /// <summary>§2.1 kind hue, as a hex token. The reserved UI-state channel (§5.1) is deliberately not here.</summary>
        public static string Hue(ElementKind kind) => kind switch
        {
            ElementKind.Package => "#6E7B8B",
            ElementKind.Class => "#0072B2",
            ElementKind.Interface => "#56B4E9",
            ElementKind.Enum => "#E69F00",
            ElementKind.Struct => "#009E73",
            ElementKind.Function => "#2CA02C",
            ElementKind.Field => "#BCBD22",
            ElementKind.Note => "#F2E2A0",
            ElementKind.Actor => "#6B5B95",
            ElementKind.UseCase => "#4E9BC4",
            ElementKind.State => "#5AB28A",
            ElementKind.StateStart => "#2A2D34",
            ElementKind.StateEnd => "#2A2D34",
            ElementKind.External => "#999999",

            ElementKind.DataType => "#7FA6B0",
            ElementKind.PrimitiveType => "#9AA7B0",
            ElementKind.ObjectInstance => "#0072B2",
            ElementKind.Boundary => "#8893A0",
            ElementKind.Decision => "#E69F00",
            ElementKind.ForkJoin => "#2A2D34",
            ElementKind.Junction => "#2A2D34",
            ElementKind.History => "#5AB28A",
            ElementKind.Terminate => "#2A2D34",
            ElementKind.Activity => "#4FA3A0",
            ElementKind.FlowFinal => "#2A2D34",
            ElementKind.Component => "#5B8AC4",
            ElementKind.Artifact => "#B0A878",
            ElementKind.DeploymentNode => "#6E7B8B",
            ElementKind.PackageNode => "#6E7B8B",
            ElementKind.Part => "#7E8AA2",
            ElementKind.Port => "#C7CDD6",
            ElementKind.Collaboration => "#B9A6C8",
            ElementKind.Lifeline => "#5B8AC4",
            ElementKind.Activation => "#DDE3EA",
            ElementKind.Frame => "#8893A0",
            ElementKind.Metaclass => "#8FA8B8",
            ElementKind.Stereotype => "#C8A2C8",
            ElementKind.Profile => "#8893A0",
            ElementKind.TimingLifeline => "#5B8AC4",
            ElementKind.CallActivity => "#4FA3A0",
            _ => "#FFFFFF",
        };

        /// <summary>A classifier is a type-level element; edges in v1 connect classifiers, not members (§4.4).</summary>
        public static bool IsClassifier(ElementKind kind) => kind switch
        {
            ElementKind.Class or ElementKind.Interface or ElementKind.Enum or ElementKind.Struct
                or ElementKind.External or ElementKind.DataType or ElementKind.ObjectInstance
                or ElementKind.Component => true,
            _ => false,
        };

        /// <summary>Members (fields/functions) are leaves: they contain nothing and are not edge endpoints (§4.4).</summary>
        public static bool IsMember(ElementKind kind) =>
            kind == ElementKind.Field || kind == ElementKind.Function;

        /// <summary>
        /// A behavioral control node (state-machine / activity vocabulary). These connect with the directional
        /// <see cref="EdgeKind.Transition"/> "flow" arrow rather than a class-diagram association.
        /// </summary>
        public static bool IsBehavioral(ElementKind kind) => kind switch
        {
            ElementKind.State or ElementKind.Activity or ElementKind.CallActivity or ElementKind.StateStart
                or ElementKind.StateEnd or ElementKind.Decision or ElementKind.ForkJoin or ElementKind.Junction
                or ElementKind.History or ElementKind.Terminate or ElementKind.FlowFinal => true,
            _ => false,
        };

        /// <summary>
        /// A free-standing diagram node drawn as its own shape on the canvas. Everything except packages (which
        /// are tabs) and members (which render inside their owner's compartments) is a diagram node.
        /// </summary>
        public static bool IsDiagramNode(ElementKind kind) =>
            kind != ElementKind.Package && !IsMember(kind);

        /// <summary>Any node that a relationship line may attach to (diagram nodes + packages).</summary>
        public static bool IsConnectable(ElementKind kind) =>
            IsDiagramNode(kind) || kind == ElementKind.Package;
    }
}

using TheRobotDraft.Authoring.Model;

namespace TheRobotDraft.Authoring.Rules
{
    /// <summary>
    /// The result of a legality check. Carries a human reason so the UI can show the §B invalid affordance
    /// (vermillion dashed rim + ✕) with a hover reason "at point-of-use rather than as a failed drop"
    /// (authoring-ux.md §3.1). A rule that is satisfied returns <see cref="Valid"/>; the reason is empty.
    /// </summary>
    public readonly struct Validity
    {
        public readonly bool IsValid;
        public readonly string Reason;

        private Validity(bool valid, string reason)
        {
            IsValid = valid;
            Reason = reason;
        }

        public static readonly Validity Valid = new Validity(true, null);
        public static Validity Invalid(string reason) => new Validity(false, reason);
    }

    /// <summary>
    /// Containment legality (authoring-ux.md §3.1 "containment-filtered"). Answers "may a child of
    /// <c>kind</c> live directly inside <c>parentKind</c>?" — the rule the creation palette dims an illegal
    /// chip on, and that add-node enforces. UML class/bubble core only for v1.
    /// </summary>
    public static class ContainmentRules
    {
        public static Validity CanContain(ElementKind parentKind, ElementKind childKind)
        {
            // External elements are read-only — nothing is authored inside them (§5.3).
            if (parentKind == ElementKind.External)
                return Validity.Invalid("external/library elements are read-only");

            // Members are leaves: they contain nothing.
            if (KindInfo.IsMember(parentKind))
                return Validity.Invalid($"a {parentKind} cannot contain other elements");

            bool ok = parentKind switch
            {
                // A package groups any diagram node and sub-packages — never raw members (the spec's worked
                // example: a Field directly under a Package is illegal).
                ElementKind.Package => childKind == ElementKind.Package || KindInfo.IsDiagramNode(childKind),

                // Classifiers hold members and (language-permitting) nested types.
                ElementKind.Class or ElementKind.Struct => childKind is ElementKind.Field or ElementKind.Function
                    or ElementKind.Class or ElementKind.Interface or ElementKind.Enum or ElementKind.Struct,

                ElementKind.Interface => childKind is ElementKind.Function or ElementKind.Field
                    or ElementKind.Interface or ElementKind.Enum,

                ElementKind.Enum => childKind is ElementKind.Field or ElementKind.Function,

                // A «dataType» carries attributes/operations; an object instance carries slot values (fields).
                ElementKind.DataType => childKind is ElementKind.Field or ElementKind.Function,
                ElementKind.ObjectInstance => childKind == ElementKind.Field,

                _ => false,
            };

            return ok
                ? Validity.Valid
                : Validity.Invalid($"a {childKind} is not allowed directly inside a {parentKind}");
        }
    }

    /// <summary>
    /// Edge legality, kind-aware and "felt during the drag" (authoring-ux.md §4.4). Edges in v1 connect
    /// classifiers (and packages, for dependency), never members. Self-edges, generalization typing, and
    /// generalization cycles are checked here so the §B invalid affordance fires before the drop.
    /// </summary>
    public static class EdgeRules
    {
        /// <param name="model">needed for the would-create-cycle generalization check.</param>
        public static Validity CanConnect(AuthoringModel model, EdgeKind kind, ElementId fromId, ElementId toId)
        {
            if (!model.TryGet(fromId, out var from) || !model.TryGet(toId, out var to))
                return Validity.Invalid("endpoint does not exist");

            // Members are never edge endpoints in v1 (§4.4: "a Field/Function as a generalization endpoint → invalid").
            if (KindInfo.IsMember(from.Kind) || KindInfo.IsMember(to.Kind))
                return Validity.Invalid("relationships connect types, not fields or methods");

            bool selfEdge = fromId == toId;

            switch (kind)
            {
                case EdgeKind.Generalization:
                    if (selfEdge)
                        return Validity.Invalid("a type cannot generalize itself");
                    // class→class or interface→interface only (§4.4).
                    bool genOk = (from.Kind == ElementKind.Class && to.Kind == ElementKind.Class)
                                 || (from.Kind == ElementKind.Interface && to.Kind == ElementKind.Interface);
                    if (!genOk)
                        return Validity.Invalid("generalization is class→class or interface→interface only");
                    // would-create-cycle: target must not already (transitively) generalize the source.
                    if (CreatesGeneralizationCycle(model, fromId, toId))
                        return Validity.Invalid("would create an inheritance cycle");
                    return Validity.Valid;

                case EdgeKind.Realization:
                    if (selfEdge) return Validity.Invalid("a type cannot realize itself");
                    // class/struct → interface (§4.4: realization: class→interface).
                    bool realOk = (from.Kind is ElementKind.Class or ElementKind.Struct)
                                  && to.Kind == ElementKind.Interface;
                    return realOk
                        ? Validity.Valid
                        : Validity.Invalid("realization is class→interface");

                case EdgeKind.Aggregation:
                case EdgeKind.Composition:
                    if (selfEdge)
                        return Validity.Invalid("self aggregation/composition is not permitted");
                    // whole/part among classifiers (not packages).
                    return (KindInfo.IsClassifier(from.Kind) && KindInfo.IsClassifier(to.Kind))
                        ? Validity.Valid
                        : Validity.Invalid($"{kind} connects types, not packages");

                case EdgeKind.Association:
                    // Associations/transitions connect any diagram nodes (types, actors, use cases, states).
                    return (KindInfo.IsConnectable(from.Kind) && KindInfo.IsConnectable(to.Kind))
                        ? Validity.Valid
                        : Validity.Invalid("association connects diagram nodes");

                case EdgeKind.Dependency:
                    // loosest: any classifier or package → any classifier or package, and notes attach this way
                    // too (a note→element comment link is a dashed line). (§4.5: package-level dependency is legal.)
                    return KindInfo.IsConnectable(from.Kind) && KindInfo.IsConnectable(to.Kind)
                        ? Validity.Valid
                        : Validity.Invalid("dependency connects diagram nodes or packages");

                case EdgeKind.Transition:
                    // State-machine / activity flow. Self-transitions are legal (a state may loop on itself).
                    return KindInfo.IsConnectable(from.Kind) && KindInfo.IsConnectable(to.Kind)
                        ? Validity.Valid
                        : Validity.Invalid("a transition connects diagram nodes");

                case EdgeKind.DirectedAssociation:
                    return KindInfo.IsConnectable(from.Kind) && KindInfo.IsConnectable(to.Kind)
                        ? Validity.Valid
                        : Validity.Invalid("a directed association connects diagram nodes");

                case EdgeKind.Include:
                case EdgeKind.Extend:
                    if (selfEdge) return Validity.Invalid("«include»/«extend» connect two use cases");
                    return (from.Kind == ElementKind.UseCase && to.Kind == ElementKind.UseCase)
                        ? Validity.Valid
                        : Validity.Invalid("«include»/«extend» connect use cases");

                case EdgeKind.NoteLink:
                    // A comment anchor: one end is a note, the other is whatever it annotates.
                    return (from.Kind == ElementKind.Note || to.Kind == ElementKind.Note)
                        ? Validity.Valid
                        : Validity.Invalid("a note anchor must touch a note");

                case EdgeKind.MessageSync:
                case EdgeKind.MessageAsync:
                case EdgeKind.MessageReply:
                    // Sequence / communication messages between lifelines, activations and objects (self-calls ok).
                    return KindInfo.IsConnectable(from.Kind) && KindInfo.IsConnectable(to.Kind)
                        ? Validity.Valid
                        : Validity.Invalid("a message connects lifelines / objects");

                case EdgeKind.Extension:
                    if (selfEdge) return Validity.Invalid("an extension links a stereotype to a metaclass");
                    return (from.Kind == ElementKind.Stereotype && to.Kind == ElementKind.Metaclass)
                        ? Validity.Valid
                        : Validity.Invalid("«extension» links a stereotype → metaclass");

                default:
                    return Validity.Invalid("unknown relationship");
            }
        }

        /// <summary>True if adding <c>from --generalizes--&gt; to</c> would close a cycle (to already reaches from).</summary>
        private static bool CreatesGeneralizationCycle(AuthoringModel model, ElementId fromId, ElementId toId)
        {
            // Walk supertypes of `to` along existing generalization edges; if we reach `from`, it's a cycle.
            var stack = new System.Collections.Generic.Stack<ElementId>();
            var seen = new System.Collections.Generic.HashSet<ElementId>();
            stack.Push(toId);
            while (stack.Count > 0)
            {
                var cur = stack.Pop();
                if (cur == fromId) return true;
                if (!seen.Add(cur)) continue;
                foreach (var edge in model.Edges)
                    if (edge.Kind == EdgeKind.Generalization && edge.From == cur)
                        stack.Push(edge.To);
            }
            return false;
        }
    }
}

