        ///</summary>
        ///<value>
        ///It returns one of these values: `Inconclusive`, `Skipped`, `Skipped:Ignored`, `Skipped:Explicit`, `Passed`, `Failed`, `Failed:Error`, `Failed:Cancelled`, `Failed:Invalid`
        ///</value>
        string ResultState { get; }
        ///<summary>
