   * primary cell — persona rows have nil user_id/email, so user_name||email would blank.
   */
  display_name?: string;
  /** Optional avatar (persona avatar; nil for users — fall back to the dot/initial). */
  avatar?: string | null;
  // ── user rows ── (nil on persona rows)
  user_id?: string;
