    return request<{ message: ChatMessage }>(
      `/api/v1/organizations/${orgId}/chat/rooms/${roomId}/messages`,
      { method: "POST", body: JSON.stringify({ message }) },
    );
  },
  // All three return the regrouped per-message summary [{emoji,count,me}] (marcus
