export type HeroIcon = ComponentType<SVGProps<SVGSVGElement>>;

interface NavDef {
  href: string;
  Icon: HeroIcon;
  label: string;
  orgScoped?: boolean;
}

export interface ResolvedNavItem {
  href: string;
  label: string;
  Icon: HeroIcon;
  active: boolean;
}

const NAV: NavDef[] = [
  { href: '/app/organizations', Icon: BuildingOffice2Icon, label: 'Organizations' },
  { href: '/members', Icon: UsersIcon, label: 'Members', orgScoped: true },
  { href: '/projects', Icon: Squares2X2Icon, label: 'Projects', orgScoped: true },
  { href: '/sessions', Icon: ClockIcon, label: 'Sessions', orgScoped: true },
  { href: '/personas', Icon: UserCircleIcon, label: 'Personas', orgScoped: true },
  { href: '/memory', Icon: SparklesIcon, label: 'Memory', orgScoped: true },
  { href: '/instructions', Icon: ClipboardDocumentListIcon, label: 'Instructions', orgScoped: true },
  { href: '/artifacts', Icon: CubeIcon, label: 'Artifacts', orgScoped: true },
  { href: '/assets', Icon: PhotoIcon, label: 'Assets', orgScoped: true },
  { href: '/browser', Icon: WindowIcon, label: 'Browser', orgScoped: true },
  { href: '/reviews', Icon: CheckBadgeIcon, label: 'Reviews', orgScoped: true },
  { href: '/chat', Icon: ChatBubbleLeftRightIcon, label: 'Chatrooms', orgScoped: true },
  { href: '/wiki', Icon: DocumentTextIcon, label: 'Wiki', orgScoped: true },
  { href: '/github', Icon: CodeBracketIcon, label: 'GitHub', orgScoped: true },
  { href: '/tickets', Icon: TicketIcon, label: 'Tickets', orgScoped: true },
  { href: '/boards', Icon: ViewColumnsIcon, label: 'Boards', orgScoped: true },
  { href: '/ticket-types', Icon: TagIcon, label: 'Ticket Types', orgScoped: true },
  { href: '/ticket-fields', Icon: AdjustmentsHorizontalIcon, label: 'Ticket Fields', orgScoped: true },
  { href: '/npl-conventions', Icon: BookOpenIcon, label: 'NPL Conventions', orgScoped: true },
  { href: '/mock-mcp', Icon: BeakerIcon, label: 'Mock MCP', orgScoped: true },
  { href: '/app/admin/authz', Icon: KeyIcon, label: 'Authz' },
];

export function useAppNav(): ResolvedNavItem[] {
  const pathname = usePathname();
  const params = useParams();
  const { currentOrg, organizations } = useOrg();

  // Only trust the route's org segment if it resolves to a known org (by slug or,
  // defensively, by id). A stray/unknown param must never propagate into every
  // nav link — fall back to the already-active org's slug so the sidebar can't be
  // left pointing at a non-org segment.
  const routeOrg = resolveOrg(organizations, params?.orgId as string | undefined);
  const orgSlug = routeOrg?.slug ?? currentOrg?.slug;
  const orgBase = orgSlug ? `/app/${orgSlug}` : '/app';

  return NAV.map((item) => {
    const href = item.orgScoped ? `${orgBase}${item.href}` : item.href;
    const active = pathname === href || pathname.startsWith(`${href}/`);
    return { href, label: item.label, Icon: item.Icon, active };
  });
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
import {
  acceptAllConsent,
  consentCategoryDetails,
  defaultConsentPreferences,
  getConsentState,
  hasConsent,
  onConsentChange,
  rejectOptionalConsent,
  setConsentPreferences,
  type ConsentCategory,
  type ConsentPreferences,
  type ConsentState,
  type OptionalConsentCategory,
} from "@/lib/consent";

interface CookieConsentContextValue {
  state: ConsentState | null;
  preferences: ConsentPreferences;
  hasDecision: boolean;
  isSettingsOpen: boolean;
  openSettings: () => void;
  closeSettings: () => void;
  acceptAll: () => void;
  rejectOptional: () => void;
  savePreferences: (preferences: Partial<Record<ConsentCategory, boolean>>) => void;
  hasCategoryConsent: (category: ConsentCategory) => boolean;
}

const CookieConsentContext = createContext<CookieConsentContextValue | null>(null);

function isOptionalCategory(category: ConsentCategory): category is OptionalConsentCategory {
  return category !== "necessary";
}

export function CookieConsentProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<ConsentState | null>(null);
  const [mounted, setMounted] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  useEffect(() => {
    setState(getConsentState());
    setMounted(true);
    return onConsentChange(setState);
  }, []);

  const openSettings = useCallback(() => setIsSettingsOpen(true), []);
  const closeSettings = useCallback(() => setIsSettingsOpen(false), []);

  const acceptAll = useCallback(() => {
    setState(acceptAllConsent());
    setIsSettingsOpen(false);
  }, []);

  const rejectOptional = useCallback(() => {
    setState(rejectOptionalConsent());
    setIsSettingsOpen(false);
  }, []);

  const savePreferences = useCallback(
    (preferences: Partial<Record<ConsentCategory, boolean>>) => {
      setState(setConsentPreferences(preferences));
      setIsSettingsOpen(false);
    },
    []
  );

  const value = useMemo<CookieConsentContextValue>(
    () => ({
      state,
      preferences: state?.categories ?? defaultConsentPreferences,
      hasDecision: Boolean(state),
      isSettingsOpen,
      openSettings,
      closeSettings,
      acceptAll,
      rejectOptional,
      savePreferences,
      hasCategoryConsent: hasConsent,
    }),
    [
      acceptAll,
      closeSettings,
      isSettingsOpen,
      openSettings,
      rejectOptional,
      savePreferences,
      state,
    ]
  );

  return (
    <CookieConsentContext.Provider value={value}>
      {children}
      {mounted ? <CookieConsentBanner /> : null}
    </CookieConsentContext.Provider>
  );
}

export function useCookieConsent() {
  const context = useContext(CookieConsentContext);
  if (!context) {
    throw new Error("useCookieConsent must be used inside CookieConsentProvider");
  }
  return context;
}

export function CookieSettingsButton({ className }: { className?: string }) {
  const { openSettings } = useCookieConsent();

  return (
    <button
      type="button"
      className={className ?? "sg-btn sg-btn--outline sg-btn--sm"}
      onClick={openSettings}
    >
      Cookie Settings
    </button>
  );
}

export function CookieConsentBanner() {
  const {
    hasDecision,
    isSettingsOpen,
    closeSettings,
    acceptAll,
    rejectOptional,
    savePreferences,
    preferences,
  } = useCookieConsent();
  const [draft, setDraft] = useState<ConsentPreferences>(preferences);

  useEffect(() => {
    if (!hasDecision || isSettingsOpen) {
      setDraft(preferences);
    }
  }, [hasDecision, isSettingsOpen, preferences]);

  if (hasDecision && !isSettingsOpen) return null;

  const updateDraft = (category: OptionalConsentCategory, value: boolean) => {
    setDraft((current) => ({ ...current, [category]: value }));
  };

  return (
    <section
      className="cookie-consent"
      role="dialog"
      aria-modal="false"
      aria-labelledby="cookie-consent-title"
    >
      <div className="cookie-consent__content">
        <div className="cookie-consent__intro">
          <p id="cookie-consent-title" className="cookie-consent__title">
            Cookie choices
          </p>
          <p className="cookie-consent__copy">
            We use necessary storage to keep this app working. Optional categories are
            disabled until you approve them, and you can change your choice later.
          </p>
        </div>

        <div className="cookie-consent__categories">
          {consentCategoryDetails.map((category) => (
            <label key={category.id} className="cookie-consent__category">
              <span>
                <span className="cookie-consent__category-title">{category.label}</span>
                <span className="cookie-consent__category-copy">{category.description}</span>
              </span>
              <input
                type="checkbox"
                checked={draft[category.id]}
                disabled={category.required}
                onChange={(event) => {
                  if (isOptionalCategory(category.id)) {
                    updateDraft(category.id, event.target.checked);
                  }
                }}
                aria-label={`${category.label} cookies`}
              />
            </label>
          ))}
        </div>

        <div className="cookie-consent__actions">
          {hasDecision ? (
            <button type="button" className="sg-btn sg-btn--outline" onClick={closeSettings}>
              Cancel
            </button>
          ) : null}
          <button type="button" className="sg-btn sg-btn--outline" onClick={rejectOptional}>
            Reject optional
          </button>
          <button
            type="button"
            className="sg-btn sg-btn--outline"
            onClick={() => savePreferences(draft)}
          >
            Save choices
          </button>
          <button type="button" className="sg-btn sg-btn--black" onClick={acceptAll}>
            Accept all
          </button>
        </div>
      </div>
    </section>
  );
}

'use client';

import { useRef, useState, useCallback } from 'react';
import {
  BoldIcon,
  ItalicIcon,
  H1Icon,
  H2Icon,
  H3Icon,
  ListBulletIcon,
  NumberedListIcon,
  ChatBubbleBottomCenterTextIcon,
  CodeBracketIcon,
  LinkIcon,
  MinusIcon,
} from '@heroicons/react/24/outline';
import { Markdown } from '@/components/markdown';

type Mode = 'write' | 'preview' | 'split';

interface Action {
  key: string;
  title: string;
  Icon: typeof BoldIcon;
  // Wrap the selection, or transform each selected line (for block actions).
  wrap?: [string, string];
  line?: (text: string, index: number) => string;
  insert?: string;
}

const ACTIONS: Action[] = [
  { key: 'bold', title: 'Bold (⌘B)', Icon: BoldIcon, wrap: ['**', '**'] },
  { key: 'italic', title: 'Italic (⌘I)', Icon: ItalicIcon, wrap: ['_', '_'] },
  { key: 'code', title: 'Inline code', Icon: CodeBracketIcon, wrap: ['`', '`'] },
  { key: 'h1', title: 'Heading 1', Icon: H1Icon, line: (t) => `# ${t.replace(/^#+\s*/, '')}` },
  { key: 'h2', title: 'Heading 2', Icon: H2Icon, line: (t) => `## ${t.replace(/^#+\s*/, '')}` },
  { key: 'h3', title: 'Heading 3', Icon: H3Icon, line: (t) => `### ${t.replace(/^#+\s*/, '')}` },
  { key: 'ul', title: 'Bulleted list', Icon: ListBulletIcon, line: (t) => `- ${t.replace(/^[-*]\s*/, '')}` },
  { key: 'ol', title: 'Numbered list', Icon: NumberedListIcon, line: (t, i) => `${i + 1}. ${t.replace(/^\d+\.\s*/, '')}` },
  { key: 'quote', title: 'Quote', Icon: ChatBubbleBottomCenterTextIcon, line: (t) => `> ${t.replace(/^>\s*/, '')}` },
  { key: 'link', title: 'Link', Icon: LinkIcon, wrap: ['[', '](https://)'] },
  { key: 'hr', title: 'Divider', Icon: MinusIcon, insert: '\n\n---\n\n' },
];

export function MarkdownEditor({
  value,
  onChange,
  rows = 18,
  placeholder = 'Write in markdown…',
}: {
  value: string;
  onChange: (next: string) => void;
  rows?: number;
  placeholder?: string;
}) {
  const ref = useRef<HTMLTextAreaElement>(null);
  const [mode, setMode] = useState<Mode>('write');

  const apply = useCallback(
    (action: Action) => {
      const ta = ref.current;
      if (!ta) return;
      const start = ta.selectionStart;
      const end = ta.selectionEnd;
      const selected = value.slice(start, end);
      let next = value;
      let caretStart = start;
      let caretEnd = end;

      if (action.insert) {
        next = value.slice(0, start) + action.insert + value.slice(end);
        caretStart = caretEnd = start + action.insert.length;
      } else if (action.wrap) {
        const [open, close] = action.wrap;
        next = value.slice(0, start) + open + selected + close + value.slice(end);
        caretStart = start + open.length;
        caretEnd = caretStart + selected.length;
      } else if (action.line) {
        // Expand selection to whole lines, then transform each line.
        const lineStart = value.lastIndexOf('\n', start - 1) + 1;
        const lineEndIdx = value.indexOf('\n', end);
        const lineEnd = lineEndIdx === -1 ? value.length : lineEndIdx;
        const block = value.slice(lineStart, lineEnd);
        const transformed = block.split('\n').map((l, i) => action.line!(l, i)).join('\n');
        next = value.slice(0, lineStart) + transformed + value.slice(lineEnd);
        caretStart = lineStart;
        caretEnd = lineStart + transformed.length;
      }

      onChange(next);
      requestAnimationFrame(() => {
        ta.focus();
        ta.setSelectionRange(caretStart, caretEnd);
      });
    },
    [value, onChange],
  );

  const onKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'b') {
        e.preventDefault();
        apply(ACTIONS[0]);
      } else if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'i') {
        e.preventDefault();
        apply(ACTIONS[1]);
      } else if (e.key === 'Tab') {
        e.preventDefault();
        const ta = e.currentTarget;
        const s = ta.selectionStart;
        const next = value.slice(0, s) + '  ' + value.slice(ta.selectionEnd);
        onChange(next);
        requestAnimationFrame(() => ta.setSelectionRange(s + 2, s + 2));
      }
    },
    [apply, value, onChange],
  );

  return (
    <div className="md-editor">
      <div className="md-toolbar">
        <div className="md-toolbar__group">
          {ACTIONS.map((a) => (
            <button
              key={a.key}
              type="button"
              className="md-tool"
              title={a.title}
              aria-label={a.title}
              disabled={mode === 'preview'}
              onClick={() => apply(a)}
            >
              <a.Icon />
            </button>
          ))}
        </div>
        <div className="md-toolbar__modes" role="group" aria-label="Editor mode">
          {(['write', 'split', 'preview'] as Mode[]).map((m) => (
            <button
              key={m}
              type="button"
              className={`md-mode${mode === m ? ' is-active' : ''}`}
              onClick={() => setMode(m)}
            >
              {m === 'write' ? 'Write' : m === 'split' ? 'Split' : 'Preview'}
            </button>
          ))}
        </div>
      </div>

      <div className={`md-body md-body--${mode}`}>
        {mode !== 'preview' && (
          <textarea
            ref={ref}
            className="md-textarea"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            onKeyDown={onKeyDown}
            placeholder={placeholder}
            rows={rows}
            spellCheck
          />
        )}
        {mode !== 'write' && (
          <div className="md-preview">
            <Markdown content={value} />
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { toast } from 'sonner';
import type { McpServerConfig } from '@/lib/api';

type McpClient = 'claude' | 'codex';

interface McpSetupPanelProps {
  token: string; // The MCP JWT token
  keyLabel: string; // Label of the API key
  servers: McpServerConfig[]; // Servers + URLs from backend config endpoint
  onClose: () => void;
}

/**
 * Generates MCP add commands for the given MCP servers.
 *
 * Claude Code:
 *   claude mcp add --transport http tobor-{id} {url} --header "Authorization: Bearer $AUTH_TOKEN"
 *
 * Codex:
 *   codex mcp add tobor-{id} --url {url} --bearer-token-env-var AUTH_TOKEN
 *
 * Server URLs come from the backend config endpoint (host-derived), so this
 * component never hardcodes a host.
 */
export default function McpSetupPanel({ token, keyLabel, servers, onClose }: McpSetupPanelProps) {
  const [client, setClient] = useState<McpClient>('claude');
  const [enabled, setEnabled] = useState<Record<string, boolean>>(() => {
    const state: Record<string, boolean> = {};
    servers.forEach((s) => { state[s.id] = true; });
    return state;
  });
  const [copiedCmd, setCopiedCmd] = useState<string | null>(null);

  function toggle(id: string) {
    const server = servers.find((s) => s.id === id);
    if (server?.required) return;
    setEnabled((prev) => ({ ...prev, [id]: !prev[id] }));
  }

  function getCommandLine(server: McpServerConfig) {
    const name = `tobor-${server.id}`;
    if (client === 'codex') {
      return `codex mcp add ${name} --url ${server.url} --bearer-token-env-var AUTH_TOKEN`;
    }

    return `claude mcp add --transport http ${name} ${server.url} --header "Authorization: Bearer $AUTH_TOKEN"`;
  }

  function buildScript() {
    const lines = [
      `export AUTH_TOKEN=${token}`,
      "",
    ];
    servers.filter((s) => enabled[s.id]).forEach((s) => {
      lines.push(getCommandLine(s));
    });
    return lines.join("\n");
  }

  async function copyScript() {
    try {
      await navigator.clipboard.writeText(buildScript());
      setCopiedCmd("script");
      setTimeout(() => setCopiedCmd(null), 2000);
      toast.success('Copied to clipboard');
    } catch {
      toast.error('Copy failed — select and copy manually');
    }
  }

  const activeCount = servers.filter((s) => enabled[s.id]).length;

  return (
    <div style={{
      background: "var(--bg-2)",
      borderRadius: "var(--radius-md)",
      padding: 16,
      marginTop: 12,
      border: "1px solid var(--border)"
    }}>
      <div style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        marginBottom: 12
      }}>
        <span style={{ fontSize: 13, fontWeight: 600 }}>MCP Setup — {keyLabel}</span>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={onClose} style={btnSm}>Close</button>
        </div>
      </div>

      <div style={{
        display: "flex",
        alignItems: "center",
        gap: 8,
        marginBottom: 12
      }}>
        <span style={{ fontSize: 11, fontWeight: 600, color: "var(--text-2)" }}>
          Client
        </span>
        <div style={{
          display: "inline-flex",
          border: "1px solid var(--border)",
          borderRadius: 6,
          overflow: "hidden",
          background: "var(--bg-3)"
        }}>
          {(['claude', 'codex'] as const).map((option) => (
            <button
              key={option}
              type="button"
              onClick={() => setClient(option)}
              style={{
                ...clientToggleBtn,
                ...(client === option
                  ? { background: "var(--accent)", color: "white" }
                  : { background: "transparent", color: "var(--text-1)" })
              }}
            >
              {option === 'claude' ? 'Claude Code' : 'Codex'}
            </button>
          ))}
        </div>
      </div>

      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(auto-fill, minmax(250px, 1fr))",
        gap: 6,
        marginBottom: 16
      }}>
        {servers.map((s) => (
          <label
            key={s.id}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              padding: "6px 10px",
              borderRadius: 6,
              background: enabled[s.id] ? "var(--accent-dim)" : "var(--bg-3)",
              border: `1px solid ${enabled[s.id] ? "var(--accent)" : "var(--border)"}`,
              cursor: s.required ? "default" : "pointer",
              fontSize: 12,
            }}
          >
            <input
              type="checkbox"
              checked={enabled[s.id]}
              onChange={() => toggle(s.id)}
              disabled={s.required}
              style={{ accentColor: "var(--accent)" }}
            />
            <div>
              <div style={{
                fontWeight: 500,
                color: enabled[s.id] ? "var(--text-0)" : "var(--text-3)"
              }}>
                {s.label}
                {s.required && (
                  <span style={{ fontSize: 9, color: "var(--text-3)", marginLeft: 4 }}>
                    required
                  </span>
                )}
              </div>
              <div style={{ fontSize: 10, color: "var(--text-3)" }}>{s.desc}</div>
            </div>
          </label>
        ))}
      </div>

      <div style={{ position: "relative" }}>
        <button
          onClick={copyScript}
          style={{
            ...btnSm,
            position: "absolute",
            top: 8,
            right: 8,
            zIndex: 1,
            ...(copiedCmd === "script"
              ? { background: "var(--green-dim)", color: "var(--green)", borderColor: "var(--green)" }
              : {})
          }}
        >
          {copiedCmd === "script" ? "Copied!" : `Copy (${activeCount})`}
        </button>
        <pre style={{
          margin: 0,
          padding: 16,
          paddingRight: 80,
          background: "var(--bg-3)",
          borderRadius: "var(--radius-sm)",
          fontFamily: "monospace",
          fontSize: 12,
          lineHeight: 1.7,
          color: "var(--text-1)",
          overflowX: "auto",
          whiteSpace: "pre-wrap",
          wordBreak: "break-all",
        }}>
          {buildScript()}
        </pre>
      </div>
    </div>
  );
}

