'use client';

// ConsoleDetailPage — the detail/edit analog of DataTable (ticket 0f8453f5, diego).
// One shared wrapper so each domain's app/[orgId]/<domain>/[id]/page.tsx is a THIN
// instantiation (descriptor + ctx + id), not a bespoke page (priya seq521 — same
// anti-divergence discipline as the canonical descriptor type). Fetches the entity,
// renders DetailView, toggles to EditForm on edit, and saves via descriptor.api.update
// (which a domain can adapt — e.g. artifacts' edit = append-revision). back-with-state
// via the router so the list's scroll/filter survive a round-trip.
import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import type { ConsoleContext, FacetOption } from '@/lib/console/types';
import { getDescriptor, type AnyDescriptor } from '@/lib/console/registry';
import { DetailView } from './DetailView';
import { EditForm } from './EditForm';

export interface ConsoleDetailPageProps {
  ctx: ConsoleContext;
  id: string;
  /** The domain's descriptor; if omitted, resolved from `domain` via registry.ts. */
  descriptor?: AnyDescriptor;
  /** Domain key — used to resolve the descriptor when `descriptor` isn't passed. */
  domain?: string;
  /** Resolved options for EditForm's dynamic select/reference fields. */
  referenceOptions?: Record<string, FacetOption[]>;
  /** Back affordance; defaults to router.back() (preserves list state). */
  onBack?: () => void;
  /** Start in edit mode (e.g. an /edit route). Default 'view'. */
  initialMode?: 'view' | 'edit';
}

export function ConsoleDetailPage({
  ctx,
  id,
  descriptor,
  domain,
  referenceOptions,
  onBack,
  initialMode = 'view',
}: ConsoleDetailPageProps) {
  const router = useRouter();
  const d = descriptor ?? (domain ? getDescriptor(domain) : undefined);

  const [row, setRow] = useState<Record<string, unknown> | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [mode, setMode] = useState<'view' | 'edit'>(initialMode);

  const fetchRow = useCallback(() => {
    if (!d) return;
    setLoading(true);
    setError(null);
    d.api
      .get(ctx.orgId, id)
      .then((r: Record<string, unknown>) => setRow(r))
      .catch((e: unknown) => setError(e instanceof Error ? e.message : 'Failed to load'))
      .finally(() => setLoading(false));
  }, [d, ctx.orgId, id]);

  useEffect(() => {
    fetchRow();
  }, [fetchRow]);

  const back = onBack ?? (() => router.back());

  if (!d) return <p className="console-state console-state--error" role="alert">Unknown domain “{domain}”.</p>;
  if (loading) return <p className="console-state" role="status">Loading {d.labels.singular.toLowerCase()}…</p>;
  if (error || !row)
    return (
      <div className="console-state console-state--error" role="alert">
        {error ?? `${d.labels.singular} not found.`}
        <button type="button" className="sg-btn" onClick={fetchRow}>
          Retry
        </button>
      </div>
    );

  if (mode === 'edit') {
    return (
      <EditForm
        descriptor={d}
        ctx={ctx}
        mode="edit"
        initial={row}
        referenceOptions={referenceOptions}
        onSubmit={async (values) => {
          if (!d.api.update) throw new Error(`${d.labels.singular} is not editable`);
          // update may throw → EditForm keeps the input + surfaces the error.
          await d.api.update(ctx.orgId, id, values);
          setMode('view');
          // refresh in the background; a refetch error must not look like a save error.
          d.api.get(ctx.orgId, id).then(setRow).catch(() => {});
        }}
        onCancel={() => setMode('view')}
      />
    );
  }

  return (
    <DetailView
      descriptor={d}
      row={row}
      ctx={ctx}
      onBack={back}
      onEdit={d.api.update ? () => setMode('edit') : undefined}
    />
  );
}

'use client';

// DataTable — config-driven console list primitive (ticket 0f8453f5, diego-frontend).
// Driven entirely by a ConsoleDescriptor (yuki §6): sort / filter / paginate, row +
// empty/loading/error states, density, bulk-select, and an accessible row kebab.
//
// a11y bar (§4): the table is a roving-tabindex grid — ArrowUp/Down move the active
// row, Home/End jump, Enter opens detail; only the active row is in the tab order.
// Sortable headers are buttons with aria-sort. The kebab is a real menu-button
// (aria-haspopup/expanded, arrow roving, Esc-restores-focus, outside-click dismiss)
// — same contract as the ReactionPicker. visibleWhen gates action visibility only.
import { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import type { ReactNode, KeyboardEvent } from 'react';
import type {
  ConsoleDescriptor,
  ConsoleContext,
  ColumnDef,
  ActionDef,
  BuiltinRowAction,
  FacetOption,
} from '@/lib/console/types';
import { renderField } from '@/lib/console/render-hints';

type Row = Record<string, unknown>;

export interface DataTableProps<T, TInput> {
  descriptor: ConsoleDescriptor<T, TInput>;
  ctx: ConsoleContext;
  /** Row opened (primary-cell click or Enter) → detail. */
  onOpenRow?: (row: T) => void;
  onEditRow?: (row: T) => void;
  onDeleteRow?: (row: T) => void;
  /** Handler for bare custom row-action keys (e.g. 'archive'). */
  onAction?: (key: string, row: T) => void;
  /**
   * G1 (priya seq495): bump this to refetch IN PLACE after a create/edit/delete —
   * preserves sort/filter/page state (vs a key-remount, which loses it).
   */
  refreshKey?: number;
  /** G2 (priya seq495): per-row class hook — e.g. mark the active scope / unread / selected. */
  rowClassName?: (row: T, ctx: ConsoleContext) => string | undefined;
  /**
   * Mei #2 (seq493): resolved options for `dynamic` facets, keyed by filter key.
   * DataTable doesn't fetch domain options itself (it can't know how); the page
   * resolves them (e.g. api.listProjects) and injects them here.
   */
  facetOptions?: Record<string, { value: string; label: string }[]>;
  /** Embedded related mini-table: drops the filter/pagination chrome, fixed scope. */
  embedded?: boolean;
  /** Extra api.list opts (related-table scope query, or a parent facet). */
  scope?: Record<string, unknown>;
  density?: 'comfortable' | 'compact';
  pageSize?: number;
}

function cell(row: Row, key: string): unknown {
  return row[key];
}

export function DataTable<T, TInput>({
  descriptor,
  ctx,
  onOpenRow,
  onEditRow,
  onDeleteRow,
  onAction,
  refreshKey = 0,
  rowClassName,
  facetOptions,
  embedded = false,
  scope,
  density = 'comfortable',
  pageSize = 25,
}: DataTableProps<T, TInput>) {
  const { columns, filters, labels, idKey = 'id', actions } = descriptor;

  const [rows, setRows] = useState<T[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  // Facet value is a string (single-select) or string[] (multi-select).
  const [facets, setFacets] = useState<Record<string, string | string[]>>({});
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [activeRow, setActiveRow] = useState(0);

  const rowId = useCallback((row: T) => String((row as Row)[idKey]), [idKey]);

  // Fetch on mount + whenever server-side facet scope changes (search/sort/paginate
  // stay client-side over the result set — console scale, deterministic).
  useEffect(() => {
    let live = true;
    setLoading(true);
    setError(null);
    const opts: Record<string, unknown> = { ...scope };
    // Single facet -> string; multi facet -> non-empty array (BE accepts array params).
    for (const [k, v] of Object.entries(facets)) {
      if (Array.isArray(v) ? v.length > 0 : v) opts[k] = v;
    }
    descriptor.api
      .list(ctx.orgId, opts)
      .then((data) => {
        if (!live) return;
        setRows(data);
      })
      .catch((e: unknown) => {
        if (!live) return;
        setError(e instanceof Error ? e.message : `Failed to load ${labels.plural.toLowerCase()}`);
        setRows([]);
      })
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
    // refreshKey forces a refetch in place (G1) — page/sort/filter state is NOT reset
    // here; only a genuine scope change (below) resets paging.
  }, [descriptor.api, ctx.orgId, facets, scope, refreshKey, labels.plural]);

  // Reset paging/active row only when the dataset SCOPE changes — not on a refresh-in-place.
  useEffect(() => {
    setPage(0);
    setActiveRow(0);
  }, [ctx.orgId, facets, scope]);

  const searched = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return rows;
    return rows.filter((r) =>
      columns.some((c) => String(cell(r as Row, c.key) ?? '').toLowerCase().includes(q)),
    );
  }, [rows, query, columns]);

  const sorted = useMemo(() => {
    if (!sortKey) return searched;
    const dir = sortDir === 'asc' ? 1 : -1;
    return [...searched].sort((a, b) => {
      const av = cell(a as Row, sortKey);
      const bv = cell(b as Row, sortKey);
      if (av == null) return 1;
      if (bv == null) return -1;
      if (typeof av === 'number' && typeof bv === 'number') return (av - bv) * dir;
      return String(av).localeCompare(String(bv)) * dir;
    });
  }, [searched, sortKey, sortDir]);

  const pageCount = Math.max(1, Math.ceil(sorted.length / pageSize));
  const pageRows = embedded ? sorted : sorted.slice(page * pageSize, page * pageSize + pageSize);

  function toggleSort(key: string) {
    if (sortKey === key) setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    else {
      setSortKey(key);
      setSortDir('asc');
    }
  }

  function onRowsKeyDown(e: KeyboardEvent<HTMLTableSectionElement>) {
    const n = pageRows.length;
    if (n === 0) return;
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveRow((i) => Math.min(n - 1, i + 1));
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveRow((i) => Math.max(0, i - 1));
        break;
      case 'Home':
        e.preventDefault();
        setActiveRow(0);
        break;
      case 'End':
        e.preventDefault();
        setActiveRow(n - 1);
        break;
      case 'Enter':
        e.preventDefault();
        if (onOpenRow && pageRows[activeRow]) onOpenRow(pageRows[activeRow]);
        break;
      default:
        break;
    }
  }

  const bulkEnabled = !embedded && (actions?.bulkActions?.length ?? 0) > 0;

  function renderCell(col: ColumnDef<T>, row: T): ReactNode {
    return renderField(col.render, col.key, row);
  }

  if (loading) return <p className="console-state" role="status">Loading {labels.plural.toLowerCase()}…</p>;
  if (error)
    return (
      <div className="console-state console-state--error" role="alert">
        {error}
        <button type="button" className="sg-btn" onClick={() => setFacets((f) => ({ ...f }))}>
          Retry
        </button>
      </div>
    );

  return (
    <div className={`console-table console-table--${density}`}>
      {!embedded && (filters?.length ?? 0) > 0 && (
        <div className="console-filters" role="search">
          {filters!.map((f) => {
            if (f.type === 'search') {
              return (
                <input
                  key={f.key}
                  type="search"
                  className="console-filters__search"
                  placeholder={`${f.label}…`}
                  aria-label={f.label}
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                />
              );
            }
            // dynamic facets take their options from the page-injected facetOptions (Mei #2).
            const opts = (f.dynamic ? facetOptions?.[f.key] : f.options) ?? [];
            if (f.multi) {
              const sel = Array.isArray(facets[f.key]) ? (facets[f.key] as string[]) : [];
              return (
                <FacetMultiSelect
                  key={f.key}
                  label={f.label}
                  options={opts}
                  selected={sel}
                  onChange={(vals) => setFacets((prev) => ({ ...prev, [f.key]: vals }))}
                />
              );
            }
            const single = typeof facets[f.key] === 'string' ? (facets[f.key] as string) : '';
            return (
              <label key={f.key} className="console-filters__facet">
                <span className="sr-only">{f.label}</span>
                <select
                  value={single}
                  onChange={(e) => setFacets((prev) => ({ ...prev, [f.key]: e.target.value }))}
                  aria-label={f.label}
                >
                  <option value="">{f.label}: all</option>
                  {opts.map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </select>
              </label>
            );
          })}
        </div>
      )}

      {pageRows.length === 0 ? (
        <p className="console-state console-state--empty">No {labels.plural.toLowerCase()} found.</p>
      ) : (
        <table className="console-table__grid">
          <thead>
            <tr>
              {bulkEnabled && <th className="console-table__check" scope="col" aria-label="Select" />}
              {columns.map((c) => {
                const isSorted = sortKey === c.key;
                return (
                  <th
                    key={c.key}
                    scope="col"
                    style={c.width ? { width: c.width } : undefined}
                    aria-sort={isSorted ? (sortDir === 'asc' ? 'ascending' : 'descending') : undefined}
                    className={c.align ? `is-${c.align}` : undefined}
                  >
                    {c.sortable ? (
                      <button type="button" className="console-table__sort" onClick={() => toggleSort(c.key)}>
                        {c.label}
                        <span aria-hidden className="console-table__sort-ind">
                          {isSorted ? (sortDir === 'asc' ? '▲' : '▼') : ''}
                        </span>
                      </button>
                    ) : (
                      c.label
                    )}
                  </th>
                );
              })}
              <th scope="col" className="console-table__actions-col" aria-label="Actions" />
            </tr>
          </thead>
          <tbody onKeyDown={onRowsKeyDown}>
            {pageRows.map((row, i) => {
              const id = rowId(row);
              return (
                <tr
                  key={id}
                  className={`console-table__row${i === activeRow ? ' is-active' : ''}${
                    rowClassName?.(row, ctx) ? ` ${rowClassName(row, ctx)}` : ''
                  }`}
                  tabIndex={i === activeRow ? 0 : -1}
                  aria-selected={selected.has(id) || undefined}
                  onFocus={() => setActiveRow(i)}
                >
                  {bulkEnabled && (
                    <td className="console-table__check">
                      <input
                        type="checkbox"
                        aria-label={`Select row ${i + 1}`}
                        checked={selected.has(id)}
                        onChange={(e) =>
                          setSelected((prev) => {
                            const next = new Set(prev);
                            if (e.target.checked) next.add(id);
                            else next.delete(id);
                            return next;
                          })
                        }
                      />
                    </td>
                  )}
                  {columns.map((c) => (
                    <td key={c.key} className={c.align ? `is-${c.align}` : undefined}>
                      {c.primary && onOpenRow ? (
                        <button type="button" className="console-table__open" onClick={() => onOpenRow(row)}>
                          {renderCell(c, row)}
                        </button>
                      ) : (
                        renderCell(c, row)
                      )}
                    </td>
                  ))}
                  <td className="console-table__actions-col">
                    <RowMenu
                      row={row}
                      ctx={ctx}
                      actions={actions?.rowActions}
                      api={descriptor.api}
                      onOpenRow={onOpenRow}
                      onEditRow={onEditRow}
                      onDeleteRow={onDeleteRow}
                      onAction={onAction}
                      canEdit={actions?.canEdit}
                      canDelete={actions?.canDelete}
                      builtinLabels={actions?.builtinLabels}
                      label={labels.singular}
                    />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}

      {!embedded && pageCount > 1 && (
        <nav className="console-pager" aria-label="Pagination">
          <button type="button" className="sg-btn" disabled={page === 0} onClick={() => setPage((p) => p - 1)}>
            ← Prev
          </button>
          <span className="console-pager__status" aria-live="polite">
            Page {page + 1} of {pageCount}
          </span>
          <button
            type="button"
            className="sg-btn"
            disabled={page >= pageCount - 1}
            onClick={() => setPage((p) => p + 1)}
          >
            Next →
          </button>
        </nav>
      )}
    </div>
  );
}

// Accessible per-row kebab menu-button (same focus contract as ReactionPicker):
// aria-haspopup/expanded, arrow-key roving, Home/End, Esc-closes-and-restores-focus,
// outside-click dismiss. Built-ins (view/edit/delete) wire from the api + callbacks;
// custom ActionDefs honor their visibleWhen(ctx) gate (visibility only).
function RowMenu<T, TInput>({
  row,
  ctx,
  actions,
  api,
  onOpenRow,
  onEditRow,
  onDeleteRow,
  onAction,
  canEdit,
  canDelete,
  builtinLabels,
  label,
}: {
  row: T;
  ctx: ConsoleContext;
  actions?: (BuiltinRowAction | (string & {}) | ActionDef<T>)[];
  api: ConsoleDescriptor<T, TInput>['api'];
  onOpenRow?: (row: T) => void;
  onEditRow?: (row: T) => void;
  onDeleteRow?: (row: T) => void;
  onAction?: (key: string, row: T) => void;
  canEdit?: (row: T, ctx: ConsoleContext) => boolean;
  canDelete?: (row: T, ctx: ConsoleContext) => boolean;
  builtinLabels?: { view?: string; edit?: string; delete?: string };
  label: string;
}) {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);

  type Item = { key: string; label: string; run: () => void | Promise<void>; danger?: boolean };
  const items: Item[] = [];
  const titleCase = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
  const list: (BuiltinRowAction | (string & {}) | ActionDef<T>)[] = actions ?? ['view', 'edit', 'delete'];
  for (const a of list) {
    if (a === 'view' && onOpenRow)
      items.push({ key: 'view', label: builtinLabels?.view ?? 'View', run: () => onOpenRow(row) });
    else if (a === 'edit' && api.update && onEditRow && (canEdit?.(row, ctx) ?? true))
      items.push({ key: 'edit', label: builtinLabels?.edit ?? 'Edit', run: () => onEditRow(row) });
    else if (a === 'delete' && api.remove && onDeleteRow && (canDelete?.(row, ctx) ?? true))
      items.push({ key: 'delete', label: builtinLabels?.delete ?? 'Delete', run: () => onDeleteRow(row), danger: true });
    else if (typeof a === 'object') {
      if (a.visibleWhen && !a.visibleWhen(row, ctx)) continue; // RBAC per-row visibility gate
      items.push({ key: a.key, label: a.label, run: () => a.run(row, ctx), danger: a.danger });
    } else if (typeof a === 'string' && onAction) {
      // Bare custom key (e.g. 'archive') — render only when the page supplies a handler.
      items.push({ key: a, label: titleCase(a), run: () => onAction(a, row) });
    }
  }

  useEffect(() => {
    if (!open) return;
    function onDown(e: PointerEvent) {
      const t = e.target as Node;
      if (!menuRef.current?.contains(t) && !triggerRef.current?.contains(t)) setOpen(false);
    }
    document.addEventListener('pointerdown', onDown);
    return () => document.removeEventListener('pointerdown', onDown);
  }, [open]);

  useEffect(() => {
    if (open) itemRefs.current[active]?.focus();
  }, [open, active]);

  if (items.length === 0) return null;

  function close(restore: boolean) {
    setOpen(false);
    if (restore) triggerRef.current?.focus();
  }

  function onMenuKey(e: KeyboardEvent<HTMLDivElement>) {
    const n = items.length;
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActive((i) => (i + 1) % n);
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActive((i) => (i - 1 + n) % n);
        break;
      case 'Home':
        e.preventDefault();
        setActive(0);
        break;
      case 'End':
        e.preventDefault();
        setActive(n - 1);
        break;
      case 'Escape':
        e.preventDefault();
        close(true);
        break;
      case 'Tab':
        setOpen(false);
        break;
      default:
        break;
    }
  }

  return (
    <div className="console-rowmenu">
      <button
        ref={triggerRef}
        type="button"
        className="console-rowmenu__trigger"
        aria-haspopup="true"
        aria-expanded={open}
        aria-label={`${label} actions`}
        onClick={() => (open ? close(false) : (setActive(0), setOpen(true)))}
        onKeyDown={(e) => {
          if (!open && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
            e.preventDefault();
            setActive(0);
            setOpen(true);
          }
        }}
      >
        ⋯
      </button>
      <div
        ref={menuRef}
        className={`console-rowmenu__menu${open ? ' is-open' : ''}`}
        role="menu"
        aria-label={`${label} actions`}
        onKeyDown={onMenuKey}
      >
        {items.map((it, i) => (
          <button
            key={it.key}
            ref={(el) => {
              itemRefs.current[i] = el;
            }}
            type="button"
            role="menuitem"
            tabIndex={open && i === active ? 0 : -1}
            className={`console-rowmenu__item${it.danger ? ' console-rowmenu__item--danger' : ''}`}
            onClick={() => {
              void it.run();
              close(true);
            }}
          >
            {it.label}
          </button>
        ))}
      </div>
    </div>
  );
}

// Multi-select facet (ticket 3c2d6bbe): a keyboard-accessible checklist popover —
// pick several values, OR-within-facet, passed to api.list as an array. Same focus
// contract as the kebab (aria-haspopup/expanded, Esc-restores-focus, outside-click).
function FacetMultiSelect({
  label,
  options,
  selected,
  onChange,
}: {
  label: string;
  options: FacetOption[];
  selected: string[];
  onChange: (values: string[]) => void;
}) {
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onDown(e: PointerEvent) {
      const t = e.target as Node;
      if (!menuRef.current?.contains(t) && !triggerRef.current?.contains(t)) setOpen(false);
    }
    document.addEventListener('pointerdown', onDown);
    return () => document.removeEventListener('pointerdown', onDown);
  }, [open]);

  function toggle(value: string, checked: boolean) {
    onChange(checked ? [...selected, value] : selected.filter((v) => v !== value));
  }

  const summary = selected.length === 0 ? `${label}: all` : `${label}: ${selected.length}`;

  return (
    <div className="console-filters__facet console-multifacet">
      <button
        ref={triggerRef}
        type="button"
        className="console-multifacet__trigger"
        aria-haspopup="true"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        {summary}
        <span aria-hidden className="console-multifacet__caret">▾</span>
      </button>
      <div
        ref={menuRef}
        className={`console-multifacet__menu${open ? ' is-open' : ''}`}
        role="group"
        aria-label={label}
        onKeyDown={(e) => {
          if (e.key === 'Escape') {
            e.preventDefault();
            setOpen(false);
            triggerRef.current?.focus();
          }
        }}
      >
        {options.length === 0 ? (
          <p className="console-muted console-multifacet__empty">No options</p>
        ) : (
          options.map((o) => (
            <label key={o.value} className="console-multifacet__option">
              <input
                type="checkbox"
                checked={selected.includes(o.value)}
                onChange={(e) => toggle(o.value, e.target.checked)}
              />
              {o.label}
            </label>
          ))
        )}
        {selected.length > 0 && (
          <button type="button" className="console-multifacet__clear" onClick={() => onChange([])}>
            Clear
          </button>
        )}
      </div>
    </div>
  );
}

'use client';

// DetailView — config-driven console detail primitive (ticket 0f8453f5, diego-frontend).
// Renders a descriptor's detail.sections (field grid) + detail.related as embedded
// read-only mini DataTables, with a back-with-state affordance and an Edit entry.
// a11y: a labelled <article>, section <h2>s, a real back button, and the same
// reserved focus channel as the rest of the console.
import type { ReactNode } from 'react';
import type { ConsoleDescriptor, ConsoleContext, DetailFieldDef } from '@/lib/console/types';
import { renderField } from '@/lib/console/render-hints';
import { getDescriptor } from '@/lib/console/registry';
import { DataTable } from './DataTable';

export interface DetailViewProps<T, TInput> {
  descriptor: ConsoleDescriptor<T, TInput>;
  row: T;
  ctx: ConsoleContext;
  /** Back-with-state: the page owns history/scroll restoration. */
  onBack?: () => void;
  /** Open the edit form for this row (omit when not editable). */
  onEdit?: (row: T) => void;
}

export function DetailView<T, TInput>({ descriptor, row, ctx, onBack, onEdit }: DetailViewProps<T, TInput>) {
  const { detail, labels, columns, idKey = 'id' } = descriptor;
  const r = row as Record<string, unknown>;

  // Title = the primary column's value (name/title), falling back to the id.
  const primaryKey = columns.find((c) => c.primary)?.key ?? 'name';
  const title = String(r[primaryKey] ?? r[idKey] ?? labels.singular);

  function field(f: DetailFieldDef<T>): ReactNode {
    return renderField(f.render, f.key, row);
  }

  return (
    <article className="console-detail" aria-label={`${labels.singular} detail`}>
      <header className="console-detail__header">
        {onBack && (
          <button type="button" className="sg-link console-detail__back" onClick={onBack}>
            ← {labels.plural}
          </button>
        )}
        <div className="console-detail__title-row">
          <h1 className="sg-page-title">{title}</h1>
          {descriptor.api.update && onEdit && (
            <button type="button" className="sg-btn" onClick={() => onEdit(row)}>
              Edit
            </button>
          )}
        </div>
      </header>

      {detail.sections.map((section) => (
        <section key={section.title} className="console-detail__section">
          <h2 className="console-detail__section-title">{section.title}</h2>
          <dl className="console-detail__fields">
            {section.fields.map((f) => (
              <div key={f.key} className={`console-detail__field${f.span ? ' console-detail__field--span' : ''}`}>
                <dt>{f.label}</dt>
                <dd>{field(f)}</dd>
              </div>
            ))}
          </dl>
        </section>
      ))}

      {detail.related?.map((rel) => {
        const relDescriptor = getDescriptor(rel.domain);
        return (
          <section key={rel.title} className="console-detail__section">
            <h2 className="console-detail__section-title">{rel.title}</h2>
            {relDescriptor ? (
              <DataTable
                descriptor={relDescriptor}
                ctx={ctx}
                embedded
                scope={rel.query(r)}
                density="compact"
              />
            ) : (
              <p className="console-muted">No “{rel.domain}” view registered yet.</p>
            )}
          </section>
        );
      })}
    </article>
  );
}

'use client';

// EditForm — config-driven console create/edit primitive (ticket 0f8453f5, diego).
// Renders a descriptor's edit.sections through a field-type registry with inline
// validation, a dirty-guard on cancel, and KEEP-INPUT-ON-FAILURE (the chat composer
// pattern: a failed submit keeps every value + surfaces the error, never clears).
// a11y: every field is labelled, required fields announce, errors wire via
// aria-invalid + aria-describedby, submit error is role=alert, reserved focus ring.
import { useId, useMemo, useState } from 'react';
import type { ConsoleDescriptor, ConsoleContext, EditFieldDef, FacetOption } from '@/lib/console/types';

export interface EditFormProps<T, TInput> {
  descriptor: ConsoleDescriptor<T, TInput>;
  ctx: ConsoleContext;
  mode: 'create' | 'edit';
  /** Edit mode: the current row's values. Create: omit (fields start empty). */
  initial?: Record<string, unknown>;
  /** Resolved options for `dynamic` select/reference fields, keyed by field key. */
  referenceOptions?: Record<string, FacetOption[]>;
  /** The page wires this to descriptor.api.create/update + a refresh. May throw to
   *  trigger keep-input-on-failure. */
  onSubmit: (values: Record<string, unknown>) => Promise<void>;
  onCancel: () => void;
}

function slugify(s: string): string {
  return s
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '') // strip combining marks (diacritic fold)
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function defaultFor(f: EditFieldDef): unknown {
  if (f.type === 'toggle') return false;
  if (f.type === 'multiselect') return [];
  return '';
}

export function EditForm<T, TInput>({
  descriptor,
  mode,
  initial,
  referenceOptions,
  onSubmit,
  onCancel,
}: EditFormProps<T, TInput>) {
  const fields = useMemo(() => descriptor.edit.sections.flatMap((s) => s.fields), [descriptor.edit.sections]);

  const initialValues = useMemo(() => {
    const v: Record<string, unknown> = {};
    for (const f of fields) v[f.key] = initial?.[f.key] ?? defaultFor(f);
    return v;
  }, [fields, initial]);

  const [values, setValues] = useState<Record<string, unknown>>(initialValues);
  const [touched, setTouched] = useState<Set<string>>(new Set());
  const [submitAttempted, setSubmitAttempted] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  // slug fields auto-derive from their source until the user edits the slug directly.
  const [slugDirty, setSlugDirty] = useState<Set<string>>(new Set());
  const baseId = useId();

  const dirty = useMemo(() => JSON.stringify(values) !== JSON.stringify(initialValues), [values, initialValues]);

  function errorFor(f: EditFieldDef): string | null {
    if (!f.required) return null;
    const v = values[f.key];
    const empty = v == null || v === '' || (Array.isArray(v) && v.length === 0);
    return empty ? `${f.label} is required` : null;
  }
  const firstError = fields.map(errorFor).find(Boolean) ?? null;

  function setValue(f: EditFieldDef, value: unknown) {
    setValues((prev) => {
      const next = { ...prev, [f.key]: value };
      // Auto-derive any slug field that sources from THIS field (unless slug edited).
      for (const sf of fields) {
        if (sf.type === 'slug' && sf.derivesFrom === f.key && !slugDirty.has(sf.key)) {
          next[sf.key] = slugify(String(value ?? ''));
        }
      }
      return next;
    });
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitAttempted(true);
    if (firstError) return; // inline errors now visible
    setSubmitting(true);
    setSubmitError(null);
    try {
      await onSubmit(values);
      // success: the page closes/navigates. Keep values otherwise.
    } catch (err) {
      // keep-input-on-failure: values stay, surface the error.
      setSubmitError(err instanceof Error ? err.message : 'Save failed');
    } finally {
      setSubmitting(false);
    }
  }

  function handleCancel() {
    if (dirty && !window.confirm('Discard unsaved changes?')) return;
    onCancel();
  }

  function fieldId(key: string) {
    return `${baseId}-${key}`;
  }

  function options(f: EditFieldDef): FacetOption[] {
    return (f.dynamic ? referenceOptions?.[f.key] : f.options) ?? [];
  }

  function renderControl(f: EditFieldDef) {
    const id = fieldId(f.key);
    const err = (touched.has(f.key) || submitAttempted) && errorFor(f);
    const invalid = err ? true : undefined;
    const describedBy = err ? `${id}-err` : f.hint ? `${id}-hint` : undefined;
    const common = {
      id,
      'aria-invalid': invalid,
      'aria-describedby': describedBy,
      disabled: f.readOnly || submitting,
      onBlur: () => setTouched((t) => new Set(t).add(f.key)),
    } as const;

    switch (f.type) {
      case 'textarea':
        return (
          <textarea
            {...common}
            className="console-field__input"
            rows={3}
            value={String(values[f.key] ?? '')}
            onChange={(e) => setValue(f, e.target.value)}
          />
        );
      case 'select':
      case 'reference':
        return (
          <select
            {...common}
            className="console-field__input"
            value={String(values[f.key] ?? '')}
            onChange={(e) => setValue(f, e.target.value)}
          >
            <option value="">{f.required ? `Select ${f.label.toLowerCase()}…` : '—'}</option>
            {options(f).map((o) => (
              <option key={o.value} value={o.value}>
                {o.label}
              </option>
            ))}
          </select>
        );
      case 'multiselect': {
        const arr = Array.isArray(values[f.key]) ? (values[f.key] as string[]) : [];
        return (
          <div className="console-field__checks" role="group" aria-labelledby={`${id}-label`}>
            {options(f).map((o) => (
              <label key={o.value} className="console-field__check">
                <input
                  type="checkbox"
                  checked={arr.includes(o.value)}
                  disabled={f.readOnly || submitting}
                  onChange={(e) =>
                    setValue(f, e.target.checked ? [...arr, o.value] : arr.filter((x) => x !== o.value))
                  }
                />
                {o.label}
              </label>
            ))}
          </div>
        );
      }
      case 'toggle':
        return (
          <input
            {...common}
            type="checkbox"
            className="console-field__toggle"
            checked={Boolean(values[f.key])}
            onChange={(e) => setValue(f, e.target.checked)}
          />
        );
      case 'date':
        return (
          <input
            {...common}
            type="date"
            className="console-field__input"
            value={String(values[f.key] ?? '')}
            onChange={(e) => setValue(f, e.target.value)}
          />
        );
      case 'number':
        return (
          <input
            {...common}
            type="number"
            className="console-field__input"
            value={String(values[f.key] ?? '')}
            onChange={(e) => setValue(f, e.target.value === '' ? '' : Number(e.target.value))}
          />
        );
      case 'slug':
        return (
          <input
            {...common}
            className="console-field__input console-field__input--mono"
            value={String(values[f.key] ?? '')}
            onChange={(e) => {
              setSlugDirty((s) => new Set(s).add(f.key));
              setValues((prev) => ({ ...prev, [f.key]: e.target.value }));
            }}
          />
        );
      case 'text':
      default:
        return (
          <input
            {...common}
            className="console-field__input"
            value={String(values[f.key] ?? '')}
            onChange={(e) => setValue(f, e.target.value)}
          />
        );
    }
  }

  return (
    <form className="console-form" onSubmit={handleSubmit} noValidate>
      {submitError && (
        <p className="console-form__error" role="alert">
          {submitError}
        </p>
      )}
      {descriptor.edit.sections.map((section) => (
        <fieldset key={section.title} className="console-form__section" disabled={submitting}>
          <legend className="console-form__legend">{section.title}</legend>
          {section.fields.map((f) => {
            const id = fieldId(f.key);
            const err = (touched.has(f.key) || submitAttempted) && errorFor(f);
            return (
              <div key={f.key} className="console-field">
                <label id={`${id}-label`} htmlFor={id} className="console-field__label">
                  {f.label}
                  {f.required && <span aria-hidden className="console-field__req"> *</span>}
                </label>
                {renderControl(f)}
                {f.hint && !err && (
                  <p id={`${id}-hint`} className="console-field__hint">
                    {f.hint}
                  </p>
                )}
                {err && (
                  <p id={`${id}-err`} className="console-field__err" role="alert">
                    {err}
                  </p>
                )}
              </div>
            );
          })}
        </fieldset>
      ))}
      <div className="console-form__actions">
        <button type="button" className="sg-btn" onClick={handleCancel} disabled={submitting}>
          Cancel
        </button>
        <button type="submit" className="sg-btn sg-btn--black" disabled={submitting}>
          {submitting ? 'Saving…' : mode === 'create' ? `Create ${descriptor.labels.singular}` : 'Save changes'}
        </button>
      </div>
    </form>
  );
}

"use client";

import { useState, useEffect } from "react";
import { api } from "@/lib/api";
import { useAuth } from "@/context/auth";
import { toast } from "sonner";

interface AdminUser {
  id: string;
  email: string;
  user_name: string;
  status: string;
  verified: boolean;
  role: string;
  created_at: string;
}

const ALL_ROLES = ["user", "moderator", "admin", "owner", "service", "other"];

export default function AdminUsersPage() {
  const { user: me } = useAuth();
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [savingId, setSavingId] = useState<string | null>(null);

  useEffect(() => {
    api.adminListUsers(page).then((res) => {
      setUsers(res.users);
      setTotal(res.total);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [page]);

  async function changeRole(id: string, role: string) {
    const prev = users.find((u) => u.id === id)?.role;
    setSavingId(id);
    // Optimistic update
    setUsers((us) => us.map((u) => (u.id === id ? { ...u, role } : u)));
    try {
      await api.adminUpdateUserRole(id, role);
      toast.success(`Role updated to ${role}`);
    } catch (err) {
      // Revert on failure
      setUsers((us) => us.map((u) => (u.id === id ? { ...u, role: prev ?? u.role } : u)));
      toast.error(err instanceof Error ? err.message : "Failed to update role");
    } finally {
      setSavingId(null);
    }
  }

  if (loading) {
    return <div className="content narrow"><main><p className="sg-page-intro">Loading…</p></main></div>;
  }

  return (
    <div className="content">
      <main>
        <h1 className="sg-page-title">Users ({total})</h1>
        <p className="sg-page-intro">Manage account roles. Elevated roles (admin, owner) grant access to this admin area.</p>
        <div className="admin-table-wrap">
          <table className="admin-table">
            <thead>
              <tr>
                <th>Email</th>
                <th>Username</th>
                <th>Status</th>
                <th>Verified</th>
                <th>Role</th>
              </tr>
            </thead>
            <tbody>
              {users.map((u) => {
                const isSelf = me?.id === u.id;
                return (
                  <tr key={u.id}>
                    <td>{u.email}</td>
                    <td>{u.user_name}</td>
                    <td>{u.status}</td>
                    <td>{u.verified ? "Yes" : "No"}</td>
                    <td>
                      <select
                        className="admin-role-select"
                        value={u.role}
                        disabled={isSelf || savingId === u.id}
                        title={isSelf ? "You cannot change your own role" : undefined}
                        onChange={(e) => changeRole(u.id, e.target.value)}
                      >
                        {ALL_ROLES.map((r) => (
                          <option key={r} value={r}>{r}</option>
                        ))}
                      </select>
                      {isSelf && <span className="admin-role-self"> (you)</span>}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <div className="button-row" style={{ marginTop: "var(--space-4)" }}>
          <button className="sg-btn sg-btn--outline sg-btn--sm" disabled={page <= 1} onClick={() => setPage(page - 1)}>Prev</button>
          <span className="sg-navbar__user" style={{ alignSelf: "center" }}>Page {page}</span>
          <button className="sg-btn sg-btn--outline sg-btn--sm" disabled={users.length < 50} onClick={() => setPage(page + 1)}>Next</button>
        </div>
      </main>
    </div>
  );
}

