'use client';

import { useState, useEffect, useMemo } from 'react';
import { toast } from 'sonner';
import {
  api,
  type GithubToken,
  type GithubRepo,
  type GithubRepoGrant,
  type RepoAcl,
  type RepoGrantLevel,
} from '@/lib/api';
import { useOrg } from '@/context/org';

const ACL_OPTIONS: { value: RepoAcl; label: string }[] = [
  { value: 'private', label: 'Private (group-only)' },
  { value: 'org_read', label: 'Org — read' },
  { value: 'org_write', label: 'Org — write' },
];

interface Group {
  id: string;
  name: string;
  display_name?: string | null;
}

export default function AdminGithubPage() {
  const { organizations, currentOrg } = useOrg();
  const [orgId, setOrgId] = useState<string>(currentOrg?.id ?? organizations[0]?.id ?? '');

  const [tokens, setTokens] = useState<GithubToken[]>([]);
  const [repos, setRepos] = useState<GithubRepo[]>([]);
  const [groups, setGroups] = useState<Group[]>([]);
  const [loading, setLoading] = useState(true);

  // New token form
  const [tokenLabel, setTokenLabel] = useState('');
  const [tokenValue, setTokenValue] = useState('');
  const [savingToken, setSavingToken] = useState(false);

  // New repo form
  const [repoName, setRepoName] = useState('');
  const [repoTokenId, setRepoTokenId] = useState<string>('');
  const [repoAcl, setRepoAcl] = useState<RepoAcl>('private');
  const [savingRepo, setSavingRepo] = useState(false);

  // Keep the selected org in sync with the org context.
  useEffect(() => {
    if (!orgId) setOrgId(currentOrg?.id ?? organizations[0]?.id ?? '');
  }, [currentOrg?.id, organizations, orgId]);

  useEffect(() => {
    if (!orgId) {
      setLoading(false);
      return;
    }
    setLoading(true);
    Promise.all([api.adminListGithubTokens(orgId), api.adminListGithubRepos(orgId), api.listGroups()])
      .then(([t, r, g]) => {
        setTokens(t.tokens);
        setRepos(r.repos);
        setGroups(g.groups ?? []);
      })
      .catch(() => toast.error('Failed to load GitHub config'))
      .finally(() => setLoading(false));
  }, [orgId]);

  async function addToken(e: React.FormEvent) {
    e.preventDefault();
    if (!orgId || !tokenLabel.trim() || !tokenValue.trim()) return;
    setSavingToken(true);
    try {
      const { token } = await api.adminCreateGithubToken(orgId, tokenLabel.trim(), tokenValue.trim());
      setTokens((prev) => [...prev, token].sort((a, b) => a.label.localeCompare(b.label)));
      setTokenLabel('');
      setTokenValue('');
      toast.success('Token added');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to add token');
    } finally {
      setSavingToken(false);
    }
  }

  async function removeToken(id: string) {
    if (!orgId || !confirm('Delete this token? Repos mapped to it will be unlinked.')) return;
    try {
      await api.adminDeleteGithubToken(orgId, id);
      setTokens((prev) => prev.filter((t) => t.id !== id));
      setRepos((prev) => prev.map((r) => (r.token_id === id ? { ...r, token_id: null, token_label: null } : r)));
      toast.success('Token deleted');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete token');
    }
  }

  async function addRepo(e: React.FormEvent) {
    e.preventDefault();
    if (!orgId || !repoName.trim()) return;
    setSavingRepo(true);
    try {
      const { repo } = await api.adminCreateGithubRepo(orgId, repoName.trim(), repoTokenId || null, repoAcl);
      setRepos((prev) => [...prev, repo].sort((a, b) => a.repo_full_name.localeCompare(b.repo_full_name)));
      setRepoName('');
      setRepoTokenId('');
      setRepoAcl('private');
      toast.success('Repo added');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to add repo');
    } finally {
      setSavingRepo(false);
    }
  }

  // Optimistically patch a repo field; revert on error.
  async function patchRepo(repoId: string, patch: Partial<GithubRepo>) {
    if (!orgId) return;
    const prev = repos.find((r) => r.id === repoId);
    if (!prev) return;
    setRepos((rs) => rs.map((r) => (r.id === repoId ? { ...r, ...patch } : r)));
    try {
      await api.adminUpdateGithubRepo(orgId, repoId, patch as { token_id?: string | null; default_acl?: RepoAcl });
    } catch (err) {
      setRepos((rs) => rs.map((r) => (r.id === repoId ? { ...r, ...prev } : r)));
      toast.error(err instanceof Error ? err.message : 'Failed to update repo');
    }
  }

  async function removeRepo(id: string) {
    if (!orgId || !confirm('Remove this repo?')) return;
    try {
      await api.adminDeleteGithubRepo(orgId, id);
      setRepos((prev) => prev.filter((r) => r.id !== id));
      toast.success('Repo removed');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to remove repo');
    }
  }

  const canEdit = useMemo(() => Boolean(orgId), [orgId]);

  if (loading && orgId) {
    return (
      <div className="content">
        <main>
          <p className="sg-page-intro">Loading…</p>
        </main>
      </div>
    );
  }

  return (
    <div className="content">
      <main>
        <h1 className="sg-page-title">GitHub Integration</h1>
        <p className="sg-page-intro">
          Manage raw GitHub tokens and the repos mapped to them. No GitHub API connection yet — paste tokens and repo names as text.
        </p>

        <div className="sg-field">
          <label htmlFor="gh-org">Organization</label>
          <select id="gh-org" value={orgId} onChange={(e) => setOrgId(e.target.value)}>
            {organizations.map((o) => (
              <option key={o.id} value={o.id}>
                {o.name} ({o.slug})
              </option>
            ))}
          </select>
        </div>

        {!canEdit ? (
          <p className="sg-page-intro">Select an organization to manage its GitHub config.</p>
        ) : (
          <div className="dash-grid" style={{ marginTop: 'var(--space-4)' }}>
            {/* Tokens */}
            <section className="dash-panel">
              <div className="dash-panel__head">
                <h2 className="dash-panel__title">Tokens</h2>
                <span className="dash-badge">{tokens.length}</span>
              </div>

              <form className="gh-add-form" onSubmit={addToken}>
                <input
                  className="gh-add-form__input"
                  value={tokenLabel}
                  onChange={(e) => setTokenLabel(e.target.value)}
                  placeholder="Label (e.g. ci-bot)"
                  aria-label="Token label"
                />
                <input
                  className="gh-add-form__input"
                  value={tokenValue}
                  onChange={(e) => setTokenValue(e.target.value)}
                  placeholder="ghp_… (raw token)"
                  aria-label="Token value"
                  autoComplete="off"
                />
                <button className="sg-btn sg-btn--black sg-btn--sm" type="submit" disabled={savingToken || !tokenLabel.trim() || !tokenValue.trim()}>
                  {savingToken ? 'Adding…' : 'Add token'}
                </button>
              </form>

              {tokens.length === 0 ? (
                <p className="sg-page-intro">No tokens yet.</p>
              ) : (
                <ul className="admin-table-wrap">
                  {tokens.map((t) => (
                    <li key={t.id} className="gh-row">
                      <div className="gh-row__main">
                        <div className="gh-row__title">{t.label}</div>
                        <div className="gh-row__sub font-mono">{t.token_preview}</div>
                      </div>
                      <button className="sg-btn sg-btn--danger sg-btn--sm" onClick={() => removeToken(t.id)}>
                        Delete
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </section>

            {/* Repos */}
            <section className="dash-panel">
              <div className="dash-panel__head">
                <h2 className="dash-panel__title">Repos</h2>
                <span className="dash-badge">{repos.length}</span>
              </div>

              <form className="gh-add-form" onSubmit={addRepo}>
                <input
                  className="gh-add-form__input"
                  value={repoName}
                  onChange={(e) => setRepoName(e.target.value)}
                  placeholder="owner/repo"
                  aria-label="Repo full name"
                />
                <select
                  className="gh-add-form__input"
                  value={repoTokenId}
                  onChange={(e) => setRepoTokenId(e.target.value)}
                  aria-label="Token"
                >
                  <option value="">— no token —</option>
                  {tokens.map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.label}
                    </option>
                  ))}
                </select>
                <select
                  className="gh-add-form__input"
                  value={repoAcl}
                  onChange={(e) => setRepoAcl(e.target.value as RepoAcl)}
                  aria-label="Default ACL"
                >
                  {ACL_OPTIONS.map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </select>
                <button className="sg-btn sg-btn--black sg-btn--sm" type="submit" disabled={savingRepo || !repoName.trim()}>
                  {savingRepo ? 'Adding…' : 'Add repo'}
                </button>
              </form>

              {repos.length === 0 ? (
                <p className="sg-page-intro">No repos yet.</p>
              ) : (
                <ul className="admin-table-wrap">
                  {repos.map((r) => (
                    <RepoRow
                      key={r.id}
                      orgId={orgId}
                      repo={r}
                      tokens={tokens}
                      groups={groups}
                      onPatch={patchRepo}
                      onRemove={removeRepo}
                    />
                  ))}
                </ul>
              )}
            </section>
          </div>
        )}
      </main>
    </div>
  );
}

function RepoRow({
  orgId,
  repo,
  tokens,
  groups,
  onPatch,
  onRemove,
}: {
  orgId: string;
  repo: GithubRepo;
  tokens: GithubToken[];
  groups: Group[];
  onPatch: (repoId: string, patch: Partial<GithubRepo>) => void;
  onRemove: (id: string) => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const [grants, setGrants] = useState<GithubRepoGrant[]>([]);
  const [grantGroup, setGrantGroup] = useState('');
  const [grantLevel, setGrantLevel] = useState<RepoGrantLevel>('read');
  const [loadingGrants, setLoadingGrants] = useState(false);

  async function loadGrants() {
    setLoadingGrants(true);
    try {
      const { grants: g } = await api.adminListGithubRepoGrants(orgId, repo.id);
      setGrants(g);
    } catch {
      toast.error('Failed to load grants');
    } finally {
      setLoadingGrants(false);
    }
  }

  async function toggleExpand() {
    const next = !expanded;
    setExpanded(next);
    if (next && grants.length === 0) await loadGrants();
  }

  async function addGrant(e: React.FormEvent) {
    e.preventDefault();
    if (!grantGroup) return;
    try {
      const { grants: g } = await api.adminGrantGithubRepoAccess(orgId, repo.id, grantGroup, grantLevel);
      setGrants(g);
      setGrantGroup('');
      setGrantLevel('read');
      toast.success('Group access granted');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to grant access');
    }
  }

  async function revokeGrant(grantId: string) {
    try {
      await api.adminRevokeGithubRepoAccess(orgId, repo.id, grantId);
      setGrants((prev) => prev.filter((g) => g.id !== grantId));
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to revoke access');
    }
  }

  return (
    <li className="gh-row gh-row--stacked">
      <div className="gh-row__main">
        <button className="gh-row__expand" onClick={toggleExpand} aria-label="Toggle ACL">
          {expanded ? '▾' : '▸'}
        </button>
        <div className="gh-row__title font-mono">{repo.repo_full_name}</div>
        <select
          className="admin-role-select"
          value={repo.token_id ?? ''}
          onChange={(e) => onPatch(repo.id, { token_id: e.target.value || null })}
        >
          <option value="">— no token —</option>
          {tokens.map((t) => (
            <option key={t.id} value={t.id}>
              {t.label}
            </option>
          ))}
        </select>
        <select
          className="admin-role-select"
          value={repo.default_acl}
          onChange={(e) => onPatch(repo.id, { default_acl: e.target.value as RepoAcl })}
          aria-label="Default ACL"
        >
          {ACL_OPTIONS.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
        <button className="sg-btn sg-btn--danger sg-btn--sm" onClick={() => onRemove(repo.id)}>
          Remove
        </button>
      </div>

      {expanded && (
        <div className="gh-grants">
          <div className="gh-grants__head">Group access grants</div>
          {loadingGrants ? (
            <p className="sg-page-intro">Loading…</p>
          ) : (
            <>
              {grants.length === 0 ? (
                <p className="sg-page-intro">No group grants — only the default ACL applies.</p>
              ) : (
                <ul className="gh-grants__list">
                  {grants.map((g) => (
                    <li key={g.id} className="gh-grant">
                      <span className="gh-grant__group">{g.display_name || g.group_name}</span>
                      <span className={`gh-grant__level gh-grant__level--${g.group_name}`}>{g.group_name === 'viewer' ? 'read' : 'write'}</span>
                      <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => revokeGrant(g.id)}>
                        Revoke
                      </button>
                    </li>
                  ))}
                </ul>
              )}

              <form className="gh-add-form" onSubmit={addGrant}>
                <select className="gh-add-form__input" value={grantGroup} onChange={(e) => setGrantGroup(e.target.value)} aria-label="Group">
                  <option value="">— select group —</option>
                  {groups.map((g) => (
                    <option key={g.id} value={g.id}>
                      {g.display_name || g.name}
                    </option>
                  ))}
                </select>
                <select
                  className="gh-add-form__input"
                  value={grantLevel}
                  onChange={(e) => setGrantLevel(e.target.value as RepoGrantLevel)}
                  aria-label="Level"
                >
                  <option value="read">read</option>
                  <option value="write">write</option>
                </select>
                <button className="sg-btn sg-btn--black sg-btn--sm" type="submit" disabled={!grantGroup}>
                  Grant
                </button>
              </form>
              <p className="sg-page-intro">
                read = read PRs, comment on PRs, read code · write = create/edit PRs, edit code
              </p>
            </>
          )}
        </div>
      )}
    </li>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { toast } from 'sonner';
import { api, type McpApiKey, type McpTokenResponse, type McpServerConfig } from '@/lib/api';
import McpSetupPanel from '@/components/mcp-setup-panel';

interface AdminUser {
  id: string;
  email: string;
  user_name: string;
  status: string;
  role: string;
}

export default function AdminAuthzPage() {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [userId, setUserId] = useState('');
  const [keys, setKeys] = useState<McpApiKey[]>([]);
  const [loadingUsers, setLoadingUsers] = useState(true);
  const [loadingKeys, setLoadingKeys] = useState(false);

  // New key form
  const [label, setLabel] = useState('default');
  const [creating, setCreating] = useState(false);

  // The most recently minted raw key (shown once).
  const [revealedKey, setRevealedKey] = useState<{ id: string; raw: string } | null>(null);

  // MCP tokens by api key id (for setup panel).
  const [tokens, setTokens] = useState<Record<string, McpTokenResponse>>({});

  // Which key's setup panel is open.
  const [setupKey, setSetupKey] = useState<string | null>(null);

  // Server config from the backend (host-derived, never hardcoded).
  const [servers, setServers] = useState<McpServerConfig[]>([]);

  // Paste-an-existing-key flow (non-destructive token mint for the selected user).
  const [pastedKey, setPastedKey] = useState('');
  const [minting, setMinting] = useState(false);

  const fetchKeys = useCallback(async (uid: string) => {
    if (!uid) {
      setKeys([]);
      return;
    }
    setLoadingKeys(true);
    setRevealedKey(null);
    try {
      const res = await api.adminListMcpKeys(uid);
      setKeys(res.keys);
    } catch {
      toast.error('Failed to load MCP keys');
    } finally {
      setLoadingKeys(false);
    }
  }, []);

  useEffect(() => {
    api
      .adminListUsers()
      .then((res) => {
        setUsers(res.users);
        const firstId = res.users[0]?.id ?? '';
        setUserId(firstId);
        fetchKeys(firstId);
      })
      .catch(() => toast.error('Failed to load users'))
      .finally(() => setLoadingUsers(false));
    api.mcpConfig().then((cfg) => setServers(cfg.servers)).catch(() => { /* non-fatal */ });
  }, [fetchKeys]);

  async function createKey(e: React.FormEvent) {
    e.preventDefault();
    if (!userId) return;
    setCreating(true);
    try {
      const { key, raw_key } = await api.adminCreateMcpKey(userId, label.trim() || 'default');
      setKeys((prev) => [key, ...prev.filter((k) => k.id !== key.id)]);
      setRevealedKey({ id: key.id, raw: raw_key });
      toast.success('MCP key created — copy it now, it won’t be shown again');

      // Auto-mint a token for the new key so setup is one click. The
      // authenticated mint is scoped to the logged-in admin, which is correct
      // when the admin is minting for their own user; for other users the admin
      // should share the raw key and let the user mint from the /mcp-keys page.
      try {
        const tokenData = await api.mintMcpTokenAuthenticated(raw_key);
        setTokens((prev) => ({ ...prev, [key.id]: tokenData }));
        setSetupKey(key.id);
      } catch (tokenErr) {
        console.error('Failed to mint token for new key:', tokenErr);
      }
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to create key');
    } finally {
      setCreating(false);
    }
  }

  async function mintFromPaste(e: React.FormEvent) {
    e.preventDefault();
    const raw = pastedKey.trim();
    if (!raw) return;
    setMinting(true);
    try {
      const tokenData = await api.mintMcpTokenAuthenticated(raw);
      await fetchKeys(userId);
      setTokens((prev) => ({ ...prev, '__pasted__': tokenData }));
      setSetupKey('__pasted__');
      setPastedKey('');
      toast.success('MCP token minted from pasted key');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to mint token');
    } finally {
      setMinting(false);
    }
  }

  async function revokeKey(id: string) {
    if (!userId || !confirm('Revoke this MCP key? Clients using it will lose access immediately.')) return;
    try {
      const { key } = await api.adminRevokeMcpKey(userId, id);
      setKeys((prev) => prev.map((k) => (k.id === id ? key : k)));
      setTokens((prev) => {
        const n = { ...prev };
        delete n[id];
        return n;
      });
      toast.success('Key revoked');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to revoke key');
    }
  }

  async function copyRaw(raw: string) {
    try {
      await navigator.clipboard.writeText(raw);
      toast.success('Copied to clipboard');
    } catch {
      toast.error('Copy failed — select and copy manually');
    }
  }

  function timeAgo(dt?: string | null) {
    if (!dt) return 'never';
    const diff = Date.now() - new Date(dt).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return 'just now';
    if (mins < 60) return `${mins}m ago`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return `${hrs}h ago`;
    return `${Math.floor(hrs / 24)}d ago`;
  }

  if (loadingUsers) {
    return (
      <div className="content">
        <main>
          <p className="sg-page-intro">Loading…</p>
        </main>
      </div>
    );
  }

  return (
    <div className="content">
      <main>
        <h1 className="sg-page-title">Authz — MCP Keys</h1>
        <p className="sg-page-intro">
          Mint and revoke long-lived MCP API keys for a user. Clients exchange a key for a short-lived MCP JWT at
          <span className="font-mono"> POST /api/mcp/token</span>. The raw key is shown only once at creation.
        </p>

        <div className="sg-field">
          <label htmlFor="authz-user">User</label>
          <select id="authz-user" value={userId} onChange={(e) => { setUserId(e.target.value); fetchKeys(e.target.value); }}>
            {users.map((u) => (
              <option key={u.id} value={u.id}>
                {u.email} ({u.role})
              </option>
            ))}
          </select>
        </div>

        {/* Connect an existing key (non-destructive). */}
        <section className="dash-panel" style={{ marginTop: 'var(--space-4)' }}>
          <div className="dash-panel__head">
            <h2 className="dash-panel__title">Connect an existing key</h2>
          </div>
          <p className="sg-page-intro" style={{ marginBottom: 12 }}>
            Paste a raw API key — combined with your login it mints an MCP token. The backend verifies
            ownership, so this only works for your own keys.
          </p>
          <form className="gh-add-form" onSubmit={mintFromPaste}>
            <input
              className="gh-add-form__input"
              value={pastedKey}
              onChange={(e) => setPastedKey(e.target.value)}
              placeholder="Paste raw API key"
              aria-label="Raw API key"
              style={{ flex: 2 }}
            />
            <button className="sg-btn sg-btn--black sg-btn--sm" type="submit" disabled={minting || !pastedKey.trim()}>
              {minting ? 'Minting…' : 'Mint Token'}
            </button>
          </form>
        </section>

        <section className="dash-panel" style={{ marginTop: 'var(--space-4)' }}>
          <div className="dash-panel__head">
            <h2 className="dash-panel__title">Create key</h2>
          </div>

          <form className="gh-add-form" onSubmit={createKey}>
            <input
              className="gh-add-form__input"
              value={label}
              onChange={(e) => setLabel(e.target.value)}
              placeholder="Label (e.g. ci-bot)"
              aria-label="Label"
            />
            <button className="sg-btn sg-btn--black sg-btn--sm" type="submit" disabled={creating || !userId}>
              {creating ? 'Creating…' : 'Generate key'}
            </button>
          </form>

          {revealedKey && (
            <div className="authz-reveal">
              <div className="authz-reveal__label">Raw key (shown once):</div>
              <div className="authz-reveal__row">
                <code className="authz-reveal__key font-mono">{revealedKey.raw}</code>
                <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => copyRaw(revealedKey.raw)}>
                  Copy
                </button>
              </div>
              <p className="sg-page-intro">Store this securely — it cannot be retrieved again.</p>
            </div>
          )}
        </section>

        <section className="dash-panel" style={{ marginTop: 'var(--space-4)' }}>
          <div className="dash-panel__head">
            <h2 className="dash-panel__title">Keys</h2>
            <span className="dash-badge">{keys.length}</span>
          </div>

          {loadingKeys ? (
            <p className="sg-page-intro">Loading…</p>
          ) : keys.length === 0 ? (
            <p className="sg-page-intro">No MCP keys yet.</p>
          ) : (
            <ul className="admin-table-wrap">
              {keys.map((k) => {
                const hasToken = !!tokens[k.id];
                return (
                  <li key={k.id} className="gh-row">
                    <div className="gh-row__main">
                      <div className="gh-row__title">{k.label}</div>
                      <div className="gh-row__sub font-mono">{k.key_prefix}…</div>
                      <span className={`gh-grant__level gh-grant__level--${k.status === 'active' ? 'member' : 'viewer'}`}>
                        {k.status}
                      </span>
                      <span className="gh-row__sub">last used {timeAgo(k.last_used_at)}</span>
                    </div>

                    <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                      {k.status === 'active' && hasToken && (
                        <>
                          <button
                            onClick={() => setSetupKey(setupKey === k.id ? null : k.id)}
                            className="sg-btn sg-btn--outline sg-btn--sm"
                            style={{
                              ...(setupKey === k.id
                                ? { background: 'var(--accent-dim)', color: 'var(--accent)', borderColor: 'var(--accent)' }
                                : {})
                            }}
                          >
                            Setup
                          </button>
                          <button
                            className="sg-btn sg-btn--outline sg-btn--sm"
                            onClick={() => copyRaw(tokens[k.id].token)}
                          >
                            Copy Token
                          </button>
                        </>
                      )}
                      {k.status === 'active' && !hasToken && (
                        <span className="gh-row__sub">paste raw key above to mint a token</span>
                      )}
                      {k.status === 'active' && (
                        <button className="sg-btn sg-btn--danger sg-btn--sm" onClick={() => revokeKey(k.id)}>
                          Revoke
                        </button>
                      )}
                    </div>
                  </li>
                );
              })}
            </ul>
          )}
        </section>

        {/* Setup panel for the selected key with a minted token. */}
        {setupKey && tokens[setupKey] && servers.length > 0 && (
          (() => {
            const key = keys.find((k) => k.id === setupKey);
            return (
              <McpSetupPanel
                token={tokens[setupKey].token}
                keyLabel={key?.label ?? 'pasted key'}
                servers={servers}
                onClose={() => setSetupKey(null)}
              />
            );
          })()
        )}
      </main>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useMemo } from 'react';
import { toast } from 'sonner';
import {
  PlusIcon,
  TrashIcon,
  ChevronRightIcon,
  PencilSquareIcon,
  DocumentPlusIcon,
  Cog6ToothIcon,
} from '@heroicons/react/24/outline';
import { api, type WikiSpace, type WikiPage, type WikiPageSummary } from '@/lib/api';
import { useOrg, useOrgId } from '@/context/org';
import { Markdown } from '@/components/markdown';
import { MarkdownEditor } from '@/components/markdown-editor';

const REACTION_EMOJI = ['👍', '🎉', '❤️', '🚀', '👀', '✅'];

function toSlug(name: string) {
  return name.toLowerCase().trim().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '').replace(/^-+|-+$/g, '');
}

// ── Page-tree types ───────────────────────────────────────────────────────
interface TreeNode {
  page: WikiPageSummary;
  children: TreeNode[];
}

function buildTree(pages: WikiPageSummary[]): TreeNode[] {
  const byId = new Map<string, TreeNode>();
  pages.forEach((p) => byId.set(p.id, { page: p, children: [] }));
  const roots: TreeNode[] = [];
  pages.forEach((p) => {
    const node = byId.get(p.id)!;
    const parent = p.parent_id ? byId.get(p.parent_id) : undefined;
    if (parent) parent.children.push(node);
    else roots.push(node);
  });
  return roots;
}

// ── Space create/edit modal ───────────────────────────────────────────────
function SpaceModal({
  orgId,
  space,
  defaultProjectId,
  onClose,
  onSaved,
}: {
  orgId: string;
  space?: WikiSpace | null;
  defaultProjectId?: string;
  onClose: () => void;
  onSaved: (space: WikiSpace) => void;
}) {
  const isEdit = !!space;
  const [name, setName] = useState(space?.name ?? '');
  const [slug, setSlug] = useState(space?.slug ?? '');
  const [description, setDescription] = useState(space?.description ?? '');
  const [slugTouched, setSlugTouched] = useState(isEdit);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!name.trim()) return;
    setSaving(true);
    setError(null);
    try {
      const payload = {
        name: name.trim(),
        slug: slug.trim() || toSlug(name),
        description: description.trim(),
        ...(isEdit ? {} : { project_id: defaultProjectId ?? null }),
      };
      const res = isEdit && space
        ? await api.updateWikiSpace(orgId, space.id, payload)
        : await api.createWikiSpace(orgId, payload);
      toast.success(isEdit ? 'Space updated' : 'Space created');
      onSaved(res.space);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Request failed');
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()}>
        <h2 className="modal-title">{isEdit ? 'Edit Space' : 'Create Space'}</h2>
        <form onSubmit={handleSubmit}>
          <div className="sg-field">
            <label htmlFor="space-name">Name</label>
            <input
              id="space-name"
              value={name}
              onChange={(e) => { setName(e.target.value); if (!slugTouched) setSlug(toSlug(e.target.value)); }}
              placeholder="Engineering"
              autoFocus
            />
          </div>
          <div className="sg-field">
            <label htmlFor="space-slug">Slug</label>
            <input id="space-slug" value={slug} onChange={(e) => { setSlugTouched(true); setSlug(e.target.value); }} placeholder="engineering" />
          </div>
          <div className="sg-field">
            <label htmlFor="space-description">Description</label>
            <textarea id="space-description" value={description ?? ''} onChange={(e) => setDescription(e.target.value)} placeholder="Optional description" />
          </div>
          {error && <div className="sg-error">{error}</div>}
          <div className="modal-actions">
            <button type="button" className="sg-btn sg-btn--outline" onClick={onClose}>Cancel</button>
            <button type="submit" className="sg-btn sg-btn--black" disabled={saving || !name.trim()}>
              {saving ? 'Saving…' : isEdit ? 'Save' : 'Create'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// ── Sidebar tree node ─────────────────────────────────────────────────────
function TreeItem({
  node,
  depth,
  activeId,
  onOpen,
  onAddChild,
  onDelete,
}: {
  node: TreeNode;
  depth: number;
  activeId: string | null;
  onOpen: (id: string) => void;
  onAddChild: (parentId: string) => void;
  onDelete: (page: WikiPageSummary) => void;
}) {
  const [open, setOpen] = useState(true);
  const hasChildren = node.children.length > 0;

  return (
    <li className="wtree__li">
      <div
        className={`wtree__row${activeId === node.page.id ? ' is-active' : ''}`}
        style={{ paddingLeft: `${depth * 14 + 6}px` }}
      >
        <button
          type="button"
          className={`wtree__caret${hasChildren ? '' : ' is-empty'}`}
          onClick={() => setOpen((v) => !v)}
          aria-label={open ? 'Collapse' : 'Expand'}
        >
          {hasChildren && <ChevronRightIcon className={open ? 'is-open' : ''} />}
        </button>
        <button type="button" className="wtree__name" onClick={() => onOpen(node.page.id)} title={node.page.title}>
          {node.page.title}
        </button>
        <span className="wtree__actions">
          <button className="wiki-icon-btn" onClick={() => onAddChild(node.page.id)} title="Add subpage" aria-label="Add subpage">
            <PlusIcon />
          </button>
          <button className="wiki-icon-btn" onClick={() => onDelete(node.page)} title="Delete page" aria-label="Delete page">
            <TrashIcon />
          </button>
        </span>
      </div>
      {hasChildren && open && (
        <ul className="wtree__children">
          {node.children.map((c) => (
            <TreeItem key={c.page.id} node={c} depth={depth + 1} activeId={activeId} onOpen={onOpen} onAddChild={onAddChild} onDelete={onDelete} />
          ))}
        </ul>
      )}
    </li>
  );
}

// ── Page view / inline editor (+ comments, reactions, attachments) ────────
function PageView({
  orgId,
  pageId,
  pages,
  onChanged,
  onDeleted,
}: {
  orgId: string;
  pageId: string;
  pages: WikiPageSummary[];
  onChanged: () => void;
  onDeleted: () => void;
}) {
  const [page, setPage] = useState<WikiPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [draftTitle, setDraftTitle] = useState('');
  const [draftContent, setDraftContent] = useState('');
  const [saving, setSaving] = useState(false);
  const [commentBody, setCommentBody] = useState('');
  const [attName, setAttName] = useState('');
  const [attUrl, setAttUrl] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await api.getWikiPage(orgId, pageId);
      setPage(res.page);
      setDraftTitle(res.page.title);
      setDraftContent(res.page.content ?? '');
      // A freshly-created "Untitled" page opens straight into edit mode.
      setEditing(res.page.title === 'Untitled' && !res.page.content);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load page');
    } finally {
      setLoading(false);
    }
  }, [orgId, pageId]);

  useEffect(() => { load(); }, [load]);

  // Breadcrumb from parent chain.
  const breadcrumb = useMemo(() => {
    if (!page) return [];
    const byId = new Map(pages.map((p) => [p.id, p]));
    const chain: WikiPageSummary[] = [];
    let cur: WikiPageSummary | undefined = byId.get(page.id);
    const seen = new Set<string>();
    while (cur && !seen.has(cur.id)) {
      seen.add(cur.id);
      chain.unshift(cur);
      cur = cur.parent_id ? byId.get(cur.parent_id) : undefined;
    }
    return chain;
  }, [page, pages]);

  async function save() {
    if (!page || !draftTitle.trim()) return;
    setSaving(true);
    try {
      const res = await api.updateWikiPage(orgId, page.id, { title: draftTitle.trim(), content: draftContent });
      setPage(res.page);
      setEditing(false);
      toast.success('Saved');
      onChanged();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to save');
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete() {
    if (!page || !confirm(`Delete page “${page.title}”?`)) return;
    try {
      await api.deleteWikiPage(orgId, page.id);
      toast.success('Page deleted');
      onDeleted();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete page');
    }
  }

  async function addComment(e: React.FormEvent) {
    e.preventDefault();
    if (!commentBody.trim()) return;
    try {
      await api.createWikiComment(orgId, pageId, { body: commentBody.trim() });
      setCommentBody('');
      await load();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to add comment');
    }
  }

  async function deleteComment(id: string) {
    try { await api.deleteWikiComment(orgId, id); await load(); }
    catch (err) { toast.error(err instanceof Error ? err.message : 'Failed to delete comment'); }
  }

  async function toggleReaction(emoji: string) {
    const has = page?.reactions?.some((r) => r.emoji === emoji);
    try {
      if (has) await api.removeWikiPageReaction(orgId, pageId, emoji);
      else await api.addWikiPageReaction(orgId, pageId, emoji);
      await load();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to react');
    }
  }

  async function addAttachment(e: React.FormEvent) {
    e.preventDefault();
    if (!attName.trim()) return;
    try {
      await api.createWikiAttachment(orgId, pageId, { filename: attName.trim(), url: attUrl.trim() || undefined });
      setAttName(''); setAttUrl(''); await load();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to add attachment');
    }
  }

  async function deleteAttachment(id: string) {
    try { await api.deleteWikiAttachment(orgId, id); await load(); }
    catch (err) { toast.error(err instanceof Error ? err.message : 'Failed to delete attachment'); }
  }

  if (loading) return <div className="wiki-doc"><p className="sg-page-intro">Loading…</p></div>;
  if (!page) return <div className="wiki-doc"><p className="sg-page-intro">Page not found.</p></div>;

  const reactionCounts = (page.reactions ?? []).reduce<Record<string, number>>((acc, r) => {
    acc[r.emoji] = (acc[r.emoji] ?? 0) + 1; return acc;
  }, {});

  return (
    <div className="wiki-doc">
      <div className="wiki-doc__bar">
        <nav className="wiki-crumbs" aria-label="Breadcrumb">
          {breadcrumb.map((b, i) => (
            <span key={b.id} className="wiki-crumb">
              {i > 0 && <span className="wiki-crumb__sep">/</span>}
              <span className={b.id === page.id ? 'wiki-crumb__current' : ''}>{b.title}</span>
            </span>
          ))}
        </nav>
        <div className="wiki-doc__actions">
          {editing ? (
            <>
              <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => { setEditing(false); setDraftTitle(page.title); setDraftContent(page.content ?? ''); }} disabled={saving}>
                Cancel
              </button>
              <button className="sg-btn sg-btn--black sg-btn--sm" onClick={save} disabled={saving || !draftTitle.trim()}>
                {saving ? 'Saving…' : 'Save'}
              </button>
            </>
          ) : (
            <>
              <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => setEditing(true)}>
                <PencilSquareIcon /> Edit
              </button>
              <button className="sg-btn sg-btn--danger sg-btn--sm" onClick={handleDelete}>
                <TrashIcon /> Delete
              </button>
            </>
          )}
        </div>
      </div>

      {editing ? (
        <div className="wiki-doc__edit">
          <input
            className="wiki-doc__title-input"
            value={draftTitle}
            onChange={(e) => setDraftTitle(e.target.value)}
            placeholder="Page title"
          />
          <MarkdownEditor value={draftContent} onChange={setDraftContent} />
        </div>
      ) : (
        <article className="wiki-doc__body">
          <h1 className="wiki-doc__title">{page.title}</h1>
          <Markdown content={page.content} />
        </article>
      )}

      {!editing && (
        <>
          <div className="wiki-reactions">
            {REACTION_EMOJI.map((emoji) => {
              const count = reactionCounts[emoji] ?? 0;
              const active = page.reactions?.some((r) => r.emoji === emoji);
              return (
                <button key={emoji} className={`wiki-reaction${active ? ' is-active' : ''}`} onClick={() => toggleReaction(emoji)} title={active ? 'Remove reaction' : 'Add reaction'}>
                  <span>{emoji}</span>
                  {count > 0 && <span className="wiki-reaction__count">{count}</span>}
                </button>
              );
            })}
          </div>

          <section className="wiki-section">
            <h3 className="wiki-section__title">Attachments</h3>
            <ul className="wiki-list">
              {(page.attachments ?? []).length === 0 && <li className="wiki-list__empty">No attachments.</li>}
              {(page.attachments ?? []).map((a) => (
                <li key={a.id} className="wiki-list__item">
                  {a.url ? <a href={a.url} target="_blank" rel="noreferrer" className="wiki-link">{a.filename}</a> : <span>{a.filename}</span>}
                  <button className="wiki-icon-btn" onClick={() => deleteAttachment(a.id)} aria-label="Delete attachment"><TrashIcon /></button>
                </li>
              ))}
            </ul>
            <form className="wiki-inline-form" onSubmit={addAttachment}>
              <input value={attName} onChange={(e) => setAttName(e.target.value)} placeholder="filename.pdf" />
              <input value={attUrl} onChange={(e) => setAttUrl(e.target.value)} placeholder="https:// (optional)" />
              <button type="submit" className="sg-btn sg-btn--outline sg-btn--sm" disabled={!attName.trim()}>Add</button>
            </form>
          </section>

          <section className="wiki-section">
            <h3 className="wiki-section__title">Comments</h3>
            <ul className="wiki-comments">
              {(page.comments ?? []).length === 0 && <li className="wiki-list__empty">No comments yet.</li>}
              {(page.comments ?? []).map((c) => (
                <li key={c.id} className="wiki-comment">
                  <div className="wiki-comment__meta">
                    <span className="wiki-comment__author">{c.author || 'unknown'}</span>
                    <button className="wiki-icon-btn" onClick={() => deleteComment(c.id)} aria-label="Delete comment"><TrashIcon /></button>
                  </div>
                  <div className="wiki-comment__body">{c.body}</div>
                </li>
              ))}
            </ul>
            <form className="wiki-inline-form" onSubmit={addComment}>
              <input value={commentBody} onChange={(e) => setCommentBody(e.target.value)} placeholder="Add a comment…" />
              <button type="submit" className="sg-btn sg-btn--black sg-btn--sm" disabled={!commentBody.trim()}>Comment</button>
            </form>
          </section>
        </>
      )}
    </div>
  );
}

// ── Page (Docmost-style: sidebar tree + document) ─────────────────────────
type SpaceModalState = { type: 'create' } | { type: 'edit'; space: WikiSpace } | null;

export default function WikiPage() {
  const { orgId, loading: orgLoading } = useOrgId();
  const { currentProject, switchProject } = useOrg();
  const [spaces, setSpaces] = useState<WikiSpace[]>([]);
  const [activeSpace, setActiveSpace] = useState<WikiSpace | null>(null);
  const [pages, setPages] = useState<WikiPageSummary[]>([]);
  const [activePageId, setActivePageId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [spaceModal, setSpaceModal] = useState<SpaceModalState>(null);

  const scopeProjectId = currentProject?.id;
  const tree = useMemo(() => buildTree(pages), [pages]);

  const fetchSpaces = useCallback(async () => {
    if (!orgId) return;
    setLoading(true);
    try {
      const res = await api.listWikiSpaces(orgId, scopeProjectId ? { projectId: scopeProjectId } : undefined);
      setSpaces(res.spaces ?? []);
      setActiveSpace((cur) => res.spaces.find((s) => s.id === cur?.id) ?? res.spaces[0] ?? null);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load spaces');
    } finally {
      setLoading(false);
    }
  }, [orgId, scopeProjectId]);

  useEffect(() => {
    if (orgId) fetchSpaces();
    else if (!orgLoading) setLoading(false);
  }, [fetchSpaces, orgId, orgLoading]);

  const fetchPages = useCallback(async () => {
    if (!orgId || !activeSpace) { setPages([]); setActivePageId(null); return; }
    try {
      const res = await api.listWikiPages(orgId, activeSpace.id);
      setPages(res.pages ?? []);
      setActivePageId((cur) => res.pages.find((p) => p.id === cur)?.id ?? res.pages[0]?.id ?? null);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load pages');
    }
  }, [orgId, activeSpace]);

  useEffect(() => { fetchPages(); }, [fetchPages]);

  async function createPage(parentId?: string) {
    if (!orgId || !activeSpace) return;
    try {
      const res = await api.createWikiPage(orgId, activeSpace.id, {
        title: 'Untitled',
        slug: `page-${Date.now()}`,
        parent_id: parentId ?? null,
      });
      await fetchPages();
      setActivePageId(res.page.id);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to create page');
    }
  }

  async function deletePage(p: WikiPageSummary) {
    if (!orgId || !confirm(`Delete page “${p.title}” and its subpages?`)) return;
    try {
      await api.deleteWikiPage(orgId, p.id);
      toast.success('Page deleted');
      if (activePageId === p.id) setActivePageId(null);
      await fetchPages();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete page');
    }
  }

  async function deleteSpace(space: WikiSpace) {
    if (!orgId || !confirm(`Delete space “${space.name}” and all its pages?`)) return;
    try {
      await api.deleteWikiSpace(orgId, space.id);
      toast.success('Space deleted');
      if (activeSpace?.id === space.id) setActiveSpace(null);
      await fetchSpaces();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete space');
    }
  }

  if (!orgId && !orgLoading) {
    return <div className="content"><main><p className="sg-page-intro">Select an organization.</p></main></div>;
  }

  return (
    <div className="content content--flush">
      <div className="wiki-shell">
        {/* Sidebar */}
        <aside className="wiki-sidebar">
          <div className="wiki-sidebar__top">
            <select
              className="wiki-space-select"
              value={activeSpace?.id ?? ''}
              onChange={(e) => setActiveSpace(spaces.find((s) => s.id === e.target.value) ?? null)}
              disabled={spaces.length === 0}
            >
              {spaces.length === 0 && <option value="">No spaces</option>}
              {spaces.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
            <button className="wiki-icon-btn" onClick={() => setSpaceModal({ type: 'create' })} title="New space" aria-label="New space">
              <PlusIcon />
            </button>
            {activeSpace && (
              <button className="wiki-icon-btn" onClick={() => setSpaceModal({ type: 'edit', space: activeSpace })} title="Space settings" aria-label="Space settings">
                <Cog6ToothIcon />
              </button>
            )}
          </div>

          {currentProject && (
            <div className="wiki-sidebar__scope">
              <span className="scope-chip">
                {currentProject.name}
                <button type="button" className="scope-chip__clear" onClick={() => switchProject(null)} aria-label="Clear project scope" title="Show all projects">×</button>
              </span>
            </div>
          )}

          <div className="wiki-sidebar__head">
            <span>Pages</span>
            <button className="wiki-icon-btn" onClick={() => createPage()} disabled={!activeSpace} title="New page" aria-label="New page">
              <DocumentPlusIcon />
            </button>
          </div>

          {loading ? (
            <p className="wiki-col__empty">Loading…</p>
          ) : !activeSpace ? (
            <p className="wiki-col__empty">Create a space to begin.</p>
          ) : tree.length === 0 ? (
            <button className="wiki-empty-cta" onClick={() => createPage()}>+ Create your first page</button>
          ) : (
            <ul className="wtree">
              {tree.map((n) => (
                <TreeItem key={n.page.id} node={n} depth={0} activeId={activePageId} onOpen={setActivePageId} onAddChild={createPage} onDelete={deletePage} />
              ))}
            </ul>
          )}

          {activeSpace && (
            <button className="wiki-sidebar__danger" onClick={() => deleteSpace(activeSpace)}>
              <TrashIcon /> Delete space
            </button>
          )}
        </aside>

        {/* Document area */}
        <div className="wiki-main">
          {activePageId && orgId ? (
            <PageView
              key={activePageId}
              orgId={orgId}
              pageId={activePageId}
              pages={pages}
              onChanged={fetchPages}
              onDeleted={() => { setActivePageId(null); fetchPages(); }}
            />
          ) : (
            <div className="wiki-doc wiki-doc--empty">
              <h1 className="sg-page-title">Wiki</h1>
              <p className="sg-page-intro">
                {activeSpace ? 'Select a page from the sidebar, or create one.' : 'Create a space to start writing.'}
              </p>
            </div>
          )}
        </div>
      </div>

      {spaceModal && orgId && (
        <SpaceModal
          orgId={orgId}
          space={spaceModal.type === 'edit' ? spaceModal.space : null}
          defaultProjectId={scopeProjectId}
          onClose={() => setSpaceModal(null)}
          onSaved={(s) => { setSpaceModal(null); setActiveSpace(s); fetchSpaces(); }}
        />
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useMemo } from 'react';
import { toast } from 'sonner';
import { PlusIcon } from '@heroicons/react/24/outline';
import { api, type TypeDefinition, type FieldDefinition } from '@/lib/api';
import { useOrg, useOrgId } from '@/context/org';

const RANK = { project: 3, org: 2, global: 1 } as const;

interface FieldRow {
  id: string;
  slug: string;
  label: string;
  checked: boolean;
  required: boolean;
}

function TypeModal({
  orgId,
  scope,
  projectId,
  type,
  prefill,
  available,
  onClose,
  onSaved,
}: {
  orgId: string;
  scope: 'org' | 'project';
  projectId?: string;
  type?: TypeDefinition | null;
  prefill?: TypeDefinition | null;
  available: FieldDefinition[];
  onClose: () => void;
  onSaved: () => void;
}) {
  const isEdit = !!type;
  const base = type ?? prefill ?? null;
  const [slug, setSlug] = useState(base?.slug ?? '');
  const [name, setName] = useState(base?.name ?? '');
  const [description, setDescription] = useState(base?.description ?? '');
  const [icon, setIcon] = useState(base?.icon ?? '');
  const [workflowText, setWorkflowText] = useState(base?.status_workflow ? JSON.stringify(base.status_workflow, null, 2) : '');
  const assigned = new Map((base?.fields ?? []).map((f) => [f.id, f.required]));
  const [rows, setRows] = useState<FieldRow[]>(
    available.map((f) => ({ id: f.id, slug: f.slug, label: f.label, checked: assigned.has(f.id), required: assigned.get(f.id) ?? false })),
  );
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  function toggle(id: string, patch: Partial<FieldRow>) {
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, ...patch } : r)));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!name.trim() || (!isEdit && !slug.trim())) return;

    let status_workflow: Record<string, unknown> | null = null;
    if (workflowText.trim()) {
      try {
        status_workflow = JSON.parse(workflowText);
      } catch {
        setError('Status workflow must be valid JSON');
        return;
      }
    }

    const fields = rows.filter((r) => r.checked).map((r) => ({ id: r.id, required: r.required }));

    setSaving(true);
    setError(null);
    try {
      const payload = { name: name.trim(), description: description.trim() || null, icon: icon.trim() || null, status_workflow, fields };
      if (isEdit && type) {
        await api.updateTypeDefinition(orgId, type.id, payload);
      } else {
        await api.createTypeDefinition(orgId, { ...payload, slug: slug.trim(), scope, project_id: scope === 'project' ? projectId : null });
      }
      toast.success(isEdit ? 'Type updated' : 'Type saved');
      onSaved();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Request failed');
    } finally {
      setSaving(false);
    }
  }

  const title = isEdit ? 'Edit Ticket Type' : prefill ? `Override “${prefill.slug}” at ${scope} scope` : `New Ticket Type (${scope})`;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()}>
        <h2 className="modal-title">{title}</h2>
        <form onSubmit={handleSubmit}>
          <div className="sg-field">
            <label htmlFor="td-slug">Slug</label>
            <input id="td-slug" value={slug} onChange={(e) => setSlug(e.target.value)} placeholder="bug" disabled={isEdit || !!prefill} />
          </div>
          <div className="sg-field">
            <label htmlFor="td-name">Name</label>
            <input id="td-name" value={name} onChange={(e) => setName(e.target.value)} placeholder="Bug" autoFocus />
          </div>
          <div className="sg-field">
            <label htmlFor="td-icon">Icon</label>
            <input id="td-icon" value={icon} onChange={(e) => setIcon(e.target.value)} placeholder="🐛 (optional)" />
          </div>
          <div className="sg-field">
            <label htmlFor="td-desc">Description</label>
            <textarea id="td-desc" value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Optional" />
          </div>

          <div className="sg-field">
            <label>Fields</label>
            {available.length === 0 ? (
              <span className="sg-field__hint">No fields available — create some on the Ticket Fields page.</span>
            ) : (
              <div className="td-fields">
                {rows.map((r) => (
                  <div key={r.id} className="td-fields__row">
                    <label className="td-fields__check">
                      <input type="checkbox" checked={r.checked} onChange={(e) => toggle(r.id, { checked: e.target.checked })} />
                      <span>
                        {r.label} <span className="font-mono sg-field__hint">{r.slug}</span>
                      </span>
                    </label>
                    {r.checked && (
                      <label className="td-fields__req">
                        <input type="checkbox" checked={r.required} onChange={(e) => toggle(r.id, { required: e.target.checked })} />
                        required
                      </label>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="sg-field">
            <label htmlFor="td-workflow">Status workflow (JSON)</label>
            <textarea
              id="td-workflow"
              value={workflowText}
              onChange={(e) => setWorkflowText(e.target.value)}
              rows={5}
              className="font-mono"
              placeholder={'{ "statuses": ["open","done"], "transitions": { "open": ["done"] } }'}
            />
          </div>

          {error && <div className="sg-error">{error}</div>}
          <div className="modal-actions">
            <button type="button" className="sg-btn sg-btn--outline" onClick={onClose}>
              Cancel
            </button>
            <button type="submit" className="sg-btn sg-btn--black" disabled={saving || !name.trim() || (!isEdit && !slug.trim())}>
              {saving ? 'Saving…' : isEdit ? 'Save' : 'Create'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

interface SlugGroup {
  slug: string;
  effective: TypeDefinition | null;
  ownRow: TypeDefinition | null;
}

type ModalState =
  | { kind: 'create' }
  | { kind: 'edit'; type: TypeDefinition }
  | { kind: 'override'; type: TypeDefinition }
  | null;

export default function TicketTypesPage() {
  const { orgId, loading: orgLoading } = useOrgId();
  const { currentProject, switchProject } = useOrg();
  const [types, setTypes] = useState<TypeDefinition[]>([]);
  const [fields, setFields] = useState<FieldDefinition[]>([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState<ModalState>(null);

  const scope: 'org' | 'project' = currentProject ? 'project' : 'org';
  const projectId = currentProject?.id;

  const fetchData = useCallback(async () => {
    if (!orgId) return;
    try {
      const opts = projectId ? { projectId } : undefined;
      const [typeData, fieldData] = await Promise.all([api.listTypeDefinitions(orgId, opts), api.listFieldDefinitions(orgId, opts)]);
      setTypes(typeData.type_definitions ?? []);
      setFields(fieldData.field_definitions ?? []);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load ticket types');
    } finally {
      setLoading(false);
    }
  }, [orgId, projectId]);

  useEffect(() => {
    if (orgId) fetchData();
    else if (!orgLoading) setLoading(false);
  }, [fetchData, orgId, orgLoading]);

  // Effective fields available for assignment (resolved, non-disabled).
  const availableFields = useMemo<FieldDefinition[]>(() => {
    const bySlug = new Map<string, FieldDefinition[]>();
    for (const f of fields) {
      const arr = bySlug.get(f.slug) ?? [];
      arr.push(f);
      bySlug.set(f.slug, arr);
    }
    return [...bySlug.values()]
      .map((rows) => [...rows].sort((a, b) => RANK[b.scope] - RANK[a.scope])[0])
      .filter((f) => f && !f.disabled)
      .sort((a, b) => a.slug.localeCompare(b.slug));
  }, [fields]);

  const groups = useMemo<SlugGroup[]>(() => {
    const bySlug = new Map<string, TypeDefinition[]>();
    for (const t of types) {
      const arr = bySlug.get(t.slug) ?? [];
      arr.push(t);
      bySlug.set(t.slug, arr);
    }
    const isOwn = (t: TypeDefinition) =>
      scope === 'project' ? t.scope === 'project' && t.project_id === projectId : t.scope === 'org';

    return [...bySlug.entries()]
      .map(([slug, rows]) => {
        const sorted = [...rows].sort((a, b) => RANK[b.scope] - RANK[a.scope]);
        const top = sorted[0];
        return { slug, effective: top && !top.disabled ? top : null, ownRow: rows.find(isOwn) ?? null };
      })
      .sort((a, b) => a.slug.localeCompare(b.slug));
  }, [types, scope, projectId]);

  async function openEdit(t: TypeDefinition, kind: 'edit' | 'override') {
    if (!orgId) return;
    try {
      const { type_definition } = await api.getTypeDefinition(orgId, t.id);
      setModal(kind === 'edit' ? { kind: 'edit', type: type_definition } : { kind: 'override', type: type_definition });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load type');
    }
  }

  async function disableHere(g: SlugGroup) {
    if (!orgId || !g.effective) return;
    try {
      await api.createTypeDefinition(orgId, {
        slug: g.slug,
        name: g.effective.name,
        disabled: true,
        scope,
        project_id: scope === 'project' ? projectId : null,
      });
      toast.success(`Disabled “${g.slug}” at ${scope} scope`);
      fetchData();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to disable');
    }
  }

  async function toggleOwnDisabled(row: TypeDefinition) {
    if (!orgId) return;
    try {
      await api.updateTypeDefinition(orgId, row.id, { disabled: !row.disabled });
      fetchData();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update');
    }
  }

  async function removeOwn(row: TypeDefinition) {
    if (!orgId) return;
    if (!confirm(`Remove the ${row.scope}-scoped “${row.slug}”?`)) return;
    try {
      await api.deleteTypeDefinition(orgId, row.id);
      toast.success('Removed');
      fetchData();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to remove');
    }
  }

  return (
    <div className="content">
      <main>
        <div className="projects-header">
          <h1 className="sg-page-title">Ticket Types</h1>
          <span className="scope-chip">
            Scope: <strong>{currentProject ? `Project · ${currentProject.name}` : 'Organization'}</strong>
            {currentProject && (
              <button type="button" className="scope-chip__clear" onClick={() => switchProject(null)} title="Manage at org scope">
                ×
              </button>
            )}
          </span>
        </div>
        <p className="sg-page-intro">
          Ticket types resolved for this {scope} scope (global → org{currentProject ? ' → project' : ''}). Override or disable inherited
          types, and add new ones at the {scope} scope.
        </p>

        {loading ? (
          <p className="sg-page-intro">Loading…</p>
        ) : groups.length === 0 ? (
          <div className="projects-empty">
            <p className="projects-empty__text">No ticket types visible. Create one at the {scope} scope.</p>
            <button className="sg-btn sg-btn--black" onClick={() => setModal({ kind: 'create' })}>
              New Ticket Type
            </button>
          </div>
        ) : (
          <div className="projects-grid">
            {groups.map((g) => {
              const eff = g.effective;
              const disabledHere = g.ownRow?.disabled;
              const ownAtScope = g.ownRow && (scope === 'project' ? g.ownRow.scope === 'project' : g.ownRow.scope === 'org');
              return (
                <div key={g.slug} className="project-card">
                  <div className="project-card__header">
                    <div className="project-card__org">{eff ? `${eff.scope}${eff.icon ? ` · ${eff.icon}` : ''}` : 'disabled here'}</div>
                    <div className="project-card__name">{eff?.name ?? g.slug}</div>
                  </div>
                  <div className="project-card__body">
                    <dl className="project-card__fields">
                      <div className="project-card__field">
                        <dt>Slug:</dt>
                        <dd className="font-mono">{g.slug}</dd>
                      </div>
                      {eff?.description && (
                        <div className="project-card__field">
                          <dt>About:</dt>
                          <dd>{eff.description}</dd>
                        </div>
                      )}
                    </dl>
                    <div className="project-card__actions">
                      {ownAtScope ? (
                        <>
                          {!disabledHere && (
                            <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => openEdit(g.ownRow!, 'edit')}>
                              Edit
                            </button>
                          )}
                          <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => toggleOwnDisabled(g.ownRow!)}>
                            {disabledHere ? 'Enable' : 'Disable'}
                          </button>
                          <button className="sg-btn sg-btn--danger sg-btn--sm" onClick={() => removeOwn(g.ownRow!)}>
                            Remove
                          </button>
                        </>
                      ) : (
                        <>
                          <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => eff && openEdit(eff, 'override')} disabled={!eff}>
                            Override
                          </button>
                          <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => disableHere(g)} disabled={!eff}>
                            Disable here
                          </button>
                        </>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </main>

      {modal && orgId && (
        <TypeModal
          orgId={orgId}
          scope={scope}
          projectId={projectId}
          type={modal.kind === 'edit' ? modal.type : null}
          prefill={modal.kind === 'override' ? modal.type : null}
          available={availableFields}
          onClose={() => setModal(null)}
          onSaved={() => {
            setModal(null);
            fetchData();
          }}
        />
      )}

      {!loading && groups.length > 0 && (
        <button className="fab" onClick={() => setModal({ kind: 'create' })} aria-label="New ticket type" title="New ticket type">
          <PlusIcon />
        </button>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useMemo } from 'react';
import { toast } from 'sonner';
import { PlusIcon } from '@heroicons/react/24/outline';
import { api, type FieldDefinition, FIELD_TYPES, type FieldType } from '@/lib/api';
import { useOrg, useOrgId } from '@/context/org';

const OPTION_TYPES: FieldType[] = ['select', 'radio', 'multi_select'];
const RANK = { project: 3, org: 2, global: 1 } as const;

function FieldModal({
  orgId,
  scope,
  projectId,
  field,
  prefill,
  onClose,
  onSaved,
}: {
  orgId: string;
  scope: 'org' | 'project';
  projectId?: string;
  field?: FieldDefinition | null; // editing an own-scope row
  prefill?: FieldDefinition | null; // overriding an inherited row
  onClose: () => void;
  onSaved: () => void;
}) {
  const isEdit = !!field;
  const base = field ?? prefill ?? null;
  const [slug, setSlug] = useState(base?.slug ?? '');
  const [label, setLabel] = useState(base?.label ?? '');
  const [fieldType, setFieldType] = useState<FieldType>((base?.field_type as FieldType) ?? 'text');
  const [defaultValue, setDefaultValue] = useState(base?.default_value ?? '');
  const [description, setDescription] = useState(base?.description ?? '');
  const [optionsText, setOptionsText] = useState(
    base?.options ? JSON.stringify(base.options, null, 2) : '{\n  "values": [\n    { "value": "", "label": "" }\n  ]\n}',
  );
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const needsOptions = OPTION_TYPES.includes(fieldType);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!label.trim() || (!isEdit && !slug.trim())) return;

    let options: Record<string, unknown> | null = null;
    if (needsOptions) {
      try {
        options = JSON.parse(optionsText);
      } catch {
        setError('Options must be valid JSON');
        return;
      }
    }

    setSaving(true);
    setError(null);
    try {
      const payload = {
        label: label.trim(),
        default_value: defaultValue.trim() || null,
        description: description.trim() || null,
        options,
      };
      if (isEdit && field) {
        await api.updateFieldDefinition(orgId, field.id, payload);
      } else {
        await api.createFieldDefinition(orgId, {
          ...payload,
          slug: slug.trim(),
          field_type: fieldType,
          scope,
          project_id: scope === 'project' ? projectId : null,
        });
      }
      toast.success(isEdit ? 'Field updated' : 'Field saved');
      onSaved();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Request failed');
    } finally {
      setSaving(false);
    }
  }

  const title = isEdit ? 'Edit Field' : prefill ? `Override “${prefill.slug}” at ${scope} scope` : `New Field (${scope})`;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()}>
        <h2 className="modal-title">{title}</h2>
        <form onSubmit={handleSubmit}>
          <div className="sg-field">
            <label htmlFor="fd-slug">Slug</label>
            <input id="fd-slug" value={slug} onChange={(e) => setSlug(e.target.value)} placeholder="story_points" disabled={isEdit || !!prefill} />
          </div>
          <div className="sg-field">
            <label htmlFor="fd-label">Label</label>
            <input id="fd-label" value={label} onChange={(e) => setLabel(e.target.value)} placeholder="Story Points" autoFocus />
          </div>
          <div className="sg-field">
            <label htmlFor="fd-type">Field type</label>
            <select id="fd-type" value={fieldType} onChange={(e) => setFieldType(e.target.value as FieldType)} disabled={isEdit}>
              {FIELD_TYPES.map((t) => (
                <option key={t} value={t}>
                  {t}
                </option>
              ))}
            </select>
          </div>
          {needsOptions && (
            <div className="sg-field">
              <label htmlFor="fd-options">Options (JSON)</label>
              <textarea id="fd-options" value={optionsText} onChange={(e) => setOptionsText(e.target.value)} rows={6} className="font-mono" />
            </div>
          )}
          <div className="sg-field">
            <label htmlFor="fd-default">Default value</label>
            <input id="fd-default" value={defaultValue} onChange={(e) => setDefaultValue(e.target.value)} placeholder="optional" />
          </div>
          <div className="sg-field">
            <label htmlFor="fd-desc">Description</label>
            <textarea id="fd-desc" value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Help text" />
          </div>
          {error && <div className="sg-error">{error}</div>}
          <div className="modal-actions">
            <button type="button" className="sg-btn sg-btn--outline" onClick={onClose}>
              Cancel
            </button>
            <button type="submit" className="sg-btn sg-btn--black" disabled={saving || !label.trim() || (!isEdit && !slug.trim())}>
              {saving ? 'Saving…' : isEdit ? 'Save' : 'Create'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

interface SlugGroup {
  slug: string;
  effective: FieldDefinition | null; // highest-precedence non-disabled
  ownRow: FieldDefinition | null; // row at the current scope, if any
  sourceScope: FieldDefinition['scope'] | 'none';
}

type ModalState =
  | { kind: 'create' }
  | { kind: 'edit'; field: FieldDefinition }
  | { kind: 'override'; field: FieldDefinition }
  | null;

export default function TicketFieldsPage() {
  const { orgId, loading: orgLoading } = useOrgId();
  const { currentProject, switchProject } = useOrg();
  const [fields, setFields] = useState<FieldDefinition[]>([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState<ModalState>(null);

  const scope: 'org' | 'project' = currentProject ? 'project' : 'org';
  const projectId = currentProject?.id;

  const fetchData = useCallback(async () => {
    if (!orgId) return;
    try {
      const data = await api.listFieldDefinitions(orgId, projectId ? { projectId } : undefined);
      setFields(data.field_definitions ?? []);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load fields');
    } finally {
      setLoading(false);
    }
  }, [orgId, projectId]);

  useEffect(() => {
    if (orgId) fetchData();
    else if (!orgLoading) setLoading(false);
  }, [fetchData, orgId, orgLoading]);

  // Collapse rows by slug into the effective view + current-scope override.
  const groups = useMemo<SlugGroup[]>(() => {
    const bySlug = new Map<string, FieldDefinition[]>();
    for (const f of fields) {
      const arr = bySlug.get(f.slug) ?? [];
      arr.push(f);
      bySlug.set(f.slug, arr);
    }
    const isOwn = (f: FieldDefinition) =>
      scope === 'project' ? f.scope === 'project' && f.project_id === projectId : f.scope === 'org';

    return [...bySlug.entries()]
      .map(([slug, rows]) => {
        const sorted = [...rows].sort((a, b) => RANK[b.scope] - RANK[a.scope]);
        const top = sorted[0];
        const effective = top && !top.disabled ? top : null;
        const ownRow = rows.find(isOwn) ?? null;
        return { slug, effective, ownRow, sourceScope: effective ? effective.scope : ('none' as const) };
      })
      .sort((a, b) => a.slug.localeCompare(b.slug));
  }, [fields, scope, projectId]);

  async function disableHere(g: SlugGroup) {
    if (!orgId || !g.effective) return;
    try {
      await api.createFieldDefinition(orgId, {
        slug: g.slug,
        label: g.effective.label,
        field_type: g.effective.field_type,
        disabled: true,
        scope,
        project_id: scope === 'project' ? projectId : null,
      });
      toast.success(`Disabled “${g.slug}” at ${scope} scope`);
      fetchData();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to disable');
    }
  }

  async function toggleOwnDisabled(row: FieldDefinition) {
    if (!orgId) return;
    try {
      await api.updateFieldDefinition(orgId, row.id, { disabled: !row.disabled });
      fetchData();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update');
    }
  }

  async function removeOwn(row: FieldDefinition) {
    if (!orgId) return;
    if (!confirm(`Remove the ${row.scope}-scoped “${row.slug}”?`)) return;
    try {
      await api.deleteFieldDefinition(orgId, row.id);
      toast.success('Removed');
      fetchData();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to remove');
    }
  }

  return (
    <div className="content">
      <main>
        <div className="projects-header">
          <h1 className="sg-page-title">Ticket Fields</h1>
          <span className="scope-chip">
            Scope: <strong>{currentProject ? `Project · ${currentProject.name}` : 'Organization'}</strong>
            {currentProject && (
              <button type="button" className="scope-chip__clear" onClick={() => switchProject(null)} title="Manage at org scope">
                ×
              </button>
            )}
          </span>
        </div>
        <p className="sg-page-intro">
          Field definitions resolved for this {scope} scope (global → org{currentProject ? ' → project' : ''}). Override or disable
          inherited fields, and add new ones at the {scope} scope.
        </p>

        {loading ? (
          <p className="sg-page-intro">Loading…</p>
        ) : groups.length === 0 ? (
          <div className="projects-empty">
            <p className="projects-empty__text">No fields visible. Create one at the {scope} scope.</p>
            <button className="sg-btn sg-btn--black" onClick={() => setModal({ kind: 'create' })}>
              New Field
            </button>
          </div>
        ) : (
          <div className="projects-grid">
            {groups.map((g) => {
              const eff = g.effective;
              const disabledHere = g.ownRow?.disabled;
              const ownAtScope = g.ownRow && (scope === 'project' ? g.ownRow.scope === 'project' : g.ownRow.scope === 'org');
              return (
                <div key={g.slug} className="project-card">
                  <div className="project-card__header">
                    <div className="project-card__org">
                      {eff ? `${eff.scope} · ${eff.field_type}` : 'disabled here'}
                    </div>
                    <div className="project-card__name">{eff?.label ?? g.slug}</div>
                  </div>
                  <div className="project-card__body">
                    <dl className="project-card__fields">
                      <div className="project-card__field">
                        <dt>Slug:</dt>
                        <dd className="font-mono">{g.slug}</dd>
                      </div>
                      {eff?.description && (
                        <div className="project-card__field">
                          <dt>Help:</dt>
                          <dd>{eff.description}</dd>
                        </div>
                      )}
                    </dl>
                    <div className="project-card__actions">
                      {ownAtScope ? (
                        <>
                          {!disabledHere && (
                            <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => setModal({ kind: 'edit', field: g.ownRow! })}>
                              Edit
                            </button>
                          )}
                          <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => toggleOwnDisabled(g.ownRow!)}>
                            {disabledHere ? 'Enable' : 'Disable'}
                          </button>
                          <button className="sg-btn sg-btn--danger sg-btn--sm" onClick={() => removeOwn(g.ownRow!)}>
                            Remove
                          </button>
                        </>
                      ) : (
                        <>
                          <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => setModal({ kind: 'override', field: eff! })} disabled={!eff}>
                            Override
                          </button>
                          <button className="sg-btn sg-btn--outline sg-btn--sm" onClick={() => disableHere(g)} disabled={!eff}>
                            Disable here
                          </button>
                        </>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </main>

      {modal && orgId && (
        <FieldModal
          orgId={orgId}
          scope={scope}
          projectId={projectId}
          field={modal.kind === 'edit' ? modal.field : null}
          prefill={modal.kind === 'override' ? modal.field : null}
          onClose={() => setModal(null)}
          onSaved={() => {
            setModal(null);
            fetchData();
          }}
        />
      )}

      {!loading && groups.length > 0 && (
        <button className="fab" onClick={() => setModal({ kind: 'create' })} aria-label="New field" title="New field">
          <PlusIcon />
        </button>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { toast } from 'sonner';
import { api, type GithubRepoSummary, type GithubPullRequest, type GithubIssue } from '@/lib/api';
import { useOrgId } from '@/context/org';

interface RepoSummary extends GithubRepoSummary {
  openPulls: number;
  openIssues: number;
}

function normalizeList<T>(res: { items: T[] } | T[] | undefined | null): T[] {
  if (!res) return [];
  return Array.isArray(res) ? res : res.items ?? [];
}

export default function GithubReposPage() {
  const { orgId, slug, loading: orgLoading } = useOrgId();
  const [repos, setRepos] = useState<RepoSummary[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchData = useCallback(async () => {
    if (!orgId) return;
    try {
      const data = await api.listGithubRepos(orgId);
      const baseRepos = data.repos ?? [];

      const enriched = await Promise.all(
        baseRepos.map(async (repo) => {
          const [pulls, issues] = await Promise.allSettled([
            api.listGithubPulls(orgId, repo.id, { state: "open", per_page: 1 }),
            api.listGithubIssues(orgId, repo.id, { state: "open", per_page: 1 }),
          ]);
          return {
            ...repo,
            openPulls: pulls.status === "fulfilled" ? normalizeList<GithubPullRequest>(pulls.value).length : 0,
            openIssues: issues.status === "fulfilled" ? normalizeList<GithubIssue>(issues.value).length : 0,
          };
        }),
      );
      setRepos(enriched);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load repositories');
    } finally {
      setLoading(false);
    }
  }, [orgId]);

  useEffect(() => {
    if (orgId) {
      fetchData();
    } else if (!orgLoading) {
      setLoading(false);
    }
  }, [fetchData, orgId, orgLoading]);

  return (
    <div className="content">
      <main>
        <div className="projects-header">
          <h1 className="sg-page-title">GitHub Repositories</h1>
        </div>
        <p className="sg-page-intro">
          Repositories mapped to this organization. Access is governed per-repo ACL and group grants.
        </p>

        {loading ? (
          <p className="sg-page-intro">Loading…</p>
        ) : repos.length === 0 ? (
          <div className="projects-empty">
            <p className="projects-empty__text">
              No repositories available. An admin must map repos and tokens first.
            </p>
          </div>
        ) : (
          <div className="projects-grid">
            {repos.map((repo) => (
              <Link
                key={repo.id}
                href={`/app/${slug}/github/${repo.id}`}
                className="project-card"
              >
                <div className="project-card__header">
                  <div className="project-card__name">{repo.repo_full_name}</div>
                </div>
                <div className="project-card__body">
                  <dl className="project-card__fields">
                    <div className="project-card__field">
                      <dt>ACL:</dt>
                      <dd>{repo.default_acl}</dd>
                    </div>
                    <div className="project-card__field">
                      <dt>Open PRs:</dt>
                      <dd>{repo.openPulls}</dd>
                    </div>
                    <div className="project-card__field">
                      <dt>Open Issues:</dt>
                      <dd>{repo.openIssues}</dd>
                    </div>
                  </dl>
                  <div className="project-card__meta">
                    <span className="project-card__status">{repo.token_preview ? 'token mapped' : 'no token'}</span>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}
